/* ════════════════════════════════════════════════════════════════════
 *  game_adv.js — 小英雄大對抗主程式模組
 *  ★ v5.235.0(2026-09-25)模組化拆分第一階段:本檔內容是從 index.html 的 inline <script>
 *    「逐位元組原封不動」搬出來的,執行位置與順序與拆分前完全相同(index.html 在原處用
 *    window._lxpsModLoad('game_adv.js') 載入)。
 *  內容:冒險模式／存檔套用／圖鑑與英雄詳情／獎章／預載清單…(原 index.html 第 101786 行起)
 *  ⚠ 改本檔後:_LXPS_FILE_VERSIONS['game_adv.js'] 必須改成本輪版號,並重新產生 version.json;
 *    上傳順序一律「本檔 → index.html → version.json」(先模組、後主檔),
 *    否則新 index.html 會用新版號去抓到舊內容,並被瀏覽器以新版號快取住。
 *  ⚠ 檔尾最後一行是載入完成記號,不可刪、不可在它後面加程式。
 * ════════════════════════════════════════════════════════════════════ */

// ── 技能 ? 按鈕 helper ──
// sk 可以是技能物件 {n,c,d,fd?,p?} 或直接傳 (name, meta, desc, lg)
// 若傳物件: _sdpBtn(sk, meta, lg)
// 若傳字串: _sdpBtn(name, meta, desc, lg)
function _sdpBtn(nameOrSk, meta, descOrLg, lg){
  let name, desc, isLg, renderType, renderHero;
  if(nameOrSk && typeof nameOrSk === 'object'){
    name = nameOrSk.n || '';
    desc = nameOrSk.fd || nameOrSk.d || '';  // 優先用完整說明
    isLg = !!descOrLg; // 第三參數是 lg
    renderType = nameOrSk._renderType || '';
    renderHero = nameOrSk._renderHero || '';
  } else {
    name = nameOrSk || '';
    desc = (typeof descOrLg === 'string') ? descOrLg : '';
    isLg = !!lg;
  }
  const cls = isLg ? 'csk-detail-btn-lg' : 'csk-detail-btn';
  const _esc = s => (s||'').replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  const _attrs = renderType
    ? ` data-renderhero="${_esc(renderHero)}" data-rendertype="${_esc(renderType)}"`
    : '';
  return `<span class="${cls}" data-skname="${_esc(name)}" data-skmeta="${_esc(meta||'')}" data-skdesc="${_esc(desc)}"${_attrs} onclick="event.stopPropagation();showSkillDetailPopup(this)">?</span>`;
}

function showSkillDetailPopup(btn){
  const name = btn.dataset.skname || '';
  const meta = btn.dataset.skmeta || '';
  let desc = btn.dataset.skdesc || '';
  // ★ v1.0.20260515.6560 — 若 dataset 有 renderhero+rendertype,popup 顯示時走升級渲染
  //   trait → _renderTraitFdWithLv,burst → _renderBurstFdWithLv,skill → _renderSkillFdWithLv
  const _renderHero = btn.dataset.renderhero || '';
  const _renderType = btn.dataset.rendertype || '';
  let _renderedHtml = '';
  if(_renderHero && _renderType){
    try{
      if(_renderType === 'trait' && typeof _renderTraitFdWithLv === 'function'){
        const _tLv = (typeof _heroTraitLevel !== 'undefined' && _heroTraitLevel[_renderHero]) || 0;
        _renderedHtml = _renderTraitFdWithLv(_renderHero, desc, _tLv);
      } else if(_renderType === 'burst' && typeof _renderBurstFdWithLv === 'function'){
        const _bLv = (typeof _heroBurstLevels !== 'undefined' && _heroBurstLevels[_renderHero]) || 0;
        _renderedHtml = _renderBurstFdWithLv(name.replace(/^極限爆發\s*/,''), desc, _bLv);
      }
    }catch(e){ _renderedHtml = ''; }
  }
  const pop = document.getElementById('skill-detail-popup');
  document.getElementById('sdp-name').textContent = name;
  document.getElementById('sdp-meta').textContent = meta;
  // 著色技能說明(若已用 trait/burst renderer 渲染,直接套 HTML;否則跑 colorizeSkillDesc)
  document.getElementById('sdp-desc').innerHTML = _renderedHtml || colorizeSkillDesc(desc);
  pop.style.display = 'block';
  // ★ 定位：先顯示再取真實尺寸，確保不超出畫面任何邊界（含縮放補償）
  requestAnimationFrame(() => {
    const _margin = 12;
    const btnRect = btn.getBoundingClientRect();
    const popRect = pop.getBoundingClientRect();
    const _popW = popRect.width || 400;
    const _popH = popRect.height || 240;
    const _vw = window.innerWidth;
    const _vh = window.innerHeight;

    // 預設：按鈕右側
    let left = btnRect.right + 8;
    let top = btnRect.top;

    // 右側放不下 → 改到按鈕左側
    if(left + _popW > _vw - _margin){
      left = btnRect.left - _popW - 8;
    }
    // 左側也放不下 → 螢幕左緣對齊
    if(left < _margin){ left = _margin; }
    // 還是放不下（極窄螢幕）→ 置中
    if(left + _popW > _vw - _margin){
      left = Math.max(_margin, (_vw - _popW) / 2);
    }

    // 垂直：對齊按鈕頂端，下方超出 → 往上移
    if(top + _popH > _vh - _margin){
      top = _vh - _popH - _margin;
    }
    // 上方超出 → 貼頂
    if(top < _margin){ top = _margin; }

    pop.style.left = left + 'px';
    pop.style.top = top + 'px';
  });
  // 點擊外部關閉
  setTimeout(()=>{
    document.addEventListener('click', _sdpOutsideClick, {once:true, capture:true});
  }, 80);
}
function _sdpOutsideClick(e){
  const pop = document.getElementById('skill-detail-popup');
  if(pop && !pop.contains(e.target)) hideSkillDetailPopup();
  else document.addEventListener('click', _sdpOutsideClick, {once:true, capture:true});
}
function hideSkillDetailPopup(){
  const pop = document.getElementById('skill-detail-popup');
  if(pop) pop.style.display = 'none';
}
// ══════════════════════════════════════════════════════════════════
//  冒險闖關 ── 核心流程控制
// ══════════════════════════════════════════════════════════════════
let _adventureMode = false;
let _adventureStage = null;

window._wbSetupAdvForBattle = function(opts){
  opts = opts || {};
  try{
    _adventureMode  = true;
    _adventureStage = opts.stage || 'worldboss';
    _advBossIntroShown = true;     // 跳過主程式 BOSS 介紹(世界戰有自己的開場)
    _advBossIntroActive = false;
    _advMiniBattleActive = false;
    if(typeof _advQuizPhase !== 'undefined') _advQuizPhase = 'idle';
    if(typeof _advQuizResolveCb !== 'undefined') _advQuizResolveCb = null;
    if(typeof _bossQuizInFlight !== 'undefined') window._bossQuizInFlight = false;
    // ★ FIX 20260518(c) #6 — 進新戰場時清玩家行動前答題的回合追蹤
    window._wbPlayerQuizDone = {};
    try{
      window._advMiniResultShowing = false;
      window._advMiniResultPending = null;
      window._advPreComposedMobs = null;
      window._advNoTreasureThisBattle = false;
      window._advBossHpMultApplied = false;
      window._advJapanEliteBuffApplied = false;
      window._advJapanYamataWeakApplied = false;
      window._advChinaChiyouWeakApplied = false;   // ★ v5.41.0 — 中國關蚩尤削弱旗標同步重置
      window._advJapanDifficultyShown = false;
      window._advMaokongLvScaleApplied = false;
      window._advRareMobLvScaleApplied = false;  // ★ v3.12.7 — 稀有怪浮動加成旗標
      // 戰鬥內憤怒爆發/封印旗標也清,避免上一場 BOSS 戰殘留誤觸發
      if(typeof _advBossActionSkip !== 'undefined') _advBossActionSkip = false;
      if(typeof _advBossRageBurstUsed !== 'undefined') _advBossRageBurstUsed = false;
      console.log('[WB-Setup v3.3.2] ✅ 清除 _advMiniResultShowing 等殘留旗標,避免 startTurn 直接 return');
    }catch(_eFlag){ console.warn('[WB-Setup v3.3.2] 清旗標失敗', _eFlag); }
    // _currentBossVariantInfo 清空(避免被當成 apricot 等變體)
    window._currentBossVariantInfo = null;
    // 設定 G.p1 / G.p2
    if(opts.p1 && Array.isArray(opts.p1)) G.p1 = opts.p1;
    if(opts.p2 && Array.isArray(opts.p2)) G.p2 = opts.p2;
    // ═══════════════════════════════════════════════════════════════
    // ★ v3.4.17 — 二重保險:日本三大妖怪 (大天狗/酒吞童子/玉藻前) 在 p1
    //   若被誤設成 BOSS 版能力 (hp>=100), 強制套回 JP_BOSS_HERO_STATS 英雄版
    // ───────────────────────────────────────────────────────────────
    // 修復:世界 BOSS 戰建構這 3 隻時, 雖然 newHero('p1') 理論上會套英雄版,
    //       但因獨立入口 (_wbSetupAdvForBattle) 跳過主程式的二重保險區段,
    //       一旦某個路徑漏套 (例如 wireToHero 反序列化用 wire 值覆蓋),
    //       這 3 隻就會帶著 BOSS 級數值進戰場。
    //   行為與主程式 13727 行的二重保險完全一致。
    // ═══════════════════════════════════════════════════════════════
    try{
      if(typeof JP_BOSS_HERO_STATS !== 'undefined' && Array.isArray(G.p1)){
        G.p1.forEach(h => {
          if(!h) return;
          const _ovr = JP_BOSS_HERO_STATS[h.name];
          // ★ v3.15.24(2026-06-17)— 修正(老師回報:世界BOSS龍王戰大天狗/酒吞/玉藻前隊伍確認顯示正確、進戰鬥變Lv1):
          //   此守門原用固定 h.hp>=100 判「誤帶 BOSS 版」,但世界 BOSS 戰傳進來的 G.p1 已套過「等級(冒險 +2%/級,
          //   Lv 上限 50)+ 素質投資(HP 自由 50 + 膠囊 20)」加成 → 英雄弱化版滿等(酒吞童子 91 基底 →
          //   (91+70)×1.98≈319)早就超過 100,合法高等妖怪被誤判成 BOSS 版、強制打回 JP_BOSS_HERO_STATS 基底 = Lv1。
          //   (主程式 confirmHeroPick 的同款守門跑在「套等級之前」的基底值故不誤觸;世界BOSS獨立入口跑在已套等級的隊伍上才誤觸。)
          //   改用「BOSS 版基礎 HP(HERO_DB,900)的一半=450」當門檻:弱化版滿等 ≤319 遠低於 450 不誤傷;真誤帶 BOSS 版(900)才還原。
          const _bossBaseHpJp = (typeof HERO_DB !== 'undefined' && HERO_DB[h.name] && HERO_DB[h.name].hp) ? HERO_DB[h.name].hp : 900;
          if(_ovr && h.hp >= _bossBaseHpJp * 0.5){
            console.warn('[WB G.p1 二重保險] '+h.name+' 偵測到 BOSS 版 hp='+h.hp+'(門檻'+(_bossBaseHpJp*0.5)+'), atk='+h.atk+', sp='+h.sp+', spd='+h.spd+' → 強制套英雄版 hp='+_ovr.hp+', atk='+_ovr.atk+', sp='+_ovr.sp+', spd='+_ovr.spd);
            h.hp  = _ovr.hp;
            h.atk = _ovr.atk;
            h.sp  = _ovr.sp;
            h.spd = _ovr.spd;
            // curHp 若已是滿血則一起改, 否則保留 (例如雲端殘血同步)
            if(typeof h.curHp !== 'number' || h.curHp <= 0 || h.curHp > _ovr.hp){
              h.curHp = _ovr.hp;
            }
          }
        });
      }
    }catch(e){ console.error('[WB G.p1 二重保險] 失敗', e); }
    // ★ v3.15.0 — 埃及雙王招募版若被帶進世界 BOSS 戰,同款二重保險套回弱化版
    try{
      if(typeof EGYPT_BOSS_HERO_STATS !== 'undefined' && Array.isArray(G.p1)){
        G.p1.forEach(h => {
          if(!h) return;
          const _egOvr = EGYPT_BOSS_HERO_STATS[h.name];
          // ★ v3.15.24 — 同上修正:埃及雙王招募版(法老王/埃及豔后)滿等弱化版 HP(~287)亦會超過 100,
          //   改用 BOSS 版基礎 HP(HERO_DB,11500/10500)的一半當門檻,避免合法高等招募版被打回基底變 Lv1。
          const _egBossBaseHp = (typeof HERO_DB !== 'undefined' && HERO_DB[h.name] && HERO_DB[h.name].hp) ? HERO_DB[h.name].hp : 10000;
          if(_egOvr && h.hp >= _egBossBaseHp * 0.5){
            console.warn('[WB G.p1 埃及保險] '+h.name+' 偵測到 BOSS 版 hp='+h.hp+'(門檻'+(_egBossBaseHp*0.5)+') → 強制套英雄版 hp='+_egOvr.hp);
            h.hp = _egOvr.hp; h.atk = _egOvr.atk; h.sp = _egOvr.sp; h.spd = _egOvr.spd;
            if(typeof h.curHp !== 'number' || h.curHp <= 0 || h.curHp > _egOvr.hp){ h.curHp = _egOvr.hp; }
          }
        });
      }
    }catch(e){ console.error('[WB G.p1 埃及保險] 失敗', e); }
    // ★ v5.46.0 — 中國三妖王招募版若被帶進世界 BOSS 戰,同款二重保險(門檻=BOSS 版基礎 HP×0.5·v3.15.24 口徑,
    //   滿等弱化版 HP 不會誤觸)
    try{
      if(typeof CHINA_BOSS_HERO_STATS !== 'undefined' && Array.isArray(G.p1)){
        G.p1.forEach(h => {
          if(!h) return;
          const _cnOvr = CHINA_BOSS_HERO_STATS[h.name];
          const _cnBossBaseHp = (typeof HERO_DB !== 'undefined' && HERO_DB[h.name] && HERO_DB[h.name].hp) ? HERO_DB[h.name].hp : 10000;
          if(_cnOvr && h.hp >= _cnBossBaseHp * 0.5){
            console.warn('[WB G.p1 中國保險] '+h.name+' 偵測到 BOSS 版 hp='+h.hp+'(門檻'+(_cnBossBaseHp*0.5)+') → 強制套英雄版 hp='+_cnOvr.hp);
            h.hp = _cnOvr.hp; h.atk = _cnOvr.atk; h.sp = _cnOvr.sp; h.spd = _cnOvr.spd;
            if(typeof h.curHp !== 'number' || h.curHp <= 0 || h.curHp > _cnOvr.hp){ h.curHp = _cnOvr.hp; }
          }
        });
      }
    }catch(e){ console.error('[WB G.p1 中國保險] 失敗', e); }
    G.round = 1;
    G.turn = 0;
    G.currentActorIdx = 0;
    G.turnOrder = [];
    // ★ G.energy 是主程式的物件結構 {p1:N, p2:N},不是純數字
    //   記憶傳承說「從 0 開始」 — 對應 G.energy.p1 = 0
    G.energy = { p1: 0, p2: 0 };
    G.energyMax = 10;
    G._resultShown = false;
    // ════════════════════════════════════════════════════════════════
    // ★ v3.11.3(2026-05-27) — 修補「龍王戰超過 11 回合不結束」
    //   老師回報:玩家第二場以後的世界 BOSS 戰,回合一直跑下去都不會崩毀,
    //             可以無限打到 BOSS HP 歸 0 或全隊倒下。
    //   根因:world-boss.js line 2155 的 _wbAdvBossTurn 內,崩毀觸發條件是
    //             if((G.round||1) >= 11 && !window._wbCollapseTriggered){
    //               window._wbCollapseTriggered = true;
    //               // ...崩毀全滅邏輯...
    //             }
    //         這個 window._wbCollapseTriggered 全域旗標**只 set 沒 reset**,
    //         第一場世界 BOSS 戰跑到 round 11 觸發後永遠是 true,
    //         之後再開的世界 BOSS 戰會被 !window._wbCollapseTriggered 條件擋下,
    //         11 回合的最終崩毀永遠不觸發 → 玩家可無限打。
    //   修法:每場世界 BOSS 戰開始時,在 _wbSetupAdvForBattle 入口主動 reset。
    //         (G._wbBurst5Used / G._wbBurst10Used 用 G.X 已隨 G 自動重建,不需處理)
    //   檢查方法:console 跑 `window._wbCollapseTriggered`,
    //             進場 setup 完應為 false,跑到 R11 BOSS turn 才變 true。
    // ════════════════════════════════════════════════════════════════
    try{ window._wbCollapseTriggered = false; }catch(_){}
    // ★ v3.11.6(2026-05-27) — 同時 reset 新版「DONE」旗標,
    //   讓多重保險機制能在新一場戰鬥重新走 R11 崩毀
    try{ window._wbCollapseDone = false; }catch(_){}
    try{ window._wbAdvBattleEnded = false; }catch(_){}
    // ★ v3.12.14(2026-05-31)— 🚨 緊急修補:_wbResultExecuting 重置斷層
    //   血淚案例(老師 2026-05-31 凌晨 1:17 回報):玩家世界 BOSS 戰第一次滅團正常結束,
    //                                              第二次滅團卡死。
    //   console 證據:[WB-Result v3.12.12] ⚠ 本場已結算過或正在結算,跳過重複呼叫 (win=false)
    //                 → 結算頁出不來 → 玩家全滅但無法結束戰鬥
    //   根因:v3.12.12 引入 _wbResultExecuting 防重入(原子操作)
    //         v3.12.15 發現「本場結束時重置」會讓 600ms fallback 重複跑 → 移除重置
    //         註解說「重置點移到戰鬥開始流程,已在其他地方有對齊處理」
    //         但實作根本沒做!grep 全專案找不到任何 `_wbResultExecuting = false` 賦值
    //         → _wbResultExecuting=true 永久卡住 → 下場戰鬥結算永遠被擋
    //   修法:在 _wbSetupAdvForBattle(每場世界 BOSS 戰開始建構函式)入口
    //         主動 reset _wbResultExecuting,跟既有 _wbAdvBattleEnded reset 對齊
    //   ★ 注意:這是 v3.12.15 註解承諾但漏寫的補丁,屬「修補修補的修補」
    try{ window._wbResultExecuting = false; }catch(_){}
    // ★ v3.11.8(2026-05-27) — reset 聯手爆發觸發次數
    try{ window._wbTeamBurstFiredCount = 0; }catch(_){}
    // ★ v3.11.7(2026-05-28) — reset BOSS 連續行動 2 次的計數(避免沿用上場殘留)
    try{
      if(G && Array.isArray(G.p2)){
        G.p2.forEach(b => {
          if(b){
            delete b._wbActionRound;
            delete b._wbActionCount;
          }
        });
      }
    }catch(_eRABC){ console.warn('[WB v3.11.7] setup 入口 reset BOSS 行動計數例外', _eRABC); }
    // ★ 同步 window.G(主程式有些路徑會重新賦值 G,確保外部能讀最新)
    try{ window.G = G; }catch(_){}
    // ★ v3.4.5 — 老師 2026/5/20 回報:累計冒險次數沒增加
    //   根因:主程式 startAdventureGame 內有呼叫 _fbIncrementAdventureCount,
    //         但世界 BOSS 戰走 _wbSetupAdvForBattle(獨立入口)沒呼叫
    //   修法:在世界 BOSS 戰場 setup 成功後也 +1(每位玩家各算一次冒險,4 人協力 = +4)
    try{
      if(typeof window._fbIncrementAdventureCount === 'function'){
        window._fbIncrementAdventureCount();
      }
    }catch(_){}
    // ★ v3.5.66 — 世界 BOSS 戰參戰獎章檢查
    try{
      if(typeof _checkMedalWbJoin === 'function') _checkMedalWbJoin();
    }catch(_){}
    // ★ v3.7.6 — 保險呼叫 _wbInstallRealtimeDmgBar 確保「本場總傷」UI 元素一定建立
    //   老師 2026/5/25 回報 BUG:「2P~4P 根本沒顯示本場總傷」(不是顯示 0,是 UI 元素不存在)
    //   根因推測:world-boss-ui.html 的 client setup 流程(line 8744 呼叫 _wbInstallRealtimeDmgBar)
    //             在某些情境下沒跑到,例如 client 進場路徑分歧、advStartBattle 失敗、或 UI 載入時序問題
    //   修補:_wbSetupAdvForBattle host 與 client 都會跑(line 8677),在這裡主動補建一道保險
    //         + setTimeout 300ms 二次補建(避免 #gc 還沒 mount 時建到 body 而走錯位)
    try{
      const _ensureDmgBar = function(){
        try{
          if(document.getElementById('wb-solo-cur-dmg-bar')) return; // 已存在,跳過
          if(typeof window._wbInstallRealtimeDmgBar === 'function'){
            window._wbInstallRealtimeDmgBar();
            console.log('[v3.7.6] _wbSetupAdvForBattle 保險呼叫 _wbInstallRealtimeDmgBar 成功');
          } else {
            console.warn('[v3.7.6] _wbInstallRealtimeDmgBar 不存在,無法補建本場總傷 UI');
          }
        }catch(_eIb){ console.warn('[v3.7.6] _ensureDmgBar 例外', _eIb); }
      };
      _ensureDmgBar();
      // 二次保險:300ms 後再檢查一次(處理 #gc 還沒 mount 完的時序問題)
      setTimeout(_ensureDmgBar, 300);
      // 三次保險:1.5 秒後最終確認
      setTimeout(_ensureDmgBar, 1500);
    }catch(_eEnsure){ console.warn('[v3.7.6 保險 dmg bar] 例外', _eEnsure); }
    console.log('[WB] _wbSetupAdvForBattle 完成,stage=' + _adventureStage
      + ', p1=' + (G.p1 ? G.p1.length : 0)
      + ', p2=' + (G.p2 ? G.p2.length : 0));
    return true;
  }catch(e){
    console.error('[WB] _wbSetupAdvForBattle 失敗', e);
    return false;
  }
};

