(function _wbExposeMainFnsToWindow(){
  function _tryAttach(name, fn){
    try{
      if(typeof fn === 'function' && !window[name]){
        window[name] = fn;
      }
    }catch(_){}
  }
  // 主程式戰鬥流程函式 — world-boss.js 的 BOSS AI 會呼叫
  if(typeof endAction === 'function') _tryAttach('endAction', endAction);
  if(typeof log === 'function') _tryAttach('log', log);
  if(typeof renderCard === 'function') _tryAttach('renderCard', renderCard);
  if(typeof doDmg === 'function') _tryAttach('doDmg', doDmg);
  if(typeof startTurn === 'function') _tryAttach('startTurn', startTurn);
  if(typeof advStartBattle === 'function') _tryAttach('advStartBattle', advStartBattle);
  if(typeof newHero === 'function') _tryAttach('newHero', newHero);
  if(typeof aiAct === 'function') _tryAttach('aiAct', aiAct);
  if(typeof checkWin === 'function') _tryAttach('checkWin', checkWin);
  if(typeof bannerFX === 'function') _tryAttach('bannerFX', bannerFX);
})();

window._wbHostSyncG = function(reason){
  try{
    // 只在世界 BOSS 戰 + 連線房主模式才推送
    if(typeof _adventureStage === 'undefined' || _adventureStage !== 'worldboss') return;
    if(!window._wbConnectedHostMode) return;
    if(!window._wbNet || typeof window._wbNet.hostPushBattleState !== 'function') return;
    if(!window._wbWireUtils || typeof window._wbWireUtils.GToWire !== 'function') return;
    const _G = (typeof G !== 'undefined') ? G : window.G;
    if(!_G) return;
    // 序列化整個 G(p1/p2/turn/energy/inv/battleStats/_activeSidePos 等)
    const wireG = window._wbWireUtils.GToWire(_G);
    // ★ 多塞一個 _activeSidePos,client 端 applyWireToG 後優先用此重建 G.activeChar
    //   (應對主程式 startTurn 動態挑下一位、不維護 currentActorIdx 的情況)
    try{
      if(_G.activeChar && _G.activeChar.side && typeof _G.activeChar.pos === 'number'){
        wireG._activeSidePos = { side: _G.activeChar.side, pos: _G.activeChar.pos };
      }
    }catch(_){}
    window._wbNet.hostPushBattleState({
      fullWireG: wireG,
      _syncReason: reason || 'host-sync',
      // 連線層內部會自動取 _wbFxQueueFlush() 把特效佇列附加
    });
    try{
      if(window._wbNet && typeof window._wbNet.getContributions === 'function'){
        const ctrb = window._wbNet.getContributions();
        if(ctrb){
          // 把 contributions 寫進獨立欄位(在 hostPushBattleState 後 fire and forget)
          // 注意:不能在 hostPushBattleState 內塞 fullWireG,因為那個會被 spread 到 battle 頂層
          // 改用 setTimeout 0 讓 hostPushBattleState 先完成,再 patch contributions 進去
          setTimeout(function(){
            try{
              if(window._wbNetUpdateContribs){
                window._wbNetUpdateContribs(ctrb);
              }
            }catch(_){}
          }, 30);
        }
      }
    }catch(_){}
    console.log('[_wbHostSyncG] ✅ pushed reason=' + (reason || 'host-sync')
      + ', round=' + (_G.round||0)
      + ', activeChar=' + (_G.activeChar && _G.activeChar.name));
  }catch(e){
    console.warn('[_wbHostSyncG] 例外', e);
  }
};

window._wbHostSyncGDebounced = (function(){
  let _timer = null;
  let _lastReason = null;
  return function(reason){
    try{
      if(typeof _adventureStage === 'undefined' || _adventureStage !== 'worldboss') return;
      if(!window._wbConnectedHostMode) return;
      _lastReason = reason || 'debounced';
      if(_timer) return; // 已有排程,直接合併
      _timer = setTimeout(function(){
        _timer = null;
        try{ window._wbHostSyncG(_lastReason); }catch(_){}
      }, 200);
    }catch(_){}
  };
})();


