  // ctrlBar.innerHTML =
  //   '<button onclick="try{playSfx(\'sfx-gentle\',0.4);ctrlFullscreen();}catch(_){}" style="' + _cnCtrlBtn + '" title="全螢幕">⛶</button>' +
  //   '<button onclick="try{playSfx(\'sfx-gentle\',0.4);ctrlOpenVolumePanel(\'bgm\');}catch(_){}" style="' + _cnCtrlBtn + '" title="音樂音量">🎵</button>' +
  //   '<button onclick="try{ctrlOpenVolumePanel(\'sfx\');}catch(_){}" style="' + _cnCtrlBtn + '" title="音效音量">🔊</button>' +
  //   '<button onclick="try{playSfx(\'sfx-cancel\',0.5);if(typeof window._chinaMapClose===\'function\')window._chinaMapClose();}catch(_){}" style="' + _cnCtrlBtn + 'border-color:rgba(220,80,80,0.5);color:#ff9999;" title="關閉地圖回選關頁">✕</button>';
  // ov.appendChild(ctrlBar);

  // ── 主區:橫式滿版畫卷(★ v5.54.0 老師需求:地圖改橫式延展到畫面最左右) ──
  //   舊直式置中版 padding:'8px 0 14px' → 改 0,地圖左右貼齊視窗邊緣
  const mainArea = document.createElement('div');
  mainArea.style.cssText = 'position:relative;flex:1;width:100%;overflow:hidden;min-height:0;display:flex;align-items:center;justify-content:center;padding:0;';
  ov.appendChild(mainArea);

  const mapInner = document.createElement('div');
  mapInner.id = 'china-map-inner';
  // ★ v5.54.0 — 橫式滿版:寬 100% 貼齊畫面最左右,高撐滿主區;素材 九州輿圖.webp=1536×864(16:9 橫卷)
  //   去左右邊框與圓角=橫幅畫卷感;上下細邊框保留。舊直式樣式保留為註解:
  //   'position:relative;height:96%;width:min(94vw,70vh);border-radius:18px;overflow:hidden;' +
  //   'border:4px solid rgba(120,70,25,0.85);...'
  mapInner.style.cssText =
    'position:relative;height:100%;width:100%;border-radius:0;overflow:hidden;' +
    'background:linear-gradient(160deg,#e8d5b0 0%,#d9c294 50%,#c8ab78 100%);' +
    'border-top:3px solid rgba(120,70,25,0.85);border-bottom:3px solid rgba(120,70,25,0.85);border-left:none;border-right:none;' +
    'box-shadow:0 0 50px rgba(255,190,90,0.25), inset 0 0 80px rgba(120,70,20,0.35);';
  // 地圖插畫(素材未上傳前保留羊皮紙底色;onerror 隱藏 img)
  const mapImg = document.createElement('img');
  mapImg.src = _CN_BG.map;
  mapImg.alt = '';
  mapImg.style.cssText = 'position:absolute;inset:0;width:100%;height:100%;object-fit:cover;';
  mapImg.onerror = function(){ this.style.display = 'none'; };
  mapInner.appendChild(mapImg);
  // ════════════════════════════════════════════════════════════
  // ★ v5.83.0（2026-08-19·老師需求）— 九州輿圖「動態版」影片覆蓋層
  //   作法完全比照既有兩處範式：召喚星空 #summon-bg-video（v3.16.54）與
  //   鬥技場 #arena-bg-video（v3.16.59）——靜態圖 mapImg 一行未動保留在下層，影片疊上去，
  //   onloadeddata 才淡入、onerror/抓不到自動隱藏 → 自動露出原本的 九州輿圖.webp。
  //   ⚠ 刻意不設 z-index（=auto）並插在 mapImg 之後、水墨飄霧層之前 →
  //     繪製順序 靜態圖 → 影片 → 飄霧層 → 採集發光點（z9） → 圖釘（z10），
  //     所有互動元素一律畫在影片之上，再加 pointer-events:none 保證影片不吃任何點擊
  //     ⇒ 圖釘/採集點/三時空 era bar/神農鼎入口 全數零影響。
  //   ⚠ muted 固定為 true（影片自帶 AAC 音軌）→ 不與 bgm-china-map 打架，iOS 才允許自動播放。
  //   素材：九州輿圖動態版.mp4（1280×720·10s·H.264 faststart），與靜態圖同為 16:9
  //   ⇒ object-fit:cover 裁切結果一致，圖釘座標不必重調。
  //   ?v=_CHINA_MAP_VID_VER 素材版本與遊戲版號脫鉤（_CHINA_ENTRY_VID_VER 前例·換片才 bump）。
  // ════════════════════════════════════════════════════════════
  window._CHINA_MAP_VID_VER = window._CHINA_MAP_VID_VER || '1';
  try{
    const mapVid = document.createElement('video');
    mapVid.id = 'china-map-bg-video';
    mapVid.setAttribute('playsinline', '');
    mapVid.setAttribute('webkit-playsinline', '');
    mapVid.setAttribute('disablepictureinpicture', '');
    mapVid.autoplay = true;
    mapVid.loop     = true;
    mapVid.controls = false;
    mapVid.preload  = 'auto';
    // JS 建立的 video 必須同時設 property，只下 attribute 在 iOS 可能失效而被擋下自動播放
    mapVid.defaultMuted = true;
    mapVid.muted        = true;
    mapVid.style.cssText =
      'position:absolute;inset:0;width:100%;height:100%;object-fit:cover;' +
      'pointer-events:none;opacity:0;transition:opacity 0.6s ease;background:transparent;';
    mapVid.onloadeddata = function(){ try{ this.style.opacity = '1'; }catch(_){} };
    mapVid.onerror      = function(){ try{ this.style.display = 'none'; }catch(_){} };
    mapVid.src = _CN_BG_BASE + encodeURIComponent('九州輿圖動態版.mp4') + '?v=' + window._CHINA_MAP_VID_VER;
    mapInner.appendChild(mapVid);
    // 自動播放保險：部分 iPad WKWebView 只認 play() 呼叫，被擋下一律靜默（靜態圖照常呈現）
    try{ const _pCnV = mapVid.play(); if(_pCnV && _pCnV.catch) _pCnV.catch(function(){}); }catch(_){}
  }catch(_eCnMapVid){ console.warn('[九州輿圖 動態版]', _eCnMapVid); }
  // 水墨飄霧層
  const ink = document.createElement('div');
  ink.style.cssText = 'position:absolute;inset:0;pointer-events:none;' +
    'background:radial-gradient(ellipse at 20% 15%,rgba(60,40,20,0.28),transparent 55%),radial-gradient(ellipse at 85% 80%,rgba(60,40,20,0.25),transparent 50%);' +
    'animation:cnInkDrift 14s ease-in-out infinite;';
  mapInner.appendChild(ink);
  mainArea.appendChild(mapInner);

  // ── 圖釘資料 ──
  //   type:'route'(選路線)/'intro'(介紹);visible 條件依進度(管理員全開便於測試)
  // ★ v5.54.0 — 座標依橫式滿版素材(1536×864)視覺內容重排:
