  r16:{ pill:'p14', mats:{ m17:2, m19:1 }, src:'mob'   },   // 金鐘罩護體丹 = 玄冰髓×2 + 千年人參×1
  r17:{ pill:'p16', mats:{ m16:2, m20:1 }, src:'mob'   },   // 五蘊封魔散 = 鐵皮石斛×2 + 太歲肉靈芝×1
  r18:{ pill:'p18', mats:{ m21:1, m22:1, m19:2 }, src:'mob' }, // 太上九轉護命丹 = 女媧五色石+崑崙不死泉+千年人參×2
