//      本次放寬的只有「在哪裡用得掉」,不是「在哪裡拿得到」。玩家仍必須回中國關補貨。
window._ALCH_BOX_MEDALS = ['china_fengshen_clear','china_xiyou_clear','china_sanguo_clear','china_caocao_clear','china_chiyou_clear'];
window._alchBoxUnlocked = function(){
  try{
    if(typeof _medals === 'undefined' || !_medals) return false;
    return window._ALCH_BOX_MEDALS.every(function(_id){ return !!_medals[_id]; });
  }catch(_){ return false; }
};
// ★ 丹藥可用場合(單一守門·全檔 9 個消費點共用,改這一支即全面生效)
