window._getEquipPoolForStage = function(){
  const stage = (typeof _adventureStage !== 'undefined') ? _adventureStage : null;
  const inAdv = (typeof _adventureMode !== 'undefined') && _adventureMode;
  if(inAdv && stage === 'japan'){
    // 日本關：只抽日本寵物
    return CARRY_PET_DB.filter(e => e && e.n && e._stage === 'japan');
  }
  // ★ v3.15.10 — 埃及關：只抽埃及寵物
  if(inAdv && stage === 'egypt'){
    return CARRY_PET_DB.filter(e => e && e.n && e._stage === 'egypt');
  }
  // ★ v5.43.0 — 中國關:只抽中國神獸寵物
  if(inAdv && stage === 'china'){
    return CARRY_PET_DB.filter(e => e && e.n && e._stage === 'china');
  }
  // 其他情況(鬥技場/貓空關/未知關)：只抽台灣原本寵物(排除日本+埃及+中國)
  return CARRY_PET_DB.filter(e => e && e.n && e._stage !== 'japan' && e._stage !== 'egypt' && e._stage !== 'china');
};

// ★ 動物學家專用池：永遠只抽台灣寵物
// ★ v5.47.0 — 補排除中國神獸(2026-08-16 稽核發現:v5.43.0 新增 _stage:'china' 後本池漏排 →
//   動物學家技能在任何關卡都可能抽到麒麟/鳳凰等中國寵物效果,中國關未公開前即洩漏)
window._getTaiwanEquipPool = function(){
  return CARRY_PET_DB.filter(e => e && e.n && e._stage !== 'japan' && e._stage !== 'egypt' && e._stage !== 'china');
};



