// ── 日本關 helper 函式：三神器持久化、獎勵加成、解鎖檢查 ──
// ★ v3.15.97(2026-06-23) — 日本三神器 key 集合(草薙劍 tengu / 八尺瓊勾玉 shutendoji / 八咫鏡 tamamo)。
//   三神器是「解鎖隱藏關卡(八岐大蛇)的任務物品」,不是台灣至寶。所有「清點 taiwanTreasureData
//   當至寶 / 從至寶帳本反推救援」的地方都要排除這三個 key,避免任務物品被誤算成至寶佔數量。
//   掛 window 供 _applySafeData / _fbRebuildAccountFromLedgers / _extractDataSummaryForCompare 共用。
window._JAPAN_TREASURE_KEYS = { tengu:1, shutendoji:1, tamamo:1 };
window._isJapanTreasureKey = function(k){ try{ return !!(window._JAPAN_TREASURE_KEYS && window._JAPAN_TREASURE_KEYS[k]); }catch(_){ return false; } };
function _japanGetTreasures(){
  try{
    const raw = localStorage.getItem('adv_japan_treasures');
    const obj = raw ? JSON.parse(raw) : {};
    return { tengu:!!obj.tengu, shutendoji:!!obj.shutendoji, tamamo:!!obj.tamamo };
  }catch(e){ return { tengu:false, shutendoji:false, tamamo:false }; }
}
function _japanSetTreasure(key){
  try{
    const cur = _japanGetTreasures();
    cur[key] = true;
    localStorage.setItem('adv_japan_treasures', JSON.stringify(cur));
    // ★ v1.0.20260422.0109 — 取得神器後即時同步到 Firebase,避免換裝置不同步
    //   (三神器擁有由 japanProgress.treasures 雲端持久;主存檔/三槽合併/載入皆已涵蓋)
    try{ if(typeof gameCloudSave === 'function') gameCloudSave().catch(()=>{}); }catch(_){}
    // ★ v3.15.97(2026-06-23) — 移除「寫至寶解鎖歷史」呼叫:日本三神器是「解鎖隱藏關卡的
    //   任務物品」,不是台灣至寶。原本呼叫 _advSaveTreasureUnlockHistory(key,'japan_clear')
    //   會同時污染 ① _treasureUnlockHistory 帳本 ② taiwanTreasureData.<key>(草薙劍/勾玉/八咫鏡),
    //   導致帳號救援(_fbRebuildAccountFromLedgers)把三神器當至寶補回、誤佔至寶 3 個數量。
    //   三神器擁有/同步全由 adv_japan_treasures + japanProgress.treasures 維護,不需混進至寶系統。
  }catch(_){}
}
function _japanTreasureCount(){
  const t = _japanGetTreasures();
  return (t.tengu?1:0) + (t.shutendoji?1:0) + (t.tamamo?1:0);
}

// 點「日本探險」按鈕時檢查解鎖條件：貓空A評價+完整通關+英雄lv≥10+額外解鎖英雄
function _japanCheckUnlock(){
  let maokongSFullClear = false;
  try{
    // 主要旗標：正規 S 完整通關才寫入
    if(localStorage.getItem('adv_maokong_s_full_clear') === '1') maokongSFullClear = true;
    // 老玩家回溯：手動確認旗標 (給老玩家的補救機制)
    if(localStorage.getItem('adv_maokong_legacy_clear_confirmed') === '1') maokongSFullClear = true;
    // 另一道備援：若從 gameCloudSave 發現有歷史 best_rank=S 紀錄也通過
    if(localStorage.getItem('adv_maokong_best_rank') === 'S') maokongSFullClear = true;
  }catch(_){}
  // 統計 Lv≥10 的英雄數量
  let lv10HeroCount = 0;
  try{
    const _counted = new Set();
    // 來源 1：全域 _heroLevels (遊戲運行時即時)
    if(typeof _heroLevels !== 'undefined' && _heroLevels && typeof _heroLevels === 'object'){
      for(const k in _heroLevels){
        if((_heroLevels[k]||1) >= 10 && !_counted.has(k)){
          _counted.add(k);
          lv10HeroCount++;
        }
      }
    }
    // 來源 2：備用 — 用 getHeroLevel() 搭配所有已解鎖的英雄（萬一 _heroLevels 沒載入）
    if(lv10HeroCount === 0 && typeof getHeroLevel === 'function' && typeof HERO_DB !== 'undefined'){
      Object.keys(HERO_DB).forEach(n => {
        try{
          if(getHeroLevel(n) >= 10 && !_counted.has(n)){
            _counted.add(n);
            lv10HeroCount++;
          }
        }catch(_){}
      });
    }
  }catch(e){ console.warn('[日本關] Lv10統計失敗:', e); }
  const hasEnoughLv10 = lv10HeroCount >= 4;
  // ★ v1.0.20260421.3012 — 檢核：擁有初始 8 隻以外的任意英雄（通關 BOSS 才會解鎖）
  let hasExtraHero = false;
  let extraHeroCount = 0;
  try{
    const INIT_8 = (typeof ADV_HERO_POOL !== 'undefined' && ADV_HERO_POOL.maokong) ? ADV_HERO_POOL.maokong : [];
    const unlocked = (typeof advGetUnlockedHeroes === 'function') ? advGetUnlockedHeroes() : [];
    const extraList = unlocked.filter(n => !INIT_8.includes(n));
    extraHeroCount = extraList.length;
    hasExtraHero = extraHeroCount > 0;
  }catch(e){ console.warn('[日本關] 額外英雄檢核失敗:', e); }
  return {
    maokongSFullClear,
    lv10HeroCount,
    hasEnoughLv10,
    hasExtraHero,
    extraHeroCount,
    canEnter: maokongSFullClear && hasEnoughLv10 && hasExtraHero
  };
}

// 日本關獎勵 +20% 的加成倍率（供金幣/EXP 系統讀取）
window._japanRewardMult = 1.20;

window._advCalcRewardMult = function(subject){
  const _isJapan = (typeof _adventureStage !== 'undefined' && _adventureStage === 'japan');
  // 課堂複習判定:跟視覺分群 _advGroupSubjects / _advGetSubjectBtnStyle 同一條規則
  // ★ v3.30.0 — GM 開關 _reviewBaseActive 套閘:關閉時基礎 +25% 不發、下游 isReview UI 一併消失
  const _reviewRe = /^(低|中|高|國[一二三]|[一二三四五六七八九十]+)[上下]/;
  const _isReviewSubject = (typeof window._reviewBaseActive !== 'function' || window._reviewBaseActive())
    && !!(subject && typeof subject === 'string' && _reviewRe.test(subject));
  // 期間加乘:管理員從教師端「加強複習提醒區間」整合進 KING_DOUBLED_REVIEW_TOPICS
  // ★ v3.30.0 — GM 開關 _doubledReviewActive 套閘:關閉時不再發「再+25%」
  let _isDoubledSubject = false;
  try{
    if(subject && Array.isArray(KING_DOUBLED_REVIEW_TOPICS)
       && (typeof window._doubledReviewActive !== 'function' || window._doubledReviewActive())){
      _isDoubledSubject = KING_DOUBLED_REVIEW_TOPICS.indexOf(subject) >= 0;
    }
  }catch(_){}
  // ★ v3.11.6(2026-05-27)鐵律 1.98 — 兩條 +25% 加成「一天各領一次」
  //   先把旗標跨日重置(_kingCheckReset 內含 _todayDateStr 比對),再決定是否套用
  try{ if(typeof _kingCheckReset === 'function') _kingCheckReset(); }catch(_){}
  const _kc = (typeof window._kingChallenge !== 'undefined') ? window._kingChallenge : null;
  const _reviewAlreadyClaimed  = !!(_kc && _kc._reviewBonusClaimedToday);
  const _doubledAlreadyClaimed = !!(_kc && _kc._doubledBonusClaimedToday);
  // 實際是否套用 +25%(科目符合 && 今天還沒領過)
  const _isReview  = _isReviewSubject  && !_reviewAlreadyClaimed;
  const _isDoubled = _isDoubledSubject && !_doubledAlreadyClaimed;
  let _mult = 1.0;
  if(_isJapan)   _mult += 0.20;
  if(_isReview)  _mult += 0.25;
  if(_isDoubled) _mult += 0.25;
  // isReview / isDoubled 回傳「實際是否套用」,讓所有下游 UI(+25% badge / 黃色閃光 / 結算列)
  // 在今天已領過後自動消失。另外多帶兩個 raw 旗標供前端決定是否顯示「✓ 今日已領」灰底提示。
  return {
    mult: _mult,
    isReview: _isReview,
    isDoubled: _isDoubled,
    isJapan: _isJapan,
    _isReviewSubject: _isReviewSubject,
    _isDoubledSubject: _isDoubledSubject,
    _reviewAlreadyClaimed: _reviewAlreadyClaimed,
    _doubledAlreadyClaimed: _doubledAlreadyClaimed
  };
};

// ★ v3.11.6(2026-05-27)鐵律 1.98 — 在「實際發放獎勵」的時刻呼叫本函式,提交當日加成已領旗標
//   傳入的 info 必須是同一場戰鬥用 _advCalcRewardMult 算出的物件
//   ※ 只在 isReview / isDoubled 為 true(即「真的觸發加成」)時設旗標
//   ※ 重複呼叫無副作用(旗標是布林,等冪)
//   ※ 設完後雲端存檔 + 立即重繪冒險關卡頁面的「📖 課堂複習獎勵增加中!」flash / 科目分群標題
window._advCommitReviewBonusFlags = function(info){
  try{
    if(!info || typeof info !== 'object') return;
    const _kc = window._kingChallenge;
    if(!_kc) return;
    // 跨日守門
    try{ if(typeof _kingCheckReset === 'function') _kingCheckReset(); }catch(_){}
    let _changed = false;
    if(info.isReview && !_kc._reviewBonusClaimedToday){
      _kc._reviewBonusClaimedToday = true;
      _changed = true;
      console.log('[複習加成 v3.11.6] 📖 課堂複習加成 +25% 今日已領取,後續關卡不再加成');
    }
    if(info.isDoubled && !_kc._doubledBonusClaimedToday){
      _kc._doubledBonusClaimedToday = true;
      _changed = true;
      console.log('[複習加成 v3.11.6] ⭐ 加強複習主題加成 +25% 今日已領取,後續關卡不再加成');
    }
    if(_changed){
      // 雲端同步
      try{ if(typeof gameCloudSave === 'function') gameCloudSave(); }catch(_){}
      // 即時刷新冒險關卡頁面的兩個 UI 元件
      try{ if(typeof window._advRefreshReviewBonusUI === 'function') window._advRefreshReviewBonusUI(); }catch(_){}
    }
  }catch(_e){ console.warn('[_advCommitReviewBonusFlags] 失敗:', _e); }
};

// ★ v3.11.6 — 即時刷新「課堂複習獎勵增加中!」flash 的工具函式
//   今天領過後呼叫一次,UI 黃色 +25% 標記就會消失;跨日後重新呼叫又會恢復
//   ※ 科目選單標題(_advGroupSubjects)是即時呼叫的,玩家下次進入科目選單時自動更新,不需要主動重繪
window._advRefreshReviewBonusUI = function(){
  try{
    const _kc = window._kingChallenge;
    if(!_kc) return;
    try{ if(typeof _kingCheckReset === 'function') _kingCheckReset(); }catch(_){}
    // 木柵防衛戰按鈕底下的「📖 課堂複習獎勵增加中!」黃色 flash
    //   若今天 review 已領,改成「✓ 今日複習加成已領」灰底,不再閃爍
    try{
      const _flashEl = document.getElementById('adv-stage-flash-review');
      if(_flashEl){
        // ★ v3.30.0 — GM 關閉基礎課堂複習加成時,flash 整顆隱藏(重新開啟後自動還原)
        if(typeof window._reviewBaseActive === 'function' && !window._reviewBaseActive()){
          _flashEl.style.display = 'none';
        } else if(_kc._reviewBonusClaimedToday){
          _flashEl.style.display = '';
          _flashEl.textContent = '✓ 今日課堂複習加成已領取';
          _flashEl.style.cssText = 'color:#999;background:rgba(80,80,80,0.3);padding:2px 8px;border-radius:8px;font-size:0.85em;animation:none;text-shadow:none;display:inline-block;';
        } else {
          _flashEl.textContent = '📖 課堂複習獎勵增加中!';
          _flashEl.style.cssText = ''; // 還原預設 (從 CSS class 取)
        }
      }
    }catch(_){}
  }catch(_e){ console.warn('[_advRefreshReviewBonusUI] 失敗:', _e); }
};

