// ★ v5.47.0 — 中國關「進入繪卷」過場動畫(老師需求 2026-08-16·素材=進入繪卷.mp4 1280×720 10s h264)
//   時機:_chinaTrySelect 通過閘門後 → 全螢幕播放 → 結束/跳過/失敗 才進 selectAdvStage('china')。
//   iOS 範式=_playBurstVideo v4.39.0 同款:先靜音起播(muted autoplay 在 iPad 必能播)→ playing 後
//   走 _bvApplyBgmVol 解靜音(影片音量隨音樂音量·音樂靜音=影片靜音·v5.37.0 單一套用點)。
//   安全網(絕不卡死):onerror / play().catch / 13s 硬兜底 / 跳過鈕 / 點畫面任意處 → 全走同一
//   _done latch,next() 保證恰好觸發一次;影片缺檔(素材未上傳)= onerror 立即靜默直進,零阻塞。
//   快取:?v=_CHINA_ENTRY_VID_VER 素材版本與遊戲版號脫鉤(_GEAR_IMG_VER 前例·換片才 bump)。
// ════════════════════════════════════════════════════════════════════
window._CHINA_ENTRY_VID_VER = '1';
// ★ v5.54.0 — 二次進場黑屏根治(老師回報:第二次起影片全黑僅剩跳過鈕):
//   根因=mp4 不經 sw 直連 raw.githubusercontent.com,Chrome 對同 URL 二次播放走
//   media cache+Range 條件請求,raw 回應不標準 → video 卡載入 stall(非 error 不觸發 onerror)
//   → 黑屏乾等 13s 硬兜底。修法:①首播直連照舊+背景 fetch 整支存 session Blob(大概率命中
//   HTTP cache 零額外流量) → 第二次起改播 blob:URL=零網路請求零 Range 問題,秒開根治
//   ②軟兜底:5s 內沒 playing(第一幀)就提早收尾直進,不再黑屏乾等 13s ③blob 播放失敗
//   → revoke 清空退回 raw,自癒不鎖死。13s 硬兜底/跳過鈕/onerror 全保留。
window._chinaEntryVidBlobUrl = window._chinaEntryVidBlobUrl || null;
window._chinaPlayEntryCinematic = function(next){
  var _go = function(){ try{ if(typeof next === 'function') next(); }catch(_eN){ console.warn('[進入繪卷 next]', _eN); } };
  /* ★ v5.227.0 動畫開關:這是一支純過場影片(沒有任何選擇或資料寫入),關閉動畫時直接走 next() 進關卡。
     ⚠ 與「過場對白」不同:對白裡有難度選擇、路線選擇、法寶發放,跳掉整關會開不起來,故刻意不動它們。 */
  if(window._lxpsFxDisabled && window._lxpsFxDisabled()){ _go(); return; }
  try{
    // 重入守門:殘留舊 overlay 先移除(雙擊選關鈕保險)
    var old = document.getElementById('china-entry-cine');
    if(old && old.parentNode) old.parentNode.removeChild(old);
    var ov = document.createElement('div');
    ov.id = 'china-entry-cine';
    ov.style.cssText = 'position:fixed;inset:0;z-index:10500;background:#000;display:flex;align-items:center;justify-content:center;opacity:0;transition:opacity 0.4s;';
    var v = document.createElement('video');
    var _rawUrl = './' + encodeURIComponent('進入繪卷.mp4') + '?v=' + window._CHINA_ENTRY_VID_VER;
    var _usingBlob = !!window._chinaEntryVidBlobUrl;
    v.src = _usingBlob ? window._chinaEntryVidBlobUrl : _rawUrl;
    v.muted = true; v.defaultMuted = true; v.setAttribute('muted',''); v.volume = 1.0;
    v.setAttribute('playsinline',''); v.setAttribute('webkit-playsinline','');
    v.autoplay = true; v.controls = false; v.loop = false; v.preload = 'auto';
    v.style.cssText = 'width:100%;height:100%;object-fit:cover;';
    var _done = false;
    var _finish = function(){
      if(_done) return; _done = true;
      try{ ov.style.opacity = '0'; }catch(_){}
      setTimeout(function(){ try{ if(ov && ov.parentNode) ov.parentNode.removeChild(ov); }catch(_){} }, 420);
      _go();
    };
    v.onended = _finish;
    // ★ v5.55.0 — 一次性當場重試(取代 v5.54.0「本次放棄·下次自癒」):blob 壞檔/黑屏當下即清
    //   blob 並改直連 raw(帶 &r= 時間戳 cache-buster 避開 media cache Range stall)重播一次;
    //   重試後再 5s 沒出第一幀或再失敗才收尾直進。老師本次進場就有第二次機會播出,不必等下次。
    var _retried = false;
    var _retryRaw = function(){
      if(_retried || _done) return false;
      _retried = true;
      if(_usingBlob){
        try{ URL.revokeObjectURL(window._chinaEntryVidBlobUrl); }catch(_){}
        window._chinaEntryVidBlobUrl = null;
        _usingBlob = false;
      }
      try{
        v.src = _rawUrl + '&r=' + Date.now();
        v.load();
        var _p2 = v.play();
        if(_p2 && _p2.catch) _p2.catch(function(){ _finish(); });
      }catch(_eR){ _finish(); return true; }
      setTimeout(function(){ if(!_played && !_done) _finish(); }, 5000);
      return true;
    };
    v.onerror = function(){
      // 播放失敗 → 先當場退 raw 重試一次;已重試過才靜默直進九州輿圖(零阻塞)
      if(!_retryRaw()) _finish();
    };
    ov.appendChild(v);
    // 跳過鈕(仿 _bv-skip·iPad 觸控 44px 下限 v5.25.0 口徑)+ 點畫面任意處也可跳過
    var _skip = document.createElement('div');
    _skip.textContent = '跳過 ⏭';
    _skip.style.cssText = 'position:absolute;top:calc(14px + env(safe-area-inset-top));right:calc(18px + env(safe-area-inset-right));padding:10px 22px;min-height:44px;display:flex;align-items:center;background:rgba(0,0,0,0.55);border:1.5px solid rgba(255,255,255,0.55);border-radius:24px;color:#fff;font-size:20px;font-weight:800;letter-spacing:2px;cursor:pointer;z-index:2;touch-action:manipulation;-webkit-tap-highlight-color:transparent;user-select:none;';
    _skip.onclick = function(ev){ try{ if(ev){ ev.stopPropagation(); ev.preventDefault(); } }catch(_){} _finish(); };
    ov.appendChild(_skip);
    ov.onclick = _finish;
    document.body.appendChild(ov);
    requestAnimationFrame(function(){ try{ ov.style.opacity = '1'; }catch(_){} });
    // playing 後才解靜音:影片音量同步受音樂音量控制(v5.37.0 _bvApplyBgmVol 單一套用點;無 helper 時直接解靜音)
    var _played = false;
    try{ v.addEventListener('playing', function(){ _played = true; try{ if(typeof window._bvApplyBgmVol === 'function') window._bvApplyBgmVol(v); else v.muted = false; }catch(_){} }); }catch(_){}
    // ★ v5.54.0 — 背景預存 Blob(只做一次;首播直連行為零影響,同 URL 大概率命中 HTTP cache 零額外流量)
    if(!window._chinaEntryVidBlobUrl && !window._chinaEntryVidBlobFetching){
      window._chinaEntryVidBlobFetching = true;
      try{
        fetch(_rawUrl).then(function(r){ if(!r || !r.ok) throw new Error('fetch not ok'); return r.arrayBuffer(); })
          .then(function(buf){
            // ★ v5.55.0 — 黑屏根因根治:raw 回應 content-type=application/octet-stream+nosniff,
            //   v5.54.0 用 r.blob() 會繼承這個錯誤 MIME → iPad Safari 對 blob: 影片 MIME 嚴格,拒解碼=黑屏。
            //   改 arrayBuffer 重包 Blob 並明確標 video/mp4,blob 播放即恢復正常。
            try{ window._chinaEntryVidBlobUrl = URL.createObjectURL(new Blob([buf], { type: 'video/mp4' })); }catch(_){}
            window._chinaEntryVidBlobFetching = false;
          })
          .catch(function(){ window._chinaEntryVidBlobFetching = false; });
      }catch(_eBf){ window._chinaEntryVidBlobFetching = false; }
    }
    // BGM:提前淡入中國關首頁 BGM 墊在影片下(素材未上傳=播放失敗自動靜默;selectAdvStage 之後同曲重 fade 無害)
    try{ if(typeof bgmFadeTo === 'function') bgmFadeTo('bgm-china-menu', 400); }catch(_){}
    var _p = v.play();
    if(_p && _p.catch) _p.catch(function(){ _finish(); });   // 靜音起播仍被擋(極少見)→ 直進不卡
    // ★ v5.54.0 軟兜底 → v5.55.0 升級:5 秒沒出第一幀(載入 stall 黑屏)先當場退 raw 重試一次;
    //   重試路徑自帶第二層 5s 兜底,已重試過才收尾直進。13s 硬兜底照舊=最壞情況上限不變。
    setTimeout(function(){ if(!_played && !_done){ if(!_retryRaw()) _finish(); } }, 5000);
    setTimeout(_finish, 13000);   // 硬兜底:影片 10s+緩衝,最長 13s 必收尾(絕不卡死)
  }catch(_eCine){ console.warn('[進入繪卷 過場]', _eCine); _go(); }
};
window._chinaTrySelect = function(btnEl){
  // ★ v5.67.0 — 每次進中國關重置「第三場菁英戰」latch:
  //   讓每趟路線挑戰都會遭遇一次菁英戰(含挑戰失敗後重打整條路線)。
  try{ window._chinaEliteDone = false; }catch(_){}
  const _isAdmin = (typeof window._isAdminUser === 'function' && window._isAdminUser());
  if(!_isAdmin){
    // 閘門①:測試期僅管理員
    if(window._CHINA_ADMIN_ONLY){ window._chinaShowComingSoon(); return; }
    // 閘門②③:埃及雙王通關 + 4 名英雄 Lv.45
    const _egCleared = !!(typeof _medals !== 'undefined' && _medals && _medals['egypt_first_clear']);
    const _heroLvs = (typeof _heroLevels === 'object' && _heroLevels) ? _heroLevels : {};
    const _qualifiedCount = Object.values(_heroLvs).filter(lv => (lv||0) >= 45).length;
    if(!_egCleared || _qualifiedCount < 4){
      try{ playSfx('sfx-cancel', 0.6); }catch(_){}
      window._chinaShowLockedModal(_qualifiedCount, _egCleared);
      return;
    }
  }
  // ★ v5.45.0 — 通過解鎖條件(或管理員)即發「繪卷旅人」獎章(比照台灣關 _checkTaiwanUnlockMedal 口徑)
  try{ if(typeof window._checkChinaUnlockMedal === 'function') window._checkChinaUnlockMedal(); }catch(_){}
  // ★ v5.47.0 — 進入繪卷過場動畫(老師需求):影片結束/跳過/缺檔失敗 才進中國關首頁(絕不卡死)
  if(typeof window._chinaPlayEntryCinematic === 'function'){
    window._chinaPlayEntryCinematic(function(){ selectAdvStage('china', btnEl); });
  } else {
    selectAdvStage('china', btnEl);
  }
};

window._TAIWAN_ADMIN_ONLY = false;       // 改用 4 名英雄 20 級解鎖,不再限管理員
window._taiwanTrySelect = function(btnEl){
  // ★ v1.1.0 — 解鎖檢查:4 名英雄達 20 級才能進入(管理員可跳過)
  const _isAdmin = (typeof window._isAdminUser === 'function' && window._isAdminUser());
  if(!_isAdmin){
    const _heroLvs = (typeof _heroLevels === 'object' && _heroLevels) ? _heroLevels : {};
    const _qualifiedCount = Object.values(_heroLvs).filter(lv => (lv||0) >= 20).length;
    if(_qualifiedCount < 4){
      try{ playSfx('sfx-cancel', 0.6); }catch(_){}
      _taiwanShowLockedModal(_qualifiedCount);
      return;
    }
    // ★ v1.1.0 — 通過解鎖條件觸發獎章
    try{ if(typeof window._checkTaiwanUnlockMedal === 'function') window._checkTaiwanUnlockMedal(); }catch(_){}
  } else {
    // 管理員也算解鎖
    try{ if(typeof window._checkTaiwanUnlockMedal === 'function') window._checkTaiwanUnlockMedal(); }catch(_){}
  }
  try{ playSfx('sfx-sel', 0.6); }catch(_){}
  // ★ v1.0.20260428.3400 — 點擊台灣關按鈕,立即切換 BGM 為「台灣關卡簡介劇情BGM」
  try{ if(typeof bgmFadeTo === 'function') bgmFadeTo('bgm-taiwan-intro', 700); }catch(_){}
  // 暫時隱藏冒險選關介面,讓地圖獨佔畫面
  try{
    const advOv = document.getElementById('adventure-overlay');
    if(advOv){ advOv.style.display='none'; advOv.classList.remove('show'); }
  }catch(_){}
  _showTaiwanMap();
};

// ★ v1.1.0 — 解鎖提示視窗(英雄等級不足時顯示)
//   原 _taiwanShowAdminOnlyModal 改名為 _taiwanShowLockedModal,顯示解鎖進度
function _taiwanShowLockedModal(currentCount){
  const _cnt = currentCount || 0;
  const _need = 4;
  const old = document.getElementById('taiwan-locked-modal');
  if(old) old.remove();
  // 列出已達 20 級的英雄(供玩家確認)
  const _heroLvs = (typeof _heroLevels === 'object' && _heroLevels) ? _heroLevels : {};
  const _qualifiedHeroes = Object.entries(_heroLvs)
    .filter(([n,lv]) => (lv||0) >= 20)
    .sort((a,b) => (b[1]||0)-(a[1]||0));
  const _qualifiedHtml = _qualifiedHeroes.length > 0
    ? _qualifiedHeroes.map(([n,lv]) => '<span style="display:inline-block;padding:6px 14px;margin:4px;background:rgba(80,200,140,0.25);border:1.5px solid rgba(120,255,180,0.6);border-radius:18px;font-size:18px;font-weight:800;color:#aaffcc;">' + n + ' Lv.' + lv + '</span>').join('')
    : '<div style="font-size:18px;color:#888;font-style:italic;">(目前還沒有英雄達到 20 級)</div>';

  const modal = document.createElement('div');
  modal.id = 'taiwan-locked-modal';
  modal.style.cssText =
    'position:fixed;inset:0;z-index:9999;display:flex;align-items:center;justify-content:center;' +
    'background:radial-gradient(circle at center,rgba(20,30,60,0.85),rgba(0,0,0,0.92));' +
    'backdrop-filter:blur(6px);animation:fadeIn 0.35s;';
  const _enough = _cnt >= _need;
  const _color = _enough ? '#88ffaa' : '#ffcc66';
  modal.innerHTML =
    '<div style="max-width:680px;width:92%;padding:36px 36px 28px;text-align:center;' +
      'background:linear-gradient(160deg,rgba(20,40,30,0.98),rgba(8,20,12,0.98));' +
      'border:2.5px solid '+_color+'88;border-radius:22px;' +
      'box-shadow:0 0 80px '+_color+'55;font-family:inherit;max-height:88vh;overflow-y:auto;">' +
      '<div style="font-size:88px;margin-bottom:8px;">🏝️</div>' +
      '<div style="font-size:clamp(28px,3.2vw,42px);font-weight:900;color:#88ffaa;margin-bottom:6px;letter-spacing:3px;">台灣環島歷險記</div>' +
      '<div style="font-size:clamp(20px,2.4vw,28px);font-weight:800;color:'+_color+';margin-bottom:20px;">' +
        (_enough ? '✓ 解鎖成功!' : '🔒 尚未解鎖') +
      '</div>' +
      // 解鎖進度
      '<div style="background:rgba(0,0,0,0.5);border:2px solid '+_color+'66;border-radius:14px;padding:20px 24px;margin-bottom:18px;">' +
        '<div style="font-size:22px;font-weight:800;color:#fff;margin-bottom:10px;">📊 解鎖條件:<span style="color:#ffcc44;">4 名英雄達到 20 級</span></div>' +
        '<div style="display:flex;align-items:center;justify-content:center;gap:14px;margin-bottom:14px;">' +
          '<div style="font-size:18px;color:#ddd;">目前進度</div>' +
          '<div style="font-size:36px;font-weight:900;color:'+_color+';letter-spacing:2px;">' + _cnt + ' / ' + _need + '</div>' +
        '</div>' +
        // 進度條
        '<div style="height:14px;background:rgba(0,0,0,0.6);border-radius:7px;overflow:hidden;border:1px solid rgba(255,255,255,0.15);margin-bottom:8px;">' +
          '<div style="height:100%;width:' + Math.min(100, Math.round((_cnt/_need)*100)) + '%;background:linear-gradient(90deg,'+_color+',#44ddaa);transition:width 0.3s;"></div>' +
        '</div>' +
        '<div style="font-size:16px;color:#aaccff;margin-top:10px;">' +
          (_enough ? '太棒了!你的隊伍已經達到挑戰台灣 BOSS 的水準,可以出發了!' : '還差 <b style="color:#ff8866;">' + (_need-_cnt) + '</b> 名英雄達 20 級,繼續加油!') +
        '</div>' +
      '</div>' +
      // 已達標英雄列表
      '<div style="background:rgba(0,0,0,0.4);border:1.5px solid rgba(120,255,180,0.3);border-radius:12px;padding:16px 18px;margin-bottom:20px;">' +
        '<div style="font-size:18px;font-weight:800;color:#88ffaa;margin-bottom:10px;">⭐ 已達 20 級的英雄 (' + _qualifiedHeroes.length + ' 名):</div>' +
        '<div style="text-align:center;line-height:1.8;">' + _qualifiedHtml + '</div>' +
      '</div>' +
      // 提示
      '<div style="background:rgba(0,0,0,0.35);border-left:4px solid #ffcc44;border-radius:8px;padding:14px 18px;margin-bottom:20px;text-align:left;">' +
        '<div style="font-size:17px;color:#ffe8a0;line-height:1.7;">' +
          '💡 <b>升級建議</b>:打貓空關卡的小怪 / BOSS 戰會給英雄經驗值,連續挑戰可以快速升級。<br>' +
          '🎯 升到 Lv 20 後,英雄擁有完整的技能組,挑戰台灣 BOSS 才不會太吃力。' +
        '</div>' +
      '</div>' +
      '<button onclick="document.getElementById(\'taiwan-locked-modal\').remove()" ' +
        'style="padding:14px 40px;font-size:24px;font-weight:800;letter-spacing:2px;' +
        'background:linear-gradient(135deg,#44ddaa,#22aa77);color:#fff;' +
        'border:2px solid rgba(120,255,180,0.7);border-radius:12px;cursor:pointer;' +
        'box-shadow:0 0 20px rgba(80,255,140,0.5);">了解 ✓</button>' +
    '</div>';
  document.body.appendChild(modal);
}
