  const mapCol = document.createElement('div');
  mapCol.style.cssText = 'position:absolute;inset:0;z-index:2;display:flex;align-items:center;justify-content:center;padding:8px;';
  const mapWrap = document.createElement('div');
  mapWrap.style.cssText = 'position:relative;width:100%;height:100%;display:flex;align-items:center;justify-content:center;';
  // mapInner:讓發光點和文字標籤的座標精準對齊圖片本身
  const mapInner = document.createElement('div');
  mapInner.style.cssText = 'position:relative;display:inline-block;max-width:100%;max-height:100%;line-height:0;';
  // 地圖背景圖
  const mapImg = document.createElement('img');
  mapImg.src = (typeof TAIWAN_IMG_BASE !== 'undefined')
    ? TAIWAN_IMG_BASE + encodeURIComponent('台灣地圖.png')
    : './' + encodeURIComponent('台灣地圖.png');
  mapImg.alt = '台灣地圖';
  mapImg.style.cssText = 'max-width:100%;max-height:100%;height:auto;width:auto;display:block;filter:drop-shadow(0 0 30px rgba(80,160,255,0.5));';
  mapImg.onerror = function(){
    // 載入失敗 fallback:藍色提示文字
    this.style.display = 'none';
    const _fb = document.createElement('div');
    _fb.style.cssText = 'color:#aaccff;font-size:18px;text-align:center;padding:40px;';
    _fb.textContent = '🗺 台灣地圖載入失敗(GitHub 圖片可能尚未上傳)';
    mapWrap.appendChild(_fb);
  };
  mapInner.appendChild(mapImg);
  // ★ v1.1.0 — 海洋特效層放在 mapImg 之上,但只覆蓋在地圖範圍內
  //   z-index:1 但被父 mapInner 限制範圍,不會洩漏到地圖外的藍色 overlay 邊界
  //   注意:這會讓特效蓋在台灣陸地上,但因為閃光/漣漪/光斑都很淡,陸地上幾乎看不出來,
  //         反而海洋區域(較暗)會凸顯這些亮點 — 視覺上正是我們要的效果
  mapInner.appendChild(oceanLayer);
  mapWrap.appendChild(mapInner);

