// BOSS 擊敗時若為日本關前三路線，自動獲得對應神器
window._onJapanBossDefeated = function(){
  if(_adventureStage !== 'japan') return;
  const v = ADV_BOSS_VARIANTS.japan && ADV_BOSS_VARIANTS.japan[window._advSelectedVariantIdx];
  if(!v || !v.treasureKey || v.id === 'yamata') return;
  const before = _japanTreasureCount();
  _japanSetTreasure(v.treasureKey);
  const after = _japanTreasureCount();
  if(after > before){
    // 顯示神器獲得通知
    try{
      setTimeout(()=>{
        if(typeof showPopup==='function'){
          // 用現有的 log 系統記錄
        }
        if(typeof log==='function') log(`🏆 獲得神器：${v.treasureName}！目前已收集 ${after}/3 件。`);
      }, 500);
    }catch(_){}
    // ★ v1.0.20260421.3000 — 三神器獎章
    try{ _checkMedalJapanTreasure(); }catch(_){}
  }
};

// ★ v5.41.0 — 中國關 Phase 3:BOSS 擊敗處理(仿 _onJapanBossDefeated;三神物發放/官渡解鎖/隱藏戰獎勵/獎章/神物消耗重鎖)
window._onChinaBossDefeated = function(){
  if(_adventureStage !== 'china') return;
  const v = (typeof ADV_BOSS_VARIANTS !== 'undefined' && ADV_BOSS_VARIANTS.china)
    ? ADV_BOSS_VARIANTS.china[window._advSelectedVariantIdx] : null;
  if(!v) return;
  // ★ v5.56.0 — 神農鼎:妖王必掉煉丹材料 仙品×2+極品×2(可重複刷)+路線首通配方(冪等·已持有不重發)
  try{ if(typeof window._alchBossDrops === 'function') window._alchBossDrops(v.id); }catch(_eAlchB){ console.warn('[神農鼎妖王掉落]', _eAlchB); }
  // ★ v5.109.0 — 煉丹小藥童 S1「百草採集」:妖王戰結束同樣額外採材料(與小怪戰共用同一支·不會兩套口徑)
  try{ if(typeof window._alchYaotongS1Proc === 'function') window._alchYaotongS1Proc(); }catch(_ytS1B){ console.warn('[百草採集·妖王戰]', _ytS1B); }
  // ── 正規三線:發放對應神物 ──
  if(v.treasureKey && (v.id === 'fengshen' || v.id === 'xiyou' || v.id === 'sanguo')){
    const before = (typeof window._chinaTreasureCount === 'function') ? window._chinaTreasureCount() : 0;
    if(typeof window._chinaSetTreasure === 'function') window._chinaSetTreasure(v.treasureKey);
    const after = (typeof window._chinaTreasureCount === 'function') ? window._chinaTreasureCount() : 0;
    if(after > before){
      try{ setTimeout(()=>{ if(typeof log==='function') log(`🏺 獲得神物:${v.treasureName}!目前已收集 ${after}/3 件。`); }, 500); }catch(_){}
      try{ _showInGameToast(`🏺 獲得神物「${v.treasureName}」!(${after}/3)`, '#ffcc66', 3500); }catch(_){}
    }
    // 獎章(重複通關可重觸發,_unlockMedal 內部去重)
    try{
      if(v.id === 'fengshen') _unlockMedal('china_fengshen_clear');
      if(v.id === 'xiyou')    _unlockMedal('china_xiyou_clear');
      if(v.id === 'sanguo')   _unlockMedal('china_sanguo_clear');
      if(after >= 3) _unlockMedal('china_treasures_all');
    }catch(_){}
  }
  // ── 三國線加碼:呂布擊破 → 官渡(曹操)路線解鎖 ──
  if(v.id === 'sanguo'){
    const _lvbuWas = !!(window._chinaProgress && window._chinaProgress.lvbuCleared);
    if(typeof window._chinaSetLvbuCleared === 'function') window._chinaSetLvbuCleared();
    if(!_lvbuWas){
      try{ setTimeout(()=>{ if(typeof log==='function') log('🏰 呂布已敗!九州輿圖上,「官渡」的烽煙悄然升起……(隱藏路線解鎖)'); }, 900); }catch(_){}
      try{ _showInGameToast('🏰 隱藏路線「官渡・曹操」已在九州輿圖浮現!', '#cc99ff', 4000); }catch(_){}
    }
  }
  // ── 隱藏一:官渡曹操 → 豐厚結算獎勵(不發神物;老師乙案 2026-08-15 裁定:高價獎勵一律首通限定,不容許重複刷) ──
  //   首通判定用雲端持久獎章 china_caocao_clear;重複通關只得一般戰鬥結算(EXP/知識幣),不再發固定大獎
  if(v.id === 'caocao'){
    try{
      const _ccFirst = !(typeof _medals !== 'undefined' && _medals && _medals['china_caocao_clear']);
      if(_ccFirst){
        if(typeof addKnowledgeCoins === 'function') addKnowledgeCoins(5000, '收入:官渡曹操首通');
        backpackAdd('summon_crystal', 30, '官渡曹操首通');
        backpackAdd('hero_exp_book_premium', 3);
        if(typeof log==='function') log('🏰 首次擊敗曹操!獲得【知識幣 ×5000】【召喚水晶 ×30】【豪華典藏版經驗之書 ×3】!');
        _showInGameToast('🏰 官渡首捷!知識幣5000+水晶30+豪華經驗書×3', '#ffdd66', 4500);
      } else {
        if(typeof log==='function') log('🏰 再次擊敗曹操!(首通大獎已領過,本次獲得一般戰鬥結算獎勵)');
      }
      _unlockMedal('china_caocao_clear');
    }catch(_eCcRw){ console.warn('[中國關 曹操獎勵]', _eCcRw); }
  }
  // ── 隱藏二:涿鹿蚩尤 → 大獎(老師乙案 2026-08-15 裁定:同樣首通限定——否則「保留神物」可無限重打刷 50 水晶;
  //   用神物與否獎勵相同維持八岐口徑,但僅首通發放) ──
  if(v.id === 'chiyou'){
    try{
      const _cyFirst = !(typeof _medals !== 'undefined' && _medals && _medals['china_chiyou_clear']);
      if(_cyFirst){
        if(typeof addKnowledgeCoins === 'function') addKnowledgeCoins(8000, '收入:涿鹿蚩尤首通');
        backpackAdd('summon_crystal', 50, '涿鹿蚩尤首通');
        backpackAdd('burst_upgrade_fruit', 2);
        try{ if(typeof window._advSaveFruitHistory === 'function') window._advSaveFruitHistory('china_chiyou_clear', 2); }catch(_){}
        backpackAdd('hero_exp_book_premium', 5);
        if(typeof log==='function') log('⚔ 首次擊敗戰神蚩尤!獲得【知識幣 ×8000】【召喚水晶 ×50】【超越極限果實 ×2】【豪華典藏版經驗之書 ×5】!');
        _showInGameToast('⚔ 涿鹿首捷!知識幣8000+水晶50+果實×2+豪華書×5', '#ffdd66', 5000);
      } else {
        if(typeof log==='function') log('⚔ 再次擊敗戰神蚩尤!(首通大獎已領過,本次獲得一般戰鬥結算獎勵)');
      }
      _unlockMedal('china_chiyou_clear');
    }catch(_eCyRw){ console.warn('[中國關 蚩尤獎勵]', _eCyRw); }
    // 戰前選「使用三神物」→ 勝利後三神物消耗、涿鹿重鎖(同八岐口徑;保留則不消耗)
    if(window._chinaUseTreasures === true){
      try{
        // ★★ v5.101.0(老師裁定乙)— 消耗改「單調遞增計數 +1」,**不再把布林寫回 false** ★★
        //   舊碼寫 false → 三槽 OR 合併(「任一 true 就採用,絕不退回」)會從殘槽把 true 撿回來,
        //   涿鹿永遠不會重鎖(本輪根治)。改為 treasuresUsed++ 後,合併端取 max ⇒ 只增不減,
        //   殘槽再舊也只會讓 used 偏小一輪,絕不可能讓「已消耗」復原成未消耗。
        //   (舊三行依鐵則保留為註解備查·勿刪:
        //     window._chinaProgress.treasures.fengshen = false;
        //     window._chinaProgress.treasures.xiyou = false;
        //     window._chinaProgress.treasures.sanguo = false; )
        if(window._chinaProgress){
          const _usedBefore = window._chinaTreasureUsed();
          // 消耗次數推進到「本輪已取得的最小件數」——正常情況三件皆 got=used+1 ⇒ used+1
          window._chinaProgress.treasuresUsed = _usedBefore + 1;
        }
        window._chinaUseTreasures = false;
        try{ if(typeof gameCloudSave === 'function') gameCloudSave().catch(()=>{}); }catch(_){}
        setTimeout(()=>{
          try{ if(typeof log==='function') log('🏺 三神物之力已耗盡,化為流光消散——涿鹿古戰場重新鎖定,需再次收集神物才能挑戰。'); }catch(_){}
          try{ _showInGameToast('🏺 三神物已消耗,涿鹿古戰場重新鎖定', '#ffaa66', 4500); }catch(_){}
        }, 1400);
      }catch(_eCyCons){ console.warn('[中國關 三神物消耗]', _eCyCons); }
    }
  }
  // ★★★ v5.46.0 — Phase 7 諸葛亮「全通關保底」(老師 3甲 裁定):
  //   五路線(封神/西遊/三國/曹操/蚩尤)全部首通 → 諸葛亮 100% 加入。
  //   判定=五枚既有雲端持久獎章(_unlockMedal 於上方各 v.id 分支同函式內先行發放,
  //   最後一條路線通關的同一場結算即觸發);零新增 chinaProgress 欄位。
  //   守門:未擁有才發(advSaveUnlockedHero 正規解鎖帳本=冪等·跨裝置雲端同步);不限評價。
  try{
    const _zgNeed = ['china_fengshen_clear','china_xiyou_clear','china_sanguo_clear','china_caocao_clear','china_chiyou_clear'];
    const _zgAllClear = (typeof _medals !== 'undefined') && _medals && _zgNeed.every(function(_id){ return !!_medals[_id]; });
    if(_zgAllClear){
      const _zgUnlocked = (typeof advGetUnlockedHeroes === 'function') ? advGetUnlockedHeroes() : [];
      if(!_zgUnlocked.includes('諸葛亮')){
        advSaveUnlockedHero('諸葛亮', 'china_all_clear');
        try{ if(typeof window._checkChinaRecruitMedal === 'function') window._checkChinaRecruitMedal(); }catch(_){}
        try{
          log('🪶 五條路線的繪卷同時亮起——羽扇綸巾的身影自光中步出。SR 軍師的真名終於揭曉:臥龍・諸葛亮,正式加入冒險者行列!(五路線全通保底·必定獲得)');
        }catch(_){}
        setTimeout(function(){
          try{ _showInGameToast('🪶 千古軍師登場![諸葛亮] 加入夥伴!(五路線全通・必定獲得)', '#ffcc44', 6000); }catch(_){}
        }, 2200);
        // ★ v5.109.0 同輪追加(老師 2026-08-22 需求)— 【諸葛亮改良丹藥盒】
        //   五路線全通的同一刻,丹藥盒由「只能在中國關用」升級為「台灣關／日本關／埃及關也能用」。
        //   ⚠ 老師 2026-08-22 更正:世界龍王戰**不可**使用丹藥盒(與鬥技場同列不適用),
        //     守門在 `_alchBattleActive` 內以獨立一行明列 `worldboss` 擋下。
        //   ⚠ 這裡只是**宣告**:真正的開關是 window._alchBoxUnlocked()(讀同一組五枚獎章),
        //     所以就算玩家沒看到這則訊息(離線/中途關掉),功能一樣已經生效,不會有「沒收到通知就沒解鎖」。
        //   ⚠ 排在諸葛亮 toast 之後 3.4 秒,避免兩則訊息疊在一起讓孩子看不完。
        setTimeout(function(){
          var _cuteZg = (typeof window._artStyle === 'string' && window._artStyle === 'cute');
          try{
            log(_cuteZg
              ? '🏺 諸葛亮看了看你背上的丹藥盒,拿羽扇輕輕一敲——「這盒子的火候封得不夠緊,難怪出了九州就散了。」他重新改良了丹藥盒:從今以後,你在**台灣關、日本關、埃及關**也都能服用丹藥了!(⚔ 鬥技場和🐉世界龍王戰除外喔)'
              : '🏺 臥龍先生端詳了背上的丹藥盒,以羽扇輕叩其蓋——「火候封存之法未臻,故出九州則藥性盡散。」諸葛亮親手改良了丹藥盒:自此丹藥可於**台灣關、日本關、埃及關**的冒險戰鬥中服用(⚔ 鬥技場維持 Lv1 公平制、🐉 世界龍王戰均不適用)。⚠ 丹藥與丹藥材仍僅能於中國古代關取得。');
          }catch(_){}
          try{ _showInGameToast('🏺🪶 諸葛亮改良了丹藥盒!台灣關、日本關、埃及關也都能吃丹藥了!(鬥技場與龍王戰除外)', '#c8a8ff', 7000); }catch(_){}
          try{ playSfx('sfx-medal-unlock', 0.8); }catch(_){}
        }, 5600);
        try{ _setNavDot('英雄', true); }catch(_){}
      }
    }
  }catch(_eZgAll){ console.warn('[中國關 諸葛亮保底] 失敗:', _eZgAll); }
};
