// 茶園事件：顯示事件對白（使用既有 adv-dialog-box）
function _tgShowDialog(speaker, lines, onDone){
  const speakerEl = document.getElementById('adv-dialog-speaker');
  const textEl    = document.getElementById('adv-dialog-text');
  const dialog    = document.getElementById('adv-dialog-box');
  if(!dialog || !textEl){ if(onDone) onDone(); return; }
  dialog.style.display = 'block';
  if(speakerEl) speakerEl.textContent = speaker;
  let idx = 0;
  const step = () => {
    if(idx >= lines.length){
      // ★ 還原 onclick 為 advNextDialog（不可設為 null，否則之後回到第一場景劇情會卡死）
      dialog.onclick = function(ev){ advNextDialog(ev); };
      dialog.style.display = 'none';
      if(onDone) onDone();
      return;
    }
    textEl.textContent = lines[idx];
    idx++;
    try{ beep(520,'sine',0.05,0.06); }catch(_){}
    // ★ v3.15.18(2026-06-16) — 事件對白每翻一行,重新計時逾時保險(玩家慢慢讀不會被誤判卡死)
    try{ if(window._advTgEventWatchdog && typeof _advTgEventArmWatchdog === 'function') _advTgEventArmWatchdog(); }catch(_){}
  };
  step();
  dialog.onclick = step;
}

