function _filterOptionsByDifficulty(options, correctLetter, difficulty){
  const _safeOpts = Array.isArray(options) ? options.slice() : [];
  const _letters = ['A','B','C','D'];
  const _correctIdx = _letters.indexOf(correctLetter);
  // 異常情況處理:選項或正確答案有問題,直接回傳原樣
  if(!_safeOpts.length || _correctIdx < 0 || _correctIdx >= _safeOpts.length){
    return { options: _safeOpts, correctIdx: Math.max(0,_correctIdx), correctLetter: correctLetter };
  }
  // 難度對應目標選項數
  const _targetMap = { '沒自信': 2, '普通': 3, '我很會': 4, '我很強': 4 };
  // 處理難度後綴(例:沒自信(輕鬆模式) / 我很會(挑戰模式))
  let _diffKey = '普通';
  if(typeof difficulty === 'string'){
    if(difficulty.indexOf('沒自信') >= 0) _diffKey = '沒自信';
    else if(difficulty.indexOf('我很會') >= 0 || difficulty.indexOf('我很強') >= 0) _diffKey = '我很會';
    else _diffKey = '普通';
  }
  let _target = _targetMap[_diffKey] || 4;
  _target = Math.min(_target, _safeOpts.length);
  if(_target >= _safeOpts.length){
    // 不需過濾,原樣回傳
    return { options: _safeOpts, correctIdx: _correctIdx, correctLetter: correctLetter };
  }
  // 從錯誤選項中隨機抽 (target-1) 個
  const _wrongs = [];
  for(let _wi = 0; _wi < _safeOpts.length; _wi++){
    if(_wi !== _correctIdx) _wrongs.push({ text: _safeOpts[_wi], origIdx: _wi });
  }
  // Fisher-Yates 洗牌錯誤選項
  for(let _ws = _wrongs.length - 1; _ws > 0; _ws--){
    const _wt = Math.floor(Math.random() * (_ws + 1));
    [_wrongs[_ws], _wrongs[_wt]] = [_wrongs[_wt], _wrongs[_ws]];
  }
  const _kept = _wrongs.slice(0, _target - 1);
  // 加入正確答案,按原始位置排序保持順序穩定
  const _combined = _kept.concat([{ text: _safeOpts[_correctIdx], origIdx: _correctIdx }]);
  _combined.sort((a, b) => a.origIdx - b.origIdx);
  const _newCorrectIdx = _combined.findIndex(c => c.origIdx === _correctIdx);
  return {
    options: _combined.map(c => c.text),
    correctIdx: _newCorrectIdx,
    correctLetter: _letters[_newCorrectIdx] || correctLetter,
  };
}

function advShowQuiz() {
  // ★ v3.3.7 — 新一輪 quiz 開始,清掉上一輪可能還沒到期的卡死救援 watchdog
  //   避免玩家正在答這一輪題目時,上一輪排的 3 秒救援突然觸發誤救
  try{
    if(window._advQuizDeadlockSaverTimer){
      clearTimeout(window._advQuizDeadlockSaverTimer);
      window._advQuizDeadlockSaverTimer = null;
    }
  }catch(_){}
  // ★ 確保法寶確認視窗已關閉
  const _tcConf = document.getElementById('adv-treasure-confirm');
  if(_tcConf) _tcConf.remove();
  // ★ 確保法寶確認視窗已關閉
  const _tcEl = document.getElementById('adv-treasure-confirm');
  if(_tcEl) _tcEl.remove();
  try{
    // ★ v3.13.33(2026-06-04) — 老師回報:鬥技場進去無法正常出現題目,console 看到 304/305 整輪迴圈
    //   根因:_advSessionQuestions 在某些路徑下沒被正確初始化(或被清掉),
    //         advPickQuestion 的 pool=[] 就 return __needRepick → setTimeout 150ms 無限重試
    //   修法:跟世界 BOSS 一樣,題庫為空時主動 prepare(用 ADV_QUIZ_DB 兜底)
    const _isWbStage = (typeof _adventureStage !== 'undefined' && _adventureStage === 'worldboss');
    const _isArenaCtxQ = (typeof _adventureMode !== 'undefined' && !_adventureMode
                         && typeof G !== 'undefined' && G && G.p1 && G.p2);
    if((_isWbStage || _isArenaCtxQ)
       && typeof _advSessionQuestions !== 'undefined'
       && (!Array.isArray(_advSessionQuestions) || _advSessionQuestions.length === 0)){
      console.log('[advShowQuiz] ' + (_isWbStage ? '世界 BOSS' : '鬥技場')
                  + '題庫為空,主動兜底(ADV_QUIZ_DB.slice() 洗牌)');
      try{
        if(typeof ADV_QUIZ_DB !== 'undefined' && Array.isArray(ADV_QUIZ_DB) && ADV_QUIZ_DB.length){
          const _bp = ADV_QUIZ_DB.slice();
          for(let _bi = _bp.length - 1; _bi > 0; _bi--){
            const _bj = Math.floor(Math.random() * (_bi + 1));
            [_bp[_bi], _bp[_bj]] = [_bp[_bj], _bp[_bi]];
          }
          _advSessionQuestions = _bp;
          if(typeof _advQuestionPool !== 'undefined') _advQuestionPool = _bp;
          if(typeof _advUsedQuestionIds !== 'undefined') _advUsedQuestionIds = new Set();
        } else if(typeof advPrepareSessionQuestions === 'function'){
          // 雙保險:若 ADV_QUIZ_DB 真的沒載入,走原 prepare
          advPrepareSessionQuestions();
        }
      }catch(_ePrepFb){ console.warn('[advShowQuiz] 兜底 prepare 失敗', _ePrepFb); }
    }
  }catch(_ePrep){ console.warn('[advShowQuiz] 題庫兜底 prepare 失敗', _ePrep); }
  // ★ v1.0.20260501.5470 — bug 修復:early return 也要先 fire 已設的 _advQuizResolveCb,
  //   否則 charm/stun 等 path 設了 cb 但 advShowQuiz 沒實際開 overlay → cb 永遠卡住 → BOSS 卡死
  // ★ v3.13.15(2026-06-02) — 鬥技場也走答題流程,擴大 early return 守門
  //   原:if (!_adventureMode || _advQuizPhase !== 'idle')
  //   改:必須在「冒險中 或 鬥技場(_adventureMode=false 且 G.p1/G.p2 都有效)」才繼續
  const _isArenaContext = (typeof _adventureMode !== 'undefined' && !_adventureMode
                          && typeof G !== 'undefined' && G && G.p1 && G.p2);
  if ((!_adventureMode && !_isArenaContext) || _advQuizPhase !== 'idle') {
    if(_advQuizResolveCb){
      console.warn('[advShowQuiz] early return(phase 非 idle 或非戰鬥場景),fire 已設的 cb 避免卡死');
      const _cb = _advQuizResolveCb; _advQuizResolveCb = null;
      try{ _cb(); }catch(_){}
    }
    return;
  }
  try{
    const _qOv = document.getElementById('adv-quiz-overlay');
    if(_qOv && _qOv.classList.contains('show')){
      console.warn('[advShowQuiz] 防重入:overlay 已顯示,跳過此次呼叫');
      if(_advQuizResolveCb){
        console.warn('[advShowQuiz] 防重入時 fire 已設的 cb 避免卡死');
        const _cb = _advQuizResolveCb; _advQuizResolveCb = null;
        try{ _cb(); }catch(_){}
      }
      return;
    }
  }catch(_){}
  // ★ v5.236.0(2026-09-25・玩家回報「動不了」貓空第三場寵物事件)—「小怪戰中直接 return」移到 33 秒 watchdog 之前
  //   舊:先 arm 33 秒 _quizDeadlockWatchdog,再判斷小怪戰直接 return ⇒ 這顆計時器沒人清,小怪戰結束後仍在跑;
  //       之後第三場「野生動物」寵物題共用 adv-quiz-overlay,計時器到期看到 overlay 開著 → advOnQuizSkip(BOSS 路徑)
  //       把學生正在答的寵物題關掉 → 題目可見性 watchdog 再判 {correct:false} ⇒ 沒作答就答錯、寵物跑掉。
  //   新:小怪戰路徑不 arm,並順手清掉殘留的那顆。
  if(typeof _advMiniBattleActive !== 'undefined' && _advMiniBattleActive){
    try{
      if(window._quizDeadlockWatchdog){ clearTimeout(window._quizDeadlockWatchdog); window._quizDeadlockWatchdog = null; }
    }catch(_){}
    if(_advQuizResolveCb){ const _cbM = _advQuizResolveCb; _advQuizResolveCb = null; _cbM(); }
    return;
  }
  try{
    if(window._quizDeadlockWatchdog){
      clearTimeout(window._quizDeadlockWatchdog);
      window._quizDeadlockWatchdog = null;
    }
    window._quizDeadlockWatchdog = setTimeout(() => {
      try{
        const _qOv2 = document.getElementById('adv-quiz-overlay');
        // ★ v5.236.0 — 自我驗證:目前 overlay 上若是寵物題 / 小怪題(共用同一個 overlay),一律不介入;
        //   它們各自有 3 秒可見性 watchdog 與第三場 120 秒事件 watchdog。BOSS 題的救援行為完全不變。
        const _wdPetOrMini = !!window._tgPetQuizMode
          || (typeof window._miniQuizPhase !== 'undefined' && (window._miniQuizPhase === 'asking' || window._miniQuizPhase === 'done'))
          || (typeof window._miniQuizOnDone === 'function');
        if(_wdPetOrMini){
          console.warn('[Quiz watchdog v5.236.0] 33 秒到期但目前是寵物/小怪題,不介入(避免誤關學生正在答的題目)');
        } else
        if(_qOv2 && _qOv2.classList.contains('show')){
          console.warn('🚨 [Quiz watchdog] 答題視窗超過 33 秒沒進展,強制 advOnQuizSkip');
          if(typeof log === 'function') log('⏰ [系統] 答題超時,自動跳過');
          if(typeof advOnQuizSkip === 'function') advOnQuizSkip();
        }
      }catch(_){}
      window._quizDeadlockWatchdog = null;
    }, 33000);
  }catch(_){}
  // ★ 小怪戰中不可觸發 BOSS 戰題目流程 —— v5.236.0 起此判斷已移到 33 秒 watchdog 之前(見上方)
  let q = advPickQuestion();
  if (!q) {
    // 沒有題目，直接讓Boss行動
    advOnQuizSkip();
    return;
  }
  // ★ 題目全部出完:自動繼續,不再彈出重選題庫視窗
  if (q && q.__needRepick) {
    setTimeout(() => {
      // ★ v3.3.7+ — 用 _advTriggerQuizSafely 包裝,3 秒內題目沒出來就自動 skip
      try{ _advTriggerQuizSafely('quiz-repick'); }catch(e){
        // 防呆:重抽失敗就走 skip,避免戰鬥卡死
        try{ advOnQuizSkip(); }catch(_){}
      }
    }, 150);
    return;
  }
  _advCurrentQuestion = q;
  _advQuizPhase = 'asking';
  _advQuizActive = true;
  _advStats.startTime = Date.now();

  // 填充題目
  document.getElementById('adv-quiz-question').textContent = q.question;
  try{ window._lxpsQuizMediaApply(document.getElementById('adv-quiz-question'), q); }catch(_qm){}   // ★ v5.145.0 題圖／播放鈕(只加不改)
  // ★ v1.0.20260424.1240 — BOSS 戰也要更新養護專題進度條
  try{ if(typeof _updateSpecialQuizProgressBar === 'function') _updateSpecialQuizProgressBar(); }catch(_){}
  const optDiv = document.getElementById('adv-quiz-options');
  const letters = ['A','B','C','D'];
  optDiv.innerHTML = '';
  // ★ v1.0.20260428 — 依玩家難度過濾選項數量(沒自信2 / 普通3 / 我很會4)
  const _diffFilt = _filterOptionsByDifficulty(q.options, q.answer, _advPlayerDifficulty);
  const _filtOpts = _diffFilt.options;
  const _filtCorrectIdx = _diffFilt.correctIdx;
  // 隨機排列選項（記錄正確答案在新位置）
  const _origOpts = _filtOpts.map((text, i) => ({text, origIdx: i, origLetter: letters[i]}));
  // Fisher-Yates 洗牌
  for(let _si = _origOpts.length-1; _si > 0; _si--){
    const _sj = Math.floor(Math.random()*(_si+1));
    [_origOpts[_si], _origOpts[_sj]] = [_origOpts[_sj], _origOpts[_si]];
  }
  // 找出正確答案在洗牌後的新位置(用過濾後的 idx,不再用 q.answer 字母對應)
  const _correctOrigIdx = _filtCorrectIdx;
  const _newCorrectIdx = _origOpts.findIndex(o => o.origIdx === _correctOrigIdx);
  const _newCorrectLetter = letters[_newCorrectIdx];
  _origOpts.forEach((opt, i) => {
    const btn = document.createElement('button');
    btn.className = 'aqo-btn';
    btn.dataset.idx = i;
    btn.dataset.letter = letters[i];
    btn.dataset.isCorrect = (opt.origIdx === _correctOrigIdx) ? '1' : '0';
    btn.innerHTML = `<span class="aqo-letter">${letters[i]}</span>${opt.text}`;
    btn.onclick = () => advSubmitAnswer(letters[i], btn.dataset.isCorrect === '1');
    optDiv.appendChild(btn);
  });
  // ★ v5.245.0 — 互動音樂題(聽音演奏/看簡譜彈/模仿拍子/音樂QTE):故事冒險模式才掛載,選項按鈕隱藏保留給作答完成後送出用
  let _lxpsEarOn = false;
  try{ _lxpsEarOn = !!(typeof window._lxpsEarMount === 'function' && window._lxpsEarMount(q, 'boss')); }catch(_eEar){ _lxpsEarOn = false; }

  // 法寶列
  advUpdateBattleTreasureBar();

  // 顯示視窗
  // ★ v3.3.3 — 清掉前一題關閉時設的 inline 'display:none',否則新題目 add show 也不會顯示
  try{
    const _qOvShow = document.getElementById('adv-quiz-overlay');
    if(_qOvShow){
      _qOvShow.style.display = ''; // 清掉 inline display:none,讓 .show class 的 display 生效
    }
  }catch(_qShowClearE){ console.warn('[advShowQuiz] 清 inline display 失敗', _qShowClearE); }
  document.getElementById('adv-quiz-overlay').classList.add('show');
  /* ★★ v4.93.0(老師 2026-07-25 回報)—— 主線前兩場「河堤小怪戰」的答題標籤誤顯示「👹 九尾空貓怪出題!」。
   *   根因:主線戰鬥設 _advMiniBattleActive=false(走冒險 BOSS 引擎),所以不吃「🐾 小怪出題!」那條;
   *   而 BGM/背景/BOSS 登場動畫又把 adv-quiz-label 覆寫成上一個 BOSS 名 → 一路殘留到答題視窗。
   *   修法:主線戰鬥若本場敵方沒有「真 BOSS」(不在 _ZEUS_TRUE_BOSSES),就把標籤改成小怪出題口徑。
   *   只影響主線 ch1_1/ch1_2(敵人是 MINI_MONSTERS),主線 BOSS 場(ch3~ch6)照舊顯示 BOSS 名。 */
  try{
    if(typeof _adventureStage !== 'undefined' && _adventureStage === 'mainstory' && G && Array.isArray(G.p2)){
      var _msHasTrueBoss = G.p2.some(function(h){
        return h && h.curHp > 0 && typeof _ZEUS_TRUE_BOSSES !== 'undefined' && _ZEUS_TRUE_BOSSES.has && _ZEUS_TRUE_BOSSES.has(h.name);
      });
      if(!_msHasTrueBoss){
        var _msLbl = document.getElementById('adv-quiz-label');
        if(_msLbl) _msLbl.textContent = '🐾 小怪出題！回答正確可獲得知識幣';
      }
    }
  }catch(_eMsLbl){ console.warn('[主線小怪出題 label] 例外', _eMsLbl); }
  //   冒險關卡的新回合答題改用輕量 _advRoundQuizPending 旗標(只攔 aiAct),
  //   避免 _gamePaused 引發 8 道 watchdog 連鎖卡死。
  //   舊版邏輯:出題時都設 _gamePaused=true → 任何環節 bug 都會整局凍結
  //   新版邏輯:_advRoundQuizPending=true → 只攔 aiAct,玩家畫面正常、可以等可以救
  try{
    const _isV360RoundQuiz = !!window._advRoundQuizPending;
    if(!_isV360RoundQuiz){
      // 舊路徑:世界 BOSS 開戰題、client 同步題等保留原行為
      _gamePaused = true;
    } else {
      // v3.6.0 新回合答題:不暫停整局,只靠 _advRoundQuizPending 攔 aiAct
      console.log('🎓 [advShowQuiz v3.6.0] 新回合答題模式,不設 _gamePaused');
    }
  }catch(_v360PauseE){ _gamePaused = true; } // 例外時保守設定

  // ★ v3.4.6 — 世界 BOSS 戰房主端:廣播題目給所有 client,讓他們同步看到一模一樣的視窗
  //   老師明確需求:「無論如何讓組隊世界 boss 戰能同步看到問題,那是這遊戲的核心」
  //   payload 把題目、洗牌後的選項、正解 idx、label、指派槽位全帶過去,client 端直接 render
  //   不重新抽題(確保所有人看到同一題)
  try{
    const _isWbStage = (typeof _adventureStage !== 'undefined' && _adventureStage === 'worldboss');
    if(_isWbStage && window._wbConnectedHostMode
       && typeof window._wbHostBroadcastQuizShow === 'function'){
      // 把 q.options 用洗牌後的順序組成 client 可直接 render 的格式
      const _payloadOptions = _origOpts.map((opt, i) => ({
        text:      opt.text,
        letter:    letters[i],
        isCorrect: (opt.origIdx === _correctOrigIdx),
      }));
      // 決定 label:沿用 _qLbl 已經被覆寫的內容(BOSS quiz hook 會在這之後覆寫,
      // 但因為這個 sync 也在「下一個 tick」才送出,所以可能讀到最新的 label)
      const _qLblEl = document.getElementById('adv-quiz-label');
      const _curLabel = _qLblEl ? (_qLblEl.textContent || '').trim() : '';
      // allowedSlot:
      //   - 開戰題期間 → window._wbOpeningQuizAllowedSlot (預設 0)
      //   - BOSS 行動前題 → window._wbAssignedQuizSlot
      //   - 都沒設 → -1 (代表不限,所有玩家都可點;一般用於主動觸發題目情境)
      let _allowedSlot = -1;
      if(window._wbIsOpeningQuizPhase){
        _allowedSlot = (typeof window._wbOpeningQuizAllowedSlot === 'number')
                     ? window._wbOpeningQuizAllowedSlot : 0;
      }else if(typeof window._wbAssignedQuizSlot === 'number'){
        _allowedSlot = window._wbAssignedQuizSlot;
      }
      // 延後 50ms 廣播,讓 BOSS quiz hook 有時間覆寫 _qLblEl(BOSS 行動前題的 label)
      setTimeout(function(){
        try{
          const _qLblEl2 = document.getElementById('adv-quiz-label');
          let _label2 = _qLblEl2 ? (_qLblEl2.textContent || '').trim() : _curLabel;
          // ★ v3.7.6 — 世界 BOSS 戰 label 統一覆寫:「【由 XX 回答】」一律改成「【由房主回答,其他隊友可以按左上角發話討論】」
          //   老師 2026/5/25 明確指示:組隊房間改為只由房主回答,
          //   題目上端的「【由 XX 回答】」一律改成「【由房主回答,其他隊友可以按左上角發話討論】」
          //   避免隊友看到自己的名字以為要答題,實際只有房主能答 → 卡死 30 秒。
          //   保險:除了 line 34925 直接覆寫之外,這裡再做一次「字串替換」防漏掉(例如未來新增的 label 模式)
          try{
            if(_label2 && /【由\s*[^】]*回答】/.test(_label2)){
              _label2 = _label2.replace(/【由\s*[^】]*回答】/, '【由房主回答,其他隊友可以按左上角發話討論】');
              // 同時把 host 自己看到的 label 也覆寫,確保兩端一致
              if(_qLblEl2) _qLblEl2.textContent = _label2;
            }
          }catch(_eLblFix){ console.warn('[v3.7.6 label 統一覆寫] 例外', _eLblFix); }
          window._wbHostBroadcastQuizShow({
            question:    q.question,
            options:     _payloadOptions,
            label:       _label2 || '🐉 BOSS 答題挑戰!',
            allowedSlot: _allowedSlot,
            timestamp:   Date.now(),
          });
        }catch(_eQs){ console.warn('[advShowQuiz quiz-show 廣播] 延後例外', _eQs); }
      }, 50);
    }
  }catch(_eQuizSync){ console.warn('[advShowQuiz quiz-show 廣播] 例外', _eQuizSync); }

  // 開始計時
  // ★ v3.3.7+ — 老師需求:答題思考時間從 60 → 30 秒(讓卡死救援更快觸發)
  _advQuizSeconds = _lxpsEarOn ? window._lxpsEarSecFor(q) : 30;   // ★ v5.245.0 互動音樂題依題型給 40~66 秒
  document.getElementById('adv-quiz-timer').textContent = String(_advQuizSeconds);
  if(_lxpsEarOn){ try{ window._lxpsEarRearmWatchdogs(_advQuizSeconds); }catch(_eEarWd){} }
  document.getElementById('adv-quiz-timer').classList.remove('urgent');
  if (_advQuizTimer) clearInterval(_advQuizTimer);
  _advQuizTimer = setInterval(() => {
    _advQuizSeconds--;
    const timerEl = document.getElementById('adv-quiz-timer');
    if (timerEl) timerEl.textContent = _advQuizSeconds;
    // ★ v3.3.7+ — 倒數時間縮為 30 秒,urgent 閾值從 10 改成 6(末段 20% 變紅)
    if (_advQuizSeconds <= 6 && timerEl) timerEl.classList.add('urgent');
    if (_advQuizSeconds <= 0) {
      clearInterval(_advQuizTimer);
      advOnQuizTimeout();
    }
  }, 1000);
}

// ════════════════════════════════════════════════════════════════
// ★ v3.3.7+ — 題目可見性 watchdog(治本卡死核心)
//   老師觀察:所有卡死都是「該出題目但沒有問題出現」才會卡死
//   設計:advShowQuiz 或 _advMiniQuizAsk 呼叫後 3 秒檢查題目是否真的渲染成功
//     - 兩項全滿足 = 題目正常出現:
//       1. adv-quiz-overlay 有 .show class(視窗顯示中)
//       2. adv-quiz-question textContent 不空(題目文字渲染了)
//     - 任一不滿足 = 題目沒出現,卡死前兆 → 直接走救援
//
//   注意:_advQuizPhase 在 BOSS 戰用、_miniQuizPhase 在小怪戰用,
//        兩者題目都寫進 adv-quiz-question,所以「DOM 訊號」是統一檢測點。
//
//   使用:把 advShowQuiz() / _advMiniQuizAsk() 觸發點包進這個函式
//        reason 用於 console.warn,定位是哪個觸發路徑卡住
// ════════════════════════════════════════════════════════════════
function _advTriggerQuizSafely(reason){
  reason = reason || 'unknown';
  // 清掉前一次的可見性 watchdog(每次新 quiz 觸發都重設)
  try{
    if(window._advQuizVisibilityWatchdog){
      clearTimeout(window._advQuizVisibilityWatchdog);
      window._advQuizVisibilityWatchdog = null;
    }
  }catch(_){}
  // 呼叫主流程
  try{
    advShowQuiz();
  }catch(e){
    console.error('🚨 [題目可見性] advShowQuiz 拋例外('+reason+'):', e);
    // 主流程拋例外,直接走 skip 救援
    try{
      if(typeof advOnQuizSkip === 'function') advOnQuizSkip();
    }catch(_){}
    return;
  }
  _startQuizVisibilityCheck(reason);
}
window._advTriggerQuizSafely = _advTriggerQuizSafely;

// ★ v3.3.7+ — 共用題目可見性檢查(BOSS 戰 + 小怪戰共用)
//   小怪戰流程不經過 advShowQuiz,但題目也寫到 adv-quiz-overlay,
//   所以小怪戰可以直接呼叫 _startQuizVisibilityCheck('mini-quiz-xxx') 開檢查
function _startQuizVisibilityCheck(reason){
  reason = reason || 'unknown';
  try{
    if(window._advQuizVisibilityWatchdog){
      clearTimeout(window._advQuizVisibilityWatchdog);
      window._advQuizVisibilityWatchdog = null;
    }
  }catch(_){}
  window._advQuizVisibilityWatchdog = setTimeout(function(){
    window._advQuizVisibilityWatchdog = null;
    try{
      const _qOv = document.getElementById('adv-quiz-overlay');
      const _qQ = document.getElementById('adv-quiz-question');
      const _overlayOk = _qOv && _qOv.classList && _qOv.classList.contains('show');
      const _questionTxt = _qQ ? (_qQ.textContent || '').trim() : '';
      const _questionOk = _questionTxt.length > 0;
      // ★ v3.4.19 — 加強條件:不只 .show + question 都要,還要 phase=asking 才算正常
      //   原本:overlay 顯示中 + question 有殘留文字 → 視為正常 → 但若 phase=idle 是孤兒,
      //          watchdog return 後孤兒永遠不被救 → 玩家卡死體驗。
      //   新:phase 必須是 asking(BOSS 或 mini 任一即可)才算「真的在出題」
      // ★ v3.6.3 — 補放行條件:小怪戰 _miniQuizPhase==='done' 也是合法狀態
      //   案例(老師 2026-05-24 12:16 BUG 回報):
      //     玩家答對 → _miniQuizPhase='done' (line 75375)
      //     接下來有一連串 setTimeout(統計、boss reaction 對白、最後才彈獎勵)
      //     watchdog 在 3 秒後檢查,overlay 還沒關 + phase=done(不是 asking)
      //     → 誤判卡死 → 救援把 _miniQuizOnDone 清掉 → 獎勵永遠不彈
      //   修法:done 是「答完正在準備彈獎勵」的中間狀態,放行
      const _phaseAsking = (typeof _advQuizPhase !== 'undefined' && _advQuizPhase === 'asking');
      const _phaseAnswered = (typeof _advQuizPhase !== 'undefined' && _advQuizPhase === 'answered');
      const _miniAsking = (typeof window._miniQuizPhase !== 'undefined' && window._miniQuizPhase === 'asking');
      const _miniDone = (typeof window._miniQuizPhase !== 'undefined' && window._miniQuizPhase === 'done');
      const _hasMiniCbPending = (typeof window._miniQuizOnDone === 'function');
      const _anyAsking = _phaseAsking || _miniAsking;
      // ★ v3.6.3 — 'done' + cb 仍在 = 正在走「答對後彈獎勵」流程,合法放行
      const _miniDonePendingReward = _miniDone && _hasMiniCbPending;
      // ★ v3.6.3 — BOSS 戰 'answered' 也是合法中間狀態(answered → setTimeout 3.2s 後才走 idle + advShowReward)
      const _bossAnsweredPending = _phaseAnswered;
      if(_overlayOk && _questionOk && (_anyAsking || _miniDonePendingReward || _bossAnsweredPending)){
        return;  // 真的在出題,或剛答完正準備彈獎勵,放行
      }
      // ★ 例外:獎勵視窗顯示中(玩家答對了還在選獎勵)= 正常,不算卡
      const _rOv = document.getElementById('adv-reward-overlay');
      if(_rOv && _rOv.classList.contains('show')) return;
      // ★ 例外:overlay 已關 + 不在 quiz phase = quiz 已正常結束,不算卡
      if(!_overlayOk && !_phaseAsking && !_miniAsking) return;
      // ── 題目沒正常出現,卡死前兆 ──
      console.warn('🚨 [題目可見性] 3 秒後題目沒正常出現 ('+reason+'): '
        + 'overlay.show=' + _overlayOk
        + ', question="' + _questionTxt.slice(0, 30) + '"'
        + ', _advQuizPhase=' + (typeof _advQuizPhase !== 'undefined' ? _advQuizPhase : 'undefined')
        + ', _miniQuizPhase=' + (typeof window._miniQuizPhase !== 'undefined' ? window._miniQuizPhase : 'undefined')
        + ' → 走救援');
      try{ if(typeof log === 'function') log('⚠️ 題目沒能正常出現,系統自動跳過'); }catch(_){}
      // 清掉殘留 flag
      try{
        if(window._bossQuizInFlight){
          console.warn('[題目可見性] 順手清掉殘留 _bossQuizInFlight');
          window._bossQuizInFlight = false;
        }
      }catch(_){}
      // 關掉孤兒 overlay
      try{
        if(_qOv && _overlayOk){
          _qOv.classList.remove('show');
          _qOv.style.display = 'none';
        }
      }catch(_){}
      // 重置 phase
      try{
        if(typeof _advQuizPhase !== 'undefined') _advQuizPhase = 'idle';
      }catch(_){}
      try{
        if(typeof window._miniQuizPhase !== 'undefined') window._miniQuizPhase = 'idle';
      }catch(_){}
      try{
        // ★ v3.5.38 — 救援判定改用「callback 是否存在 + _miniQuizPhase」
        //   v3.5.37 舊版用 _advMiniBattleActive,但開場題(mini-quiz-opening)觸發時
        //   _advMiniBattleActive 可能還是 false(戰鬥剛要開始),或已被 finish 清回 false,
        //   導致救援走錯到 advOnQuizSkip(BOSS 路徑),callback 永遠不被呼叫,_gamePaused
        //   永久 true → 戰鬥卡死(老師 2026-05-22 22:29 console 鐵證)。
        //   新邏輯:只要 _miniQuizOnDone 是 function 或 _miniQuizPhase=='asking',
        //          就走小怪戰救援路徑,不再單靠 _advMiniBattleActive flag。
        const _hasMiniCb = (typeof window._miniQuizOnDone === 'function');
        const _miniPhaseAsking = (typeof window._miniQuizPhase !== 'undefined'
                                  && window._miniQuizPhase === 'asking');
        const _isMiniQuizPath = _hasMiniCb || _miniPhaseAsking ||
                                (typeof _advMiniBattleActive !== 'undefined' && _advMiniBattleActive);
        if(_isMiniQuizPath && _hasMiniCb){
          console.warn('[題目可見性] 小怪戰救援 → 觸發 _miniQuizOnDone');
          const _cb = window._miniQuizOnDone;
          window._miniQuizOnDone = null;
          window._miniQuizCurrentQ = null;
          window._miniQuizOnDoneSetAt = 0;  // ★ v3.4.18 — 同步清時間戳
          // ★ v3.4.13 — 救援時傳 {correct:false},與寵物事件路徑相容
          //   (寵物事件 onDone 簽名是 function(res){ ok = res.correct; },沒參數會走錯)
          try{ _cb({correct:false}); }catch(_eCb){ console.error('[題目可見性] _miniQuizOnDone 拋例外', _eCb); }
        } else if(_isMiniQuizPath){
          // ★ v3.4.13 — 小怪戰中但 _miniQuizOnDone 已被別人清掉(被 _advMiniQuizSubmit 的
          //   setTimeout 搶先消費,或前次救援已 null 但 _gamePaused 還掛著)
          //   此時必須主動把流程推進去,不然就永遠停在 _gamePaused=true
          //   ★ v3.5.38 — 加 _miniQuizPhase reset,避免下一輪檢查仍看到 asking
          console.warn('[題目可見性] 小怪戰救援 → 無 _miniQuizOnDone,強制解 paused+推進');
          try{ window._miniQuizPhase = 'idle'; }catch(_){}
          try{ window._gamePaused = false; }catch(_){}
          try{ if(typeof _gamePaused !== 'undefined') _gamePaused = false; }catch(_){}
          try{ if(typeof _resumeTimers === 'function') _resumeTimers(); }catch(_){}
          // 找下一個沒行動的 p2 接著走
          setTimeout(function(){
            try{
              if(!G || !G.p2) return;
              const _ac = G.activeChar;
              if(_ac && _ac.curHp > 0 && !_ac.acted){
                console.warn('[題目可見性] 推進 activeChar:' + _ac.name);
                if(typeof aiAct === 'function' && _ac.side === 'p2') aiAct(_ac);
                else if(typeof startTurn === 'function') startTurn();
              } else if(typeof startTurn === 'function'){
                startTurn();
              }
            }catch(_eStart){ console.error('[題目可見性] 推進例外', _eStart); }
          }, 400);
        }else if(typeof advOnQuizSkip === 'function'){
          // BOSS 戰救援 → advOnQuizSkip
          advOnQuizSkip();
        }
      }catch(_eSkip){
        console.error('[題目可見性] 救援動作失敗', _eSkip);
      }
    }catch(_eOuter){
      console.warn('[題目可見性 watchdog] 內部例外', _eOuter);
    }
  }, 3000);
}
window._startQuizVisibilityCheck = _startQuizVisibilityCheck;

// 追蹤題目輪次
let _advQuizRound = 0;
let _advSceneChoiceDone = false; // ★ 防止場景選題重複出現
// ★ 近期出過的題目佇列（最多 24 題），用來減少短期內重複
let _advRecentQuestionIds = [];

function advPickQuestion() {
  // ★ v1.0.20260424.0680 — 照顧/狗狗題庫:不彈「重選題目」視窗,自動重洗繼續
  // ★ v3.11.2(2026-05-27) — 修補「會一直出同樣的題目」(BUG #3,玩家 5/27 9:49 回報)
  //   災情:玩家在 maokong 關卡選「五下自然第三單元」,連續幾回合都看到同樣的題目。
  //   根因:該科目玩家已答對 50 題,_filterPersistent 觸發「全部答對自動重置」後,
  //         整池洗牌但池子只有少數題,_advSessionQuestions 殘留舊版,advPickQuestion
  //         的 default 分支雖有 _advRecentQuestionIds(40 題避免池),但對「答對後立刻
  //         又出現同題」的情境保護不夠(池子小時 random 仍會打到剛答對的題)。
  //   修補:把五下自然 3 個專屬題庫(三/四/期中)套同款「本場避免重複池」邏輯,
  //         用 _advUsedQuestionIds 過濾本場已抽過的,池空才呼叫 advGetQuizPool 重洗。
  if (typeof _advPlayerSubject !== 'undefined' &&
      (_advPlayerSubject === '照顧與陪伴幼兒' || _advPlayerSubject === '領養與照顧狗狗'
       || _advPlayerSubject === '世界機關王大賽'
       || _advPlayerSubject === '五下自然第三單元'
       || _advPlayerSubject === '五下自然第四單元'
       // ★ v5.115.0 — 六上自然四單元同款「本場避免重複池」(前綴判定,日後加單元自動涵蓋)
       || (_advPlayerSubject && _advPlayerSubject.indexOf('六上自然') === 0)
       || (_advPlayerSubject && _advPlayerSubject.includes('評量')))) {
    // 從 _advSessionQuestions 中過濾掉本場已用過的
    const _used = _advUsedQuestionIds || new Set();
    let _pool = (_advSessionQuestions || []).filter(q => !_used.has(q.id));
    // 池空 → 重新呼叫 advGetQuizPool 拿新一批(會剔除已答對過的,若都答對則拿全題隨機)
    if (_pool.length === 0) {
      const _fresh = (typeof advGetQuizPool === 'function')
        ? advGetQuizPool(_advPlayerGrade, _advPlayerSubject, _advPlayerDifficulty) : [];
      _advSessionQuestions = _fresh;
      _advQuestionPool = _fresh;
      _advUsedQuestionIds = new Set();
      _pool = _fresh;
      try { log(`📚 [${_advPlayerSubject}] 本場題目用完,自動重洗(已答對的不會再出)。`); } catch(_){}
    }
    if (!_pool.length) return null;
    const _chosen = _pool[Math.floor(Math.random() * _pool.length)];
    // ★ v3.11.2 — 抽到後立刻 add 到 _advUsedQuestionIds(本場避免重複)
    //   只對五下自然 3 個科目加,不動照顧/狗狗的既有行為
    //   (照顧/狗狗用 _medalStats.careInfantUsed/dogCareUsed 走 streak 連對記錄,
    //    答錯不記、答對才記,跟五下自然「本場任何抽過都不再抽」邏輯不同)
    if(_chosen && _chosen.id != null
       && (_advPlayerSubject === '五下自然第三單元'
         || _advPlayerSubject === '五下自然第四單元'
         || (_advPlayerSubject && _advPlayerSubject.indexOf('六上自然') === 0)   // ★ v5.115.0
         || (_advPlayerSubject && _advPlayerSubject.includes('評量')))){
      if(!_advUsedQuestionIds || typeof _advUsedQuestionIds.add !== 'function'){
        _advUsedQuestionIds = new Set();
      }
      _advUsedQuestionIds.add(_chosen.id);
    }
    return _chosen;
  }
  // ★ v1.0.20260423.0100 — 日本關洗牌制:100 題全部出完才重新洗牌,期間保證不重複
  //   (取代原本「最近 40 題避免池」的軟性機制,真正的 shuffle-bag 發牌)
  if(typeof _adventureStage !== 'undefined' && _adventureStage === 'japan'){
    if(!Array.isArray(window._japanShuffleBag) || !window._japanShuffleBag.length){
      const _jpAll = ADV_QUIZ_DB.filter(q => q.subject === '日本關').slice();
      for(let i = _jpAll.length - 1; i > 0; i--){
        const j = Math.floor(Math.random() * (i + 1));
        [_jpAll[i], _jpAll[j]] = [_jpAll[j], _jpAll[i]];
      }
      window._japanShuffleBag = _jpAll;
      // ★ v1.0.20260423.1500 — bag 重置時也清空 _miniQuizUsedIds,讓小怪戰和 BOSS 共用
      //   同一輪次的「未出題」狀態
      try{ if(window._miniQuizUsedIds) window._miniQuizUsedIds.clear(); }catch(_){}
      try{ log(`📚 [日本關] 題庫已重新洗牌,共 ${_jpAll.length} 題,下一輪前保證不重複。`); }catch(_){}
    }
    return window._japanShuffleBag.shift() || null;
  }
  if(typeof _adventureStage !== 'undefined' && _adventureStage === 'taiwan'){
    if(!(window._taiwanRoundUsedIds instanceof Set)) window._taiwanRoundUsedIds = new Set();
    if(!Array.isArray(window._taiwanShuffleBag) || !window._taiwanShuffleBag.length){
      const _twBossId = window._advSelectedTaiwanBoss;
      const _twAllOriginal = (typeof TAIWAN_QUIZ_DB !== 'undefined' && _twBossId)
        ? TAIWAN_QUIZ_DB.filter(q => q.bossId === _twBossId).slice()
        : (typeof TAIWAN_QUIZ_DB !== 'undefined' ? TAIWAN_QUIZ_DB.slice() : []);
      // ★ v1.0.20260428.4070 — 依玩家難度過濾出選項數合適的題目
      const _curDiff = (typeof _advPlayerDifficulty === 'string') ? _advPlayerDifficulty : '';
      let _wantOptCount = 4;
      if(_curDiff.indexOf('沒自信') >= 0) _wantOptCount = 2;
      else if(_curDiff.indexOf('普通') >= 0) _wantOptCount = 3;
      else _wantOptCount = 4;
      const _byOptCount = _twAllOriginal.filter(q =>
        q && Array.isArray(q.options) && q.options.length === _wantOptCount);
      let _twAll = _byOptCount.length > 0 ? _byOptCount : _twAllOriginal;
      // ★ v1.1.0 — 過濾「本場已出過」的題目
      const _notUsedThisRound = _twAll.filter(q => !window._taiwanRoundUsedIds.has(q.id));
      if(_notUsedThisRound.length > 0){
        // 還有沒出過的題目 → 從這些挑
        _twAll = _notUsedThisRound;
        try{ console.log('[台灣關抽題] 難度='+_curDiff+', 過濾出 '+_wantOptCount+' 選項題,本場剩餘未出 '+_notUsedThisRound.length+' 題'); }catch(_){}
      } else {
        // 全部題目都出過了 → 清空本場記錄,重新一輪
        try{ console.log('[台灣關抽題] 全部題目已答過一輪,清空已出記錄重新洗牌(共 '+_twAll.length+' 題)'); }catch(_){}
        try{ log('🔄 [台灣關] 全部題目已答過一輪,重新洗牌!'); }catch(_){}
        window._taiwanRoundUsedIds.clear();
      }
      // 過濾跨關卡持久已答對(只在還有「未出+未答對」題目時才套用,避免兩個過濾把池子掏空)
      let _twPool = _twAll;
      try{
        if(typeof _persistentCorrectQuestions === 'object' && _persistentCorrectQuestions['台灣環島']){
          const _correctSet = _persistentCorrectQuestions['台灣環島'];
          const _filtered = _twAll.filter(q => !_correctSet[q.id]);
          if(_filtered.length > 0) _twPool = _filtered;
        }
      }catch(_){}
      // Fisher-Yates 洗牌
      for(let i = _twPool.length - 1; i > 0; i--){
        const j = Math.floor(Math.random() * (i + 1));
        [_twPool[i], _twPool[j]] = [_twPool[j], _twPool[i]];
      }
      window._taiwanShuffleBag = _twPool;
      try{ if(window._miniQuizUsedIds) window._miniQuizUsedIds.clear(); }catch(_){}
      try{ log('📚 [台灣關] 題庫已重新洗牌,共 ' + _twPool.length + ' 題。'); }catch(_){}
    }
    let _twQ = window._taiwanShuffleBag.shift() || null;
    // ★ v1.1.0 — 抽出題目後,記錄到「本場已出」集合
    if(_twQ && _twQ.id != null && (window._taiwanRoundUsedIds instanceof Set)){
      window._taiwanRoundUsedIds.add(_twQ.id);
    }
    // ★ v1.0.20260428.4070 — 既然已依難度過濾選項數,這裡不用再 trim,題目原本就是對的選項數
    return _twQ;
  }
  const used = _advUsedQuestionIds;
  let pool = _advSessionQuestions.filter(q => !used.has(q.id));
  // 按科目過濾（如有）
  // ★ v3.17.9 — 修正:原本只是把符合科目的題目排到前面、再把其他科目的題目整包接在後面
  //   (pool = [...subPool, ...其他科目]),但下面抽題是「整個 pool 隨機挑一個 index」,
  //   排序對隨機挑選毫無作用 → 等於完全沒過濾,玩家選了「自然」實際上什麼科目都可能抽到
  //   (學生回報:選自然,結果出現的全是隨機主題)。改成真正限縮 pool,只留符合科目的題目;
  //   若當下真的一題都不剩(該科目本輪已抽完)才交給下面「pool.length===0」的補題邏輯處理。
  if (_advPlayerSubject) {
    const subjectMap = {'國語文':'國語文','英文':'英文','數學':'數學','自然':'自然','社會':'社會','音樂':'音樂','美術':'美術'};
    const subj = subjectMap[_advPlayerSubject];
    if (subj) {
      const subPool = pool.filter(q => q.subject === subj);
      if (subPool.length > 0) pool = subPool;   // 真正過濾,不再把其他科目題目接回來
    }
  }
  if (pool.length === 0) {
    // ★ 題目全部出過一輪：重置後繼續出題
    _advQuizRound++;
    _advUsedQuestionIds.clear();
    // ★ v1.0.20260423.1500 — 木柵關/其他關卡 BOSS 題庫耗盡時,同步清空
    //   _miniQuizUsedIds,讓下一輪小怪戰也從完整題庫重新出題
    try{ if(window._miniQuizUsedIds) window._miniQuizUsedIds.clear(); }catch(_){}
    // ★ v3.13.33(2026-06-04) — 老師回報「鬥技場無法正常出現題目 + 整輪 304/305 迴圈」
    //   根因:_advSessionQuestions 在鬥技場下某些路徑可能是空 array(初始化失敗 / 被某流程清掉),
    //         原本走 needRepick 路徑 → setTimeout 150ms 無限重試 → 304/305 整輪迴圈
    //   修補:鬥技場 + 世界 BOSS 不走 needRepick,直接用 ADV_QUIZ_DB 兜底洗牌補滿 pool
    try{
      const _isArenaPick = (typeof _adventureMode !== 'undefined' && !_adventureMode
                            && typeof G !== 'undefined' && G && G.p1 && G.p2);
      const _isWbStagePick = (typeof _adventureStage !== 'undefined' && _adventureStage === 'worldboss');
      if((_isArenaPick || _isWbStagePick)
         && (!Array.isArray(_advSessionQuestions) || _advSessionQuestions.length === 0)
         && typeof ADV_QUIZ_DB !== 'undefined' && Array.isArray(ADV_QUIZ_DB) && ADV_QUIZ_DB.length){
        const _bp = ADV_QUIZ_DB.slice();
        for(let _bi = _bp.length - 1; _bi > 0; _bi--){
          const _bj = Math.floor(Math.random() * (_bi + 1));
          [_bp[_bi], _bp[_bj]] = [_bp[_bj], _bp[_bi]];
        }
        _advSessionQuestions = _bp;
        if(typeof _advQuestionPool !== 'undefined') _advQuestionPool = _bp;
        pool = _bp;
        console.log('[advPickQuestion] ' + (_isArenaPick ? '鬥技場' : '世界 BOSS')
                    + '題庫兜底:從 ADV_QUIZ_DB 洗牌補滿 ' + _bp.length + ' 題');
        // 不 return needRepick,直接往下走到隨機選題邏輯
      } else {
        try{ log(`📚 [題庫] 整輪 ${_advQuizRound} 題庫已全部出過,重新開始新一輪(不重複保證延續)。`); }catch(_){}
        // ★ v3.15.25(2026-06-17)— 老師需求:戰鬥題目出完後自動從頭循環、避免卡死。
        //   原本 BOSS 戰回傳 __needRepick → advShowQuiz 隔 150ms 重觸發再抽一次;但若 _advSessionQuestions
        //   此時是空陣列(某些路徑沒初始化/被清掉),重觸發後 advPickQuestion 仍走到空池 → 又回傳 __needRepick
        //   → 150ms 無限重觸發、題目永遠不出 → 卡死。修法:只在「session 題庫非空(剛清完 used、重觸發保證
        //   抽得到)」時才走 __needRepick;session 為空時直接用 ADV_QUIZ_DB 兜底洗牌補回 _advSessionQuestions、
        //   當場往下抽 → 必出題、從頭循環不卡。
        if(_advQuizResolveCb && !_advMiniBattleActive
           && Array.isArray(_advSessionQuestions) && _advSessionQuestions.length > 0){
          return { __needRepick: true };
        }
        // 小怪戰 / session 為空 / 其他情況:直接兜底,保證有題可出(從頭循環)
        if((!Array.isArray(_advSessionQuestions) || _advSessionQuestions.length === 0)
           && typeof ADV_QUIZ_DB !== 'undefined' && Array.isArray(ADV_QUIZ_DB) && ADV_QUIZ_DB.length){
          // ★ v3.17.9 — 修正:原本直接兜底整個 ADV_QUIZ_DB(不分科目)重新洗牌 → 玩家選的科目(如「自然」)
          //   一旦題目抽完觸發此兜底,後面就會開始出現任何科目的題目(學生回報的根因之一)。
          //   改為:若玩家有選科目,先用 advGetQuizPool 依科目重新抽一批(邏輯與初次進題庫相同);
          //   真的抽不到(科目題庫本身是空的)才退回全題庫兜底,保證不會卡死。
          let _fbAll = null;
          if (_advPlayerSubject && typeof advGetQuizPool === 'function') {
            try{ _fbAll = advGetQuizPool(_advPlayerGrade, _advPlayerSubject, _advPlayerDifficulty); }catch(_eSubjRefill){ _fbAll = null; }
          }
          if (!Array.isArray(_fbAll) || !_fbAll.length) {
            _fbAll = ADV_QUIZ_DB.slice();
            for(let _fbi = _fbAll.length - 1; _fbi > 0; _fbi--){ const _fbj = Math.floor(Math.random()*(_fbi+1)); const _t=_fbAll[_fbi]; _fbAll[_fbi]=_fbAll[_fbj]; _fbAll[_fbj]=_t; }
          }
          _advSessionQuestions = _fbAll;
          if(typeof _advQuestionPool !== 'undefined') _advQuestionPool = _fbAll;
          try{ log('📚 [題庫] session 題庫為空,改用' + (_advPlayerSubject ? ('「'+_advPlayerSubject+'」科目') : '完整') + '題庫(' + _fbAll.length + '題)從頭循環。'); }catch(_){}
        }
        pool = (Array.isArray(_advSessionQuestions) && _advSessionQuestions.length)
               ? _advSessionQuestions
               : (typeof ADV_QUIZ_DB !== 'undefined' ? ADV_QUIZ_DB : []);
        if(!pool.length) return null;
      }
    }catch(_ePickFb){
      console.warn('[advPickQuestion 兜底] 例外', _ePickFb);
      try{ log(`📚 [題庫] 整輪 ${_advQuizRound} 題庫已全部出過,重新開始新一輪(不重複保證延續)。`); }catch(_){}
      // ★ v3.15.25 — 同上:session 非空才走 __needRepick 重觸發,否則直接兜底保證有題(避免無限重觸發卡死)
      if(_advQuizResolveCb && !_advMiniBattleActive
         && Array.isArray(_advSessionQuestions) && _advSessionQuestions.length > 0){
        return { __needRepick: true };
      }
      // ★ v3.17.9 — 同上:例外兜底也優先嘗試依科目重新抽題,抽不到才退回全題庫
      let _fbAllCatch = null;
      if (_advPlayerSubject && typeof advGetQuizPool === 'function'
          && (!Array.isArray(_advSessionQuestions) || !_advSessionQuestions.length)) {
        try{ _fbAllCatch = advGetQuizPool(_advPlayerGrade, _advPlayerSubject, _advPlayerDifficulty); }catch(_eSubjRefillCatch){ _fbAllCatch = null; }
        if (Array.isArray(_fbAllCatch) && _fbAllCatch.length) _advSessionQuestions = _fbAllCatch;
      }
      pool = (Array.isArray(_advSessionQuestions) && _advSessionQuestions.length)
             ? _advSessionQuestions
             : (typeof ADV_QUIZ_DB !== 'undefined' ? ADV_QUIZ_DB : []);
      if(!pool.length) return null;
    }
  }
  // ★ 出題隨機性強化：
  //    1) 先在整個 pool（整個未出現過題庫的剩餘題）隨機抽
  //    2) 並額外以最近出過的 24 題為避免池，優先挑未在近期出現過的題
  const _recent = (_advRecentQuestionIds && _advRecentQuestionIds.length) ? _advRecentQuestionIds : [];
  const _fresh = pool.filter(q => !_recent.includes(q.id));
  const _picked = _fresh.length ? _fresh : pool;
  const _chosen = _picked[Math.floor(Math.random() * _picked.length)] || null;
  // 維護最近出現佇列
  if(_chosen){
    if(!Array.isArray(_advRecentQuestionIds)) _advRecentQuestionIds = [];
    _advRecentQuestionIds.push(_chosen.id);
    if(_advRecentQuestionIds.length > 40) _advRecentQuestionIds.shift();
  }
  return _chosen;
}

