// ═══════════════════════════════════════════════════════════════════
// ★★★★★ v3.6.0 — 新回合答題系統(取代舊版「全局暫停」式 quiz) ★★★★★
// ───────────────────────────────────────────────────────────────────
// 設計目標:
//   1. 答題只在「新回合開始」觸發一次,固定時機,流程簡單
//   2. 答題期間「只暫停對手行動」,不再用 _gamePaused 整局凍結
//   3. 30 秒硬性超時,超時=答錯,絕不無限等待
//   4. 答對的獎勵可選「立即使用」或「存到技能格 3」
//   5. 技能格 3「知識化為力量」:任何回合可額外免費發動一次
//
// 與舊版的根本差別:
//   舊版 _gamePaused=true → 整個 timer 系統 queue → 任何環節 bug 全卡死
//   新版 _advRoundQuizPending=true → 只攔 aiAct,玩家可以正常看畫面
// ═══════════════════════════════════════════════════════════════════

// 新回合答題狀態旗標(輕量級,只攔 aiAct)
window._advRoundQuizPending = false;
// 上一個觸發答題的回合(避免同回合重複觸發)
window._advLastQuizRound = 0;
// 30 秒超時 watchdog
window._advRoundQuizTimeout = null;
// 技能格 3「知識化為力量」儲存的獎勵
window._advKnowledgePowerReward = null;

// 是否需要在這個回合開頭觸發新回合答題
function _advShouldStartRoundQuiz(){
  try{
    // ★ v3.14.6 — PvP 連線對戰:停用內建答題(其 _gamePaused 暫停機制與雙端同步互斥),
    //   改由 PvP 模組的「20 秒非暫停答題面板」處理(答對 +1 能量,各答各的)。
    if(window._pvpCtx && window._pvpCtx.battleLive) return false;
    // ★ v3.13.15(2026-06-02) — 鬥技場也走「每回合開場答題」流程
    //   原本第一行 if(!_adventureMode) return false 會擋掉鬥技場
    //   改判:冒險模式 或 鬥技場 都通過(其他場景如主選單 G 不存在會被下一條擋掉)
    if(typeof G === 'undefined' || !G) return false;
    const _isAdv = (typeof _adventureMode !== 'undefined' && _adventureMode);
    const _isArena = (typeof _adventureMode !== 'undefined' && !_adventureMode && G && G.p1 && G.p2);
    if(!_isAdv && !_isArena) return false;
    // 已經在答題中 → 不重複觸發
    if(window._advRoundQuizPending) return false;
    // 答題流程進行中 → 不重複觸發
    if(typeof _advQuizPhase !== 'undefined' && _advQuizPhase !== 'idle') return false;
    // 同回合已觸發過 → 不重複
    const _curR = G.round || 1;
    if(window._advLastQuizRound === _curR) return false;
    // ★ v3.13.25(2026-06-02) — 鬥技場第 1 回合也要答題(老師裁示,鐵律 1.160)
    //   冒險模式第 1 回合不答(因為已有 cutscene 開場流程);
    //   鬥技場沒有 cutscene,所以第 1 回合就要先答題再行動。
    //   _isArena 用 _arenaBgmContext 或 _adventureMode===false 偵測(已在上面定義)
    if(_curR <= 1 && !_isArena) return false;
    // 戰鬥已結束
    if(typeof checkWin === 'function' && checkWin()) return false;
    // 世界 BOSS 戰 — 只有房主負責答題(client 端不主動觸發,等 host sync)
    if(typeof _adventureStage !== 'undefined' && _adventureStage === 'worldboss'){
      if(window._wbConnectedClientMode === true) return false;
    }
    // 玩家全滅
    if(!G.p1 || !G.p1.some(h => h && h.curHp > 0)) return false;
    // 敵方全滅
    if(!G.p2 || !G.p2.some(h => h && h.curHp > 0)) return false;
    // 過場/對白/結算中
    const _blockingIds = ['adv-cutscene-overlay','adv-dialog-box','adv-result-overlay',
                          'adv-mini-result','adv-boss-intro','battle-start-overlay',
                          'taiwan-cutscene-overlay','taiwan-dialog-overlay'];
    for(const _id of _blockingIds){
      const _el = document.getElementById(_id);
      if(_el && (_el.classList.contains('show')
                 || (_el.style.display && _el.style.display !== 'none'))){
        return false;
      }
    }
    return true;
  }catch(e){ console.warn('[v3.6.0 _advShouldStartRoundQuiz] 例外', e); return false; }
}

// 主入口:啟動新回合答題
function _advStartRoundQuiz(){
  try{
    if(!_advShouldStartRoundQuiz()) return false;
    const _curR = (G && G.round) || 1;
    // ★ v3.6.0 — _advLastQuizRound 改在「真的答完」才設(_advFinishRoundQuiz 內),
    //   避免「答題中當機 → 恢復後跳過答題」漏洞。玩家答題答到一半當機,
    //   恢復後 _advLastQuizRound 仍是上一輪的回合數,_advShouldStartRoundQuiz 判斷該觸發,
    //   會重新出題,公平合理。
    // ★ v3.13.81 防迴圈卡死 — 同一回合的新回合答題若「重複觸發多次卻從未答完」
    //   (典型:答題視窗被 item-panel/背包蓋住或 race → 觸發→startTurn 孤兒清除→再觸發
    //    無限循環,對手永遠輪不到行動 = 玩家回報「對手不動卡死」)。正常回合只會觸發 1 次
    //   (答完即設 _advLastQuizRound→不再觸發),故觸發 ≥3 次必為卡死迴圈:直接標記本回合
    //   已答、跳過答題讓戰鬥推進(寧可少答一回合題也不要永久卡死;鐵律 1.231)。
    try{
      const _trR = _curR;
      if(window._advRoundQuizTrigRound !== _trR){ window._advRoundQuizTrigRound = _trR; window._advRoundQuizTrigCount = 0; }
      window._advRoundQuizTrigCount = (window._advRoundQuizTrigCount || 0) + 1;
      if(window._advRoundQuizTrigCount >= 3){
        console.warn('[防迴圈卡死 v3.13.81] 第 ' + _trR + ' 回合新回合答題重複觸發 ' + window._advRoundQuizTrigCount + ' 次仍未答完 → 視為卡死迴圈,跳過本回合答題並推進對手行動');
        window._advLastQuizRound = _trR;
        window._advRoundQuizPending = false;
        try{ if(typeof _advQuizPhase !== 'undefined' && _advQuizPhase !== 'idle') _advQuizPhase = 'idle'; }catch(_){}
        return false;
      }
    }catch(_eLoop){}
    window._advRoundQuizPending = true;
    console.log('🎓 [v3.6.0 新回合答題] 觸發, round=' + _curR + ', stage=' +
                (typeof _adventureStage !== 'undefined' ? _adventureStage : '?'));

    // 設定 quiz cb:答完根據對錯決定獎勵或懲罰
    _advQuizResolveCb = function(){
      try{
        const _isCorrect = (typeof _advStats !== 'undefined' && _advStats
                           && _advStats.lastAnswerCorrect === true);
        // 清除 30 秒 watchdog
        if(window._advRoundQuizTimeout){
          clearTimeout(window._advRoundQuizTimeout);
          window._advRoundQuizTimeout = null;
        }
        if(_isCorrect){
          // 答對 → 顯示獎勵選擇
          console.log('🎓 [v3.6.0] 答對,顯示獎勵');
          // ★ v3.7.6 — v3.5.71 的 _wbOnQuizCorrect hook 已移除(移到 advSubmitAnswer 答對路徑)
          //   背景:這條 cb 本來就不會在「答對」路徑被呼叫(advSubmitAnswer 答對直接呼叫 advShowReward,
          //         完全繞過 _advQuizResolveCb),所以 v3.5.71 的 hook 一直是 dead code。
          //   現在 _wbOnQuizCorrect 改在 advSubmitAnswer 答對 setTimeout 內呼叫(line ~54330 區),
          //         確保 BOSS 行動前 quiz 與新回合答題答對都能觸發聯手爆發 5/10/15/20。
          //   這條 cb 只剩「答錯」會走,所以下方 else 分支仍正常運作。
          try{ advShowReward(); }catch(eR){
            console.warn('[v3.6.0] advShowReward 例外,直接解鎖', eR);
            _advFinishRoundQuiz();
          }
        } else {
          // 答錯 → 龍王打最低血英雄(維持既有規則)+ 解鎖戰鬥
          console.log('🎓 [v3.6.0] 答錯,套用懲罰');
          _advRoundQuizPenalty();
          _advFinishRoundQuiz();
        }
      }catch(eCb){
        console.warn('[v3.6.0] quiz cb 例外', eCb);
        _advFinishRoundQuiz();
      }
    };

    // 30 秒超時 watchdog
    if(window._advRoundQuizTimeout){
      clearTimeout(window._advRoundQuizTimeout);
    }
    window._advRoundQuizTimeout = setTimeout(function(){
      console.warn('🎓 [v3.6.0] 30 秒超時,視為答錯');
      try{
        if(typeof _advStats !== 'undefined' && _advStats){
          _advStats.lastAnswerCorrect = false;
        }
      }catch(_){}
      try{
        const _qOv = document.getElementById('adv-quiz-overlay');
        if(_qOv){
          _qOv.classList.remove('show');
          _qOv.style.display = 'none';
        }
      }catch(_){}
      _advRoundQuizPenalty();
      _advFinishRoundQuiz();
    }, 30000);

    // 啟動 quiz overlay
    try{
      if(typeof advShowQuiz === 'function'){
        advShowQuiz();
      } else {
        console.warn('[v3.6.0] advShowQuiz 不存在,跳過答題');
        _advFinishRoundQuiz();
      }
    }catch(eShow){
      console.warn('[v3.6.0] advShowQuiz 拋例外', eShow);
      _advFinishRoundQuiz();
    }
    // ★ v3.13.26(2026-06-02) — 鬥技場 AI 公平性:玩家答題的同時,AI 必定獲得 1 個答題獎勵
    //   設計理念:AI 無法操作答題介面,為公平起見,每回合 AI 必定獲得 1 個獎勵(等於 100% 答對)
    //   玩家答錯時自己沒獎勵但 AI 仍有 — 這是「答對與否的價值」,玩家答對才能跟 AI 同步取得獎勵
    //   延遲 1500ms 讓玩家先看到題目與 AI 獎勵 banner,不打架
    try{
      const _isArenaCtx = (typeof _adventureMode !== 'undefined' && !_adventureMode
                          && G && G.p1 && G.p2);
      if(_isArenaCtx && typeof _arenaAIPickAndApplyReward === 'function'){
        setTimeout(function(){
          try{ _arenaAIPickAndApplyReward(); }catch(_eAIRw){
            console.warn('[鬥技場 AI 答題獎勵] 例外', _eAIRw);
          }
        }, 1500);
      }
    }catch(_eAITrig){ console.warn('[鬥技場 AI 答題獎勵觸發] 例外', _eAITrig); }
    return true;
  }catch(e){
    console.warn('[v3.6.0 _advStartRoundQuiz] 例外', e);
    _advFinishRoundQuiz();
    return false;
  }
}

// ════════════════════════════════════════════════════════════════════
// ★ v3.13.26(2026-06-02) — 鬥技場 AI 答題獎勵(鐵律 1.163)
// ────────────────────────────────────────────────────────────────────
// 設計目標:
//   AI 無法操作答題介面,為公平起見,每回合玩家被觸發答題的同時,
//   AI 必定獲得 1 個答題獎勵(視同 100% 答對),由智能邏輯自動選擇最有用的並對 P2 釋放。
//
// 套用對象:
//   AI 自家 = G.p2(友方獎勵對 p2 套用)
//   AI 敵方 = G.p1(攻擊性獎勵對 p1 套用)
//   ★ 嚴禁搞反方向 — 例如 dmg_all 對 G.p2 套會打到自己人,嚴重 BUG
//
// 智能優先序(從上往下檢查,第一個滿足條件就選):
//   (1) 有 AI 隊友倒下          → revive
//   (2) AI 隊友任一 HP<30%       → fullheal_min
//   (3) AI 隊友身上有 ≥3 不利狀態 → cleanse
//   (4) AI 全隊平均 HP<50%       → heal_50
//   (5) AI 能量<5               → full_energy
//   (6) 玩家有 ≥3 個有利狀態     → remove_buff
//   (7) 玩家平均 HP≥70%          → dmg_all (全敵 20% 當前 HP)
//   (8) 有玩家 HP<50%(可集火)   → dmg_one
//   (9) 沒被控制的玩家 ≥1        → stun_enemy
//  (10) 隨機:invincible_team 或 dmg_all
//  (11) 保底:heal_50
//
// 排除的獎勵(原冒險模式專用,鬥技場 AI 不適合):
//   - boss_skip:鬥技場 P2 不是 BOSS,封印行動沒邏輯
//   - instant_burst:AI 沒爆發目標選擇 UI 流程
//   - get_pet / get_card:涉及背包 UI,AI 不該觸發
//   - remove_pet:冒險戰用,鬥技場 P1 沒有寵物
// ════════════════════════════════════════════════════════════════════
function _arenaAIPickAndApplyReward(){
  try{
    // 鬥技場前置防呆:不在鬥技場直接 return
    if(typeof _adventureMode !== 'undefined' && _adventureMode) return;
    if(!G || !Array.isArray(G.p1) || !Array.isArray(G.p2)) return;
    // 戰鬥已結束就跳過
    if(typeof checkWin === 'function' && checkWin()) return;
    const _aiAlive = G.p2.filter(h => h && h.curHp > 0);
    if(!_aiAlive.length) return;  // AI 全滅就沒必要套
    const _foeAlive = G.p1.filter(h => h && h.curHp > 0);
    if(!_foeAlive.length) return;

    // ─── 1. 智能挑選獎勵 ───
    const _aiDead = G.p2.filter(h => h && h.curHp === 0);
    const _aiLowest = _aiAlive.reduce((lo, h) => (h.curHp / h.hp < lo.curHp / lo.hp ? h : lo), _aiAlive[0]);
    const _aiAvgHpPct = _aiAlive.reduce((sum, h) => sum + (h.curHp / h.hp), 0) / _aiAlive.length;
    const _aiTotalBadStatus = _aiAlive.reduce((sum, h) => sum + ((h.status || []).length), 0);
    const _aiEnergy = (G.energy && G.energy.p2) || 0;
    const _foeAvgHpPct = _foeAlive.reduce((sum, h) => sum + (h.curHp / h.hp), 0) / _foeAlive.length;
    const _foeLowHp = _foeAlive.filter(h => h.curHp / h.hp < 0.5);
    const _foeBuffTotal = _foeAlive.reduce((sum, h) => sum + ((h.buffs || []).length), 0);
    const _foeNoStun = _foeAlive.filter(h => !(h.status || []).some(s => s && (s.t === 'stun' || s.t === 'freeze' || s.t === 'sleep')));

    let _pickedId = null;
    // ★ v3.13.42(2026-06-04) — 任務5:鬥技場移除「奇蹟復活(revive)/補滿血(fullheal_min)」,
    //   AI 也不再選這兩個(原本 (1)有人倒下→revive (2)有人<30%→fullheal_min 兩條移除),
    //   低血情況改走 heal_50(全體回 50%),與玩家端一致(公平)。
    if(_aiTotalBadStatus >= 3){
      _pickedId = 'cleanse';
    } else if(_aiAvgHpPct < 0.5 || _aiAlive.some(h => h.curHp / h.hp < 0.3)){
      _pickedId = 'heal_50';
    } else if(_aiEnergy < 5){
      _pickedId = 'full_energy';
    } else if(_foeBuffTotal >= 3){
      _pickedId = 'remove_buff';
    } else if(_foeAvgHpPct >= 0.7){
      _pickedId = 'dmg_all';
    } else if(_foeLowHp.length > 0){
      _pickedId = 'dmg_one';
    } else if(_foeNoStun.length > 0){
      _pickedId = 'stun_enemy';
    } else {
      // 都不符合就 50/50 隨機選無敵或全體傷害
      _pickedId = (Math.random() < 0.5) ? 'invincible_team' : 'dmg_all';
    }

    console.log('[鬥技場 AI 答題獎勵] 已選擇:' + _pickedId
      + ' | AI 平均 HP=' + Math.round(_aiAvgHpPct*100) + '%'
      + ', 玩家平均 HP=' + Math.round(_foeAvgHpPct*100) + '%'
      + ', AI 能量=' + _aiEnergy
      + ', AI 倒下=' + _aiDead.length);

    // ─── 2. 對 G.p2(AI 友方)/ G.p1(AI 敵方)套用獎勵 ───
    //   ⚠ 方向絕對不能搞反:友方獎勵對 G.p2、攻擊獎勵對 G.p1
    _arenaAIApplyReward(_pickedId);

    // ─── 3. 顯示提示 banner(讓玩家知道 AI 拿了什麼獎勵)─
    try{
      const _rwDef = (typeof ADV_REWARDS !== 'undefined')
        ? ADV_REWARDS.find(r => r.id === _pickedId)
        : null;
      const _rwLabel = _rwDef ? (_rwDef.icon + ' ' + _rwDef.name) : _pickedId;
      // 在 AI 隊伍區域中央顯示 banner
      const _aiBannerTarget = _aiAlive[0];
      if(_aiBannerTarget && typeof bannerFX === 'function'){
        bannerFX(_aiBannerTarget, '🤖 對手獲得獎勵:' + _rwLabel, '#aa99ff', 1500);
      }
      if(typeof log === 'function'){
        log('🤖 對手隊伍答題獎勵:' + _rwLabel + '(智能選擇)');
      }
    }catch(_eBanner){ console.warn('[AI 獎勵 banner]', _eBanner); }
  }catch(e){
    console.warn('[_arenaAIPickAndApplyReward] 例外', e);
  }
}

// ════════════════════════════════════════════════════════════════════
// ★ v3.13.26 — AI 套用獎勵實作(P1↔P2 完全鏡像 advApplyReward 邏輯)
// ────────────────────────────────────────────────────────────────────
// ⚠ 關鍵:AI 友方 = G.p2、AI 敵方 = G.p1
//     不是 copy & paste advApplyReward 直接替換 p1↔p2 就好,
//     許多細節(如 G.energy.p2、actor 設置等)要逐一檢查
// ════════════════════════════════════════════════════════════════════
function _arenaAIApplyReward(id){
  if(!G || !Array.isArray(G.p1) || !Array.isArray(G.p2)) return;
  try{
    if(id === 'fullheal_min'){
      // AI 隊友 HP% 最低者補滿
      const _aiAlive = G.p2.filter(x => x.curHp > 0);
      if(!_aiAlive.length) return;
      const h = _aiAlive.sort((a,b) => (a.curHp / a.hp) - (b.curHp / b.hp))[0];
      if(h){
        const _prev = h.curHp;
        h.curHp = h.hp;
        try{ renderCard(h); }catch(_){}
        try{ showPopup(h, '+' + (h.hp - _prev), 'heal'); }catch(_){}
        try{ if(typeof healParticles === 'function') healParticles(h); }catch(_){}
        try{ bannerFX(h, '💖 滿血!', '#ff88cc', 900); }catch(_){}
        try{ playSfx('sfx-heal', 0.9); }catch(_){}
        try{ if(typeof ringFX === 'function') ringFX(h, '#ff88cc', 700); }catch(_){}
        log('[對手獎勵] ' + h.name + ' 恢復滿血!');
      }
    } else if(id === 'revive'){
      // AI 隊友倒下者隨機 1 名復活
      const _aiDead = G.p2.filter(x => x.curHp === 0);
      if(_aiDead.length){
        const h = _aiDead[Math.floor(Math.random() * _aiDead.length)];
        try{ doRevive(h, 1.0); }catch(_){}
        try{ if(typeof healParticles === 'function') healParticles(h); }catch(_){}
        try{ if(typeof ringFX === 'function') ringFX(h, '#ffcc44', 700); }catch(_){}
        try{ bannerFX(h, '💫 奇蹟復活!', '#ffcc44', 900); }catch(_){}
        try{ playSfx('sfx-revive', 0.9); }catch(_){}
        log('[對手獎勵] ' + h.name + ' 完全復活!');
      }
    } else if(id === 'full_energy'){
      // ⚠ AI 能量是 G.energy.p2,不是 .p1
      G.energy.p2 = 10;
      try{ updateUI(); }catch(_){}
      try{
        G.p2.filter(h => h.curHp > 0).forEach(h => {
          try{ showPopup(h, '+E', 'energy'); }catch(_){}
          try{ if(typeof ringFX === 'function') ringFX(h, '#4a9eff', 500); }catch(_){}
        });
      }catch(_){}
      try{ playSfx('sfx-powerup', 0.85); }catch(_){}
      try{ flashScreen('rgba(74,158,255,0.4)', 300); }catch(_){}
      log('[對手獎勵] 對手能量全滿!');
    } else if(id === 'cleanse'){
      // AI 隊友全員清不利狀態
      G.p2.forEach(h => {
        if(h.curHp > 0){
          try{ if(typeof clearBadStatus === 'function') clearBadStatus(h); }catch(_){}
          try{ renderCard(h); }catch(_){}
          try{ if(typeof ringFX === 'function') ringFX(h, '#ffffaa', 600); }catch(_){}
          try{ bannerFX(h, '✨ 淨化!', '#ffffaa', 800); }catch(_){}
        }
      });
      try{ flashScreen('rgba(255,255,150,0.4)', 350); }catch(_){}
      try{ playSfx('sfx-passive', 0.85); }catch(_){}
      log('[對手獎勵] 對手全體狀態清除!');
    } else if(id === 'stun_enemy'){
      // ⚠ 暈眩玩家(G.p1)1 名
      const _foes = G.p1.filter(x => x.curHp > 0);
      if(_foes.length){
        const t = (typeof _pickWeightedTarget === 'function')
          ? (_pickWeightedTarget(_foes) || _foes[0])
          : _foes[Math.floor(Math.random() * _foes.length)];
        try{ addStatus(t, 'stun', 1); }catch(_){}
        try{ showPopup(t, '🌀暈眩', 'dmg'); }catch(_){}
        try{ if(typeof flashCard === 'function') flashCard(t, 'rgba(180,80,255,0.7)', 400); }catch(_){}
        try{ bannerFX(t, '🌀 靜止封印!', '#cc88ff', 900); }catch(_){}
        try{ playSfx('sfx-cantmove', 0.85); }catch(_){}
        log('[對手獎勵] ' + t.name + ' 被封印 1 回合!');
      }
    } else if(id === 'heal_50'){
      // AI 隊友全員回 50% HP
      G.p2.forEach(h => {
        if(h.curHp > 0){
          const _amt = Math.floor(h.hp * 0.5);
          try{
            if(typeof doHeal === 'function'){
              doHeal(h, _amt, { isMassHeal:true, fixedDmg:true, isHeal:true });
            } else {
              h.curHp = Math.min(h.hp, h.curHp + _amt);
            }
          }catch(_){
            h.curHp = Math.min(h.hp, h.curHp + _amt);
          }
          try{ renderCard(h); }catch(_){}
          try{ if(typeof healParticles === 'function') healParticles(h); }catch(_){}
          try{ if(typeof ringFX === 'function') ringFX(h, '#55ee88', 600); }catch(_){}
        }
      });
      try{ playSfx('sfx-heal', 0.85); }catch(_){}
      try{ flashScreen('rgba(85,238,136,0.3)', 300); }catch(_){}
      log('[對手獎勵] 對手全體回復 50% HP!');
    } else if(id === 'dmg_one'){
      // ⚠ 對玩家(G.p1)1 名造成當前 HP 20% 傷害
      const _foes = G.p1.filter(x => x.curHp > 0);
      if(_foes.length){
        // 集火:挑 HP 最低者
        const t = _foes.sort((a,b) => (a.curHp / a.hp) - (b.curHp / b.hp))[0];
        const dmg = Math.max(1, Math.floor(t.curHp * 0.2));
        try{ if(typeof flashCard === 'function') flashCard(t, 'rgba(100,200,80,0.85)', 400); }catch(_){}
        try{
          if(typeof doDmg === 'function'){
            doDmg(t, dmg, { fixedDmg:true, isSkill:true, _arenaScalingExempt:true });
          } else {
            t.curHp = Math.max(0, t.curHp - dmg);
          }
        }catch(_){
          t.curHp = Math.max(0, t.curHp - dmg);
        }
        try{ playSfx('sfx-explode', 0.75); }catch(_){}
        try{ bannerFX(t, '🌿 竹筍突刺!', '#88ff44', 900); }catch(_){}
        log('[對手獎勵] ' + t.name + ' 受到 ' + dmg + ' 傷害!');
      }
    } else if(id === 'dmg_all'){
      // ⚠ 對玩家(G.p1)全體造成各自當前 HP 20% 傷害
      G.p1.filter(x => x.curHp > 0).forEach(t => {
        const dmg = Math.max(1, Math.floor(t.curHp * 0.2));
        try{ if(typeof flashCard === 'function') flashCard(t, 'rgba(255,80,30,0.85)', 400); }catch(_){}
        try{
          if(typeof doDmg === 'function'){
            doDmg(t, dmg, { fixedDmg:true, isSkill:true, _arenaScalingExempt:true });
          } else {
            t.curHp = Math.max(0, t.curHp - dmg);
          }
        }catch(_){
          t.curHp = Math.max(0, t.curHp - dmg);
        }
        try{ bannerFX(t, '🔥 焰尾橫掃!', '#ff6633', 900); }catch(_){}
      });
      try{ flashScreen('rgba(255,80,30,0.4)', 350); }catch(_){}
      try{ playSfx('sfx-explode', 0.9); }catch(_){}
      log('[對手獎勵] 焰尾橫掃!玩家全體受傷!');
    } else if(id === 'invincible_team'){
      // AI 隊友(G.p2)全體無敵 1 回合
      const _aiAlive = G.p2.filter(x => x.curHp > 0);
      _aiAlive.forEach(t => {
        try{
          if(typeof addBuff === 'function'){
            addBuff(t, 'immune', 1);
            addBuff(t, 'statusImmune', 1);
            addBuff(t, 'ctrlImmune', 1);
          }
          try{ bannerFX(t, '🛡 絕對防禦!', '#ffee44', 900); }catch(_){}
          try{ renderCard(t); }catch(_){}
        }catch(_){}
      });
      try{ flashScreen('rgba(255,230,80,0.4)', 500); }catch(_){}
      try{ playSfx('sfx-guard', 0.9); }catch(_){}
      log('[對手獎勵] 🛡 絕對防禦!對手全體無敵 1 回合!');
    } else if(id === 'remove_buff'){
      // ⚠ 消除玩家(G.p1)全體 buff
      const _foes = G.p1.filter(x => x.curHp > 0);
      let _removedTotal = 0;
      _foes.forEach(t => {
        try{
          const _bcount = (t.buffs || []).length;
          try{ if(typeof _lxpsStatFxRestoreAll === 'function') _lxpsStatFxRestoreAll(t, 'buffs'); }catch(_){}   // ★ v5.239.0
          t.buffs = [];
          _removedTotal += _bcount;
          if(_bcount > 0){
            try{ bannerFX(t, '🌪 buff 全消!', '#aaccff', 900); }catch(_){}
            try{ if(typeof flashCard === 'function') flashCard(t, 'rgba(170,200,255,0.7)', 400); }catch(_){}
          }
          try{ renderCard(t); }catch(_){}
        }catch(_){}
      });
      try{ flashScreen('rgba(170,200,255,0.35)', 450); }catch(_){}
      try{ playSfx('sfx-cancel', 0.6); }catch(_){}
      try{ playSfx('sfx-fantasy', 0.7); }catch(_){}
      log('[對手獎勵] 🌪 破滅吹拂!消除玩家全體共 ' + _removedTotal + ' 個有利狀態!');
    } else {
      console.warn('[_arenaAIApplyReward] 未知獎勵 ID:' + id);
    }
    try{ updateUI(); }catch(_){}
  }catch(e){
    console.error('[_arenaAIApplyReward]', e);
  }
}

// 答錯/超時的懲罰:龍王或第一個 BOSS 打最低血英雄
function _advRoundQuizPenalty(){
  try{
    if(!G || !G.p1 || !G.p2) return;
    const _alive = G.p1.filter(h => h && h.curHp > 0);
    if(!_alive.length) return;
    const _boss = G.p2.find(h => h && h.curHp > 0);
    if(!_boss) return;
    const _target = _alive.reduce((lo, h) => (h.curHp < lo.curHp ? h : lo), _alive[0]);
    const _dmg = Math.max(1, Math.floor(_target.hp * 0.15));
    try{ log('💥 答題失敗![' + _boss.name + '] 對最低血英雄 [' + _target.name + '] 造成 ' + _dmg + ' 點傷害!'); }catch(_){}
    try{ bannerFX(_target, '❌ 答題失敗!', '#ff4466', 1100); }catch(_){}
    try{
      if(typeof doDmg === 'function'){
        doDmg(_target, _dmg, { fixedDmg:true, actor:_boss, ignoreBuffs:true, isRebound:true });
      } else {
        _target.curHp = Math.max(0, _target.curHp - _dmg);
      }
    }catch(_){}
    try{ if(typeof renderCard === 'function') renderCard(_target); }catch(_){}
    try{ if(typeof updateUI === 'function') updateUI(); }catch(_){}
  }catch(e){ console.warn('[v3.6.0 _advRoundQuizPenalty] 例外', e); }
}

// 結束新回合答題流程:解鎖對手行動
function _advFinishRoundQuiz(){
  try{
    // ★ v3.6.0 — 在這裡才標記「這回合已答過題」,確保答題中當機後恢復可重答
    try{
      const _curR = (typeof G !== 'undefined' && G && G.round) || 1;
      window._advLastQuizRound = _curR;
    }catch(_){}
    window._advRoundQuizPending = false;
    if(window._advRoundQuizTimeout){
      clearTimeout(window._advRoundQuizTimeout);
      window._advRoundQuizTimeout = null;
    }
    try{
      if(typeof _advQuizPhase !== 'undefined' && _advQuizPhase !== 'idle'){
        _advQuizPhase = 'idle';
      }
    }catch(_){}
    try{ window._bossQuizInFlight = false; }catch(_){}
    try{ _advQuizResolveCb = null; }catch(_){}
    // ★ v3.7.6 — 世界 BOSS 戰房主端:廣播關題給所有 client,讓他們關掉自己的 quiz 視窗
    //   老師 2026/5/25 回報 BUG:「組隊 round 10 卡死,client 端 quiz overlay 沒消失蓋住戰場」
    //   根因:新回合答題答對/答錯走的是 _advFinishRoundQuiz,沒有對應的 _wbHostBroadcastQuizClose,
    //         而 client 端只在收到 quiz-close sync 才會關自己的 adv-quiz-overlay。
    //         結果:host 自己關了 overlay 推進到下一回合,但 client 卡著 quiz overlay 看不到行動面板,
    //         30 秒後 watchdog 跳 _client_stuck_resync 也無法解決(因為 actor 就是真的等不到 client 點)。
    //   修法:跟 advOnQuizSkip 一樣補一個 quiz-close 廣播,讓 client 同步關掉視窗。
    //   注意:只有 host 跑這個分支(client 不會跑新回合答題,因為 _advShouldStartRoundQuiz 在 client 直接 return false)
    try{
      if(typeof _adventureStage !== 'undefined' && _adventureStage === 'worldboss'
         && window._wbConnectedHostMode
         && typeof window._wbHostBroadcastQuizClose === 'function'){
        window._wbHostBroadcastQuizClose('round-quiz-finished');
        console.log('🎓 [v3.7.6] 廣播 quiz-close 給 client(round-quiz-finished)');
      }
    }catch(_eQc){ console.warn('[v3.7.6 _advFinishRoundQuiz quiz-close 廣播] 例外', _eQc); }
    console.log('🎓 [v3.6.0] 新回合答題結束,對手行動解除暫停');
    // 更新技能格 3 顯示
    try{ if(typeof _advRefreshSkill3Btn === 'function') _advRefreshSkill3Btn(); }catch(_){}
    // 推進戰鬥(若 startTurn 還在等)
    setTimeout(function(){
      try{
        if(typeof checkWin === 'function' && checkWin()) return;
        if(typeof startTurn === 'function') startTurn();
      }catch(_){}
    }, 200);
  }catch(e){ console.warn('[v3.6.0 _advFinishRoundQuiz] 例外', e); }
}

// 套用獎勵到「知識化為力量」技能格 3
// ★ v3.12.4(2026-05-30) — 若已存在舊獎勵,彈出比較確認框讓玩家選擇是否覆蓋
//   opts.force=true 跳過確認(由確認框的「覆蓋」按鈕呼叫)
//   opts.onAfter 存好後執行的 callback(由覆蓋確認框使用,接續原本流程)
function _advStoreRewardToSkill3(rewardId, opts){
  opts = opts || {};
  try{
    if(!rewardId) return false;
    const _pool = (typeof ADV_REWARDS !== 'undefined' && ADV_REWARDS) ? ADV_REWARDS : [];
    const _r = _pool.find(x => x && x.id === rewardId);
    if(!_r) return false;
    // ★ v3.12.4 — 已存在舊獎勵 → 彈比較確認框
    const _existing = window._advKnowledgePowerReward;
    if(_existing && !opts.force){
      try{
        _showKnowledgePowerOverwriteConfirm(_existing, _r, function(_confirmed){
          if(_confirmed){
            // 玩家選覆蓋 → 強制存
            _advStoreRewardToSkill3(rewardId, { force: true, onAfter: opts.onAfter });
          } else {
            // 玩家選不覆蓋 → 直接使用舊的(代表這次新獎勵丟掉)
            console.log('🎓 [v3.12.4] 玩家選擇保留舊獎勵,不覆蓋');
            try{ bannerFX(null, '⚠ 新獎勵已丟棄,保留舊獎勵', '#ffaa66', 1400); }catch(_){}
            if(typeof opts.onAfter === 'function') opts.onAfter(false);
          }
        });
      }catch(_oce){
        // 確認框出錯 → 安全 fallback:直接覆蓋(維持舊行為)
        console.warn('[v3.12.4] 覆蓋確認框失敗,直接覆蓋', _oce);
        window._advKnowledgePowerReward = JSON.parse(JSON.stringify(_r));
        try{ if(typeof _advRefreshSkill3Btn === 'function') _advRefreshSkill3Btn(); }catch(_){}
        try{ bannerFX(null, '💡 已存入「知識化為力量」!', '#88ddff', 1400); }catch(_){}
        if(typeof opts.onAfter === 'function') opts.onAfter(true);
      }
      return true; // 已彈框,讓 caller 不要繼續走後續流程
    }
    window._advKnowledgePowerReward = JSON.parse(JSON.stringify(_r));
    console.log('🎓 [v3.6.0] 獎勵存入技能格 3:', _r.name);
    try{ if(typeof _advRefreshSkill3Btn === 'function') _advRefreshSkill3Btn(); }catch(_){}
    try{ bannerFX(null, '💡 已存入「知識化為力量」!', '#88ddff', 1400); }catch(_){}
    if(typeof opts.onAfter === 'function') opts.onAfter(true);
    return true;
  }catch(e){ console.warn('[v3.6.0 _advStoreRewardToSkill3] 例外', e); return false; }
}

// ★ v3.12.4(2026-05-30) — 知識化為力量覆蓋確認框
//   參數:oldReward 舊獎勵物件、newReward 新獎勵物件、callback(confirmed:boolean)
function _showKnowledgePowerOverwriteConfirm(oldReward, newReward, callback){
  // 防重複
  const _existing = document.getElementById('_knowpwr-overwrite-modal');
  if(_existing){ try{ _existing.remove(); }catch(_){} }
  const _backdrop = document.createElement('div');
  _backdrop.id = '_knowpwr-overwrite-modal';
  // ★ v3.12.6 — 整體放大 1.6 倍,padding 也加大
  _backdrop.style.cssText = 'position:fixed;inset:0;z-index:99996;background:rgba(0,0,0,0.72);display:flex;align-items:center;justify-content:center;font-family:"M PLUS Rounded 1c","Nunito",sans-serif;padding:24px;';
  const _box = document.createElement('div');
  // ★ v3.12.6 — max-width 520→780(×1.5)、padding 22/24→32/36、border 2→3、border-radius 14→18
  _box.style.cssText = 'background:linear-gradient(140deg,#1a2540 0%,#0d1428 100%);border:3px solid #88ccff;border-radius:18px;padding:32px 36px;max-width:780px;width:96%;box-shadow:0 0 48px rgba(120,180,255,0.55);max-height:92vh;overflow-y:auto;';
  const _ttl = document.createElement('div');
  // ★ v3.12.6 — 標題 22→36px(×1.6)、margin 8→14px
  _ttl.style.cssText = 'font-size:36px;font-weight:900;color:#88ddff;text-align:center;margin-bottom:14px;letter-spacing:1.5px;';
  _ttl.innerHTML = '💡 知識化為力量 — 覆蓋確認';
  const _msg = document.createElement('div');
  // ★ v3.12.6 — 訊息 13→21px(×1.6)、margin 14→22px
  _msg.style.cssText = 'font-size:21px;color:#ffcc88;line-height:1.6;text-align:center;margin-bottom:22px;';
  _msg.innerHTML = '技能格已存在舊獎勵,確定要覆蓋嗎?<br><span style="color:#ff8866;">⚠ 舊獎勵會被永久丟棄</span>';
  // ★ v3.12.6 — 並列改上下堆疊(grid:1fr 而非 flex),手機/平板友善
  const _compare = document.createElement('div');
  _compare.style.cssText = 'display:grid;grid-template-columns:1fr;gap:16px;margin-bottom:26px;';
  const _renderCard = (_r, _label, _color, _isOld) => {
    const _icon = (_r && _r.icon) || '💡';
    const _name = (_r && _r.name) || '?';
    const _desc = (_r && (_r.fd || _r.d || _r.desc)) || '';
    // ★ v3.12.6 — 卡片 padding 12→20、字級全部 ×1.6
    //   標籤 11→18px、icon 30→48px、名稱 15→24px、描述 11→18px、行高放寬
    return `<div style="background:rgba(0,0,0,0.42);border:2.5px solid ${_color};border-radius:14px;padding:20px 22px;${_isOld?'opacity:0.72;':''}">
      <div style="font-size:18px;color:${_color};font-weight:800;margin-bottom:10px;text-align:center;letter-spacing:3px;">${_label}</div>
      <div style="font-size:48px;text-align:center;margin-bottom:8px;line-height:1;">${_icon}</div>
      <div style="font-size:24px;color:#fff;font-weight:800;text-align:center;margin-bottom:10px;">${_name}</div>
      <div style="font-size:18px;color:#cce0ff;line-height:1.55;text-align:left;">${_desc}</div>
    </div>`;
  };
  _compare.innerHTML = _renderCard(oldReward, '舊獎勵(目前)', '#ffaa66', true)
                     + _renderCard(newReward, '新獎勵(本次答對)', '#88ddff', false);
  const _btns = document.createElement('div');
  // ★ v3.12.6 — 按鈕區 gap 10→16
  _btns.style.cssText = 'display:flex;gap:16px;justify-content:center;flex-wrap:wrap;';
  const _yesBtn = document.createElement('button');
  // ★ v3.12.6 — 按鈕 padding 11/22→17/34、font 15→24px(×1.6)、min-width 170→260
  _yesBtn.style.cssText = 'background:linear-gradient(135deg,#3a7bd5,#5599ff);color:#fff;border:none;border-radius:12px;padding:17px 34px;font-size:24px;font-weight:800;cursor:pointer;min-width:260px;box-shadow:0 0 18px rgba(80,150,255,0.5);letter-spacing:1.5px;';
  _yesBtn.textContent = '✅ 用新的覆蓋舊的';
  const _noBtn = document.createElement('button');
  _noBtn.style.cssText = 'background:linear-gradient(135deg,#aa6633,#cc8855);color:#fff;border:none;border-radius:12px;padding:17px 34px;font-size:24px;font-weight:800;cursor:pointer;min-width:260px;letter-spacing:1.5px;';
  _noBtn.textContent = '🛡 保留舊的(丟棄新的)';
  let _done = false;
  const _close = (_confirmed)=>{
    if(_done) return;
    _done = true;
    try{ _backdrop.remove(); }catch(_){}
    try{ if(typeof callback === 'function') callback(_confirmed); }catch(e){ console.error('[覆蓋確認 callback]', e); }
  };
  _yesBtn.onclick = ()=>{ try{ if(typeof playSfx==='function') playSfx('sfx-confirm',0.6); }catch(_){} _close(true); };
  _noBtn.onclick  = ()=>{ try{ if(typeof playSfx==='function') playSfx('sfx-cancel',0.5); }catch(_){} _close(false); };
  _btns.appendChild(_yesBtn);
  _btns.appendChild(_noBtn);
  _box.appendChild(_ttl);
  _box.appendChild(_msg);
  _box.appendChild(_compare);
  _box.appendChild(_btns);
  _backdrop.appendChild(_box);
  document.body.appendChild(_backdrop);
}
window._showKnowledgePowerOverwriteConfirm = _showKnowledgePowerOverwriteConfirm;

// 玩家點擊技能格 3 → 套用儲存的獎勵(v3.6.7 加上確認/取消)
function _advUseKnowledgePower(){
  try{
    const _r = window._advKnowledgePowerReward;
    if(!_r){
      try{ bannerFX(null, '⚠ 技能格 3 是空的', '#888888', 900); }catch(_){}
      return;
    }
    // 戰鬥未開始或已結束時不可用
    // ★ v3.13.32(2026-06-03) — 任務 4 修補:原本只允許 _adventureMode=true(冒險模式),
    //   但鬥技場 _adventureMode=false 也是戰鬥狀態,被誤擋 → 玩家答對存技能格 3 後按了沒反應
    //   改為:用 G.p1 是否有英雄 + 戰鬥未結束 判斷,涵蓋冒險與鬥技場
    const _inBattle = (typeof G !== 'undefined' && G
                      && Array.isArray(G.p1) && G.p1.length > 0
                      && Array.isArray(G.p2) && G.p2.length > 0);
    if(!_inBattle){
      console.warn('[v3.13.32] 非戰鬥狀態無法使用知識化為力量');
      try{ bannerFX(null, '⚠ 戰鬥外無法使用', '#888888', 900); }catch(_){}
      return;
    }
    if(typeof checkWin === 'function' && checkWin()) return;
    // 答題進行中不可用(避免衝突)
    if(window._advRoundQuizPending){
      try{ bannerFX(null, '⚠ 答題中,稍候再用', '#ffaa44', 900); }catch(_){}
      return;
    }
    // ★ v3.7.0 — 改用跟 s1/s2 一樣的內嵌確認欄,不再彈系統對話框
    //   老師指示:「點了那格再出現使用和取消就好(跟 s1/s2 一樣)」
    //   行為對齊 requestAction:
    //     ① 同一個按鈕再點一次 → 收起確認欄(切換)
    //     ② 點別的按鈕 → 清掉舊確認欄、按鈕 sel 高亮、在下方插入新確認欄
    //     ③ 按綠色「✔ 確認」→ 呼叫 _advUseKnowledgePower_doApply 真正發動
    //     ④ 按紅色「✕ 取消」→ 清確認欄、移除 sel
    const _btn = document.getElementById('b-s3');
    if(!_btn) return;

    // ① 已有自己的確認欄 → 收起(切換行為)
    if(window._kpPendingConfirm){
      window._kpClearConfirmBar && window._kpClearConfirmBar();
      return;
    }

    // ② 清掉 s1/s2 / atk / rest 留下的舊確認欄與 sel,確保版面整潔
    try{
      const _oldBar = document.getElementById('action-confirm-bar');
      if(_oldBar) _oldBar.remove();
      document.querySelectorAll('.abtn.sel').forEach(b => b.classList.remove('sel'));
      if(typeof _pendingActionType !== 'undefined') _pendingActionType = null;
    }catch(_){}

    // 按鈕亮起 sel
    _btn.classList.add('sel');
    window._kpPendingConfirm = true;

    // 建立確認欄(視覺與 s1/s2 完全一致,line ~26220)
    const _bar = document.createElement('div');
    _bar.id = 'kp-confirm-bar';
    _bar.style.cssText = 'display:flex;gap:8px;margin-top:6px;animation:confirmBarIn 0.18s ease-out;';
    _bar.innerHTML =
      '<button onclick="playSfx(\'sfx-confirm\',0.5);window._kpClearConfirmBar();_advUseKnowledgePower_doApply();"'
        + ' style="flex:1;padding:10px 0;font-size:24px;font-weight:700;'
        +   'background:linear-gradient(135deg,rgba(50,180,80,0.25),rgba(30,120,50,0.2));'
        +   'border:2px solid #3ec87a;color:#3ec87a;border-radius:8px;cursor:pointer;'
        +   'font-family:\'M PLUS Rounded 1c\',\'Nunito\',sans-serif;letter-spacing:2px;transition:0.15s;"'
        + ' onmouseover="this.style.background=\'rgba(62,200,122,0.35)\'"'
        + ' onmouseout="this.style.background=\'linear-gradient(135deg,rgba(50,180,80,0.25),rgba(30,120,50,0.2))\'">✔ 使用</button>'
      + '<button onclick="playSfx(\'sfx-cancel\',0.4);window._kpClearConfirmBar();"'
        + ' style="flex:1;padding:10px 0;font-size:24px;font-weight:700;'
        +   'background:rgba(60,10,10,0.3);border:2px solid #e84040;color:#e84040;'
        +   'border-radius:8px;cursor:pointer;'
        +   'font-family:\'M PLUS Rounded 1c\',\'Nunito\',sans-serif;letter-spacing:2px;transition:0.15s;"'
        + ' onmouseover="this.style.background=\'rgba(232,64,64,0.25)\'"'
        + ' onmouseout="this.style.background=\'rgba(60,10,10,0.3)\'">✕ 取消</button>';

    // 插入到 b-s3 後方(action-panel 內)
    const _panel = document.getElementById('action-panel');
    if(_panel && _btn.parentNode === _panel){
      _panel.insertBefore(_bar, _btn.nextSibling);
    } else if(_panel){
      _panel.appendChild(_bar);
    }
  }catch(e){ console.warn('[v3.7.0 _advUseKnowledgePower] 例外', e); }
}

// ★ v3.7.0 — 清除知識化為力量確認欄的小工具(暴露給「使用」「取消」按鈕內 inline onclick 呼叫)
window._kpClearConfirmBar = function(){
  try{
    const _bar = document.getElementById('kp-confirm-bar');
    if(_bar) _bar.remove();
    const _btn = document.getElementById('b-s3');
    if(_btn) _btn.classList.remove('sel');
    window._kpPendingConfirm = false;
  }catch(_){}
};

// ★ v3.6.7 — 實際套用獎勵的內部函式(玩家在確認視窗按「確定」後才會呼叫)
function _advUseKnowledgePower_doApply(){
  try{
    const _r = window._advKnowledgePowerReward;
    if(!_r) return;  // 確認過程中被清掉(理論上不會但保險)
    // 雙重檢查:確認彈窗顯示期間若戰鬥結束,不發動
    if(typeof checkWin === 'function' && checkWin()) return;
    if(window._advRoundQuizPending){
      try{ bannerFX(null, '⚠ 答題中,稍候再用', '#ffaa44', 900); }catch(_){}
      return;
    }
    console.log('🎓 [v3.6.0] 玩家使用知識化為力量:', _r.name);
    // ★ v3.13.32(2026-06-03) — 任務 3:鬥技場時 banner 文字中 BOSS 改為對手
    const _kpInArena = (typeof _adventureMode !== 'undefined' && _adventureMode === false);
    let _kpDesc = _r.desc || _r.name || '';
    if(_kpInArena) _kpDesc = String(_kpDesc).replace(/BOSS/g, '對手');
    try{ bannerFX(null, '💡 ' + (_r.icon || '✨') + ' ' + _kpDesc + ' 發動!', '#88ddff', 1400); }catch(_){}
    // 清空技能格 3(用完即清)
    window._advKnowledgePowerReward = null;
    try{ if(typeof _advRefreshSkill3Btn === 'function') _advRefreshSkill3Btn(); }catch(_){}
    // 套用獎勵效果(複用既有 advApplyReward 邏輯)
    try{
      if(typeof advApplyReward === 'function'){
        // ★ v3.6.4 — 簡化:直接呼叫 advApplyReward,不再強制關閉 reward overlay
        advApplyReward(_r.id);
      }
    }catch(eAp){ console.warn('[v3.6.0] advApplyReward 例外', eAp); }
    // ★ v3.6.0 — 世界 BOSS:廣播給隊友
    try{
      if(typeof _adventureStage !== 'undefined' && _adventureStage === 'worldboss'
         && window._wbBroadcastCenterToast){
        const _myName = window._playerNickname || '隊友';
        const _text = '<span style="color:#88ddff;font-weight:900;">' + _myName + '</span>'
                    + ' 使用了「知識化為力量」<br>'
                    + '<span style="font-size:1.15em;color:#aaeeff;">'
                    + (_r.icon || '💡') + ' ' + (_r.desc || _r.name) + '</span>';
        window._wbBroadcastCenterToast(_text, '#88ddff', 3000);
      }
    }catch(_){}
  }catch(e){ console.warn('[v3.6.0 _advUseKnowledgePower_doApply] 例外', e); }
}

// 更新技能格 3 按鈕顯示
function _advRefreshSkill3Btn(){
  try{
    const _btn = document.getElementById('b-s3');
    if(!_btn) return;
    const _r = window._advKnowledgePowerReward;
    if(_r){
      // 有儲存獎勵 → 亮起來,可點
      _btn.disabled = false;
      _btn.style.opacity = '1';
      _btn.style.borderColor = '#88ddff';
      _btn.style.color = '#aaeeff';
      _btn.style.background = 'linear-gradient(135deg,rgba(20,50,80,0.85),rgba(40,20,80,0.85))';
      _btn.style.cursor = 'pointer';
      _btn.style.boxShadow = '0 0 16px rgba(136,221,255,0.55),inset 0 0 12px rgba(136,221,255,0.25)';
      _btn.style.animation = 'knowledgePowerPulse 1.6s ease-in-out infinite';
      // ★ v3.7.0 — 從空格切回有內容時,還原 .abtn 預設的 min-height/padding,避免按鈕卡在迷你尺寸
      _btn.style.minHeight = '';
      _btn.style.padding = '';
      // ★ v3.6.7 — 按鈕主文字顯示「效果文字」,不再顯示名稱
      //   原本:「💡 知識化為力量 / ✨ 貓空茶香 / 點擊發動」 玩家看不懂貓空茶香是什麼
      //   新版:「💡 答題效果 / 🍵 全體隊友恢復 50% HP / 點擊發動」 一目瞭然
      // ★ v3.7.0 — 三行縮成單行,跟「普通攻擊」同尺寸(35px),不再 28+40+13 三層堆疊
      // ★ v3.13.32(2026-06-03) — 任務 3:鬥技場時把 "BOSS" 文字改成 "對手"
      const _inArenaS3 = (typeof _adventureMode !== 'undefined' && _adventureMode === false);
      let _safeDesc = String(_r.desc || _r.name || '').replace(/[<>&]/g, '');
      if(_inArenaS3) _safeDesc = _safeDesc.replace(/BOSS/g, '對手');
      _btn.innerHTML = '<b style="font-size:35px;margin-bottom:0;color:#aaeeff;">💡 ' + (_r.icon || '✨') + ' ' + _safeDesc + '</b>';
    } else {
      // 空白 → 灰色不能按
      _btn.disabled = true;
      _btn.style.opacity = '0.45';
      _btn.style.borderColor = '#555';
      _btn.style.color = '#888';
      _btn.style.background = 'rgba(40,40,50,0.55)';
      _btn.style.cursor = 'not-allowed';
      _btn.style.boxShadow = 'none';
      _btn.style.animation = 'none';
      // ★ v3.7.0 — 空格狀態縮成單行迷你版,省出垂直空間給物品欄
      _btn.style.minHeight = '0';
      _btn.style.padding = '6px 10px';
      _btn.innerHTML = '<span style="font-size:16px;line-height:1.3;">💡 知識化為力量 <span style="color:#888;opacity:0.85;">— 空格(答題保留獎勵後可用)</span></span>';
    }
  }catch(e){ console.warn('[v3.6.0 _advRefreshSkill3Btn] 例外', e); }
}

