  G.comboFatigue = 0; G.comboFatigueByHero = {}; G.lastSkillName = null; G.lastSkillByHero = {};
  G.energy={p1:2,p2:2};
  // 重置法寶（從過場備份取回，未實作備份則隨機三個）
  _advTreasures = [null,null,null];
  // ★ 隨機不重複分配3個法寶
(function(){
  const pool = ADV_TREASURES.slice().sort(()=>Math.random()-0.5);
  for(let i=0;i<3;i++) _advTreasures[i] = pool[i % pool.length];
})();
  advUpdateTreasureBar();
  // 重置接關
  _advContinueCount=0;
  _advStats={rounds:0,correctCount:0,totalAnswerTime:0,deathCount:0,continueCount:0,startTime:Date.now(),totalQuizScore:0,totalQuestions:0,itemUsedCount:0,currentStreak:0,maxStreak:0};
  _advPendingReward=null;
