        // 標題
        try{ const _t = document.getElementById('adv-result-title'); if(_t) _t.textContent = _wdWin ? '🏆 Boss 討伐成功！' : '💀 再接再厲！'; }catch(_){}
        // 顯示對應按鈕(靜態 HTML,onclick 已內建)
