  //   註:讀評分/分數是讀 DOM textContent,移除 'show' 只是視覺隱藏、元素與文字仍在,不影響後續計算。
  try{
    const _rovEarly = document.getElementById('adv-result-overlay');
    if(_rovEarly){ _rovEarly.classList.remove('show'); }
    const _gcEarly = document.getElementById('gc');
    if(_gcEarly){ _gcEarly.classList.remove('adv-battle'); _gcEarly.style.filter = ''; }
    const _tbarEarly = document.getElementById('turn-bar');
    if(_tbarEarly) _tbarEarly.innerHTML = '';
  }catch(_eEarlyHide){ console.warn('[advStartWinSequence 入口收 UI]', _eEarlyHide); }
  // ════════════════════════════════════════════════════════════════════
