// ════════════════════════════════════════════════════════════════════
// ★ v3.5.50 — 「檢查遊戲版本」主動功能
// ★ v3.13.22(2026-06-02) — 改造為「逐檔掃描對齊」版
// ────────────────────────────────────────────────────────────────────
// 老師需求(2026-06-02):原本只比對 _GAME_LOADED_VERSION 主版號,當主版號未動
// 但其他檔案(arena.js / hero_db.js / admin_panel.js 等)實際已升版時會誤判
// 為「已是最新版」(同 console 看到的 [版本戳健康檢查] 警告)。
// 改造:點下「檢查遊戲版本」後 →
//   1. 開啟逐檔掃描視窗(藍底清單,每行一檔)
//   2. fetch 伺服器 HTML、解析 _LXPS_FILE_VERSIONS 清單
//   3. 對 window._LXPS_FILE_VERSIONS 裡每一個 key,動畫式逐檔揭曉:
//        ⏳ 檢查中… → ✅ 一致 / ⚠ 需更新
//      每筆間隔 ~180ms,給玩家清楚的「一個一個打勾」儀式感
//   4. 全部跑完:
//        - 全 ✅ → 沿用原「已是最新版」綠勾視窗
//        - 任一 ⚠ → 改顯示橘色「需要更新」視窗,主按鈕「立即重新整理」
//   5. 若 fetch / 解析失敗 → 走原「無法連線伺服器」紅色視窗
// ════════════════════════════════════════════════════════════════════
window._manualCheckGameVersion = async function(btnEl){
  try{ playSfx('sfx-sel', 0.5); }catch(_){}
  // 防重複點擊
  if(btnEl){
    if(btnEl.disabled) return;
    btnEl.disabled = true;
    btnEl._origText = btnEl.textContent;
    btnEl.textContent = '⏳ 檢查中…';
    btnEl.style.opacity = '0.65';
  }
  const _restoreBtn = ()=>{
    try{
      if(btnEl && btnEl._origText){
        btnEl.disabled = false;
        btnEl.textContent = btnEl._origText;
        btnEl.style.opacity = '1';
      }
    }catch(_){}
  };
  try{
    const _current = window._GAME_LOADED_VERSION || '未知';
    const _localVers = window._LXPS_FILE_VERSIONS || {};
    const _fileKeys  = Object.keys(_localVers);
    // 主程式版本鍵也加進掃描(放在最前面,有獨立意義)
    const _scanKeys = ['_GAME_LOADED_VERSION'].concat(_fileKeys);

    // ── 1. 先把掃描視窗打開,讓玩家看到「逐檔對齊」進度 ──
    _showVersionScanDialog(_scanKeys, _localVers, _current);

    // ── 2. fetch 伺服器 HTML ──
    let _serverHtml = null;
    let _latest = null;
    try{
      // v3.13.22 — 沿用 _checkNewVersionOnServer 的 cache-buster + no-store 寫法
      let _checkUrl;
      try{ _checkUrl = location.pathname + '?_versionCheck=' + Date.now(); }
      catch(_eUrl){ _checkUrl = location.href; }
      const resp = await fetch(_checkUrl, {
        cache: 'no-store',
        headers: { 'Cache-Control': 'no-cache', 'Pragma': 'no-cache' }
      });
      if(resp.ok){
        _serverHtml = await resp.text();
        const m1 = _serverHtml.match(/window\._GAME_LOADED_VERSION\s*=\s*['"]([^'"]+)['"]/);
        if(m1) _latest = m1[1];
      }else{
        console.warn('[v3.13.22 _manualCheckGameVersion] fetch 失敗 status=' + resp.status);
      }
    }catch(e){
      console.warn('[v3.13.22 _manualCheckGameVersion] fetch 例外', e);
    }
    _restoreBtn();

    // fetch 失敗 → 關掉掃描視窗,改顯示紅色「無法連線」
    if(!_serverHtml){
      try{ document.getElementById('version-scan-modal').remove(); }catch(_){}
      _showVersionCheckResultDialog({ ok: false, current: _current, latest: null });
      return;
    }

    // ── 3. 解析伺服器清單 ──
    const _serverVers = (typeof _lxpsParseFileVersions === 'function')
                        ? (_lxpsParseFileVersions(_serverHtml) || {})
                        : {};

    // ── 4. 逐檔比對 + 動畫式揭曉 ──
    //   每筆間隔 ~180ms,讓清單有「一個一個打勾」的儀式感
    const _mismatches = [];   // 收集所有不一致的檔案(給結果視窗用)
    for(let i = 0; i < _scanKeys.length; i++){
      const k = _scanKeys[i];
      let localV, serverV;
      if(k === '_GAME_LOADED_VERSION'){
        localV  = _current;
        serverV = _latest || '(無法解析)';
      }else{
        localV  = String(_localVers[k] || '(本地無)');
        serverV = String(_serverVers[k] || '(伺服器無)');
      }
      const ok = (localV === serverV) && (localV !== '(本地無)') && (serverV !== '(伺服器無)' || k === '_GAME_LOADED_VERSION');
      // 主程式版本:只要 latest 解析成功且相等即 OK
      const okFinal = (k === '_GAME_LOADED_VERSION')
                      ? (!!_latest && localV === serverV)
                      : (localV === serverV);
      if(!okFinal){
        _mismatches.push({ key: k, local: localV, server: serverV });
      }
      // 揭曉這一筆(更新 DOM)
      _markVersionScanRow(k, okFinal, localV, serverV);
      // 等一拍(製造逐筆顯示效果);最後一筆不等
      if(i < _scanKeys.length - 1){
        await new Promise(r => setTimeout(r, 180));
      }
    }

    // ── 5. 全部跑完,延一拍讓玩家看清結果 ──
    await new Promise(r => setTimeout(r, 450));
    try{ document.getElementById('version-scan-modal').remove(); }catch(_){}

    if(_mismatches.length === 0){
      // 全 ✅
      _showVersionCheckResultDialog({
        ok: true, isLatest: true,
        current: _current, latest: _latest,
      });
    }else{
      // 任一 ⚠ → 顯示需要更新視窗
      console.warn('[v3.13.22 逐檔掃描] 偵測到 ' + _mismatches.length + ' 個檔案未對齊:',
        _mismatches.map(o => o.key + ':' + o.local + '→' + o.server).join(' , '));
      _showVersionCheckResultDialog({
        ok: true, isLatest: false,
        current: _current, latest: _latest || '(逐檔掃描偵測到差異)',
        mismatches: _mismatches,
      });
    }
  }catch(e){
    console.warn('[v3.13.22 _manualCheckGameVersion] 例外', e);
    _restoreBtn();
    try{ document.getElementById('version-scan-modal').remove(); }catch(_){}
    try{ _showInGameToast('⚠ 檢查失敗,請稍後再試', '#ff8844', 2500); }catch(_){}
  }
};

// ════════════════════════════════════════════════════════════════════
// ★ v3.13.22(2026-06-02) — 逐檔掃描清單視窗
// ────────────────────────────────────────────────────────────────────
// 顯示一個藍色彈窗,內含每個檔案一行:
//   📄 檔名 ─ 本地:vX.Y.Z ─ 伺服器:vX.Y.Z ─ [⏳ / ✅ / ⚠]
// 由 _manualCheckGameVersion 逐筆呼叫 _markVersionScanRow() 揭曉結果。
// ════════════════════════════════════════════════════════════════════
function _showVersionScanDialog(keys, localVers, currentGameVer){
  const _old = document.getElementById('version-scan-modal');
  if(_old) _old.remove();

  const modal = document.createElement('div');
  modal.id = 'version-scan-modal';
  modal.style.cssText =
    'position:fixed;inset:0;z-index:9999;display:flex;align-items:center;justify-content:center;' +
    'background:radial-gradient(circle at center,rgba(15,25,50,0.88),rgba(0,5,15,0.96));' +
    'backdrop-filter:blur(6px);animation:fadeIn 0.25s;';

  // 為了避免 key 內含的特殊符號干擾 querySelector,用 index 當 id
  let _rowsHtml = '';
  keys.forEach(function(k, idx){
    const labelText = (k === '_GAME_LOADED_VERSION') ? '🎮 主程式版本' : ('📄 ' + k);
    const localV = (k === '_GAME_LOADED_VERSION')
                   ? (currentGameVer || '(未知)')
                   : String((localVers && localVers[k]) || '(本地無)');
    _rowsHtml +=
      '<div id="vscan-row-' + idx + '" data-key="' + _escAttr(k) + '" ' +
      'style="display:flex;align-items:center;gap:10px;padding:9px 14px;border-radius:8px;' +
      'background:rgba(0,0,0,0.32);margin-bottom:6px;font-size:13.5px;line-height:1.45;">' +
        '<span style="flex:0 0 24px;font-size:18px;text-align:center;" class="vscan-icon">⏳</span>' +
        '<span style="flex:0 0 38%;color:#cfdfee;font-weight:700;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + labelText + '</span>' +
        '<span style="flex:1;color:#aaccee;font-family:monospace;font-size:12.5px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" class="vscan-detail">' +
          '本地:<b style="color:#ffe399;">' + _escHtml(localV) + '</b> ─ 伺服器:<span style="color:#888;">檢查中…</span>' +
        '</span>' +
      '</div>';
  });

  modal.innerHTML =
    '<div style="max-width:640px;width:94%;max-height:88vh;overflow-y:auto;-webkit-overflow-scrolling:touch;' +
    'background:linear-gradient(160deg,#162a44 0%,#0a1626 100%);' +
    'border:3px solid #66aaff;border-radius:18px;padding:24px 22px;color:#fff;' +
    'font-family:\'M PLUS Rounded 1c\',\'Microsoft JhengHei\',sans-serif;' +
    'box-shadow:0 0 50px rgba(100,170,255,0.4);">' +
      '<div style="text-align:center;margin-bottom:16px;">' +
        '<div style="font-size:42px;margin-bottom:4px;">🔍</div>' +
        '<h2 style="font-size:21px;color:#aaccff;margin:0;letter-spacing:1.5px;">正在逐檔對齊版本…</h2>' +
        '<div style="font-size:12.5px;color:#88aacc;margin-top:5px;">與 GitHub 伺服器逐一比對,任一檔不一致就要更新</div>' +
      '</div>' +
      '<div id="vscan-list" style="background:rgba(0,0,0,0.2);border-radius:10px;padding:10px 8px;">' +
        _rowsHtml +
      '</div>' +
    '</div>';

  document.body.appendChild(modal);
}

// 揭曉某一筆掃描結果(由 _manualCheckGameVersion 逐筆呼叫)
function _markVersionScanRow(key, ok, localV, serverV){
  try{
    // 用 attribute selector 找對應的 row(避免 key 內含字元影響)
    const root = document.getElementById('version-scan-modal');
    if(!root) return;
    const rows = root.querySelectorAll('[data-key]');
    let target = null;
    for(let i = 0; i < rows.length; i++){
      if(rows[i].getAttribute('data-key') === key){ target = rows[i]; break; }
    }
    if(!target) return;
    const iconEl   = target.querySelector('.vscan-icon');
    const detailEl = target.querySelector('.vscan-detail');
    if(iconEl){
      iconEl.textContent = ok ? '✅' : '⚠';
      iconEl.style.color = ok ? '#88ff99' : '#ff9966';
    }
    if(detailEl){
      const serverColor = ok ? '#99ffaa' : '#ff9966';
      detailEl.innerHTML =
        '本地:<b style="color:#ffe399;">' + _escHtml(localV) + '</b> ─ ' +
        '伺服器:<b style="color:' + serverColor + ';">' + _escHtml(serverV) + '</b>';
    }
    if(!ok){
      // 不一致整列改紅橘背景以醒目
      target.style.background = 'rgba(255,120,60,0.18)';
      target.style.border = '1px solid rgba(255,150,80,0.5)';
    }else{
      target.style.background = 'rgba(80,180,120,0.12)';
    }
    // 輕量音效(每筆都響會很煩,只在不一致時響一下)
    if(!ok){ try{ playSfx && playSfx('sfx-warn', 0.35); }catch(_){} }
  }catch(_){}
}

// 小工具:HTML escape / attribute escape
function _escHtml(s){
  return String(s == null ? '' : s)
    .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
    .replace(/"/g,'&quot;').replace(/'/g,'&#39;');
}
function _escAttr(s){
  return String(s == null ? '' : s)
    .replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/'/g,'&#39;')
    .replace(/</g,'&lt;').replace(/>/g,'&gt;');
}

