// ★★ v5.152.0（2026-09-08・25 台 iPad 同時登入卡住）— gameCloudLoad 同 uid 併發合流 ★★
//   稽核發現登入時 gameCloudLoad 會被叫兩次：_lgAfterSignIn（登入閘門路徑）自己叫一次、
//   onAuthStateChanged 隨後又叫一次 ⇒ 同一帳號同時開兩組「三槽並行讀取」= 6 次讀取，且兩組各自
//   _applySafeData 互相覆蓋（相同資料，但白白耗一倍頻寬與配額，校網 25 台同開時特別致命）。
//   修法：30 秒內同 uid 的第二次呼叫直接回傳第一次的 Promise（await 語意不變，兩邊都等到同一份結果）。
//   ⚠ 只合流「進行中」的那一次；完成後再呼叫（例如進關前重讀）照常重新讀取，行為零改動。
window._gameCloudLoadOnce = window.gameCloudLoad;
window._lxpsCloudLoadInflight = null;
window.gameCloudLoad = function(uid){
  let _u = uid;
  try{
    if(!_u) _u = (typeof window._lxpsResolveUid === 'function') ? window._lxpsResolveUid() : (window._gUserId || null);
  }catch(_){}
  try{
    const _inf = window._lxpsCloudLoadInflight;
    if(_u && _inf && _inf.uid === _u && _inf.p && (Date.now() - _inf.at) < 30000){
      console.info('[gameCloudLoad v5.152.0] 同 uid 讀取進行中,合流共用同一次結果 uid=' + String(_u).slice(0,8));
      return _inf.p;
    }
  }catch(_){}
  const _p = window._gameCloudLoadOnce(uid);
  if(_u){
    window._lxpsCloudLoadInflight = { uid: _u, p: _p, at: Date.now() };
    const _clear = function(){ try{ if(window._lxpsCloudLoadInflight && window._lxpsCloudLoadInflight.p === _p) window._lxpsCloudLoadInflight = null; }catch(_){} };
    _p.then(_clear, _clear);
  }
  return _p;
};

// ── 英雄養成資料 ──
let _heroLevels = {};       // {heroName: level}
let _heroExp = {};          // {heroName: exp}
let _heroStatPoints = {};   // {heroName: freePoints}
let _heroStatInvested = {}; // {heroName: {hp,atk,sp,spd}}
// ★ v3.13.83 — 極限膠囊投資(獨立於 _heroStatInvested):突破自由投資上限的「付費加成」。
//   {heroName: {hp,atk,sp,spd}},每能力 0~20。刻意與 _heroStatInvested 分開:
//   ① 不被素質點數自癒/重置之書動到(膠囊是花錢買的,重置只退自由點數)
//   ② 不會觸發「投資超過等級上限」健康閘(那只檢查 _heroStatInvested ≤ 30/50)
//   實戰加成在 _applyAdvLevelHpBonus 一處統一套用(冒險/世界BOSS;鬥技場不套投資=膠囊也不套)。
let _heroCapsuleInvested = {}; // {heroName: {hp,atk,sp,spd}} 0~20/能力
let _heroSkillLevels = {};  // {heroName: {s1:n, s2:n}}  n=0~9 (+0~+9)
let _heroBurstLevels = {};  // {heroName: n}  n=0~4 (+0~+4 極限爆發等級)
let _skillBookCount = 0;    // 技能升級書數量（舊：現已移至背包）
let _heroExpBookCount = 0;  // 英雄經驗值之書數量（舊：現已移至背包）
let _heroTraitLevel = {};   // {heroName: 天賦等級}

function _expectedTraitLv(heroLv){
  return Math.min(4, Math.max(0, Math.floor((heroLv||1) / 10)));
}

function _syncHeroTraitLevels(){
  if(!_heroLevels || typeof _heroLevels !== 'object') return 0;
  let _fixed = 0;
  Object.keys(_heroLevels).forEach(function(name){
    const lv = _heroLevels[name] || 1;
    const expected = _expectedTraitLv(lv);
    const current = (_heroTraitLevel && _heroTraitLevel[name]) || 0;
    if(expected !== current){
      _heroTraitLevel[name] = expected;
      _fixed++;
    }
  });
  return _fixed;
}

// ★ v5.86.0（2026-08-19·老師需求）— 編組頁「有待提升」標籤：養成資料跨區塊唯讀投影。
//   ★ 定位：_heroLevels / _heroStatPoints / _heroSkillLevels / _heroBurstLevels / _adventureStage
//     都是本 <script> 區塊的 let。實測確認：同頁的多個 classic <script> **共用同一個
//     script scope**，故編組頁（另一區塊）的函式在執行期是讀得到的（不同於跨檔或 module）。
//     本投影因此不是「修偵錯」而是「單一取值口徑」：六項養成資料一次取齊、逐欄包 try，
//     日後若養成表拆檔或改名，只需改本函式一處，_lxpsPrepCheck 零改動。
//   ★ 純唯讀零寫入；任何欄位讀取失敗一律回安全預設（ok=false → 上游直接不標，絕不誤報）。
window._lxpsPrepGrowth = function(name){
  var _o = { lv:1, free:0, s1:0, s2:0, burst:0, stage:null, ok:false };
  if(!name) return _o;
  try{
    if(typeof getHeroLevel === 'function') _o.lv = getHeroLevel(name) || 1;
    else if(typeof _heroLevels !== 'undefined' && _heroLevels) _o.lv = _heroLevels[name] || 1;
  }catch(_e1){}
  try{ if(typeof _heroStatPoints !== 'undefined' && _heroStatPoints) _o.free = _heroStatPoints[name] || 0; }catch(_e2){}
  try{
    if(typeof _heroSkillLevels !== 'undefined' && _heroSkillLevels && _heroSkillLevels[name]){
      _o.s1 = _heroSkillLevels[name].s1 || 0;
      _o.s2 = _heroSkillLevels[name].s2 || 0;
    }
  }catch(_e3){}
  try{ if(typeof _heroBurstLevels !== 'undefined' && _heroBurstLevels) _o.burst = _heroBurstLevels[name] || 0; }catch(_e4){}
  try{ if(typeof _adventureStage !== 'undefined') _o.stage = _adventureStage || null; }catch(_e5){}
  _o.ok = true;
  return _o;
};

// ★ 取得英雄特質等級（戰鬥用）：鬥技場一律回 0 以保持 Lv1 公平性，冒險模式才回實際值
// ★ v1.0.20260423.1500 — 加上依等級反推的防禦性計算，避免歷史資料造成天賦停在 Lv1
function _getTraitLv(name){
  // ★ v3.15.72 — 偵探天賦「縝密推理」:被「天賦失效」(_traitSeal)的英雄,其天賦等級視為 0(天賦完全失效)。
  //   務實版(取捨二甲):檢查戰場上是否有同名存活英雄身上帶 _traitSeal。走 _getTraitLv 的天賦(玩家方英雄 + PVP 對手玩家英雄)皆生效;AI 寫死天賦另有其顯示但不全攔。
  try{
    if(typeof G !== 'undefined' && G){
      const _allTSeal = (G.p1||[]).concat(G.p2||[]);
      if(_allTSeal.some(h => h && h.name === name && h.curHp > 0 && (h.status||[]).some(s => s.type === '_traitSeal' || s.type === 'imprison'))) return 0;
    }
  }catch(_){}
  if(typeof _adventureMode === 'undefined' || !_adventureMode) return 0;
  const stored = (_heroTraitLevel && _heroTraitLevel[name]) || 0;
  const heroLv = (typeof _heroLevels !== 'undefined' && _heroLevels && _heroLevels[name]) || 1;
  return Math.max(stored, _expectedTraitLv(heroLv));
}
// ════════════════════════════════════════════════════════════════
// ★ v5.119.0(老師裁定一·甲)— 菇女 S2「極限菇」每場可用次數(單一真相)
//   內部技能等級 skLv 0~9 = 顯示 Lv.1~Lv.10。
//     顯示 Lv1~Lv4 (skLv 0~3) → 2 次
//     顯示 Lv5~Lv9 (skLv 4~8) → 3 次
//     顯示 Lv10    (skLv 9)   → 4 次
//   ★ 與 _renderSkillFdWithLv 的 `special_extreme_xie` 分支、buildSkillLvTable 的逐級表
//     用完全相同的門檻(>=4 / >=9),三處不可各寫一份。
//   ★ 讀 h._skLv(戰鬥中角色身上的技能等級快照),鬥技場一律 0 ⇒ 自然回 2 次,維持 Lv1 公平性。
//   ★ 極限菇固定登記在 s2;仍做 s1 容錯(繼承/改招時不會整個失效)。
// ════════════════════════════════════════════════════════════════
window._guniuS2MaxOf = function(h){
  try{
    var _lv = 0;
    if(h && h._skLv){
      if(h.s2 && h.s2.n === '極限菇' && typeof h._skLv.s2 === 'number')      _lv = h._skLv.s2;
      else if(h.s1 && h.s1.n === '極限菇' && typeof h._skLv.s1 === 'number') _lv = h._skLv.s1;
      else if(typeof h._skLv.s2 === 'number')                                _lv = h._skLv.s2;
    }
    if(_lv >= 9) return 4;
    if(_lv >= 4) return 3;
    return 2;
  }catch(_){ return 2; }
};
