// 背包工具函式
// ★ v3.17.6(老師需求 2)— GM 發放召喚卷 ↔ 對應「一般 base 卷」映射(gm_ → 一般 / 一般 → gm_)。
//   gm_ 卷為獨立道具(與自己合成的永久區分);使用時暫時實體化 base 卷沿用既有召喚流程。
window._GM_TICKET_BASE = {
  'gm_summon_ticket_ssr':           'summon_ticket_ssr',
  'gm_summon_ticket_sr':            'summon_ticket_sr',
  'gm_summon_ticket_ssr_pick':      'summon_ticket_ssr_pick',
  'gm_summon_ticket_sr_pick':       'summon_ticket_sr_pick',
  'gm_summon_ticket_ur_pick':       'summon_ticket_ur_pick',
  'gm_summon_ticket_treasure':      'summon_ticket_treasure',
  'gm_summon_ticket_treasure_pick': 'summon_ticket_treasure_pick'
};
window._GM_TICKET_OF = {};
try{ Object.keys(window._GM_TICKET_BASE).forEach(function(g){ window._GM_TICKET_OF[window._GM_TICKET_BASE[g]] = g; }); }catch(_){}
window._isGmTicketId = function(id){ return !!(id && window._GM_TICKET_BASE && window._GM_TICKET_BASE[id]); };
// ── GM 卷「發放理由 + 時間」中繼資料(供背包說明顯示;綁 uid 存 localStorage,認領成功時寫入)──
window._gmTicketMetaKey = function(uid){
  var _u = uid || (window._fbUser && window._fbUser.uid) || window._gUserId || 'anon';
  return 'lxps_gm_ticket_meta_' + _u;
};
// 認領某筆 GM 獎勵成功後,把該筆「事蹟/理由 + 時間」記到其含有的每種 gm_ 卷(存最新一筆)
window._recordGmTicketMeta = function(uid, rewardBackpack, merit, at){
  try{
    if(!rewardBackpack || typeof rewardBackpack !== 'object') return;
    var _key = window._gmTicketMetaKey(uid);
    var _meta = {};
    try{ _meta = JSON.parse(localStorage.getItem(_key) || '{}') || {}; }catch(_){ _meta = {}; }
    var _t = at || Date.now();
    Object.keys(rewardBackpack).forEach(function(itemId){
      if(!window._isGmTicketId(itemId)) return;
      _meta[itemId] = { merit: String(merit || ''), at: _t, n: (rewardBackpack[itemId] || 0) };
    });
    try{ localStorage.setItem(_key, JSON.stringify(_meta)); }catch(_){}
  }catch(_e){ try{ console.warn('[_recordGmTicketMeta]', _e); }catch(_){} }
};
window._getGmTicketMeta = function(itemId){
  try{
    var _meta = JSON.parse(localStorage.getItem(window._gmTicketMetaKey()) || '{}') || {};
    return _meta[itemId] || null;
  }catch(_){ return null; }
};
// GM 卷背包說明尾巴:顯示「🎁 老師發放理由 + 時間」(有中繼資料才顯示理由)
window._gmTicketDescTail = function(itemId){
  try{
    var _m = window._getGmTicketMeta(itemId);
    if(_m && (_m.merit || _m.at)){
      var _d = _m.at ? new Date(_m.at) : null;
      var _dstr = _d ? ((_d.getMonth()+1) + '/' + _d.getDate() + ' ' + String(_d.getHours()).padStart(2,'0') + ':' + String(_d.getMinutes()).padStart(2,'0')) : '';
      return '🎁 老師發放' + (_m.merit ? ('・理由:' + _m.merit) : '') + (_dstr ? ('（' + _dstr + '）') : '');
    }
    return '🎁 這是老師親自發放的獎勵召喚卷';
  }catch(_){ return '🎁 這是老師親自發放的獎勵召喚卷'; }
};
// ════════════════════════════════════════════════════════════════════
// ★★ v5.135.0（2026-09-03・老師裁定「所有的卷都補上 ID，一張卷對應一隻角色／至寶」）★★
//   【召喚卷唯一 ID・實例制】根治「一張券被用多次 → 資產複製」
// ────────────────────────────────────────────────────────────────────
//   【為什麼要做】v5.91.0／v5.97.0 只把「扣券」補成即時落地，本質仍是「背包數字 −1」。
//     數字沒有身分，所以雲端一旦回退（App 被切走／網路不穩／寫入配額耗盡／殘槽 union），
//     券就完好如初，同一張可以再用第 N 次。
//   【怎麼根治】給每一張券一個唯一 tid，並記下「哪些 tid 已經用掉」：
//     ① inst 才是唯一權威，背包數字降為投影（backpackGet 券類一律讀實例數）
//     ② 消費 ＝ 刪 inst ＋ push used（used 為 append-only 已用清單）
//     ③ 三槽合併最後一律 inst = inst \ used ⇒ 殘槽把已用券 union 回來當場蒸發
//     ④ 對帳分母 un[item]（歷來離開 inst 的張數・單調遞增・逐鍵 max・永不裁切）
//        ⇒ 「背包數字沒降的幽靈券」不會被對帳器補成新實例（見 _ticketReconcile 公式）
//   【零改動納管】掛鉤直接下在 backpackAdd／backpackRemove ⇒ 任何發放端（課堂獎勵／知識王／
//     靈魂碎片／鬥技場兌換／好友贈禮／補償／序號）與任何消費端一律自動納管，
//     不必逐處改寫，日後新增的入口也不可能漏接。
//   ⚠ pet_summon_ticket 刻意不納入：消費路徑不同且不涉及英雄／至寶複製；納入會因
//     「降了 backpack 卻沒降 inst」被對帳器補回 ＝ 變成無限券。
//   ⚠ 資料存主檔 ticketData（+ _s 字串權威），零新 collection ⇒ firestore.rules 零改動。
// ════════════════════════════════════════════════════════════════════
window._TICKET_INST_IDS = (function(){
  var _m = {};
  try{
    Object.keys(window._GM_TICKET_BASE || {}).forEach(function(g){
      _m[g] = 1;                              // gm_ 券
      _m[window._GM_TICKET_BASE[g]] = 1;      // 對應 base 券
    });
  }catch(_){}
  return _m;   // 共 14 個 id（7 base + 7 gm_）
})();
window._ticketData = { v:1, inst:{}, used:[], un:{}, bf:false };
window._ticketHydrated = false;
window._ticketBusy = false;   // 內部操作 _playerBackpack 時的防遞迴閘門
window._TICKET_USED_CAP = 2000;

window._isTicketInstId = function(id){ try{ return !!window._TICKET_INST_IDS[id]; }catch(_){ return false; } };
// 券短碼（讓 tid 一眼看得出是哪種券；不影響唯一性）
window._ticketShortCode = function(itemId){
  try{
    var s = String(itemId || '');
    var g = (s.indexOf('gm_') === 0) ? 'G' : 'N';
    var b = s.replace('gm_', '').replace('summon_ticket_', '');
    var _map = { 'ssr':'SSR', 'sr':'SR', 'ssr_pick':'SSP', 'sr_pick':'SRP', 'ur_pick':'URP', 'treasure':'TRE', 'treasure_pick':'TRP' };
    return g + (_map[b] || 'XXX');
  }catch(_){ return 'NXXX'; }
};
// 產生唯一 tid：uid前6碼 - 券短碼 - 時間36進位 - 亂數4（跨裝置不可能相撞）
window._ticketNewTid = function(itemId){
  var _u = '';
  try{ _u = String(window._gUserId || 'anon').replace(/[^a-zA-Z0-9]/g, '').slice(0, 6); }catch(_){ _u = 'anon'; }
  var _r = Math.random().toString(36).slice(2, 6).toUpperCase();
  return _u + '-' + window._ticketShortCode(itemId) + '-' + Date.now().toString(36).toUpperCase() + '-' + _r;
};
window._ticketEnsure = function(){
  var d = window._ticketData;
  if(!d || typeof d !== 'object' || Array.isArray(d)){ d = window._ticketData = { v:1, inst:{}, used:[], un:{}, bf:false }; }
  if(!d.inst || typeof d.inst !== 'object' || Array.isArray(d.inst)) d.inst = {};
  if(!Array.isArray(d.used)) d.used = [];
  if(!d.un || typeof d.un !== 'object' || Array.isArray(d.un)) d.un = {};
  d.v = 1;
  return d;
};
// 該券種目前持有的實例 tid 清單（依取得時間由舊到新 ⇒ 消費一律先進先出）
window._ticketListOf = function(itemId){
  try{
    var d = window._ticketEnsure(), out = [];
    Object.keys(d.inst).forEach(function(tid){
      var r = d.inst[tid];
      if(r && r.it === itemId) out.push({ tid: tid, at: (r.at || 0) });
    });
    out.sort(function(a, b){ return (a.at - b.at) || (a.tid < b.tid ? -1 : 1); });
    return out.map(function(o){ return o.tid; });
  }catch(_){ return []; }
};
window._ticketCountOf = function(itemId){
  try{
    var d = window._ticketEnsure(), n = 0;
    Object.keys(d.inst).forEach(function(tid){ var r = d.inst[tid]; if(r && r.it === itemId) n++; });
    return n;
  }catch(_){ return 0; }
};
// 發放 n 張實例（src：來源標籤；lg：舊制券合法化標記・老師裁定①丙「要加註曾經是幽靈卷」）
window._ticketGrantInst = function(itemId, n, src, lg){
  try{
    if(!window._isTicketInstId(itemId)) return [];
    var d = window._ticketEnsure(), _n = Math.max(0, parseInt(n, 10) || 0), _out = [];
    for(var i = 0; i < _n; i++){
      var tid = window._ticketNewTid(itemId);
      while(d.inst[tid] || d.used.indexOf(tid) !== -1){ tid = window._ticketNewTid(itemId); }   // 撞號重抽（理論上不會發生）
      var rec = { it: itemId, at: Date.now() + i, src: String(src || 'grant').slice(0, 24) };
      if(lg) rec.lg = 1;                       // ⚠ 舊制券：查無取得紀錄，已依老師裁定合法化
      d.inst[tid] = rec;
      _out.push(tid);
    }
    return _out;
  }catch(_e){ try{ console.warn('[_ticketGrantInst]', _e); }catch(_){} return []; }
};
// 消費 n 張（先進先出）：刪 inst ＋ push used ＋ un 計數 +n。回傳被用掉的 tid 陣列
window._ticketConsumeInst = function(itemId, n){
  try{
    if(!window._isTicketInstId(itemId)) return [];
    var d = window._ticketEnsure(), _n = Math.max(0, parseInt(n, 10) || 0);
    var _list = window._ticketListOf(itemId).slice(0, _n), _out = [];
    _list.forEach(function(tid){
      delete d.inst[tid];
      if(d.used.indexOf(tid) === -1) d.used.push(tid);
      _out.push(tid);
    });
    if(_out.length){
      d.un[itemId] = (parseInt(d.un[itemId], 10) || 0) + _out.length;   // ★ 單調遞增・永不遞減 ＝ 對帳分母
      if(d.used.length > window._TICKET_USED_CAP) d.used = d.used.slice(-window._TICKET_USED_CAP);
    }
    return _out;
  }catch(_e){ try{ console.warn('[_ticketConsumeInst]', _e); }catch(_){} return []; }
};
// ★ v5.143.0 — 取「剛剛用掉的券 tid」供解鎖帳本寫入（只認 30 秒內、且來源標籤含 ticket 的解鎖）
//   backpackRemove 每次消費券實例都會覆寫 window._ticketLastUsed；解鎖帳本在同一個同步流程內緊接呼叫，
//   故取到的一定是本次那張。逾時或非券來源一律回空字串（不影響舊格式）。
window._ticketTidTag = function(source){
  try{
    var s = String(source || '');
    if(s.indexOf('ticket') < 0) return '';
    var l = window._ticketLastUsed;
    if(!l || !Array.isArray(l.tids) || !l.tids.length) return '';
    if((Date.now() - (l.at || 0)) > 30000) return '';
    return l.tids.join(',').slice(0, 200);
  }catch(_){ return ''; }
};
// ★★ 對帳器：把「沒經過 backpackAdd 的入口」補上實例（GM 後台直寫雲端背包／舊券 backfill）★★
//   公式：需補 = 背包張數 −（目前實例數 ＋ 歷來離開數 un）
//     ・舊券 backfill        inst0 un0 bag3 → 補 3（標 lg ＝ 舊制券）
//     ・GM 直寫發 2 張        inst3 un0 bag5 → 補 2
//     ・學生正常用掉一張      inst2 un1 bag2 → 2−3 = −1 → 不補 ✓
//     ・★幽靈券（扣券沒上雲） inst2 un1 bag3 → 3−3 =  0 → **不補** ✓ 這就是根治點
//   ⚠ un 必須單調遞增且永不裁切；分母一旦縮水，幽靈券就會重新被補成合法實例（設計反例，勿改）。
window._ticketReconcile = function(tag){
  try{
    if(typeof _playerBackpack !== 'object' || !_playerBackpack) return 0;
    var d = window._ticketEnsure(), _added = 0, _first = !d.bf;
    Object.keys(window._TICKET_INST_IDS).forEach(function(itemId){
      var _bag  = parseInt(_playerBackpack[itemId], 10) || 0;
      var _have = window._ticketCountOf(itemId);
      var _un   = parseInt(d.un[itemId], 10) || 0;
      var _need = _bag - (_have + _un);
      if(_need > 0){
        window._ticketGrantInst(itemId, _need, _first ? 'legacy' : 'grant', _first ? 1 : 0);
        _added += _need;
      }
    });
    if(_first) d.bf = true;   // 首次 backfill 已完成（之後補的一律當正常新券，不再標舊制）
    if(_added > 0){ try{ console.log('[召喚卷ID] 對帳補發 ' + _added + ' 張實例' + (_first ? '（舊制券合法化）' : '') + (tag ? ('・' + tag) : '')); }catch(_){} }
    return _added;
  }catch(_e){ try{ console.warn('[_ticketReconcile]', _e); }catch(_){} return 0; }
};
// 投影：券類背包數字一律以實例數為準（inst 是權威，背包數字只是顯示用的投影）
window._ticketProjectBackpack = function(){
  try{
    if(typeof _playerBackpack !== 'object' || !_playerBackpack) return;
    window._ticketBusy = true;
    Object.keys(window._TICKET_INST_IDS).forEach(function(itemId){
      var n = window._ticketCountOf(itemId);
      if(n > 0) _playerBackpack[itemId] = n;
      else if(_playerBackpack[itemId] != null) delete _playerBackpack[itemId];
    });
  }catch(_e){ try{ console.warn('[_ticketProjectBackpack]', _e); }catch(_){} }
  finally{ window._ticketBusy = false; }
};
// 上雲用的乾淨副本
window._ticketDataForCloud = function(){
  try{
    var d = window._ticketEnsure();
    return { v:1, inst: d.inst, used: d.used.slice(-window._TICKET_USED_CAP), un: d.un, bf: !!d.bf };
  }catch(_){ return { v:1, inst:{}, used:[], un:{}, bf:false }; }
};
// 供背包說明／GM 稽核查詢：某券種的實例摘要（含編號與是否為舊制券）
window._ticketSummaryOf = function(itemId){
  try{
    var d = window._ticketEnsure();
    return window._ticketListOf(itemId).map(function(tid){
      var r = d.inst[tid] || {};
      return { tid: tid, src: r.src || '', at: r.at || 0, legacy: !!r.lg };
    });
  }catch(_){ return []; }
};

function backpackGet(id){
  // ★ v5.135.0 — 券類一律回「實例數」（inst 是唯一權威，背包數字只是投影）。
  //   hydrate 完成前退回背包數字，避免載入途中誤報 0 讓學生以為券不見了。
  try{
    if(window._ticketHydrated && window._isTicketInstId(id)) return window._ticketCountOf(id);
  }catch(_){}
  return (_playerBackpack[id]||0);
}
