function _checkShowTutorial(ctx) {
  const done = ctx === 'mini' ? _tutorialMiniDone : _tutorialDone;
  if(done) return;
  _tutorialContext = ctx;
  // 暫停戰鬥
  _tutorialActive = true;
  try{ if(typeof _gamePaused !== 'undefined') _gamePaused = true; }catch(_){}

  // 顯示「是否需要教學？」提示
  const pm = document.createElement('div');
  pm.id = '_tut-prompt';
  pm.style.cssText = [
    'position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);',
    'z-index:9900;background:linear-gradient(160deg,rgba(8,14,35,0.99),rgba(4,8,22,0.99));',
    'border:2.5px solid rgba(100,180,255,0.85);border-radius:20px;',
    'padding:clamp(18px,3vw,32px) clamp(20px,4vw,40px);text-align:center;width:min(96vw,520px);overflow-y:auto;max-height:90vh;',
    'box-shadow:0 0 60px rgba(60,140,255,0.5);',
    'font-family:"M PLUS Rounded 1c","Nunito",sans-serif;',
  ].join('');
    if(window.innerWidth > 1180){ pm.style.width='min(96vw,900px)'; pm.style.fontSize='150%'; }
  const ctxLabel = ctx === 'mini' ? '小怪戰鬥' : '鬥技場戰鬥';

  // ★ v3.5.69 — 暫停鍵介紹金框
  // ★ v3.16.57 — 老師要求:很多學生不知道戰鬥可暫停存檔·改為「每次都顯示」
  //   移除原 localStorage('pauseHintDismissed') 永久關閉閘門 + 移除「不再顯示」勾選框
  //   (共用 iPad 上一人勾選會害全班看不到·與「每次戰鬥教學都提醒」需求相違)
  let _pauseHintHtml = '';
  try{
    _pauseHintHtml =
      '<div class="_tut-pause-hint-box">'+
        '<div class="_tph-title">⏸ 重要提醒:戰鬥可以隨時暫停存檔!</div>'+
        '<div class="_tph-body">'+
          '戰鬥途中按<b style="color:#ffcc66">右上角 ⏸ 按鈕</b>,可以把目前戰鬥進度<br>'+
          '(HP、爆發、回合)存到雲端,<br>'+
          '<b style="color:#88ffaa">下次登入就能從這個回合繼續打 ⚔️</b>'+
        '</div>'+
      '</div>';
  }catch(_e){}

  pm.innerHTML = _pauseHintHtml + `
    <div style="font-size:60px;margin-bottom:12px;">📖</div>
    <div style="font-size:28px;font-weight:900;color:#88ccff;margin-bottom:10px;">第一次${ctxLabel}！</div>
    <div style="font-size:20px;color:#ffffff;line-height:1.7;margin-bottom:24px;">
      需要戰鬥教學指引嗎？<br>
      <span style="font-size:16px;color:#aabbcc;">（可隨時從「❓ 教學指引」重新開啟）</span>
    </div>
    <div style="display:flex;gap:16px;justify-content:center;">
      <button onclick="_tutBeforeAction();_startBattleTutorial()"
        style="padding:14px 36px;font-size:22px;font-weight:800;cursor:pointer;
          background:rgba(50,120,255,0.3);border:2px solid #4499ff;
          color:#88ccff;border-radius:12px;font-family:inherit;">
        📖 需要教學
      </button>
      <button onclick="_tutBeforeAction();_skipTutorial()"
        style="padding:14px 36px;font-size:22px;font-weight:800;cursor:pointer;
          background:rgba(60,10,10,0.3);border:2px solid #e84040;
          color:#e84040;border-radius:12px;font-family:inherit;">
        ✕ 直接開始
      </button>
    </div>`;
  const dim = document.createElement('div');
  dim.id = '_tut-dim';
  dim.onclick = null; // 不可關閉
  document.body.appendChild(dim);
  document.body.appendChild(pm);
}

// ★ v3.5.69 — 按下「需要教學」或「直接開始」前,先檢查暫停鍵金框的勾選狀態
window._tutBeforeAction = function(){
  try{
    const _chk = document.getElementById('_tph_dismiss_check');
    if(_chk && _chk.checked){
      localStorage.setItem('pauseHintDismissed', 'true');
      console.log('[v3.5.69] 暫停鍵介紹已永久關閉(玩家勾選)');
    }
  }catch(_e){}
};

