// ★★ v4.93.0(老師 2026-07-25 裁定甲)—— 主角「休息」天賦引導階段。
//   主角覺醒前沒有技能,改教牠用「☕ 休息」發動天賦「異界旅人的歇息」:
//   ①休息額外 +1 能量(合計 +2) ②我方全體各恢復自身最大 HP 一定比例(Lv1=10%)。
//   手指指向 b-rest 鈕,訊息條說明天賦意義與效果;玩家點下休息 → aiAct 推進 → poll 偵測完成 → 稱讚 → 完成卡。
function _tutInterStartRestPhase() {
  const hero = _tutInterHero;
  if(!hero) { _tutInterFinal(); return; }
  const ap = document.getElementById('action-panel');
  if(ap) ap.style.display = 'block';
  const restBtn = document.getElementById('b-rest');
  if(!restBtn) { _tutInterFinal(); return; }
  _tutInterPhase = 'rest_btn';
  const _rb = restBtn;
  requestAnimationFrame(() => {
    requestAnimationFrame(() => {
      try{ _tutInterShowDim(_rb, 20); }catch(_){}
      _tutInterShowArrow(_rb, 'auto');
      _tutInterShowMsg('☕ 試試「休息」！',
        '主角還沒覺醒，先用「休息」！主角有專屬天賦「異界旅人的歇息」——休息時不只回自己，還會多拿 1 點能量、讓<b>全隊夥伴一起恢復體力</b>。點「☕ 休息」發動看看！');
    });
  });
  if(_tutInterPollId) clearInterval(_tutInterPollId);
  _tutInterPollId = setInterval(_tutInterPoll, 250);
}

// ── 教學完成演出 ──
function _tutInterFinal() {
  _tutInterPhase = 'idle';
  if(_tutInterPollId){ clearInterval(_tutInterPollId); _tutInterPollId = null; }
  _tutInterClearAll();
  try{ gameCloudSave(); }catch(_){}

  const d = document.createElement('div');
  d.id = '_ti-final-el'; d.className = '_ti-final';
  /* ★ v4.93.0 —— 主角(未覺醒)走的是休息天賦支線,完成卡不提「使用技能」(牠還沒有技能),
   *   改述已學會的:普通攻擊 / 賣物品換能量 / 休息發動天賦。其他英雄維持原文。 */
  var _tfIsProtag = false;
  try{ _tfIsProtag = !!(window._isProtagHero && window._isProtagHero((_tutInterHero||{}).name)
        && !(window._lxpsProtagAwakened && window._lxpsProtagAwakened())); }catch(_eTf){}
  var _tfSub = _tfIsProtag
    ? '你已經學會戰鬥的基本操作！<br>⚔️ 普通攻擊 &nbsp;💰 賣物品換能量 &nbsp;☕ 休息發動天賦<br>主角的技能要等第六章覺醒後才會解鎖喔！<br>隨時可以點左下角「❓ 教學指引」重看說明。<br>祝你戰鬥順利，小英雄！🎉'
    : '你已掌握了戰鬥的基本操作！<br>⚔️ 普通攻擊 &nbsp;💰 賣物品換能量 &nbsp;✨ 使用技能<br>隨時可以點左下角「❓ 教學指引」重看說明。<br>祝你戰鬥順利，小英雄！🎉';
  d.innerHTML = `
    <div class="tf-icon">🏆</div>
    <div class="tf-title">教學完成！</div>
    <div class="tf-sub">
      ${_tfSub}
    </div>
    <button class="tf-btn"
      onclick="document.getElementById('_ti-final-el').remove(); playSfx('sfx-confirm2',0.7);">
      🎮 繼續戰鬥！
    </button>`;
  document.body.appendChild(d);
}


