// 檢查單一英雄,若 Lv 達標則自動解鎖,回傳新解鎖的 id 陣列
function _checkLvUnlockPortraits(name){
  const def = _LV_UNLOCK_PORTRAITS[name];
  if(!def || !def.ids || !def.ids.length) return [];
  const lv = (_heroLevels && _heroLevels[name]) || 1;
  if(lv < def.lv) return [];
  if(!_heroPortraitUnlocked[name]) _heroPortraitUnlocked[name] = [];
  const newlyUnlocked = [];
  def.ids.forEach(id => {
    if(!_heroPortraitUnlocked[name].includes(id)){
      _heroPortraitUnlocked[name].push(id);
      try{ _logSkinUnlock(name, id, 'level'); }catch(_){}
      newlyUnlocked.push(id);
    }
  });
  return newlyUnlocked;
}

// 啟動 / 雲端載入後 / 玩家進英雄圖鑑時呼叫,掃所有英雄補發
function _scanAllLvUnlockPortraits(){
  let _totalNew = 0;
  Object.keys(_LV_UNLOCK_PORTRAITS).forEach(name => {
    const newly = _checkLvUnlockPortraits(name);
    _totalNew += newly.length;
  });
  if(_totalNew > 0){
    try{ if(typeof gameCloudSave === 'function') gameCloudSave(); }catch(_){}
  }
  return _totalNew;
}

// ★ 冒險模式：等級每級 +2% 原始HP上限（線性疊加，無條件進位）
// 呼叫時機：所有英雄加入 G.p1 **並套用素質投資後**（這樣「投資HP」也會被加成）
// 使用傳入 hero 當下的 hp 作為 baseHp（即 HERO_DB 基本HP + 玩家HP投資）
// 不對小怪/BOSS 套用（它們走 HERO_DB 原始值，不呼叫這個 helper）
function _applyAdvLevelHpBonus(hero){
  if(typeof _adventureMode === 'undefined' || !_adventureMode) return;
  if(!hero || !hero.name) return;
  // ★ v3.13.83 — 先套用「極限膠囊」投資(突破自由投資上限的付費加成),再算 HP 等級加成。
  //   ① 膠囊與一般素質投資一樣只在冒險/世界BOSS生效(本函式即各戰鬥套投資後的統一收口;
  //      鬥技場不呼叫本函式 → 膠囊也不套,與一般投資一致)。
  //   ② 放在 HP 等級加成之前 → 膠囊 HP 也吃到 +2%/級(和一般投資 HP 行為一致)。
  //   ③ _capsuleApplied 旗標防同一英雄物件被重複加(快照還原的英雄已含膠囊且帶旗標,不會再加)。
  try{
    if(!hero._capsuleApplied && typeof _heroCapsuleInvested !== 'undefined' && _heroCapsuleInvested && _heroCapsuleInvested[hero.name]){
      const _c = _heroCapsuleInvested[hero.name] || {};
      if(_c.hp)  { hero.hp  += (_c.hp  || 0); hero.curHp = hero.hp; }
      if(_c.atk) { hero.atk += (_c.atk || 0); }
      if(_c.sp)  { hero.sp  += (_c.sp  || 0); }
      if(_c.spd) { hero.spd += (_c.spd || 0); }
      hero._capsuleApplied = true;
    }
  }catch(_eCap){ console.warn('[極限膠囊套用]', _eCap); }
  const lv = getHeroLevel(hero.name);
  if(lv <= 1) return;  // Lv1 無加成
  const baseHp = hero.hp;  // ★ 目前HP已含投資加成，當作 base
  if(!baseHp) return;
  const bonus = Math.ceil(baseHp * 0.02 * (lv - 1));
  if(bonus > 0){
    hero.hp    += bonus;
    hero.curHp  = hero.hp;
    hero._advLvHpBonus = bonus;  // 記錄以供顯示
  }
}
function getHeroExp(name)   { return _heroExp[name] || 0; }

function _showLevelUpSequence(levelUps, onDone) {
  if(!levelUps || !levelUps.length){ onDone(); return; }
  // ★ v3.15.68 — 連續吃經驗書會各自觸發本函式 → 多個 #_levelup-ov 疊在一起。
  //   開頭先移除既有升級彈窗,讓最新(最高等級)的取代舊的,玩家只需確認最後一個即可。
  try{ const _oldLuOv = document.getElementById('_levelup-ov'); if(_oldLuOv) _oldLuOv.remove(); }catch(_){}
  // ★ v6180 合併同英雄連續升級事件:[{A,5},{A,6},{A,7},{B,3}] → [{A,7,from:4,gain:3},{B,3,from:2,gain:1}]
  //   注意:每個 levelUp 條目記錄的是「升級後的等級」,所以 fromLv = 首個事件.lv - 1
  //   合併只對「在陣列中相鄰的同名英雄」做(維持原本顯示順序)
  const merged = [];
  for(let i = 0; i < levelUps.length; i++){
    const cur = levelUps[i];
    if(!cur || !cur.name) continue;
    const last = merged[merged.length - 1];
    if(last && last.name === cur.name && cur.lv === last.lv + 1){
      // 連續升級 → 合併到上一個條目
      last.lv = cur.lv;
      last.gain = (last.gain || 1) + 1;
    } else {
      // 新英雄或不連續 → 新條目
      merged.push({ name: cur.name, lv: cur.lv, fromLv: cur.lv - 1, gain: 1 });
    }
  }
  const item = merged[0];
  const rest = merged.slice(1);

  // 取角色圖片
  const imgUrl = (typeof HERO_IMGS !== 'undefined' && HERO_IMGS[item.name]) || '';

  // 播放音效
  try{
    const _lu = document.getElementById('sfx-level-up');
    if(_lu){ _lu.currentTime=0; _lu.volume=0.63; _lu.play().catch(()=>{}); }
    else{ beep(660,'sine',0.1,0.1); setTimeout(()=>beep(880,'sine',0.12,0.12),150); setTimeout(()=>beep(1100,'sine',0.15,0.15),320); }
  }catch(_){}

  // 建立 overlay
  const ov = document.createElement('div');
  ov.id = '_levelup-ov';
  ov.style.cssText = [
    'position:fixed;top:0;right:0;bottom:0;z-index:9800;',
    'display:flex;flex-direction:column;',
    'align-items:center;justify-content:center;',
    'width:min(92vw,420px);min-width:280px;',
    'background:linear-gradient(160deg,rgba(20,10,0,0.96),rgba(10,5,0,0.97));',
    'border-left:3px solid rgba(255,200,0,0.5);',
    'box-shadow:-8px 0 40px rgba(255,180,0,0.25);',
    'font-family:"M PLUS Rounded 1c","Nunito",sans-serif;',
    'animation:_luSlideIn 0.4s cubic-bezier(0.22,1,0.36,1);',
    'padding:24px 20px;',
  ].join('');

  // 注入 keyframes
  if(!document.getElementById('_lu-style')){
    const st = document.createElement('style');
    st.id = '_lu-style';
    st.textContent = `
      @keyframes _luFadeIn{from{opacity:0;transform:scale(0.85)}to{opacity:1;transform:scale(1)}}
      @keyframes _luSlideIn{from{opacity:0;transform:translateX(100%)}to{opacity:1;transform:translateX(0)}}
      @keyframes _luFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-8px)}}
      @keyframes _luGlow{0%,100%{text-shadow:0 0 8px #ffcc44,0 0 16px #ff8800}50%{text-shadow:0 0 12px #ffee44,0 0 22px #ffaa00,0 0 30px #fff}}
      @keyframes _luParticle{0%{opacity:1;transform:translate(0,0) scale(1)}100%{opacity:0;transform:translate(var(--px),var(--py)) scale(0)}}
      ._lu-img{width:180px;height:180px;object-fit:cover;border-radius:50%;border:4px solid #ffcc44;
        box-shadow:0 0 30px rgba(255,200,0,0.7);animation:_luFloat 2s ease-in-out infinite;}
      ._lu-title{font-size:36px;font-weight:900;color:#ffe066;margin:12px 0 6px;animation:_luGlow 1.5s ease-in-out infinite;text-align:center;}
      ._lu-name{font-size:28px;font-weight:800;color:#fff;margin-bottom:4px;text-align:center;}
      ._lu-lv{font-size:44px;font-weight:900;color:#44ff88;text-shadow:0 0 20px #00ff88;text-align:center;}
      ._lu-pt{font-size:20px;color:#aaffcc;margin-top:4px;text-align:center;}
    `;
    document.head.appendChild(st);
  }

  // 生成粒子
  let particlesHTML = '';
  for(let p=0; p<20; p++){
    const angle = (p/20)*Math.PI*2;
    const dist = 120 + Math.random()*120;
    const px = Math.round(Math.cos(angle)*dist)+'px';
    const py = Math.round(Math.sin(angle)*dist)+'px';
    const colors = ['#ffcc44','#ff8800','#44ff88','#88ccff','#ff88cc'];
    const col = colors[p%colors.length];
    const size = 8+Math.random()*12;
    const dur = 0.8+Math.random()*0.8;
    const delay = Math.random()*0.4;
    particlesHTML += `<div style="position:absolute;width:${size}px;height:${size}px;background:${col};border-radius:50%;
      --px:${px};--py:${py};animation:_luParticle ${dur}s ${delay}s ease-out forwards;top:50%;left:50%;margin:-${size/2}px 0 0 -${size/2}px;"></div>`;
  }

  ov.innerHTML = `
    <div style="position:relative;text-align:center;">
      ${imgUrl ? `<img class="_lu-img" src="${imgUrl}" alt="${item.name}">` :
        `<div style="width:180px;height:180px;border-radius:50%;border:4px solid #ffcc44;
          background:rgba(255,200,0,0.2);display:flex;align-items:center;justify-content:center;
          font-size:80px;box-shadow:0 0 30px rgba(255,200,0,0.7);animation:_luFloat 2s ease-in-out infinite;">
          ${(typeof AVATARS!=='undefined'&&AVATARS[item.name])||'⭐'}
        </div>`}
    </div>
    <div class="_lu-title">🎉 升 級 ！</div>
    <div class="_lu-name">${item.name}</div>
    <div class="_lu-lv">${item.gain > 1 ? `Lv. ${item.fromLv} → ${item.lv}` : `Lv. ${item.lv}`}</div>
    <div class="_lu-pt">✨ 獲得 ${item.gain || 1} 點素質點數！</div>
    <button class="_lu-confirm-btn" style="margin-top:20px;padding:12px 40px;font-size:26px;font-weight:900;
      background:linear-gradient(135deg,rgba(80,180,80,0.9),rgba(40,120,40,0.9));
      border:3px solid #44ff88;color:#fff;border-radius:14px;cursor:pointer;
      font-family:inherit;box-shadow:0 0 20px rgba(0,255,100,0.4);">
      ✔ 確認
    </button>
    <div style="font-size:9px;color:#666;opacity:0.5;margin-top:8px;">v6180</div>`;

  // ★ 用 addEventListener 取代 inline onclick，避免 JSON.stringify 的 " 破壞 HTML 屬性
  const _luBtn = ov.querySelector('._lu-confirm-btn');
  if(_luBtn){
    _luBtn.addEventListener('click', function _luConfirm(){
      _luBtn.removeEventListener('click', _luConfirm);
      ov.style.opacity = '0';
      ov.style.transition = 'opacity 0.3s';
      setTimeout(() => {
        if(ov.parentNode) ov.remove();
        _showLevelUpSequence(rest, onDone);  // ★ 直接傳 rest/onDone 閉包，不走 JSON.stringify
      }, 300);
    });
  }

  flashScreen('rgba(255,220,50,0.3)', 400);
  document.body.appendChild(ov);
  // ★ 升級特效 GIF：疊在角色圖片上
  try{
    const _luImg = ov.querySelector('._lu-img');
    if(_luImg) _levelUpGifOverlay(_luImg);
  }catch(_){}
}


window._treasureLevelUpQueue = [];
window._treasureLevelUpProcessing = false;

function _enqueueTreasureLevelUp(item){
  // item: { id, name, iconUrl, icon, lv }
  if(!item) return;
  window._treasureLevelUpQueue.push(item);
  if(!window._treasureLevelUpProcessing){
    window._treasureLevelUpProcessing = true;
    setTimeout(_processTreasureLevelUpQueue, 1500); // 延遲 1.5 秒讓戰鬥動畫先跑
  }
}

function _processTreasureLevelUpQueue(){
  try{
    if(!window._treasureLevelUpQueue || window._treasureLevelUpQueue.length === 0){
      window._treasureLevelUpProcessing = false;
      return;
    }
    const item = window._treasureLevelUpQueue.shift();
    _showTreasureLevelUpModal(item, () => {
      // 確認後 200ms 處理下一個
      setTimeout(_processTreasureLevelUpQueue, 200);
    });
  }catch(e){
    console.warn('[至寶升級視窗] 處理失敗', e);
    window._treasureLevelUpProcessing = false;
  }
}

