function _calcMobExp(mob){
  if(!mob) return 0;
  const _hp  = (typeof mob.hp  === 'number') ? mob.hp  : 0;
  const _atk = (typeof mob.atk === 'number') ? mob.atk : 0;
  const _sp  = (typeof mob.sp  === 'number') ? mob.sp  : 0;
  const _spd = (typeof mob.spd === 'number') ? mob.spd : 0;
  return Math.max(0, Math.round((_hp + _atk + _sp + _spd) * 0.5));
}

function _calcBaseExpFromName(name){
  try{
    if(typeof HERO_DB === 'undefined' || !HERO_DB[name]) return 0;
    const b = HERO_DB[name];
    return _calcMobExp({ hp: b.hp, atk: b.atk, sp: b.sp, spd: b.spd });
  }catch(_){ return 0; }
}

function _advMaokongLvBonusPct(){
  try{
    if(typeof _adventureStage === 'undefined' || _adventureStage !== 'maokong') return 0;
    if(typeof G === 'undefined' || !G || !G.p1 || !G.p1.length) return 0;
    if(typeof _heroLevels === 'undefined' || !_heroLevels) return 0;
    let _sum = 0, _count = 0;
    G.p1.forEach(h => {
      if(h && h.name){
        const _lv = _heroLevels[h.name] || 1;
        _sum += _lv;
        _count++;
      }
    });
    if(_count === 0) return 0;
    const _avg = _sum / _count;
    return Math.max(0, _avg - 1) * 0.02;
  }catch(_e){
    console.warn('[木柵浮動 % 計算] 失敗,回傳 0:', _e);
    return 0;
  }
}

async function grantBattleExp(win, stats) {
  if(!win) return;
  // ★ 鬥技場模式不給予任何獎勵（只有冒險模式才有EXP和技能書）
  if(typeof _adventureMode === 'undefined' || !_adventureMode) return;
  // ★ v3.12.13(2026-05-31)— BUG 復發核心修補 #3:grantBattleExp 最後一道防線
  //   血淚案例(老師確認):若 _showResultWithDrama / advStartWinSequence 守門全部失靈,
  //                       grantBattleExp 就是「真正寫雲端發 EXP+幣」的最後執行點
  //                       上次世界 BOSS 戰跑到這裡 → 發了 +306 萬 EXP + +91 萬幣 + 污染 _heroLevels
  //   修法:函式入口直接守 worldboss stage,任何路徑跑進來都直接 return
  //         即使上游守門全失靈,這裡也絕對不會發任何 EXP/幣
  //   ★ 為什麼要在這裡 (重複)守:_showResultWithDrama 是「UI 結算流程」入口,
  //     但 grantBattleExp 也有從 advStartWinSequence、捷徑補發(line ~68059)、
  //     advShowWinSequence(line ~68210)等獨立呼叫點。世界 BOSS 戰絕不能跑這條路。
  //   ★ 鐵律 1.112 補強:任何「實際發 EXP / 幣 / 寫雲端」的函式必須先擋 worldboss stage
  try{
    if(typeof _adventureStage !== 'undefined' && _adventureStage === 'worldboss'){
      console.warn('🛡 [grantBattleExp v3.12.13] worldboss stage → 直接 return,'
        + '絕不發 EXP/幣(鐵律 1.112,世界 BOSS 戰純名譽戰)');
      return;
    }
  }catch(_eWbExpGuard){ console.warn('[grantBattleExp v3.12.13 worldboss 守門例外]', _eWbExpGuard); }
  // ★ v1.0.20260423.5800 — 修正:基礎英雄沒被列入 advGetUnlockedHeroes,出戰也拿不到 EXP
  const _unlocked = advGetUnlockedHeroes();
  const _basePool = (typeof ADV_HERO_POOL !== 'undefined' && ADV_HERO_POOL[_adventureStage]) || [];
  const heroes = Array.from(new Set([..._basePool, ..._unlocked]));
  if(!heroes.length) return;
  // ★ v1.0.20260512.6350 — baseExp 改用「base stat」計算(從 HERO_DB 直接讀,不從 G.p2 當下 stat)
  //   設計理念:加法疊加制下,baseExp 必須穩定不浮動,避免木柵/HP 倍率被重複計入(既影響 BOSS 變強又加進加成池)
  let baseExp = 0;
  if(typeof window !== 'undefined' && typeof window._lastBattleBaseExp === 'number' && window._lastBattleBaseExp > 0){
    baseExp = window._lastBattleBaseExp;
    console.log('[grantBattleExp] 使用 advStartWinSequence 快照的 baseExp (base stat) =', baseExp);
  } else if(G && G.p2 && G.p2.length){
    // fallback:G.p2 還在的話用 _calcBaseExpFromName(讀 HERO_DB),不要用 _calcMobExp(讀當下 stat)
    // ★ v3.13.28 — 排除 BOSS 分身(_isBossClone):黑暗球分身不計經驗
    G.p2.forEach(h => {
      if(h && h.name && !h._isBossClone) baseExp += (typeof _calcBaseExpFromName === 'function' ? _calcBaseExpFromName(h.name) : _calcMobExp(h));
    });
  }
  if(baseExp === 0) baseExp = 100; // 保底:極端情況(p2 全空且無快照)的預設值
  const correct = stats && stats.correctCount ? stats.correctCount : 0;
  const rounds  = stats && stats.rounds ? stats.rounds : 1;
  const score   = stats && stats.totalQuizScore ? stats.totalQuizScore : 0;
  const ratio = Math.min(2.0,
    1.0 + correct*0.08 + Math.max(0,20-rounds)*0.02 + score*0.0005
  );
  const _ratioAdd = ratio - 1; // 答題加成 % 部分(0~1.0)
  // 自信(同 HP 倍率):沒自信+0% / 普通+25% / 我很會+50%
  const _confMult = (typeof ADV_CONFIDENCE_MULT !== 'undefined' && ADV_CONFIDENCE_MULT[_advPlayerDifficulty]) || 1.00;
  const _confAdd = _confMult - 1; // 0 / 0.25 / 0.5
  // 連擊:0~+45%
  const _maxStreak = (stats && stats.maxStreak) || 0;
  const _streakAdd = Math.max(0, Math.min(9, _maxStreak - 1)) * 0.05;
  // 評分:S+50% / A+20% / B+0% / C-20% / D-40%
  let _gradeAdd = 0;
  try{
    const _gradeText = (document.getElementById('adv-result-grade')||{}).textContent || '';
    const _gradeAddMap = {'S':0.50, 'A':0.20, 'B':0.00, 'C':-0.20, 'D':-0.40};
    for(const _g of Object.keys(_gradeAddMap)){
      if(_gradeText.includes(_g)){ _gradeAdd = _gradeAddMap[_g]; break; }
    }
  }catch(_){}
  // 通用獎勵倍率(課堂 +25% + 期間 +25% + 日本 +20%)
  const _gbInfo = (typeof window._advCalcRewardMult === 'function')
    ? window._advCalcRewardMult(_advPlayerSubject)
    : { mult: 1.0, isReview: false, isDoubled: false, isJapan: false };
  // ★ v3.11.6(2026-05-27)鐵律 1.98 — 出戰英雄 EXP 發放時提交「今日加成已領」旗標(等冪,可重複呼叫)
  try{ if(win && typeof window._advCommitReviewBonusFlags === 'function') window._advCommitReviewBonusFlags(_gbInfo); }catch(_){}
  const _jpAdd = _gbInfo.mult - 1; // 0 / 0.20 / 0.25 / 0.45 / 0.50 / 0.70 等
  // 木柵浮動加成(平均 Lv,每高 1 級 +2%,Lv50 達上限 +98%)
  // 取用 advStartWinSequence 快照(G.p1 清空前算好的),fallback 即時計算
  let _mkAdd = 0;
  if(typeof window !== 'undefined' && typeof window._lastBattleMaokongPct === 'number' && window._lastBattleMaokongPct > 0){
    _mkAdd = window._lastBattleMaokongPct;
  } else if(typeof _advMaokongLvBonusPct === 'function'){
    _mkAdd = _advMaokongLvBonusPct();
  }
  // 加法疊加總倍率
  const _totalMult = Math.max(0.6, 1 + _ratioAdd + _confAdd + _streakAdd + _gradeAdd + _jpAdd + _mkAdd);
  // ★ v3.14.13(丙)— 龍王的祝福:全服 EXP +25%(乘法,疊在加法總倍率之外)
  const _blessMultExp = (typeof window._gameBlessingMult === 'function') ? window._gameBlessingMult() : 1.0;
  console.log('[grantBattleExp v6350 加法疊加]', {
    baseExp,
    ratio: ratio.toFixed(2),  ratioAdd: (_ratioAdd*100).toFixed(0)+'%',
    conf: _confMult, confAdd: (_confAdd*100).toFixed(0)+'%',
    streak: _maxStreak, streakAdd: (_streakAdd*100).toFixed(0)+'%',
    gradeAdd: (_gradeAdd*100).toFixed(0)+'%',
    jpAdd: (_jpAdd*100).toFixed(0)+'%',
    mkAdd: (_mkAdd*100).toFixed(1)+'%',
    totalMult: _totalMult.toFixed(3),
    blessMult: _blessMultExp.toFixed(2),
  });
  // ★ v5.30.0 — 裝備「經驗獲得 +%」(筆記本/學習天賦詞條;上場隊伍取單一英雄合計最大值,比照至寶掉寶口徑)
  const _gearExpMult = 1 + ((typeof _gearTeamPct === 'function') ? _gearTeamPct('exp') : 0) / 100;
  const totalExpFinal = Math.round(baseExp * _totalMult * _blessMultExp * _gearExpMult);
  let battleHeroes;
  if(typeof window !== 'undefined' && Array.isArray(window._lastBattleP1Names) && window._lastBattleP1Names.length){
    battleHeroes = window._lastBattleP1Names;
    console.log('[grantBattleExp] 使用 advStartWinSequence 快照的出戰名單:', battleHeroes);
  } else {
    battleHeroes = G && G.p1 ? G.p1.map(h=>h.name) : [];
  }
  const _bossLevelUps = [];
  // ★ v3.14.12 — 好友英雄 EXP 排除根治:舊判定 window._invitedFriendHero 恆為 undefined
  //   (_invitedFriendHero 是 let 變數不掛 window,鐵律 1.52 同型陷阱)→ 排除從未生效
  //   → 借用英雄領 EXP → _heroLevels 被建立 → 自癒網把它補進解鎖清單 → 「借巫女打貓空直接解鎖巫女」災難。
  //   新判定:advStartWinSequence 快照 _lastBattleBorrowedNames(主)+ _advBorrowedHeroNames()(輔)+ 裸讀 _invitedFriendHero(後備)
  const _exclBorrowExp = new Set(Array.isArray(window._lastBattleBorrowedNames) ? window._lastBattleBorrowedNames : []);
  try{ if(typeof window._advBorrowedHeroNames === 'function') window._advBorrowedHeroNames().forEach(n => _exclBorrowExp.add(n)); }catch(_){}
  try{ if(typeof _invitedFriendHero !== 'undefined' && _invitedFriendHero && _invitedFriendHero.name && window._friendHeroInParty) _exclBorrowExp.add(_invitedFriendHero.name); }catch(_){}
  heroes.forEach(name => {
    if(_exclBorrowExp.has(name)) return; // ★ 好友英雄不獲得EXP(v3.14.12 修復)
    const mul = battleHeroes.includes(name) ? 1.5 : 0; // ★ 未出戰=0
    const _lu = addHeroExp(name, Math.round(totalExpFinal * mul));
    if(_lu && _lu.length) _bossLevelUps.push(..._lu);
  });
  // ★ v3.37.0 寵物馴養 — 跟隨中寵物同步獲得 EXP(僅勝利主戰鬥;小怪戰不經此=保守漏收可接受)
  try{ if(typeof window._grantPetBattleExp==='function') window._grantPetBattleExp(battleHeroes, _exclBorrowExp); }catch(_){}
  if(typeof window !== 'undefined') window._lastBossLevelUps = _bossLevelUps;
  const battleExp = Math.round(totalExpFinal * 1.5);
  // ★ v1.0.20260423.5600 — 暴露最後結算 EXP,讓金幣計算可用 battleExp × 0.5 公式
  if(typeof window !== 'undefined') window._lastBattleExp = battleExp;
  // ★ v1.0.20260512.6350 — banner 顯示總加成 % 與評分加成(非 B=0 才顯示)
  const _gradeAddPct = Math.round(_gradeAdd * 100);
  const _gradeTxt = _gradeAddPct !== 0 ? `,評分${_gradeAddPct > 0 ? '+' : ''}${_gradeAddPct}%` : '';
  const _totalAddPct = Math.round((_totalMult - 1) * 100);
  bannerFX(null, `⭐ 出戰英雄 +${battleExp} EXP（總加成+${_totalAddPct}%${_gradeTxt}）`, '#ffe066', 2400);
  // 技能升級書
  const books = 1 + (score > 500 ? 1 : 0) + (correct >= 3 ? 1 : 0);
  _skillBookCount += books;
  log(`📖 獲得技能升級書×${books}（共${_skillBookCount}本）`);
  // ★ v1.0.20260512.6350 — 用完快照後清掉,避免下一場戰鬥誤用上一場的快照
  try{
    if(typeof window !== 'undefined'){
      window._lastBattleP1Names = null;
      window._lastBattleBaseExp = null;
      window._lastBattleMaokongPct = null;
      window._lastBattleBorrowedNames = null;  // ★ v3.14.12
    }
  }catch(_){}
  // ★ v3.14.23(2026-06-13)— 縮短「結算 → 升級彈窗」等待:雲端存檔改背景非同步(不 await)
  //   血淚教訓:BOSS 戰 advStartWinSequence 是「await grantBattleExp() → 才彈升級」,
  //   本函式內原本 await gameCloudSave() 會卡住整個流程 → 共用平板網路慢時,玩家
  //   按完確認後要乾等存檔跑完才看到升級畫面,容易誤以為卡死。
  //   EXP/等級此時已套用進 _heroLevels、升級清單已存入 _lastBossLevelUps(本行之前),
  //   存檔只是持久化,不需擋 UI。對齊小怪戰 advFinishMiniBattle(line ~106536)既有
  //   fire-and-forget 慣例;持久化另有 autosave + 中斷快照雙重保險,不影響存檔安全。
  _setNavDot('英雄', true);
  try{ Promise.resolve(gameCloudSave()).catch(function(){}); }catch(_){}
}

function addHeroExp(name, exp) {
  // ★ v3.16.30 — 待審查英雄(這是我的但與雲端不符)凍結:戰鬥中仍可出戰,但不獲得經驗/升級(靜默跳過,不打斷戰鬥)。
  try{ if(window._isAuditPending && window._isAuditPending(name)) return 0; }catch(_){}
  // ★ v3.5.50 — 預防 _heroLevels 污染(老師 2026/05/23 回報:本地統計算到 94 位但實際 62 位)
  //   舊版即使 exp=0 也會「if(!_heroLevels[name]) _heroLevels[name] = 1」初始化,
  //   小怪戰結束時 heroes.forEach 對「全部解鎖角色 + base pool」呼叫 addHeroExp(name, 0),
  //   把根本沒培養的角色也塞進 _heroLevels lv=1,造成統計污染。
  //   修法:exp=0 + 該英雄從未在 _heroLevels 內 → 直接 return,不污染。
  //   exp>0 或既有資料 → 正常處理(升級流程不受影響)。
  if((!exp || exp <= 0) && !_heroLevels[name]){
    return [];  // 不污染,回傳空升級事件陣列
  }
  if(!_heroExp[name]) _heroExp[name] = 0;
  if(!_heroLevels[name]) _heroLevels[name] = 1;
  // ★ v1.0.20260423.5800 — 診斷 log:確認 EXP 真的進到角色身上
  const _expBefore = _heroExp[name];
  const _lvBefore = _heroLevels[name];
  _heroExp[name] += exp;
  console.log(`[addHeroExp] ${name} Lv${_lvBefore} EXP ${_expBefore}→${_heroExp[name]} (+${exp})`);
  const _levelUps = []; // ★ 收集本次升級事件
  // 升級
  while(_heroLevels[name] < 50) {
    const needed = _expForLevel(_heroLevels[name]);
    if(_heroExp[name] >= needed) {
      _heroExp[name] -= needed;
      _heroLevels[name]++;
      _levelUps.push({ name, lv: _heroLevels[name] }); // ★ 記錄
      if(!_heroStatPoints[name]) _heroStatPoints[name] = 0;
      _heroStatPoints[name]++;
      log(`🌟 [${name}] 升級！LV${_heroLevels[name]}！獲得1點素質點數！`);
      // ★ v3.5.15 — 老師回報(2026/5/22):有同學英雄 11 級卻沒解鎖「初顯鋒芒」獎章
      //   根因:_checkMedalHeroLevel 函式定義在 line 74642,但「沒有任何地方呼叫它」,
      //         所以英雄升到 10/30/50 級的獎章(hero_lv10/hero_lv30/hero_lv50)永遠不會解鎖。
      //   修補:在升級成功後立即呼叫,以「升級後的等級」 _heroLevels[name] 為依據。
      //   注意:此處的「補檢查」機制 — 即使學生已過 Lv10 沒解鎖,只要再升一級會把所有
      //         達標的獎章一次補解鎖(因為 _checkMedalHeroLevel 用 >= 比較)。
      try{
        if(typeof _checkMedalHeroLevel === 'function'){
          _checkMedalHeroLevel(name, _heroLevels[name]);
        }
      }catch(_eMedal){ console.warn('[英雄升級獎章檢查] 例外', _eMedal); }
      // ★ v1.0.20260423.6800 — 等級解鎖肖像(統一處理 Lv10 / Lv20):
      //   到達該角色定義的解鎖等級時觸發,可解鎖 1 張或多張(boy + girl)
      try{
        const _newPortraits = _checkLvUnlockPortraits(name);
        if(_newPortraits.length > 0){
          const _def = _LV_UNLOCK_PORTRAITS[name];
          const _msg = `🎨 [${name}] 達 Lv${_def.lv}!解鎖精美肖像 ${_newPortraits.length} 張!可在英雄圖鑑切換`;
          log(_msg);
          if(typeof _showInGameToast === 'function'){
            _showInGameToast(_msg, '#ffcc88', 3500);
          }
        }
      }catch(_){}
      // ★ 里程碑升級：天賦技能強化（角色 Lv10/20/30/40 → 天賦 Lv2/Lv3/Lv4/Lv5 MAX；Lv50 僅給素質點與獎章）
      const _lv = _heroLevels[name];
      if([10,20,30,40].includes(_lv)){
        if(!_heroTraitLevel[name]) _heroTraitLevel[name] = 0;
        _heroTraitLevel[name]++;
        const _tl = _heroTraitLevel[name];
        const _tlDisp = _tl + 1; // 顯示值：內部0→Lv1, 內部4→Lv5(MAX)
        log(`✨ [${name}] 天賦強化！角色Lv${_lv} → 天賦 Lv${_tlDisp}${_tl>=4?'（MAX）':''}！`);
        // ★ 計算當前等級效果說明（用於動畫顯示）
        let _curEffectTxt = '';
        try{
          const _info = (typeof _TRAIT_LV_INFO !== 'undefined') ? _TRAIT_LV_INFO[name] : null;
          if(_info){
            if(_info.bonus && _info.bonus.indexOf('固定') === 0){
              _curEffectTxt = `效果：${_info.base}（固定）`;
            } else {
              const _bm = (_info.base||'').match(/(\d+)%/);
              const _om = (_info.bonus||'').match(/\+(\d+)%/);
              if(_bm && _om){
                const _rate = Math.min(100, parseInt(_bm[1]) + _tl * parseInt(_om[1]));
                _curEffectTxt = `${_info.effect}：<b style="color:#ffee88;">${_rate}%</b>`;
              } else {
                _curEffectTxt = _info.effect || '';
              }
            }
          }
        }catch(_){}
        // 動態升級演示訊息
        setTimeout(()=>{
          try{
            // ★ v1.0.20260420.3300 — 天賦強化通知從中央彈窗改為「右側滑入」,與角色升級 UI 一致,避免遮擋畫面
            flashScreen('rgba(255,220,50,0.35)', 450);
            const _fx = document.createElement('div');
            _fx.className = '_trait-up-ov';
            _fx.style.cssText = [
              'position:fixed;top:0;right:0;bottom:0;z-index:9790;',  // 9790 < 角色升級 9800,角色升級在上
              'display:flex;flex-direction:column;',
              'align-items:center;justify-content:center;',
              'width:min(92vw,380px);min-width:260px;',
              'background:linear-gradient(160deg,rgba(30,20,0,0.96),rgba(15,10,0,0.97));',
              'border-left:3px solid rgba(255,200,40,0.6);',
              'box-shadow:-8px 0 40px rgba(255,180,0,0.28);',
              'font-family:"M PLUS Rounded 1c","Nunito",sans-serif;',
              'animation:_traitSlideIn 0.4s cubic-bezier(0.22,1,0.36,1);',
              'padding:20px 18px;pointer-events:none;text-align:center;'
            ].join('');
            // 注入 keyframes(共用 _lu-style 已注入的話就跟著,否則自己加一個)
            if(!document.getElementById('_trait-up-style')){
              const _ts = document.createElement('style');
              _ts.id = '_trait-up-style';
              _ts.textContent =
                '@keyframes _traitSlideIn{from{opacity:0;transform:translateX(100%)}to{opacity:1;transform:translateX(0)}}' +
                '@keyframes _traitPulse{0%,100%{text-shadow:0 0 4px #ffcc44}50%{text-shadow:0 0 8px #ffee44,0 0 16px #ffaa00}}';
              document.head.appendChild(_ts);
            }
            const _heroImg = (typeof HERO_IMGS !== 'undefined' && HERO_IMGS[name]) || '';
            const _avEmoji = (typeof AVATARS !== 'undefined' && AVATARS[name]) || '⭐';
            _fx.innerHTML =
              '<div style="font-size:28px;font-weight:900;color:#ffcc44;letter-spacing:3px;margin-bottom:12px;animation:_traitPulse 1.5s ease-in-out infinite;">🌟 天賦強化 ！</div>' +
              (_heroImg
                ? `<img src="${_heroImg}" alt="${name}" style="width:140px;height:140px;object-fit:cover;border-radius:50%;border:3px solid #ffcc44;box-shadow:0 0 22px rgba(255,200,0,0.55);margin-bottom:10px;">`
                : `<div style="width:140px;height:140px;border-radius:50%;border:3px solid #ffcc44;background:rgba(255,200,0,0.2);display:flex;align-items:center;justify-content:center;font-size:72px;box-shadow:0 0 22px rgba(255,200,0,0.55);margin-bottom:10px;">${_avEmoji}</div>`) +
              `<div style="font-size:24px;font-weight:800;color:#fff;margin-bottom:4px;">${name}</div>` +
              `<div style="font-size:22px;color:#ffee88;margin-bottom:3px;">角色 Lv.${_lv} 里程碑</div>` +
              `<div style="font-size:28px;font-weight:900;color:#44ff88;text-shadow:0 0 16px #00ff88;margin-bottom:6px;">天賦 → Lv.${_tlDisp}${_tl>=4?' (MAX)':''}</div>` +
              (_curEffectTxt
                ? `<div style="font-size:18px;color:#ffccaa;margin-top:6px;padding:6px 12px;background:rgba(255,200,100,0.1);border:1px solid rgba(255,200,100,0.3);border-radius:8px;max-width:95%;">${_curEffectTxt}</div>`
                : '');
            document.body.appendChild(_fx);
            // 2.8 秒後淡出自動消失(跟原本中央版本一樣時長)
            setTimeout(()=>{
              if(_fx.parentNode){
                _fx.style.transition = 'opacity 0.45s, transform 0.45s ease-in';
                _fx.style.opacity = '0';
                _fx.style.transform = 'translateX(20%)';
                setTimeout(()=>{ if(_fx.parentNode) _fx.remove(); }, 480);
              }
            }, 2800);
          }catch(_){}
        }, 500);
      }
    } else break;
  }
  return _levelUps; // ★ 回傳升級清單
}

// ── 紅點通知系統 ──
const _navDots = {};
function _setNavDot(label, show) {
  _navDots[label] = show;
  // Update nav button UI if visible
  document.querySelectorAll('.adv-nav-btn').forEach(btn => {
    const lbl = btn.querySelector('.adv-nav-label');
    if(!lbl) return;
    const txt = lbl.textContent.trim();
    if(txt !== label) return;
    let dot = btn.querySelector('.adv-nav-dot');
    if(show) {
      if(!dot) {
        dot = document.createElement('div');
        dot.className = 'adv-nav-dot';
        dot.style.cssText = 'position:absolute;top:6px;left:calc(50% + 16px);width:10px;height:10px;' +
          'background:#ff3333;border-radius:50%;border:2px solid #fff;animation:navDotPulse 1s ease-in-out infinite;';
        btn.appendChild(dot);
      }
    } else if(dot) { dot.remove(); }
  });
}

// 自動儲存在 advHeroMeetDone 之後

// ══════════════════════════════════════════════
//  英雄頁面
// ══════════════════════════════════════════════
function highlightUpgradableHeroes() {
  if(backpackGet('skill_upgrade_book') <= 0) return;
  // 找出可升級技能的英雄（已解鎖，有 s1/s2 技能等級 < 9）
  const unlocked = advGetUnlockedHeroes();
  const advPool = typeof ADV_HERO_POOL !== 'undefined' ? (ADV_HERO_POOL.maokong || []) : [];
  const all = [...new Set([...unlocked, ...advPool])];
  const upgradable = all.filter(name => {
    const sl = _heroSkillLevels[name] || {};
    return (sl.s1 || 0) < 9 || (sl.s2 || 0) < 9;
  });
  // 在對應卡片上加黃色閃爍箭頭
  document.querySelectorAll('.hero-grid-card').forEach(card => {
    const existing = card.querySelector('.upgrade-arrow');
    if(existing) existing.remove();
  });
  upgradable.forEach(name => {
    const cards = document.querySelectorAll('.hero-grid-card');
    cards.forEach(card => {
      const nm = card.querySelector('.hn-label');
      if(nm && nm.textContent.trim() === name) {
        const arrow = document.createElement('div');
        arrow.className = 'upgrade-arrow';
        arrow.style.cssText = 'position:absolute;bottom:36px;left:50%;transform:translateX(-50%);' +
          'font-size:28px;animation:upgradeArrowBounce 0.6s ease-in-out infinite alternate;' +
          'z-index:10;pointer-events:none;';
        arrow.textContent = '⬆';
        card.appendChild(arrow);
        setTimeout(()=>{ if(arrow.parentNode) arrow.remove(); }, 4000);
      }
    });
  });
  if(upgradable.length === 0) {
    try{ bannerFX(null,'所有技能已達最高等級！','#ffcc44',1500); }catch(_){}
  }
}

// ★ 圖鑑高亮：英雄經驗值書可用的英雄（等級未滿50）
function _highlightHeroesForExpBook() {
  const unlocked = advGetUnlockedHeroes();
  const advPool = typeof ADV_HERO_POOL !== 'undefined' ? (ADV_HERO_POOL.maokong || []) : [];
  const all = [...new Set([...unlocked, ...advPool])];
  const eligible = all.filter(name => (getHeroLevel(name) || 1) < 50);
  _showHeroGridHighlight(eligible, '📗', '#88ff88');
  if(eligible.length === 0){
    try{ bannerFX(null,'所有英雄已達最高等級！','#ffcc44',1500); }catch(_){}
  }
}

// ★ 圖鑑高亮：超越極限果實可用的英雄（有爆發技能且等級 < 4）
function _highlightHeroesForBurstUpgrade() {
  const unlocked = advGetUnlockedHeroes();
  const advPool = typeof ADV_HERO_POOL !== 'undefined' ? (ADV_HERO_POOL.maokong || []) : [];
  const all = [...new Set([...unlocked, ...advPool])];
  const eligible = all.filter(name => {
    if(typeof BURST_DB === 'undefined' || !BURST_DB[name]) return false;
    const lv = (_heroBurstLevels && _heroBurstLevels[name]) || 0;
    return lv < 4;
  });
  _showHeroGridHighlight(eligible, '🍑', '#ffaa44');
  if(eligible.length === 0){
    try{ bannerFX(null,'所有英雄極限爆發已達最高等級！','#ffaa44',1500); }catch(_){}
  }
}

// ★ 共用：在圖鑑格子上顯示升級標記
function _showHeroGridHighlight(names, icon, color) {
  // 先清除舊的
  document.querySelectorAll('.hero-grid-card .upgrade-arrow').forEach(el => el.remove());
  const nameSet = new Set(names);
  document.querySelectorAll('.hero-grid-card').forEach(card => {
    const nm = card.querySelector('.hn-label');
    if(nm && nameSet.has(nm.textContent.trim())) {
      const arrow = document.createElement('div');
      arrow.className = 'upgrade-arrow';
      arrow.style.cssText = 'position:absolute;bottom:36px;left:50%;transform:translateX(-50%);' +
        'font-size:26px;animation:upgradeArrowBounce 0.6s ease-in-out infinite alternate;' +
        'z-index:10;pointer-events:none;';
      arrow.textContent = icon || '⬆';
      if(color) arrow.style.filter = `drop-shadow(0 0 6px ${color})`;
      card.appendChild(arrow);
      setTimeout(() => { if(arrow.parentNode) arrow.remove(); }, 6000);
    }
  });
}

function _showProgressLoadingMask(parentId, _opts){
  const opts = _opts || {};
  const parent = document.getElementById(parentId);
  if(!parent) return null;
  // 已有遮罩 → 不重複建立
  let mask = parent.querySelector('._progress-load-mask');
  if(mask) return mask;
  // ★ 防禦:確保父元素有 position 屬性,讓遮罩(absolute;inset:0)能正確覆蓋
  //   如果父是 static,absolute 子會跑到 <body> 鋪滿整個視窗
  try{
    const _pos = (window.getComputedStyle && window.getComputedStyle(parent).position) || '';
    if(_pos === '' || _pos === 'static'){
      parent.style.position = 'relative';
      parent.dataset._plmAddedRelative = '1'; // 標記:_hide 時清掉
    }
  }catch(_){}
  mask = document.createElement('div');
  mask.className = '_progress-load-mask';
  mask.style.cssText = 'position:absolute;inset:0;z-index:9999;'
    + 'background:linear-gradient(135deg,rgba(20,15,40,0.96),rgba(10,5,25,0.96));'
    + 'display:flex;flex-direction:column;align-items:center;justify-content:center;'
    + 'gap:20px;backdrop-filter:blur(4px);';
  mask.innerHTML = '<div style="font-size:56px;animation:_plmSpin 1.4s linear infinite;">⏳</div>'
    + '<div style="font-size:24px;font-weight:900;color:#ffe066;letter-spacing:2px;'
    + 'text-shadow:0 2px 8px rgba(0,0,0,0.7),0 0 14px rgba(255,220,100,0.4);">'
    + (opts.title || '雲端進度載入中...') + '</div>'
    + '<div style="font-size:15px;color:#aac;letter-spacing:1px;max-width:80%;text-align:center;line-height:1.6;">'
    + (opts.subtitle || '正在從雲端同步您的英雄資料,請稍候...<br>避免顯示錯誤等級') + '</div>'
    + '<style>@keyframes _plmSpin{from{transform:rotate(0)}to{transform:rotate(360deg)}}</style>';
  parent.appendChild(mask);
  return mask;
}

function _hideProgressLoadingMask(parentId, onHide){
  const parent = document.getElementById(parentId);
  if(!parent) return;
  const mask = parent.querySelector('._progress-load-mask');
  if(mask){
    mask.style.transition = 'opacity 0.3s';
    mask.style.opacity = '0';
    setTimeout(() => {
      try{ if(mask.parentNode) mask.remove(); }catch(_){}
      // ★ 還原:若先前是我們加上的 position:relative,清掉
      try{
        if(parent.dataset && parent.dataset._plmAddedRelative === '1'){
          parent.style.position = '';
          delete parent.dataset._plmAddedRelative;
        }
      }catch(_){}
      if(typeof onHide === 'function') { try{ onHide(); }catch(_){} }
    }, 320);
  } else if(typeof onHide === 'function') {
    try{ onHide(); }catch(_){}
  }
}

// 主要進入點:若需要遮罩就先擋住,然後在背景輪詢 _progressLoaded
// 一旦 _progressLoaded 變 true → 移除遮罩 + 呼叫 onReady(通常是重新渲染)
// 12 秒超時(safety net):無論如何放行,避免邊角狀況卡死
function _progressLoadGuard(parentId, onReady, _opts){
  const opts = _opts || {};
  // 訪客模式 / 未登入 → 不需要等雲端,直接放行
  if(!window._gUserId){
    if(typeof onReady === 'function') { try{ onReady(); }catch(_){} }
    return false;
  }
  // 雲端已載完(成功 or 失敗都算數) → 不需要遮罩,直接放行
  // _progressLoaded=true(成功) → 資料正確
  // _cloudLoadDone=true 但 _progressLoaded=false → 載入失敗,沒辦法只能放行
  if(window._progressLoaded === true || window._cloudLoadDone === true){
    if(typeof onReady === 'function') { try{ onReady(); }catch(_){} }
    return false;
  }
  // 還在載 → 顯示遮罩
  _showProgressLoadingMask(parentId, opts);
  const _startAt = Date.now();
  const _maxWait = 12000; // 12 秒安全網
  const _iv = setInterval(() => {
    const _ok = (window._progressLoaded === true) || (window._cloudLoadDone === true);
    const _timedOut = (Date.now() - _startAt) >= _maxWait;
    if(_ok || _timedOut){
      clearInterval(_iv);
      _hideProgressLoadingMask(parentId, () => {
        if(_timedOut && !_ok){
          console.warn('[_progressLoadGuard] 12 秒超時放行,_progressLoaded 仍為 false');
        }
        if(typeof onReady === 'function') { try{ onReady(); }catch(_){} }
      });
    }
  }, 250);
  return true; // 表示「有放遮罩」
}

function openHeroPage() {
  const ov = document.getElementById('hero-page-overlay');
  if(!ov) return;
  ov.style.display = 'flex';
  _progressLoadGuard('hero-page-overlay', () => {
    // 載完後執行(或訪客/已載完 → 直接執行)
    _openHeroPage_doRender();
  }, { title: '英雄資料載入中...', subtitle: '正在從雲端同步您的英雄等級與技能<br>避免顯示錯誤資訊,請稍候...' });
}

function _openHeroPage_doRender() {
  // Clear red dot
  _setNavDot('英雄', false);
  // Update book count
  document.getElementById('hero-page-book-count').textContent = backpackGet('skill_upgrade_book');
  const _expBookEl = document.getElementById('hero-expbook-count');
  if(_expBookEl) _expBookEl.textContent = _heroExpBookCount||0;
  const _expBtnEl = document.getElementById('hero-expbook-btn');
  if(_expBtnEl) _expBtnEl.style.display = 'none'; // 書現在在背包裡
  // 更新知識幣顯示
  const _hpCoinsEl = document.getElementById('hero-page-coins-val');
  if(_hpCoinsEl) _hpCoinsEl.textContent = (_knowledgeCoins||0).toLocaleString();
  // Build grid
  _buildHeroGrid();
  // ★ v3.15.70 — 需求5:頂列各稀有度「已解鎖/最大」彩色計數
  try{ _renderHeroCodexRarityCount(); }catch(_eRc){ console.warn('[稀有度計數]', _eRc); }
  // ★ v3.16.28 — 點進英雄圖鑑時自動彈出「英雄來源自我審查」(帳號有非初始 8 隻的英雄時·per-uid 一次性·延 350ms 讓格子先畫)
  try{ setTimeout(function(){ try{ if(typeof window._maybeShowAccountAuditOnLogin === 'function') window._maybeShowAccountAuditOnLogin(0); }catch(_){} }, 350); }catch(_){}
}

// ★ v3.15.70 — 需求5:英雄圖鑑頂列各稀有度「已解鎖/最大」彩色計數
//   母體:UR=_RARITY_UR_HEROES / SSR=SUMMON_RARE_HEROES / SR=SUMMON_SR_HEROES / R=_RARITY_R_HEROES
//   已解鎖:advGetUnlockedHeroes() 經 _getHeroRarity 分類(admin 自動全解鎖);上限保護避免溢出。
function _renderHeroCodexRarityCount(){
  const _el = document.getElementById('hero-codex-rarity-count');
  if(!_el) return;
  const _urSet = (typeof _RARITY_UR_HEROES !== 'undefined') ? _RARITY_UR_HEROES : new Set();
  const _ssrArr = (typeof SUMMON_RARE_HEROES !== 'undefined') ? SUMMON_RARE_HEROES : [];
  const _srArr = (typeof window!=='undefined' && window.SUMMON_SR_HEROES) ? window.SUMMON_SR_HEROES
               : ((typeof SUMMON_SR_HEROES !== 'undefined') ? SUMMON_SR_HEROES : []);
  const _rSet = (typeof _RARITY_R_HEROES !== 'undefined') ? _RARITY_R_HEROES : new Set();
  const _urMax = _urSet.size, _ssrMax = _ssrArr.length, _srMax = (_srArr&&_srArr.length)||0, _rMax = _rSet.size;
  let _unlocked = [];
  try{ _unlocked = (typeof advGetUnlockedHeroes==='function') ? (advGetUnlockedHeroes()||[]) : []; }catch(_){ _unlocked=[]; }
  const _uSet = new Set(_unlocked.map(n=>(n||'').trim()).filter(Boolean));
  let _urU=0,_ssrU=0,_srU=0,_rU=0;
  _uSet.forEach(n=>{
    const _r = (typeof _getHeroRarity==='function') ? _getHeroRarity(n) : null;
    if(_r==='UR') _urU++; else if(_r==='SSR') _ssrU++; else if(_r==='SR') _srU++; else if(_r==='R') _rU++;
  });
  _urU=Math.min(_urU,_urMax); _ssrU=Math.min(_ssrU,_ssrMax); _srU=Math.min(_srU,_srMax); _rU=Math.min(_rU,_rMax);
  const _mk = (label,u,max,col) =>
    '<span style="display:inline-flex;align-items:baseline;gap:3px;">'
    + '<span style="color:'+col+';font-weight:900;">'+label+'</span>'
    + '<span style="color:#fff;font-weight:900;">'+u+'</span>'
    + '<span style="color:rgba(255,255,255,0.45);font-weight:700;font-size:18px;">/'+max+'</span></span>';
  _el.innerHTML = _mk('👑UR',_urU,_urMax,'#ffe680')+_mk('SSR',_ssrU,_ssrMax,'#ff9d5c')+_mk('SR',_srU,_srMax,'#b18bff')+_mk('R',_rU,_rMax,'#7fd4ff');
}
try{ window._renderHeroCodexRarityCount = _renderHeroCodexRarityCount; }catch(_){}


