// ════════════════════════════════════════════════════════════════════
// ★ v3.15.26 — 虛寶序號兌換彈窗:開關 + 兌換邏輯(學生端)
//   呼叫後端 window._fbRedeemCode(code):成功→顯示獎勵清單+重新整理鈕;
//   失敗→顯示原因(含「此序號已被使用」/ _critical 找老師補發)。
// ════════════════════════════════════════════════════════════════════
function _redeemEsc(s){
  return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}
function openRedeemDialog(){
  const ov = document.getElementById('redeem-overlay');
  if(!ov) return;
  const inp = document.getElementById('redeem-input');
  const res = document.getElementById('redeem-result');
  const btn = document.getElementById('redeem-submit-btn');
  if(inp) inp.value = '';
  if(res) res.innerHTML = '';
  if(btn){ btn.disabled = false; btn.textContent = '✨ 兌換'; }
  ov.style.display = 'flex';
  if(typeof _syncMobileNav === 'function'){ try{ _syncMobileNav(); }catch(_e){} }
  // ★ v3.16.65 — 開窗即渲染「課堂獎勵收件區」(老師指派的待領獎勵);不自動聚焦序號框,讓收件區優先顯示
  try{ if(typeof _renderGmClassRewardInbox === 'function') _renderGmClassRewardInbox(); }catch(_eIb){}
}
function closeRedeemDialog(){
  const ov = document.getElementById('redeem-overlay');
  if(ov) ov.style.display = 'none';
  if(typeof _syncMobileNav === 'function'){ try{ _syncMobileNav(); }catch(_e){} }
}
async function _doRedeem(){
  const inp = document.getElementById('redeem-input');
  const res = document.getElementById('redeem-result');
  const btn = document.getElementById('redeem-submit-btn');
  if(!inp || !res) return;
  const code = String(inp.value || '').trim();
  if(!code){ res.innerHTML = '<span style="color:#ffaa66;">請先輸入序號</span>'; return; }
  if(typeof window._fbRedeemCode !== 'function'){ res.innerHTML = '<span style="color:#ff7766;">兌換功能未就緒,請重新整理頁面</span>'; return; }
  if(btn){ btn.disabled = true; btn.textContent = '兌換中...'; }
  res.innerHTML = '<span style="color:#cbb8e0;">兌換中,請稍候...</span>';
  let r;
  try{ r = await window._fbRedeemCode(code); }
  catch(e){ r = { ok:false, reason:'兌換發生錯誤,請稍後再試' }; }
  if(r && r.ok){
    try{ if(typeof playSfx==='function') playSfx('sfx-coin',0.85); }catch(_e){}
    const items = (r.itemsLabel || []);
    // ★ v3.17.8 — 比照 v3.16.97:兌換成功即時把獎勵套進記憶體背包,票券成為當前真相,
    //   免疫玩家沒按「重新整理」就繼續遊戲時,後續 autosave 用舊記憶體背包把剛兌換的券沖掉。
    try{
      if(r.reward && r.reward.backpack && typeof r.reward.backpack === 'object' && typeof backpackAdd === 'function'){
        Object.keys(r.reward.backpack).forEach(function(_bk){
          var _bq = Math.max(0, parseInt(r.reward.backpack[_bk], 10) || 0);
          if(_bq > 0) backpackAdd(_bk, _bq, '兌換碼 ' + String(code || '').slice(0, 16));
        });
      }
    }catch(_eApplyMem){ console.warn('[序號兌換] 套記憶體背包失敗(不影響·重新整理會補)', _eApplyMem); }
    const listHtml = items.length
      ? ('<div style="margin-top:10px;color:#ffe066;font-weight:800;font-size:16px;line-height:1.8;">' + items.map(function(s){ return _redeemEsc(s); }).join('<br>') + '</div>')
      : '';
    res.innerHTML = '<span style="color:#88ff99;font-size:20px;font-weight:900;">🎉 兌換成功!</span>' + listHtml +
                    '<div style="margin-top:10px;font-size:13px;color:#bbcce0;">獎勵已存入你的帳號,重新整理後就能看到囉!</div>' +
                    '<button onclick="_lxpsReloadKeepLoginIfLoggedIn()" style="margin-top:12px;padding:10px 22px;font-size:15px;font-weight:800;' +   /* ★ v5.148.0 舊:onclick=location.reload() */
                    'background:linear-gradient(135deg,#3a8a4a,#2a7a3a);border:2px solid #6dd66d;color:#fff;border-radius:10px;cursor:pointer;font-family:inherit;letter-spacing:1px;">🔄 重新整理看獎勵</button>';
    if(inp) inp.value = '';
    if(btn){ btn.disabled = false; btn.textContent = '✨ 兌換'; }
    return;
  }
  try{ if(typeof playSfx==='function') playSfx('sfx-cancel',0.5); }catch(_e){}
  const reason = (r && r.reason) || '兌換失敗,請確認序號是否正確';
  const critical = !!(r && r._critical);
  res.innerHTML = '<span style="color:' + (critical ? '#ffcc44' : '#ff8877') + ';font-weight:800;font-size:16px;">' +
                  (critical ? '⚠ ' : '❌ ') + _redeemEsc(reason) + '</span>';
  if(btn){ btn.disabled = false; btn.textContent = '✨ 兌換'; }
}

