// ★ v3.16.65 — GM獎勵:課堂獎勵收件區(渲染待領 + 確認領取 + 鈕上方標籤刷新)
//   後端 window._fbReadMyGmClassRewards / _fbClaimGmClassReward 在 block#02。
//   領取成功 → 1.8s 自動 location.reload():讓剛入帳獎勵(尤其 UR 英雄)從雲端乾淨載入,
//   避免被遊戲記憶體狀態於下次 autosave 覆蓋(同序號兌換/全體獎勵「reload 生效」原則)。
// ════════════════════════════════════════════════════════════════════
async function _renderGmClassRewardInbox(){
  var box = document.getElementById('gmcr-inbox');
  if(!box) return;
  box.innerHTML = '<div style="font-size:36px;color:#cbb8e0;text-align:center;padding:18px;">📨 讀取老師發的獎勵中…</div>';
  var list = [];
  try{ if(typeof window._fbReadMyGmClassRewards === 'function') list = await window._fbReadMyGmClassRewards(); }
  catch(e){ list = []; }
  // ★ v3.16.66 — 一併讀「已領取紀錄」(_gmcrClaimLog),領完不再空白→根治學生不認帳
  var claimed = [];
  try{ if(typeof window._fbReadMyGmClassRewardLog === 'function') claimed = await window._fbReadMyGmClassRewardLog(); }
  catch(_e){ claimed = []; }

  var html = '';
  // ★ v5.204.0（老師需求：「自選卷確認單的登入提示改成進入冒險模式後出現在 GM 獎勵箱，
  //   要勾選完送出才能繼續領取 GM 獎勵」）— 先問「這位學生還有沒有一封沒填的召喚卷確認單」。
  //   有 ⇒ 置頂一張問卷卡，且下面所有「✅ 確認領取」一律鎖住（鈕 disabled + 點擊時再守一次）。
  //   ⚠ 查不到／讀失敗一律不擋（_fbAssetSelfCheckPending 內部已 fail-open）：
  //     問卷再重要，也不該因為一次網路不順就讓學生領不到獎。
  var _ascP = null, _ascUid = '';
  try{
    _ascUid = (window._fbAuth && window._fbAuth.currentUser && window._fbAuth.currentUser.uid) || window._gUserId || '';
    if(_ascUid && typeof window._fbAssetSelfCheckPending === 'function') _ascP = await window._fbAssetSelfCheckPending(_ascUid);
  }catch(_eAscP){ _ascP = null; }
  try{ window._LXPS_ASC_BLOCK = !!_ascP; window._LXPS_ASC_UID = _ascUid; window._LXPS_ASC_PENDING = _ascP; }catch(_){}
  // ★ v4.8.0(2026-07-04·老師需求 1)— 🔄 重新整理鈕(雲端同步收件箱+已領取紀錄):
  //   _gmcrRefreshInbox 走 v3.16.97 冪等對帳(_fbReconcileGmClassRewardTickets·永不重複發)
  //   後重繪本收件箱;不碰任何領取/去重/transaction 邏輯。說明句依鐵律 1.232 雙版。
  var _gmcrIsCute = (typeof _artStyle !== 'undefined' && _artStyle === 'cute');
  var _gmcrRefHint = _gmcrIsCute
    ? '沒看到老師發的獎勵?按一下,從雲端再拿一次!'
    : '如果老師剛發的獎勵還沒出現,點「🔄 重新整理」會重新連線雲端,同步收件箱與已領取紀錄(不會重複領取)。';
  html += '<div style="margin:0 0 18px;padding:14px 16px;background:rgba(90,140,220,0.10);border:1.5px solid rgba(120,170,255,0.4);border-radius:14px;text-align:center;">'
    + '<button id="gmcr-refresh-btn" onclick="_gmcrRefreshInbox(this)" style="padding:14px 34px;font-size:34px;font-weight:900;background:linear-gradient(135deg,#3a6fd8,#2a4fa8);border:2px solid #88bbff;color:#fff;border-radius:12px;cursor:pointer;font-family:inherit;letter-spacing:2px;">🔄 重新整理</button>'
    + '<div style="font-size:26px;color:#a9c8f0;margin-top:10px;line-height:1.6;">' + _gmcrRefHint + '</div>'
    + '</div>';
  // ★ v5.204.0 — 召喚卷確認單置頂卡（沒填完就領不了獎）
  if(_ascP){
    var _ascCute = (typeof _artStyle !== 'undefined' && _artStyle === 'cute');
    html += '<div id="gmcr-asc-card" style="margin:0 0 18px;padding:22px;background:linear-gradient(160deg,rgba(255,150,90,0.14),rgba(255,90,90,0.10));border:2.5px solid rgba(255,170,90,0.75);border-radius:16px;text-align:left;">'
      + '<div style="font-size:42px;font-weight:900;color:#ffcf8a;margin-bottom:10px;">🎫 老師要先問你一件事</div>'
      + '<div style="font-size:34px;color:#ffe7cc;line-height:1.7;margin-bottom:14px;">'
      + (_ascCute
          ? '關於老師發給你的<b>召喚卷</b>，有幾個小問題想確認一下。<br>照實際情況勾一勾、送出，就可以繼續領獎勵了！<br><span style="font-size:28px;color:#ffd9a8;">老實說不會被罵，這是遊戲的問題，老師只是想把該補的補給你。</span>'
          : '關於老師發給你的<b>召喚卷</b>，請先完成一份簡短的確認單。<br>依實際情況勾選並送出後，即可繼續領取 GM 獎勵。<br><span style="font-size:28px;color:#ffd9a8;">據實回報不會受到任何處分，這是程式端的問題，老師只是要把該補發的補給你。</span>')
      + '</div>'
      + '<button id="gmcr-asc-btn" style="width:100%;padding:20px;font-size:46px;font-weight:900;background:linear-gradient(135deg,#d77a2a,#b0541d);border:2px solid #ffc07a;color:#fff;border-radius:14px;cursor:pointer;font-family:inherit;letter-spacing:2px;">📝 開始填寫（填完才能領獎）</button>'
      + '</div>';
  }
  // ── 上半:待領獎勵 ──
  if(list && list.length){
    html += '<div style="font-size:44px;font-weight:900;color:#ffd54f;text-align:center;margin-bottom:18px;letter-spacing:1px;">🎉 老師發給你 ' + list.length + ' 份獎勵!</div>';
    list.forEach(function(rw){
      var items = Array.isArray(rw.itemsLabel) ? rw.itemsLabel : [];
      var rid = _redeemEsc(rw.id);
      html += '<div class="gmcr-card" data-rid="' + rid + '" style="margin:0 0 18px;padding:22px;background:linear-gradient(160deg,rgba(255,210,90,0.10),rgba(160,110,255,0.08));border:2px solid rgba(255,210,90,0.5);border-radius:16px;text-align:left;">';
      if(rw.merit){
        html += '<div style="font-size:34px;font-weight:900;color:#ffd98c;margin-bottom:8px;">🏅 表現優良事蹟</div><div style="font-size:40px;color:#fff;font-weight:800;line-height:1.6;margin-bottom:16px;">' + _redeemEsc(rw.merit) + '</div>';
      }
      html += '<div style="font-size:34px;font-weight:800;color:#a9d8ff;margin-bottom:6px;">🎁 獲得獎項</div><div style="font-size:42px;color:#ffe066;font-weight:900;line-height:1.9;margin-bottom:18px;">' + (items.length ? items.map(_redeemEsc).join('<br>') : '(獎勵內容)') + '</div>';
      /* ★ v5.204.0 問卷沒填完 ⇒ 領取鈕鎖住（灰階 + disabled），並明講原因與解法 */
      if(_ascP){
        html += '<button class="gmcr-claim-btn" data-rid="' + rid + '" disabled style="width:100%;padding:20px;font-size:48px;font-weight:900;background:#3a3030;border:2px solid #6a5a4a;color:#9a8f85;border-radius:14px;cursor:not-allowed;font-family:inherit;letter-spacing:2px;">🔒 先填上面的確認單</button>';
        html += '<div style="margin-top:10px;font-size:28px;color:#ffcf8a;text-align:center;line-height:1.6;">⬆ 填完最上面那張「🎫 召喚卷確認」並送出，這顆按鈕就會解開。</div>';
      } else {
        html += '<button class="gmcr-claim-btn" data-rid="' + rid + '" style="width:100%;padding:20px;font-size:48px;font-weight:900;background:linear-gradient(135deg,#2a8a3a,#1d7a2a);border:2px solid #66dd88;color:#fff;border-radius:14px;cursor:pointer;font-family:inherit;letter-spacing:2px;">✅ 確認領取</button>';
      }
      html += '<div class="gmcr-card-result" style="margin-top:12px;font-size:34px;text-align:center;line-height:1.6;"></div>';
      html += '</div>';
    });
  } else {
    html += '<div style="font-size:34px;color:#9aa6c8;text-align:center;padding:20px;background:rgba(255,255,255,0.04);border:1px dashed rgba(160,170,210,0.3);border-radius:14px;">目前沒有老師指派的待領獎勵<br><span style="font-size:28px;color:#7f8aa8;">老師發獎後,這裡會出現「確認領取」的卡片</span></div>';
  }

  // ── 下半:已領取紀錄(_gmcrClaimLog·含獎項/事蹟/領取時間) ──
  if(claimed && claimed.length){
    html += '<div style="margin:22px 0 12px;border-top:2px dashed rgba(160,170,210,0.3);"></div>';
    html += '<div style="font-size:38px;font-weight:900;color:#9fe0b0;text-align:center;margin-bottom:14px;letter-spacing:1px;">✅ 已領取紀錄（' + claimed.length + '）</div>';
    claimed.forEach(function(cl){
      var its = Array.isArray(cl && cl.items) ? cl.items : [];
      var dt = new Date(cl && cl.at ? cl.at : 0);
      var dstr = (cl && cl.at) ? ((dt.getMonth() + 1) + '/' + dt.getDate() + '/' + dt.getFullYear() + ' ' + String(dt.getHours()).padStart(2, '0') + ':' + String(dt.getMinutes()).padStart(2, '0')) : '';
      html += '<div style="margin:0 0 14px;padding:18px 18px;background:rgba(90,200,140,0.08);border:1.5px solid rgba(120,210,160,0.4);border-radius:14px;text-align:left;">';
      if(cl && cl.merit) html += '<div style="font-size:30px;color:#bff0cf;font-weight:800;margin-bottom:7px;">🏅 ' + _redeemEsc(cl.merit) + '</div>';
      html += '<div style="font-size:36px;color:#ffe066;font-weight:800;line-height:1.7;">🎁 ' + (its.length ? its.map(_redeemEsc).join('、') : '(獎勵內容)') + '</div>';
      if(dstr) html += '<div style="font-size:26px;color:#9ad6b0;margin-top:8px;">🕐 領取時間：' + _redeemEsc(dstr) + '</div>';
      html += '</div>';
    });
  }

  box.innerHTML = html;
  Array.prototype.forEach.call(box.querySelectorAll('.gmcr-claim-btn'), function(btn){
    btn.onclick = function(){ _claimGmClassRewardFromInbox(btn.getAttribute('data-rid'), btn); };
  });
  /* ★ v5.204.0 問卷卡的「開始填寫」：開既有問卷視窗（同一支，不另做第二份），
     送出成功後那支視窗自己會消化通知並把快取標成已回答 ⇒ 這裡只要重繪，領獎鈕就解開。 */
  var _ascBtn = document.getElementById('gmcr-asc-btn');
  if(_ascBtn && _ascP){
    _ascBtn.onclick = function(){ _gmcrOpenAscForm(_ascP, _ascUid, _ascBtn); };
  }
  try{ _refreshGmClassRewardBadge(); }catch(_e){}
}

/* ★ v5.204.0 — GM 獎勵箱內開「召喚卷確認單」。
   ⚠ 無論學生是送出、按「稍後再處理」還是關掉，一律重繪一次收件箱：
     送出了就解鎖領獎鈕；沒送出就把鎖定狀態原樣畫回來（不會因為視窗關掉就誤解鎖）。 */
async function _gmcrOpenAscForm(p, uid, btn){
  if(!p || !p.data) return;
  var _uid = uid || window._LXPS_ASC_UID || (window._fbAuth && window._fbAuth.currentUser && window._fbAuth.currentUser.uid) || '';
  if(!_uid){ try{ _showInGameToast('請先登入帳號', '#ffcc66', 2500); }catch(_){} return; }
  if(typeof window._showAssetSelfCheckModal !== 'function'){
    try{ _showInGameToast('問卷還沒載入完成，請重新整理後再試一次', '#ffcc66', 3000); }catch(_){}
    return;
  }
  if(btn){ btn.disabled = true; btn.style.opacity = '0.6'; }
  try{ await window._showAssetSelfCheckModal(_uid, p.data, { id: p.id }); }
  catch(_eF){ console.warn('[召喚卷確認] 收件箱開啟問卷失敗', _eF); }
  try{ if(typeof window._fbAssetSelfCheckClearCache === 'function') window._fbAssetSelfCheckClearCache(); }catch(_){}
  try{ await _renderGmClassRewardInbox(); }catch(_eR){ if(btn){ btn.disabled = false; btn.style.opacity = ''; } }
}
try{ window._gmcrOpenAscForm = _gmcrOpenAscForm; }catch(_e){}

// ★ v4.8.0(2026-07-04·老師需求 1)— 🔄 重新整理:先跑 v3.16.97 冪等對帳
//   (_fbReconcileGmClassRewardTickets·安全不等式·永不重複發·失敗略過),
//   再重繪收件箱(_renderGmClassRewardInbox 會重新從雲端讀待領+已領取紀錄)。
//   零改動任何領取/去重/transaction 路徑(_fbClaimGmClassReward/_gmcrClaimed 不碰)。
async function _gmcrRefreshInbox(btn){
  try{ if(typeof playSfx === 'function') playSfx('sfx-sel', 0.5); }catch(_e){}
  if(btn){ btn.disabled = true; btn.textContent = '🔄 同步中…'; btn.style.opacity = '0.6'; }
  try{
    try{
      if(typeof window._fbReconcileGmClassRewardTickets === 'function'){
        await window._fbReconcileGmClassRewardTickets();
      }
    }catch(_eRec){ console.warn('[v4.8.0 GM獎勵重新整理] 對帳略過', _eRec); }
    try{ if(typeof window._fbAssetSelfCheckClearCache === 'function') window._fbAssetSelfCheckClearCache(); }catch(_){}   /* ★ v5.204.0 老師剛處理完／學生在別台填完 ⇒ 按重新整理就會重查一次，不必等快取過期 */
    await _renderGmClassRewardInbox();  // 重繪即重建鈕(含本鈕),不需手動還原
  }catch(_eRf){
    console.warn('[v4.8.0 GM獎勵重新整理] 失敗', _eRf);
    if(btn){ btn.disabled = false; btn.textContent = '🔄 重新整理'; btn.style.opacity = ''; }
  }
}
try{ window._gmcrRefreshInbox = _gmcrRefreshInbox; }catch(_e){}

async function _claimGmClassRewardFromInbox(rid, btn){
  if(!rid) return;
  /* ★ v5.204.0 第二道守門：鈕本身已經 disabled，這裡再擋一次（DOM 被改、或重繪前殘留的舊鈕） */
  if(window._LXPS_ASC_BLOCK){
    try{ _showInGameToast('請先完成最上面那張「🎫 召喚卷確認」再領取獎勵', '#ffcc66', 3200); }
    catch(_){ try{ alert('請先完成最上面那張「召喚卷確認」再領取獎勵'); }catch(__){} }
    return;
  }
  var card = btn && btn.closest ? btn.closest('.gmcr-card') : null;
  var resEl = card ? card.querySelector('.gmcr-card-result') : null;
  if(btn){ btn.disabled = true; btn.textContent = '領取中…'; btn.style.opacity = '0.6'; }
  if(resEl) resEl.innerHTML = '<span style="color:#cbb8e0;">領取中,請稍候…</span>';
  var r;
  try{ r = await window._fbClaimGmClassReward(rid); }
  catch(e){ r = { ok:false, reason:'領取發生錯誤,請稍後再試' }; }
  if(r && r.ok){
    try{ if(typeof playSfx==='function') playSfx('sfx-coin',0.9); }catch(_e){}
    var items = (r.itemsLabel || []);
    if(resEl){
      resEl.innerHTML = '<span style="color:#88ff99;font-size:40px;font-weight:900;">🎉 領取成功!</span>'
        + (items.length ? ('<div style="color:#ffe066;font-weight:800;font-size:36px;margin-top:8px;line-height:1.7;">' + items.map(_redeemEsc).join('<br>') + '</div>') : '')
        + '<div style="color:#bbcce0;font-size:28px;margin-top:10px;">正在重新整理讓獎勵生效…</div>';
    }
    if(btn){ btn.textContent = '✅ 已領取'; }
    // ★ v3.16.97 — 甲:reload 前「即時把獎勵套進記憶體背包」→ 票券成為當前真相,
    //   1.8s 內任何 autosave 都帶著它寫進槽(免疫 _lxpsMergeSlots 消耗型「最新槽」把雲端授予丟掉);
    //   backpackAdd 與 _fbCompensatePlayer 同目標(記憶體 0→qty·對齊雲端),reload 後再以雲端權威覆蓋,不重複加。
    try{
      if(r.reward && r.reward.backpack && typeof r.reward.backpack === 'object' && typeof backpackAdd === 'function'){
        Object.keys(r.reward.backpack).forEach(function(_bk){
          var _bq = Math.max(0, parseInt(r.reward.backpack[_bk], 10) || 0);
          if(_bq > 0) backpackAdd(_bk, _bq, 'GM 課堂獎勵');
        });
      }
    }catch(_eApplyMem){ console.warn('[GM獎勵領取·甲] 套記憶體背包失敗(不影響·reload 會補)', _eApplyMem); }
    setTimeout(function(){ try{ window._lxpsReloadKeepLogin(); }catch(_e){ try{ location.reload(); }catch(__){} } }, 1800);   // ★ v5.141.0 — 自家重載設放行旗標
    return;
  }
  try{ if(typeof playSfx==='function') playSfx('sfx-cancel',0.5); }catch(_e){}
  if(r && r.already){
    if(resEl) resEl.innerHTML = '<span style="color:#ffcc44;font-size:34px;font-weight:800;">這筆獎勵已經領過了</span>';
    setTimeout(function(){ try{ _renderGmClassRewardInbox(); }catch(_e){} }, 900);
    return;
  }
  var reason = (r && r.reason) || '領取失敗,請稍後再試';
  if(resEl) resEl.innerHTML = '<span style="color:#ff8877;font-size:34px;font-weight:800;">❌ ' + _redeemEsc(reason) + '</span>';
  if(btn){ btn.disabled = false; btn.textContent = '✅ 確認領取'; btn.style.opacity = '1'; }
}

// 鈕上方「有可領取獎勵」標籤刷新(讀待領數,>0 顯示)
async function _refreshGmClassRewardBadge(){
  var badge = document.getElementById('gmcr-badge');
  if(!badge) return;
  var n = 0;
  try{
    if(typeof window._fbReadMyGmClassRewards === 'function'){
      var list = await window._fbReadMyGmClassRewards();
      n = (list && list.length) || 0;
    }
  }catch(e){ n = 0; }
  badge.style.display = n > 0 ? 'inline-block' : 'none';
  /* ★ v5.204.0 — 順便查一次「還有沒有沒填的召喚卷確認單」：
     ①同步 window._LXPS_ASC_BLOCK，讓領取守門在收件箱重繪之前就已經生效；
     ②選關頁頂端那條提醒改講問卷（就算目前沒有待領獎勵也要出現，否則學生根本不知道有東西要填）。 */
  var _ascPend = null;
  try{
    var _ascU = (window._fbAuth && window._fbAuth.currentUser && window._fbAuth.currentUser.uid) || window._gUserId || '';
    if(_ascU && typeof window._fbAssetSelfCheckPending === 'function') _ascPend = await window._fbAssetSelfCheckPending(_ascU);
  }catch(_eAsc2){ _ascPend = null; }
  try{ window._LXPS_ASC_BLOCK = !!_ascPend; }catch(_){}
  // ★ v5.185.0 — 頂端提醒條同步（有幾份未接收）
  try{
    var _rm = document.getElementById('gmcr-remind'), _rn = document.getElementById('gmcr-remind-n');
    if(_rm){
      if(window._gmcrRemindHtml0 == null) window._gmcrRemindHtml0 = _rm.innerHTML;   /* 只存一次原始內容 */
      if(_ascPend){
        _rm.innerHTML = '🎫 老師要你先填一張確認單 <span style="font-weight:700;opacity:.92;font-size:0.85em;">填完才能領獎勵，點我填寫</span>';
        _rm.style.display = 'flex';
      } else {
        if(_rm.innerHTML !== window._gmcrRemindHtml0) _rm.innerHTML = window._gmcrRemindHtml0;
        _rn = document.getElementById('gmcr-remind-n');
        _rm.style.display = n > 0 ? 'flex' : 'none';
        if(_rn) _rn.textContent = String(n);
      }
    }
  }catch(_eRm){}
}
window._refreshGmClassRewardBadge = _refreshGmClassRewardBadge;

