const SUMMON_FX_1X_GIF  = './%E5%8F%AF%E6%84%9B%E6%B5%81%E6%98%9F.gif';   // 單抽:可愛流星
const SUMMON_FX_FRUIT_GIF = './%E9%87%91%E8%89%B2%E5%85%89%E5%9C%88.gif';   // ★ v3.17.5 召喚到超越極限果實:金色光圈(與角色召喚區別)
const SUMMON_FX_10X_GIF = './%E5%8D%81%E9%80%A3%E6%8A%BD.gif';            // 十連抽:豪華演出(★ v4.13.3 起改用 mp4 全畫面動畫,此 gif const 保留備用不刪)
