// 螢火蟲粒子 timer handle
let _summonFireflyTimer = null;
// ★ v1.0.20260424.0970 — 星星 / 流星 / 河面波紋 timer handles
let _summonStarsInited = false;
let _summonShootingStarTimer = null;
let _summonRiverRippleTimer = null;
let _summonRiverShimmerInited = false;

function _spawnSummonFirefly(){
  const layer = document.getElementById('summon-fireflies');
  if(!layer) return;
  const ff = document.createElement('div');
  const sz = 4 + Math.random()*8;
  const dur = 4 + Math.random()*4;
  const startX = Math.random()*100;
  const startY = 60 + Math.random()*40; // 從下半部開始飛
  const dx = (Math.random()-0.5) * 200;
  const dy = -(60 + Math.random()*120); // 往上飛
  ff.style.cssText = [
    'position:absolute',
    'left:' + startX + '%',
    'top:' + startY + '%',
    'width:' + sz + 'px',
    'height:' + sz + 'px',
    'border-radius:50%',
    'background:radial-gradient(circle,rgba(255,240,150,1) 0%,rgba(255,200,80,0.85) 40%,rgba(255,150,50,0) 70%)',
    'box-shadow:0 0 ' + (sz*2) + 'px rgba(255,220,100,0.95),0 0 ' + (sz*4) + 'px rgba(255,200,80,0.5)',
    '--ffx:' + dx + 'px',
    '--ffy:' + dy + 'px',
    'animation:summonFireflyFloat ' + dur + 's ease-in-out forwards',
    'pointer-events:none',
  ].join(';');
  layer.appendChild(ff);
  setTimeout(()=>{ try{ ff.remove(); }catch(_){} }, dur*1000 + 100);
}

// ★ v1.0.20260424.0970 — 在天空層(上半部)生成靜態閃爍星星
//   星星只生成一次,每顆有不同的閃爍週期讓畫面有層次
function _initSummonStars(){
  if(_summonStarsInited) return;
  const layer = document.getElementById('summon-stars');
  if(!layer) return;
  layer.innerHTML = '';
  // 大量小星星(約 60 顆)做底色
  const _starCount = 60;
  for(let i=0; i<_starCount; i++){
    const st = document.createElement('div');
    const sz = 1.2 + Math.random()*2.5;            // 1.2~3.7px
    const x = Math.random()*100;                    // 整個天空區域
    const y = Math.random()*95;                     // 上下都有
    const dur = 1.4 + Math.random()*2.6;            // 1.4~4 秒週期
    const delay = -Math.random()*3;                 // 隨機起始 phase
    const isSlowStar = Math.random() < 0.35;
    const animName = isSlowStar ? 'summonStarTwinkleSlow' : 'summonStarTwinkle';
    const tone = Math.random();
    let color, glow;
    if(tone < 0.5){
      // 白色星
      color = 'rgba(255,255,255,1)';
      glow = 'rgba(220,230,255,0.85)';
    } else if(tone < 0.8){
      // 淡紫色星
      color = 'rgba(220,210,255,1)';
      glow = 'rgba(190,170,255,0.8)';
    } else {
      // 金黃色星
      color = 'rgba(255,240,200,1)';
      glow = 'rgba(255,220,140,0.85)';
    }
    st.style.cssText = [
      'position:absolute',
      'left:' + x + '%',
      'top:' + y + '%',
      'width:' + sz + 'px',
      'height:' + sz + 'px',
      'border-radius:50%',
      'background:radial-gradient(circle,' + color + ' 0%,' + glow + ' 50%,rgba(255,255,255,0) 80%)',
      'box-shadow:0 0 ' + (sz*2.5) + 'px ' + glow + ',0 0 ' + (sz*5) + 'px ' + glow,
      'animation:' + animName + ' ' + dur + 's ease-in-out infinite',
      'animation-delay:' + delay + 's',
      'pointer-events:none',
    ].join(';');
    layer.appendChild(st);
  }
  // 少量大型亮星(約 8 顆)點綴
  for(let i=0; i<8; i++){
    const st = document.createElement('div');
    const sz = 3.5 + Math.random()*2.5;             // 3.5~6px
    const x = Math.random()*100;
    const y = Math.random()*70;                     // 主要在上半段(避免擠到山稜)
    const dur = 2 + Math.random()*2;
    const delay = -Math.random()*3;
    st.style.cssText = [
      'position:absolute',
      'left:' + x + '%',
      'top:' + y + '%',
      'width:' + sz + 'px',
      'height:' + sz + 'px',
      'border-radius:50%',
      'background:radial-gradient(circle,rgba(255,255,255,1) 0%,rgba(255,240,200,0.9) 40%,rgba(220,200,255,0.5) 70%,rgba(255,255,255,0) 90%)',
      'box-shadow:0 0 ' + (sz*4) + 'px rgba(255,240,200,0.9),0 0 ' + (sz*8) + 'px rgba(220,200,255,0.65)',
      'animation:summonStarTwinkle ' + dur + 's ease-in-out infinite',
      'animation-delay:' + delay + 's',
      'pointer-events:none',
    ].join(';');
    layer.appendChild(st);
  }
  _summonStarsInited = true;
}

function _spawnSummonShootingStar(){
  const layer = document.getElementById('summon-stars');
  if(!layer) return;
  const ss = document.createElement('div');
  // ★ v1.0.20260424.1010 — 流星方向左右翻轉:由左上往右下劃落
  // 起點:左上角區域 (X=12%~45%,Y=3%~25%)
  const startX = 12 + Math.random()*33;
  const startY = 3 + Math.random()*22;
  // 移動向量:由左上往右下 (dx 正值往右, dy 正值往下)
  // 限制 dy 不超過天空區域剩餘高度,避免流星跑到山下
  const dx = 280 + Math.random()*200;                // +280 ~ +480 px (往右)
  const dy = 60 + Math.random()*80;                  // 60~140 px (往下,但仍在天空區)
  const dur = 0.9 + Math.random()*0.6;              // 0.9~1.5 秒
  const len = 60 + Math.random()*60;                 // 流星本體長度 60~120 px
  ss.style.cssText = [
    'position:absolute',
    'left:' + startX + '%',
    'top:' + startY + '%',
    'width:' + len + 'px',
    'height:2px',
    // ★ v1.0.20260424.1040 — 漸變與 transform-origin 與移動方向一致(左上→右下)
    // 漸變:左(尾巴,透明)→右(頭,亮白) — 配合 +25deg 旋轉,線條呈「左上→右下」斜線
    'background:linear-gradient(90deg,rgba(255,255,255,0) 0%,rgba(220,230,255,0.6) 30%,rgba(255,240,200,1) 80%,rgba(255,255,255,1) 100%)',
    'box-shadow:0 0 8px rgba(220,230,255,0.9),0 0 16px rgba(220,230,255,0.5)',
    'border-radius:1px',
    // 從尾巴端伸長:scaleX 以左端(左上的尾巴)為錨點,讓尾巴留在原處往右下伸出頭
    'transform-origin:left center',
    '--ssx:' + dx + 'px',
    '--ssy:' + dy + 'px',
    'animation:summonShootingStar ' + dur + 's ease-out forwards',
    'pointer-events:none',
  ].join(';');
  layer.appendChild(ss);
  setTimeout(()=>{ try{ ss.remove(); }catch(_){} }, dur*1000 + 100);
}

// ★ v1.0.20260424.0970 — 河面靜態反光條紋(只生成一次)
function _initSummonRiverShimmer(){
  if(_summonRiverShimmerInited) return;
  const layer = document.getElementById('summon-river');
  if(!layer) return;
  layer.innerHTML = '';
  // 約 14 條水平反光線(水面波紋)
  const _stripeCount = 14;
  for(let i=0; i<_stripeCount; i++){
    const stripe = document.createElement('div');
    const w = 30 + Math.random()*45;                // 30~75% 寬
    const x = Math.random()*60;                     // 左側起點
    const y = 5 + (i / _stripeCount) * 90 + Math.random()*8;  // 從上到下分散
    const h = 1 + Math.random()*2.5;                // 1~3.5px
    const dur = 2.5 + Math.random()*3;              // 2.5~5.5 秒
    const delay = -Math.random()*4;
    const tone = Math.random();
    let bg;
    if(tone < 0.5){
      bg = 'linear-gradient(90deg,rgba(180,210,255,0) 0%,rgba(200,220,255,0.85) 50%,rgba(180,210,255,0) 100%)';
    } else if(tone < 0.8){
      bg = 'linear-gradient(90deg,rgba(255,240,200,0) 0%,rgba(255,230,170,0.85) 50%,rgba(255,240,200,0) 100%)';
    } else {
      bg = 'linear-gradient(90deg,rgba(220,200,255,0) 0%,rgba(220,200,255,0.7) 50%,rgba(220,200,255,0) 100%)';
    }
    stripe.style.cssText = [
      'position:absolute',
      'left:' + x + '%',
      'top:' + y + '%',
      'width:' + w + '%',
      'height:' + h + 'px',
      'background:' + bg,
      'box-shadow:0 0 6px rgba(200,220,255,0.55)',
      'border-radius:2px',
      'animation:summonRiverShimmer ' + dur + 's ease-in-out infinite',
      'animation-delay:' + delay + 's',
      'pointer-events:none',
      'filter:blur(0.5px)',
    ].join(';');
    layer.appendChild(stripe);
  }
  _summonRiverShimmerInited = true;
}

// ★ v1.0.20260424.0970 — 動態波紋(漣漪擴散),由 timer 持續生成
function _spawnSummonRiverRipple(){
  const layer = document.getElementById('summon-river');
  if(!layer) return;
  const rp = document.createElement('div');
  const x = 5 + Math.random()*90;                   // 河面任一位置
  const y = 20 + Math.random()*70;                  // 河面高度範圍
  const w = 60 + Math.random()*120;                 // 60~180px 起始寬度
  const dur = 2.4 + Math.random()*1.8;
  rp.style.cssText = [
    'position:absolute',
    'left:' + x + '%',
    'top:' + y + '%',
    'width:' + w + 'px',
    'height:' + (w*0.18) + 'px',
    'border:1.5px solid rgba(220,235,255,0.85)',
    'border-radius:50%',
    'box-shadow:0 0 10px rgba(200,220,255,0.7),inset 0 0 6px rgba(255,255,255,0.5)',
    'animation:summonRiverRipple ' + dur + 's ease-out forwards',
    'pointer-events:none',
  ].join(';');
  layer.appendChild(rp);
  setTimeout(()=>{ try{ rp.remove(); }catch(_){} }, dur*1000 + 100);
}

function _startSummonFireflies(){
  if(_summonFireflyTimer) return;
  // 一開始先生成 6 隻,讓畫面就有
  for(let i=0;i<6;i++) setTimeout(_spawnSummonFirefly, i*220);
  _summonFireflyTimer = setInterval(()=>{
    // 每 0.45 秒生成 1~2 隻
    _spawnSummonFirefly();
    if(Math.random() < 0.5) _spawnSummonFirefly();
  }, 450);
  // ★ v1.0.20260424.0970 — 同時啟動星星與河面特效
  try{ _initSummonStars(); }catch(_){}
  try{ _initSummonRiverShimmer(); }catch(_){}
  // 流星每 6~12 秒一顆
  if(!_summonShootingStarTimer){
    const _scheduleShootingStar = () => {
      const delay = 6000 + Math.random()*6000;
      _summonShootingStarTimer = setTimeout(()=>{
        try{ _spawnSummonShootingStar(); }catch(_){}
        _scheduleShootingStar();
      }, delay);
    };
    _scheduleShootingStar();
  }
  // 河面動態漣漪每 1.2~2.2 秒生成一個
  if(!_summonRiverRippleTimer){
    _summonRiverRippleTimer = setInterval(()=>{
      try{ _spawnSummonRiverRipple(); }catch(_){}
      // 偶爾連續生成兩個漣漪,讓河面更生動
      if(Math.random() < 0.3){
        setTimeout(()=>{ try{ _spawnSummonRiverRipple(); }catch(_){} }, 400);
      }
    }, 1500);
    // 開場立即生成 2 個漣漪
    for(let i=0; i<2; i++) setTimeout(_spawnSummonRiverRipple, i*600);
  }
}

function _stopSummonFireflies(){
  if(_summonFireflyTimer){ clearInterval(_summonFireflyTimer); _summonFireflyTimer = null; }
  const layer = document.getElementById('summon-fireflies');
  if(layer) layer.innerHTML = '';
  // ★ v1.0.20260424.0970 — 同時停止星星閃爍與河面特效
  if(_summonShootingStarTimer){ clearTimeout(_summonShootingStarTimer); _summonShootingStarTimer = null; }
  if(_summonRiverRippleTimer){ clearInterval(_summonRiverRippleTimer); _summonRiverRippleTimer = null; }
  // 清掉動態元素(漣漪、流星) 但保留靜態星星與條紋,下次開啟可重用
  // 但若要徹底清除可重置標記
  const starLayer = document.getElementById('summon-stars');
  if(starLayer){
    // 只移除 transform-origin 的流星(短期元素,通常 1.5 秒內消失,但保險起見清掉)
    Array.from(starLayer.querySelectorAll('div')).forEach(el => {
      if(el.style.animation && el.style.animation.indexOf('summonShootingStar') >= 0){
        try{ el.remove(); }catch(_){}
      }
    });
  }
  const riverLayer = document.getElementById('summon-river');
  if(riverLayer){
    // 移除動態漣漪(animation 含 summonRiverRipple),保留靜態反光條紋
    Array.from(riverLayer.querySelectorAll('div')).forEach(el => {
      if(el.style.animation && el.style.animation.indexOf('summonRiverRipple') >= 0
         && el.style.animation.indexOf('Shimmer') < 0){
        try{ el.remove(); }catch(_){}
      }
    });
  }
}

function _syncSummonCrystalDisplay(){
  const el = document.getElementById('summon-crystal-count');
  if(!el) return;
  let n = 0;
  try{
    if(typeof backpackGet === 'function'){
      n = backpackGet('summon_crystal') || 0;
    } else if(window._playerBackpack){
      n = window._playerBackpack.summon_crystal || 0;
    }
  }catch(_){}
  el.textContent = n;
}

let _dailyFreeSummonDate = null; // 'YYYY/M/D' (台灣時區),記錄上次使用免費召喚的日期

// 取得今日日期字串(台灣 UTC+8,8:00 為界)
// ★ v3.13.12(2026-06-01) 鐵律 1.142 — 全遊戲對齊台灣 8:00。
//   原本是台灣 00:00(午夜 12 點)重置,現改成 8:00,跟其他每日重置一致。
function _getTaiwanDateStr(){
  try{
    if(typeof window._lxpsGetGameDayKey === 'function'){
      return window._lxpsGetGameDayKey();
    }
  }catch(_){}
  // fallback (舊邏輯,台灣 00:00 重置)
  try{
    return new Date().toLocaleDateString('zh-TW', { timeZone: 'Asia/Taipei' });
  }catch(_){
    const d = new Date();
    return d.getFullYear() + '/' + (d.getMonth()+1) + '/' + d.getDate();
  }
}

// 是否還可用「今日首次免費召喚」
function _isDailyFreeSummonAvailable(){
  return _dailyFreeSummonDate !== _getTaiwanDateStr();
}

// 標記今日已用過免費召喚
function _markDailyFreeSummonUsed(){
  _dailyFreeSummonDate = _getTaiwanDateStr();
  try{ localStorage.setItem('lxps_daily_free_summon_date', _dailyFreeSummonDate); }catch(_){}
  try{
    if(typeof gameCloudSave === 'function'){
      const _p = gameCloudSave();
      if(_p && typeof _p.catch === 'function'){
        _p.catch(e => console.warn('[每日免費召喚 雲端寫入失敗,本地已記錄]', e));
      }
    }
  }catch(_){}
  // 立即更新按鈕文字
  try{ if(typeof _updateSingleSummonBtnLabel === 'function') _updateSingleSummonBtnLabel(); }catch(_){}
}

// 從 localStorage 讀取(初始化時呼叫)
function _loadDailyFreeSummonDate(){
  try{
    const _raw = localStorage.getItem('lxps_daily_free_summon_date');
    if(_raw && typeof _raw === 'string') _dailyFreeSummonDate = _raw;
  }catch(_){}
}

// 計算到「下次台灣時區 08:00」剩多少毫秒(用於倒數顯示)
// ★ v3.13.12(2026-06-01) 鐵律 1.142 — 原本算到 00:00,現改算到 08:00。
function _getMsUntilNextTaiwanMidnight(){
  try{
    const _now = new Date();
    // 取得當前台灣時間的 H/M/S
    const _taiwanStr = _now.toLocaleString('en-US', { timeZone: 'Asia/Taipei', hour12: false });
    // 解析 HH:MM:SS
    const _m = _taiwanStr.match(/(\d{1,2}):(\d{2}):(\d{2})/);
    if(_m){
      const h = parseInt(_m[1], 10);
      const min = parseInt(_m[2], 10);
      const s = parseInt(_m[3], 10);
      const _curSec = h*3600 + min*60 + s;
      // ★ 算到「下次 08:00」
      //   若現在 < 08:00:今日 08:00 距現在 = (8*3600 - _curSec)
      //   若現在 >= 08:00:明日 08:00 距現在 = (24*3600 - _curSec) + 8*3600
      const _targetSec = 8 * 3600;
      let _remainSec;
      if(_curSec < _targetSec){
        _remainSec = _targetSec - _curSec;
      } else {
        _remainSec = (24*3600 - _curSec) + _targetSec;
      }
      return _remainSec * 1000;
    }
  }catch(_){}
  // fallback:用本地時區明天 08:00
  const _now = new Date();
  const _tomorrow = new Date(_now);
  // 若現在 < 8 點 → 今天 8 點;否則明天 8 點
  if(_now.getHours() < 8){
    _tomorrow.setHours(8, 0, 0, 0);
  } else {
    _tomorrow.setDate(_now.getDate() + 1);
    _tomorrow.setHours(8, 0, 0, 0);
  }
  return _tomorrow.getTime() - _now.getTime();
}

// 格式化 HH:MM:SS
function _formatHMS(ms){
  const _s = Math.max(0, Math.floor(ms / 1000));
  const _h = Math.floor(_s / 3600);
  const _m = Math.floor((_s % 3600) / 60);
  const _sec = _s % 60;
  const _pad = n => String(n).padStart(2, '0');
  return _pad(_h) + ':' + _pad(_m) + ':' + _pad(_sec);
}

// 更新單抽按鈕副標籤
function _updateSingleSummonBtnLabel(){
  const _label = document.getElementById('summon-1x-sublabel');
  if(!_label) return;
  if(_isDailyFreeSummonAvailable()){
    _label.innerHTML = '<span style="color:#ffe066;font-weight:900;">🎁 今日首次免費!</span>';
  } else {
    const _ms = _getMsUntilNextTaiwanMidnight();
    _label.innerHTML = '消耗 🔮 ×1 <span style="color:#bbaadd;font-size:0.85em;">(下次免費 ' + _formatHMS(_ms) + ')</span>';
  }
}

