    + '<button type="button" data-urswap="back2" style="font-size:17px;padding:12px 24px;border-radius:14px;border:2px solid #b070ff;background:rgba(255,255,255,0.06);color:#e0c8ff;font-weight:800;">◀ 重選</button>'
    + '<button type="button" data-urswap="cancel" style="font-size:17px;padding:12px 24px;border-radius:14px;border:2px solid #888;background:rgba(255,255,255,0.06);color:#ddd;font-weight:800;">取消</button></div>';
