window._urSwapBusy = false;
async function _urSwapRun(fromName, toName){
  if(window._urSwapBusy) return;
  window._urSwapBusy = true;
  /* 20 秒看門狗:任何想不到的中斷都把旗標解開,不讓功能永久卡住(v5.198.0 的教訓) */
  try{ clearTimeout(window._urSwapBusyT); }catch(_){}
  window._urSwapBusyT = setTimeout(function(){ window._urSwapBusy = false; }, 20000);
  var _tid = window._URSWAP_TICKET_ID;
  try{
    /* ── 出手前最後一次本機複查(面板開著的期間玩家可能在別的分頁動過東西)── */
    if(!window._gUserId || window._progressLoaded !== true){
      _urSwapFail('資料還沒載好,請稍等幾秒再試一次'); return;
    }
    if(((typeof backpackGet === 'function') ? backpackGet(_tid) : 0) <= 0){ _urSwapFail('沒有替換卷了'); return; }
    var _own = (typeof advGetUnlockedHeroes === 'function') ? advGetUnlockedHeroes() : [];
    if(_own.indexOf(fromName) < 0){ _urSwapFail('你已經沒有 ' + fromName + ' 了'); return; }
    if(_own.indexOf(toName) >= 0){ _urSwapFail('你已經有 ' + toName + ' 了,不能換成已經擁有的'); return; }
    /* ★ v5.232.0 — 兩端都必須是 UR(新 UR 自動涵蓋;非 UR 一律擋下,券不扣) */
    if(typeof window._lxpsIsUR === 'function' && (!window._lxpsIsUR(fromName) || !window._lxpsIsUR(toName))){
      _urSwapFail('只能在 UR 角色之間替換'); return;
    }
    /* ── 交易帳(沿用召喚那一套):頁面若在雲端寫入途中被重載,下次開機 _lxpsURSwapRecover 會依雲端現況把券補正 ── */
    var _before = (typeof backpackGet === 'function') ? (backpackGet(_tid) | 0) : 0;
    try{
      localStorage.setItem('lxps_urswap_txn', JSON.stringify({
        from: fromName, to: toName, ticketId: _tid, ticketBefore: _before,
        uid: window._gUserId, ts: Date.now()
      }));
    }catch(_){}

    /* ── 真正的加減:三槽同寫、主檔最後寫(見 _fbURSwapApply 說明)── */
    if(typeof window._fbURSwapApply !== 'function') throw new Error('替換通道未載入');
    var _r = await window._fbURSwapApply(window._gUserId, fromName, toName, {
      reason: '玩家使用「UR 英雄替換卷」(v5.227.0)'
    });
    if(!_r || !_r.ok){
      /* 雲端沒成功 ⇒ 本機一個位元組都沒改、券也沒扣 ⇒ 什麼都沒發生,請學生再試一次 */
      try{ localStorage.removeItem('lxps_urswap_txn'); }catch(_){}
      var _why = (_r && _r.reason) || 'unknown';
      _urSwapFail(_why === 'not_owned' ? '你已經沒有這隻 UR 了'
                : _why === 'target_owned' ? '你已經有這隻 UR 了'
                : '雲端沒有寫入成功(' + _why + '),你的替換卷沒有被扣掉,請再試一次');
      return;
    }

    /* ── 雲端成功了,才同步本機記憶體(順序不可顛倒:先改本機、雲端又失敗 = 兩邊對不起來)── */
    try{ window._lxpsURSwapApplyLocal(fromName, toName); }catch(_eL){ console.warn('[UR 替換卷] 本機同步例外(雲端已完成,重整後即正確)', _eL); }
    /* ★ v5.254.0 命座(裁定 13甲):被換掉的 UR 身上所有命星(含已點亮)退回成等量「UR 自選命星」,只能用在已擁有的 UR */
    try{ if(typeof window._cstOnURSwap === 'function') window._cstOnURSwap(fromName); }catch(_eCstSw){ console.warn('[UR 替換卷] 命星退回例外', _eCstSw); }
    /* ── 最後才扣券,並即時落地(與召喚卷同一條車道)── */
    try{ backpackRemove(_tid, 1); }catch(_){}
    try{ if(typeof window._lxpsInstantBackpackPersist === 'function') window._lxpsInstantBackpackPersist('UR英雄替換卷'); }catch(_){}
    try{ if(typeof window._logActivity === 'function') window._logActivity('ur_swap', { from: fromName, to: toName }); }catch(_){}
    try{ localStorage.removeItem('lxps_urswap_txn'); }catch(_){}
    try{ if(typeof gameCloudSave === 'function') Promise.resolve(gameCloudSave()).catch(function(){}); }catch(_){}
    try{ if(typeof _setNavDot === 'function') _setNavDot('英雄', true); }catch(_){}

    window._urSwapBusy = false;
    try{ clearTimeout(window._urSwapBusyT); }catch(_){}
    _urSwapDone(fromName, toName);
  }catch(e){
    console.error('[UR 替換卷] 例外', e);
    try{ localStorage.removeItem('lxps_urswap_txn'); }catch(_){}
    _urSwapFail((e && e.message) ? e.message : '發生未知錯誤');
  }
}
function _urSwapFail(msg){
  window._urSwapBusy = false;
  try{ clearTimeout(window._urSwapBusyT); }catch(_){}
  _urSwapClose();
  try{ playSfx('sfx-cancel', 0.6); }catch(_){}
  try{ _showInGameToast('🛠️ 這次替換沒有完成:' + msg + '\n你的替換卷沒有被扣掉,可以再試一次。', '#ffaa44', 7000); }catch(_){}
}
function _urSwapDone(fromName, toName){
  var h = '<div style="text-align:center;padding:6px 0;">'
    + '<div style="font-size:56px;margin-bottom:6px;">🎉</div>'
    + '<div style="font-size:20px;font-weight:900;color:#ffe9b0;margin-bottom:10px;">替換完成!</div>'
    + '<div style="font-size:17px;color:#e8dcff;line-height:1.9;">' + fromName + ' <span style="color:#ffd166;">➜</span> <b>' + toName + '</b><br>'
    + '等級與所有養成都已經搬過去了。<br>'
    + '<span style="font-size:14px;color:#ffc48a;">原本裝在 ' + fromName + ' 身上的至寶、寵物、裝備已經卸下來,記得到英雄圖鑑重新裝備。</span></div></div>';
  var f = '<div style="text-align:center;margin-top:14px;"><button type="button" data-urswap="cancel"'
    + ' style="font-size:19px;padding:12px 34px;border-radius:14px;border:2px solid #ffd166;background:rgba(255,200,80,0.18);color:#ffe9b0;font-weight:900;">太好了!</button></div>';
  var w = _urSwapShell('替換完成', h, f);
  w.onclick = function(ev){
    var t = ev.target;
    while(t && t !== w && !(t.getAttribute && t.getAttribute('data-urswap'))) t = t.parentNode;
    if(t && t !== w) _urSwapClose();
  };
  try{ playSfx('sfx-medal-unlock', 0.85); }catch(_){}
}
/* 本機記憶體同步(雲端成功之後才呼叫)。★ 與 _fbURSwapApply 的 patch 必須一一對應,少搬一張表就會讓
   「畫面看到的」與「雲端存的」不一致,下次 gameCloudSave 還會把錯的寫回去。 */
window._lxpsURSwapApplyLocal = function(fromName, toName){
  var _move = function(obj){
    if(!obj || typeof obj !== 'object') return;
    if(Object.prototype.hasOwnProperty.call(obj, fromName)){ obj[toName] = obj[fromName]; delete obj[fromName]; }
  };
  try{ if(typeof _heroLevels        !== 'undefined') _move(_heroLevels); }catch(_){}
  try{ if(typeof _heroExp           !== 'undefined') _move(_heroExp); }catch(_){}
  try{ if(typeof _heroStatInvested  !== 'undefined') _move(_heroStatInvested); }catch(_){}
  try{ if(typeof _heroStatPoints    !== 'undefined') _move(_heroStatPoints); }catch(_){}
  try{ if(typeof _heroSkillLevels   !== 'undefined') _move(_heroSkillLevels); }catch(_){}
  try{ if(typeof _heroBurstLevels   !== 'undefined') _move(_heroBurstLevels); }catch(_){}
  try{ if(typeof _heroTraitLevel    !== 'undefined') _move(_heroTraitLevel); }catch(_){}
  try{ if(typeof _heroCapsuleInvested !== 'undefined') _move(_heroCapsuleInvested); }catch(_){}
  /* 至寶/裝備/寵物:只解除,不轉移(老師指定) */
  try{
    if(typeof _taiwanTreasureData !== 'undefined' && _taiwanTreasureData){
      Object.keys(_taiwanTreasureData).forEach(function(k){
        var r = _taiwanTreasureData[k]; if(r && r.equippedTo === fromName) r.equippedTo = null;
      });
    }
  }catch(_){}
  try{
    var _gd = window._gearData;
    if(_gd && _gd.instances) Object.keys(_gd.instances).forEach(function(k){
      var r = _gd.instances[k]; if(r && r.equippedTo === fromName) r.equippedTo = null;
    });
  }catch(_){}
  try{
    var _tp = window._tamedPets;
    if(_tp) Object.keys(_tp).forEach(function(k){
      var r = _tp[k]; if(r && r.followTo === fromName) r.followTo = null;
    });
  }catch(_){}
  /* 解鎖清單:localStorage 'adv_unlocked_heroes' 才是 advGetUnlockedHeroes 的真實來源 */
  try{
    var _raw = localStorage.getItem('adv_unlocked_heroes'), _l = _raw ? JSON.parse(_raw) : [];
    if(!Array.isArray(_l)) _l = [];
    _l = _l.filter(function(n){ return n !== fromName; });
    if(_l.indexOf(toName) < 0) _l.push(toName);
    localStorage.setItem('adv_unlocked_heroes', JSON.stringify(_l));
  }catch(_){}
  try{
    var _rawLv = localStorage.getItem('adv_hero_levels');
    if(_rawLv){ var _o = JSON.parse(_rawLv); if(_o && typeof _o === 'object' && !Array.isArray(_o)){ _move(_o); localStorage.setItem('adv_hero_levels', JSON.stringify(_o)); } }
  }catch(_){}
  /* 本機解鎖帳本也補兩筆,口徑與雲端一致(否則 gameCloudSave 組裝時會把舊紀錄寫回去) */
  try{
    var _rawH = localStorage.getItem('adv_hero_unlock_history'), _h = _rawH ? JSON.parse(_rawH) : [];
    if(!Array.isArray(_h)) _h = [];
    var _u12 = String(window._gUserId || '').slice(0, 12), _n = Date.now();
    _h.push({ name: fromName, at: _n, source: 'admin_delete', uid: _u12, urSwap: true, swapTo: toName, reason: 'UR 英雄替換卷(v5.227.0)' });
    _h.push({ name: toName, at: _n + 1, source: 'ticket_ur_swap', uid: _u12, urSwap: true, swapFrom: fromName });
    if(_h.length > 300) _h = _h.slice(-300);
    localStorage.setItem('adv_hero_unlock_history', JSON.stringify(_h));
  }catch(_){}
  /* 被換掉的英雄若還留在預設陣容裡 ⇒ 那一格會變成「套用時說你沒有這隻英雄」的死陣容,直接換成新英雄 */
  try{
    if(Array.isArray(_advPresetTeams)){
      _advPresetTeams.forEach(function(pt){
        if(pt && Array.isArray(pt.heroes)){
          for(var i = 0; i < pt.heroes.length; i++) if(pt.heroes[i] === fromName) pt.heroes[i] = toName;
          if(Array.isArray(pt.pets)) for(var j = 0; j < pt.pets.length; j++) if(pt.heroes[j] === toName) pt.pets[j] = null;
        }
      });
    }
  }catch(_){}
};
/* 開機對帳:頁面若在雲端寫入途中被重載,依「雲端現況」決定券該不該扣(冪等,靠 ticketBefore 判斷)。 */
window._lxpsURSwapRecover = function(){
  var o = null;
  try{ o = JSON.parse(localStorage.getItem('lxps_urswap_txn') || 'null'); }catch(_){ o = null; }
  if(!o) return;
  try{
    if(!window._gUserId || window._progressLoaded !== true) return;
    if(o.uid && o.uid !== window._gUserId){ localStorage.removeItem('lxps_urswap_txn'); return; }
    if(!o.ts || (Date.now() - o.ts) > 24 * 3600 * 1000){ localStorage.removeItem('lxps_urswap_txn'); return; }
    var _own = (typeof advGetUnlockedHeroes === 'function') ? advGetUnlockedHeroes() : [];
    var _hasFrom = _own.indexOf(o.from) >= 0, _hasTo = _own.indexOf(o.to) >= 0;
    var _cur = (typeof backpackGet === 'function') ? (backpackGet(o.ticketId) | 0) : 0;
    localStorage.removeItem('lxps_urswap_txn');
    if(_hasTo && !_hasFrom){
      /* 替換其實成功了(主檔是最後寫的,寫到了就代表全部成功)⇒ 只要確認券有扣掉 */
      if(_cur > 0 && _cur === (o.ticketBefore | 0)){
        try{ backpackRemove(o.ticketId, 1); }catch(_){}
        try{ if(typeof window._lxpsInstantBackpackPersist === 'function') window._lxpsInstantBackpackPersist('UR替換對帳補扣'); }catch(_){}
        try{ if(typeof gameCloudSave === 'function') Promise.resolve(gameCloudSave()).catch(function(){}); }catch(_){}
      }
      try{ _showInGameToast('✅ 上次的 UR 替換已經完成了:' + o.from + ' ➜ ' + o.to, '#66ddaa', 7000); }catch(_){}
      return;
    }
    if(_hasFrom && !_hasTo){
      /* 主檔沒寫到 ⇒ 什麼都沒發生。券本來就還沒扣,這裡什麼都不必補,只要告訴學生可以再試一次 */
      try{ _showInGameToast('上次的 UR 替換沒有完成,替換卷還在背包裡,可以再試一次 🔁', '#ffd166', 6000); }catch(_){}
      return;
    }
    /* 兩者都有 / 兩者都沒有 = 理論上不可能(主檔那一次 setDoc 是原子的)。
       不自作主張加減任何英雄,只留下紀錄請老師處理 —— 亂補比不補更危險。 */
    try{ console.warn('[UR 替換對帳] 出現理論上不可能的狀態,未做任何補償', o, { hasFrom:_hasFrom, hasTo:_hasTo }); }catch(_){}
  }catch(e){ try{ localStorage.removeItem('lxps_urswap_txn'); }catch(_){} }
};

