      + '<div style="margin-top:22px;"><button id="_summon-ticket-okbtn" style="font-size:20px;padding:12px 34px;border-radius:16px;border:2px solid ' + _ac + ';background:rgba(255,255,255,0.08);color:#fff;font-weight:800;">知道了</button></div>'
