// ★ v3.15.46 — 商店購買「最大可購買數」計算(今日上限/本週上限/背包容量取最小),回傳 {max, reason}
function _shopMaxBuyable(prod){
  if(!prod) return { max: 99, reason: '' };
  if(prod.stock === '限購1' || prod.oneTime === true) return { max: 1, reason: 'one' };
  var _max = 99, _reason = '';
  if(prod.dailyLimit > 0){
    try{ var _rd = Math.max(0, prod.dailyLimit - _shopDailyBought(prod.id)); if(_rd < _max){ _max = _rd; _reason = 'daily'; } }catch(_){}
  }
  if(prod.weeklyLimit > 0){
    try{ var _rw = Math.max(0, prod.weeklyLimit - _shopWeeklyBought(prod.id)); if(_rw < _max){ _max = _rw; _reason = 'weekly'; } }catch(_){}
  }
  if(prod.monthlyLimit > 0){   /* ★ v5.227.0 每月限購 */
    try{ var _rm = Math.max(0, prod.monthlyLimit - _shopMonthlyBought(prod.id)); if(_rm < _max){ _max = _rm; _reason = 'monthly'; } }catch(_){}
  }
  try{ var _rb = Math.max(0, 99 - ((typeof backpackGet === 'function') ? backpackGet(prod.id) : 0)); if(_rb < _max){ _max = _rb; _reason = 'bag'; } }catch(_){}
  return { max: Math.max(1, _max), reason: _reason };
}

// ★ v3.15.46 — 統一設定「+」按鈕鎖定視覺(達上限變灰;購買/販賣共用,+ 按鈕皆綠色系)
function _setPlusBtnLocked(btnId, locked){
  try{
    var b = document.getElementById(btnId);
    if(!b) return;
    if(locked){
      b.style.opacity = '0.4'; b.style.background = 'rgba(60,60,60,0.3)';
      b.style.borderColor = '#666'; b.style.color = '#888';
    }else{
      b.style.opacity = ''; b.style.background = 'rgba(0,60,0,0.4)';
      b.style.borderColor = '#44ff88'; b.style.color = '#44ff88';
    }
  }catch(_){}
}

function shopAdjQty(id, delta){
  // ★ v1.0.20260510.5770 — 限購 1 個的物品強制數量為 1,即使 onclick 被觸發也擋下
  const _prod = SHOP_PRODUCTS.find(p => p.id === id);
  if(_prod && (_prod.stock === '限購1' || _prod.oneTime === true)){
    window['_shopQty_'+id] = 1;
    const el = document.getElementById('shop-qty-'+id);
    if(el) el.textContent = '1';
    return;
  }
  // ★ v3.15.46 — 數量調整新規則:① + 超過今日/本週/背包上限 → 彈窗提示 + 卡在上限(鎖按鈕)
  //                              ② 數量為 1 時按 - → 跳到最大可購買數循環,方便調整
  const _mb = _shopMaxBuyable(_prod);
  const _max = _mb.max;
  const _cur = window['_shopQty_'+id] || 1;
  let _next;
  if(delta > 0){
    if(_cur >= _max){
      var _msg = _mb.reason === 'weekly'  ? '🧪 已達本週購買上限數量'
               : _mb.reason === 'monthly' ? '🔁 這個月的免費份額已經領完了,下個月 1 號再來'   /* ★ v5.227.0 */
               : _mb.reason === 'bag'     ? '🎒 背包已滿(最多持有 99 個)'
               : '🛒 已達今日購買上限數量';
      _showInGameToast(_msg, '#ffaa44', 2000);
      _next = _max;
    }else{
      _next = Math.min(_max, _cur + delta);
    }
  }else{
    _next = (_cur <= 1) ? _max : Math.max(1, _cur + delta);  // 從 1 循環到最大,方便調整
  }
  window['_shopQty_'+id] = _next;
  const el = document.getElementById('shop-qty-'+id);
  if(el) el.textContent = _next;
  _renderShopProducts(); // 重新渲染（更新合計和按鈕狀態,含 + 按鈕鎖定）
}

// ★ 每日商店庫存輔助
// ★ v3.13.12(2026-06-01) 鐵律 1.142 — 改用統一 _lxpsGetGameDayKey()。
//   原本 toISOString().slice(0,10) 是 UTC 日期,湊巧 UTC 00:00 = 台灣 8:00,
//   但設計上靠湊巧不嚴謹。現對齊統一函式,強制台灣 8:00 為界。
//   注意:格式從 'YYYYMMDD' 改為 'YYYY-MM-DD',會讓既有 _shopDailyData.date
//   對不上 → 玩家會被視為「跨日」一次,重新抽折扣 + 重置限購計數(可接受)。
function _getShopDailyKey(){
  try{
    if(typeof window._lxpsGetGameDayKey === 'function'){
      return window._lxpsGetGameDayKey().replace(/-/g, '');  // 保持原 'YYYYMMDD' 無破折號格式
    }
  }catch(_){}
  return new Date().toISOString().slice(0,10).replace(/-/g,'');
}
// ★ v1.0.20260421.3000L — 距離下次重置（UTC 00:00 = 台灣 08:00）的倒數文字
function _shopResetCountdown(){
  const now = new Date();
  const next = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()+1, 0, 0, 0));
  const diff = Math.max(0, next.getTime() - now.getTime());
  const h = Math.floor(diff / 3600000);
  const m = Math.floor((diff % 3600000) / 60000);
  return h + '小時 ' + m + '分';
}
function _shopDailyBought(id){
  const today = _getShopDailyKey();
  if(!_shopDailyData || _shopDailyData.date !== today) return 0;
  return _shopDailyData[id] || 0;
}

// ★ v3.13.83 — 每週商店限購系統(極限膠囊用)。以「遊戲日」(08:00 TW = UTC 00:00 為界)
//   找出本週一的日期當 week key,週一 08:00 自動重置。
function _getShopWeeklyKey(){
  try{
    let dayStr;
    if(typeof window._lxpsGetGameDayKey === 'function'){
      dayStr = window._lxpsGetGameDayKey();          // 'YYYY-MM-DD'(已含 08:00 邊界)
    } else {
      dayStr = new Date().toISOString().slice(0,10);
    }
    const d = new Date(dayStr + 'T00:00:00Z');        // 當作 UTC 午夜處理
    const dow = d.getUTCDay();                         // 0=Sun,1=Mon,...,6=Sat
    const diffToMon = (dow === 0) ? 6 : (dow - 1);     // 回推到本週一
    d.setUTCDate(d.getUTCDate() - diffToMon);
    return d.toISOString().slice(0,10).replace(/-/g,''); // 本週一 'YYYYMMDD'
  }catch(_){
    return new Date().toISOString().slice(0,10).replace(/-/g,'');
  }
}
function _shopWeeklyBought(id){
  const wk = _getShopWeeklyKey();
  if(!_shopWeeklyData || _shopWeeklyData.week !== wk) return 0;
  return _shopWeeklyData[id] || 0;
}
function _shopWeeklyRecordBuy(id, qty){
  const wk = _getShopWeeklyKey();
  if(!_shopWeeklyData || _shopWeeklyData.week !== wk){
    _shopWeeklyData = { week: wk };
  }
  _shopWeeklyData[id] = (_shopWeeklyData[id] || 0) + qty;
}

/* ★★ v5.227.0 — 每月商店限購系統（UR 英雄替換卷用；老師：「每個月 1 號更新，免費限購 1 張」）★★
   月份 key 一律由 `_lxpsGetGameDayKey()`（已含「台灣 08:00 為界」的遊戲日定義）取前 6 碼 'YYYYMM'，
   與每日／每週兩套完全同源 —— 不另外去算時區，避免三套邊界各自為政。
   ⇒ 實際重置時刻＝每月 1 號台灣時間 08:00（與每日商店刷新同一刻），完全符合老師說的「每個月 1 號更新」。
   ⚠ 取不到 helper 時退回 UTC 年月，只會讓邊界早 8 小時，不會壞掉也不會多給一張。 */
function _getShopMonthlyKey(){
  try{
    if(typeof window._lxpsGetGameDayKey === 'function'){
      return window._lxpsGetGameDayKey().replace(/-/g, '').slice(0, 6);   // 'YYYY-MM-DD' → 'YYYYMM'
    }
  }catch(_){}
  return new Date().toISOString().slice(0, 7).replace('-', '');
}
function _shopMonthlyBought(id){
  const mk = _getShopMonthlyKey();
  if(!_shopMonthlyData || _shopMonthlyData.month !== mk) return 0;
  return _shopMonthlyData[id] || 0;
}
function _shopMonthlyRecordBuy(id, qty){
  const mk = _getShopMonthlyKey();
  if(!_shopMonthlyData || _shopMonthlyData.month !== mk){
    _shopMonthlyData = { month: mk };
  }
  _shopMonthlyData[id] = (_shopMonthlyData[id] || 0) + qty;
}
function _shopDailyRecordBuy(id, qty){
  const today = _getShopDailyKey();
  if(!_shopDailyData || _shopDailyData.date !== today){
    // ★ v1.0.20260424.0740 — 跨日重置時,保留剛抽的 discountId(如果有)
    const _keepDiscount = (_shopDailyData && _shopDailyData.date === today) ? _shopDailyData.discountId : undefined;
    _shopDailyData = { date: today };
    if(_keepDiscount) _shopDailyData.discountId = _keepDiscount;
  }
  _shopDailyData[id] = (_shopDailyData[id]||0) + qty;
}

// ★ v1.0.20260424.0740 — 每日特價系統:每天 08:00(UTC 00:00)隨機抽一樣商品打 7 折
const SHOP_DISCOUNT_RATE = 0.7;
function _shopGetEligibleDiscountIds(){
  // 找出可被抽中折扣的商品:
  // - 排除一次性已擁有的(玩家無法購買)
  // - 排除已達每日限購上限的(無意義)
  // - 排除沒有 price 或 price <= 0 的
  const ids = [];
  if(typeof SHOP_PRODUCTS === 'undefined') return ids;
  SHOP_PRODUCTS.forEach(prod => {
    if(!prod || !prod.id || !(prod.price > 0)) return;
    // 一次性商品已擁有 → 排除
    if(prod.oneTime){
      const itemDef = (typeof BACKPACK_ITEM_DEF !== 'undefined') ? (BACKPACK_ITEM_DEF[prod.id]||{}) : {};
      const alreadyOwned = (itemDef.type === 'portrait'
                          && itemDef.heroName && itemDef.portraitId
                          && (typeof _heroPortraitUnlocked!=='undefined')
                          && (_heroPortraitUnlocked[itemDef.heroName] || []).includes(itemDef.portraitId))
                       || (typeof backpackGet === 'function' && backpackGet(prod.id) > 0);
      if(alreadyOwned) return;
    }
    // ★ v3.13.83 — 已達每週限購上限的商品(膠囊)排除,避免「打折卻買不了」的困惑
    if(prod.weeklyLimit > 0 && typeof _shopWeeklyBought === 'function' && _shopWeeklyBought(prod.id) >= prod.weeklyLimit) return;
    /* ★ v5.227.0 — 每月限購已領完的同樣排除(免費商品本來就 price<=0 進不來,這行是給日後其他月限商品用的) */
    if(prod.monthlyLimit > 0 && typeof _shopMonthlyBought === 'function' && _shopMonthlyBought(prod.id) >= prod.monthlyLimit) return;
    ids.push(prod.id);
  });
  return ids;
}
function _shopGetTodayDiscountId(){
  const today = _getShopDailyKey();
  if(!_shopDailyData || _shopDailyData.date !== today){
    // 跨日 → 重置 _shopDailyData,並抽當日新折扣
    const eligible = _shopGetEligibleDiscountIds();
    const newDiscount = eligible.length > 0
      ? eligible[Math.floor(Math.random() * eligible.length)]
      : null;
    _shopDailyData = { date: today };
    if(newDiscount) _shopDailyData.discountId = newDiscount;
  } else if(!_shopDailyData.discountId){
    // 當天首次進商店,抽折扣
    const eligible = _shopGetEligibleDiscountIds();
    if(eligible.length > 0){
      _shopDailyData.discountId = eligible[Math.floor(Math.random() * eligible.length)];
    }
  }
  return _shopDailyData.discountId || null;
}
// 取得實際售價(套用每日折扣)
function _shopGetEffectivePrice(prod){
  if(!prod) return 0;
  const basePrice = prod.price || 0;
  const todayDiscount = _shopGetTodayDiscountId();
  if(todayDiscount && todayDiscount === prod.id){
    return Math.round(basePrice * SHOP_DISCOUNT_RATE);
  }
  return basePrice;
}

async function shopBuyItem(id, _portraitConfirmed){
  // ★ v3.5.53 — 0.8 秒冷卻(防玩家連點寫雲端爆炸)
  // ★ v3.16.46 — 肖像確認 OK 後以 _portraitConfirmed=true 重跑,不再受 800ms 冷卻擋(否則確認常被冷卻吃掉)
  if(!_portraitConfirmed && !window._btnCooldown('shop_buy', 800)) return;
  const prod = SHOP_PRODUCTS.find(p=>p.id===id);
  if(!prod) return;
  const qty = window['_shopQty_'+id]||1;
  // ★ 一次性商品（例如肖像）：已擁有或已解鎖則不能再買
  if(prod.oneTime){
    const itemDef = BACKPACK_ITEM_DEF[id] || {};
    const alreadyUnlocked = itemDef.type === 'portrait'
      && itemDef.heroName && itemDef.portraitId
      && (_heroPortraitUnlocked[itemDef.heroName] || []).includes(itemDef.portraitId);
    if(alreadyUnlocked || backpackGet(id) > 0){
      _showInGameToast(`✨ 「${prod.name}」已擁有，無需再購買！`, '#ffaa44', 2500); return;
    }
    if(qty > 1){ _showInGameToast(`此商品限購 1 次`, '#ffaa44', 2000); return; }
  }
  // ★ 每日限購檢查
  if(prod.dailyLimit > 0){
    const alreadyBought = _shopDailyBought(id);
    const remaining = prod.dailyLimit - alreadyBought;
    if(remaining <= 0){
      _showInGameToast(`🍑 今日 ${prod.name} 已售完！明天再來！`, '#ff8844', 2500); return;
    }
    if(qty > remaining){
      _showInGameToast(`🍑 今日只剩 ${remaining} 個可購買！`, '#ffaa44', 2500); return;
    }
  }
  // ★ v3.13.83 — 每週限購檢查(極限膠囊:每週各 1 顆)
  if(prod.weeklyLimit > 0){
    const _wkBought = _shopWeeklyBought(id);
    const _wkRemain = prod.weeklyLimit - _wkBought;
    if(_wkRemain <= 0){
      _showInGameToast(`🧪 本週 ${prod.name} 已售完！下週一再來!`, '#ff8844', 3000); return;
    }
    if(qty > _wkRemain){
      _showInGameToast(`🧪 本週只剩 ${_wkRemain} 個可購買!`, '#ffaa44', 2800); return;
    }
  }
  const effectivePrice = _shopGetEffectivePrice(prod);
  const total = effectivePrice * qty;
  if((_knowledgeCoins||0) < total){
    _showInGameToast('💰 知識幣不足！', '#ff6644', 2000); return;
  }
  const canAdd = 99 - backpackGet(id);
  if(canAdd < qty){
    _showInGameToast(`🎒 背包已滿！（${prod.name} 最多持有99個）`, '#ff8844', 2500); return;
  }
  // ★ v3.16.46 — 肖像商品:若玩家尚未收錄該英雄,購買前貼心提示(老師需求)
  //   提示「只是外觀圖片、之後解鎖英雄才能套用」→ 確認後以 _portraitConfirmed=true 重跑完成購買
  if(!_portraitConfirmed){
    const _pcDef = BACKPACK_ITEM_DEF[id] || {};
    if(_pcDef.type === 'portrait' && _pcDef.heroName){
      let _heroOwned = false;
      try{
        const _uh = (typeof advGetUnlockedHeroes === 'function') ? advGetUnlockedHeroes() : [];
        _heroOwned = Array.isArray(_uh) && _uh.includes(_pcDef.heroName);
      }catch(_){}
      if(!_heroOwned){
        _customConfirm(
          '此商品只是外觀圖片，並非直接獲得該英雄，確定要現在就購買嗎?\n(等之後解鎖英雄時就能套用)',
          function(){ shopBuyItem(id, true); }
        );
        return;
      }
    }
  }
  _knowledgeCoins = Math.max(0, (_knowledgeCoins||0) - total);
  try{ _logCoinTx(-total, '消費:商店-' + ((prod && prod.name) || id)); }catch(_){}
  // ★ 肖像類商品：購買後立即解鎖，不進背包（避免多份佔格子）
  const _itemDef = BACKPACK_ITEM_DEF[id] || {};
  if(_itemDef.type === 'portrait' && _itemDef.heroName && _itemDef.portraitId){
    if(!_heroPortraitUnlocked[_itemDef.heroName]) _heroPortraitUnlocked[_itemDef.heroName] = [];
    if(!_heroPortraitUnlocked[_itemDef.heroName].includes(_itemDef.portraitId)){
      _heroPortraitUnlocked[_itemDef.heroName].push(_itemDef.portraitId);
      try{ _logSkinUnlock(_itemDef.heroName, _itemDef.portraitId, 'shop'); }catch(_){}
    }
    // 自動套用新肖像（玩家可事後在圖鑑切回原肖像）
    _switchHeroPortrait(_itemDef.heroName, _itemDef.portraitId);
  } else {
    backpackAdd(id, qty);
    // ★ v3.13.94 — 若購買的是召喚券,寫入活動紀錄(供 GM 查證券來源/時間)
    try{
      if(typeof id === 'string' && id.indexOf('summon_ticket') === 0 && typeof window._logActivity === 'function'){
        window._logActivity('ticket', { ticket: id, qty: qty, source: 'shop' });
      }
    }catch(_eShopTkLog){}
  }
  if(prod.dailyLimit > 0) _shopDailyRecordBuy(id, qty);
  if(prod.weeklyLimit > 0) _shopWeeklyRecordBuy(id, qty);  // ★ v3.13.83 — 記錄每週購買
  if(prod.monthlyLimit > 0) _shopMonthlyRecordBuy(id, qty); // ★ v5.227.0 — 記錄每月購買(UR 英雄替換卷)
  // ★ v4.97.0 主線第二章商店實戰教學 — 購買完成通知(教學未啟動時為 no-op)
  try{ if(typeof window._msShopTutNotify === 'function') window._msShopTutNotify('buy', id); }catch(_msTutE2){}
  try{ _checkMedalShop(); }catch(_){}
  _showInGameToast(`✅ 購買 ${prod.name} ×${qty}！支出 ${total.toLocaleString()} 知識幣`, '#44ff88', 2500);
  try{ playSfx('sfx-powerup', 0.7); }catch(_){}
  // ★ 立即同步知識幣顯示（跟賣出時一致）
  _syncCoinsDisplay();
  // ★ 不用 openShopOverlay() 避免觸發 BGM 重播；只重新渲染商品列表與背包欄
  _renderShopProducts();
  _renderShopBagPanel();
  // ★ 等待雲端同步完成
  try{ await gameCloudSave(); }catch(e){ console.error('[buy cloud save]', e); }
}

// ★ v3.13.72 — 超越極限果實「每日販售上限」helper。回傳今日「還可賣幾顆」。
//   用 _getTodayKeyTW()(遊戲日 08:00 為界,與預習領幣同基準);跨日自動歸零 fruitSellToday。
const FRUIT_SELL_DAILY_LIMIT = 5;
function _fruitSellRemainingToday(){
  try{
    if(typeof _medalStats !== 'object' || !_medalStats) return FRUIT_SELL_DAILY_LIMIT;
    const _today = (typeof _getTodayKeyTW === 'function') ? _getTodayKeyTW() : '';
    if(_medalStats.fruitSellDate !== _today){
      _medalStats.fruitSellDate = _today;
      _medalStats.fruitSellToday = 0;
    }
    return Math.max(0, FRUIT_SELL_DAILY_LIMIT - (_medalStats.fruitSellToday || 0));
  }catch(_){ return FRUIT_SELL_DAILY_LIMIT; }
}

async function shopSellItem(id, qty){
  // ★ v3.5.53 — 0.8 秒冷卻(防玩家連點寫雲端爆炸)
  if(!window._btnCooldown('shop_sell', 800)) return;
  const def = BACKPACK_ITEM_DEF[id]||{};
  const have = backpackGet(id);
  let actual = Math.min(have, qty);
  if(actual<=0){ _showInGameToast('背包中沒有這個物品', '#ff8844', 1500); return; }
  // ★ v3.13.72 — 超越極限果實每日販售上限 5 顆(跨遊戲日 08:00 自動重置)
  if(id === 'burst_upgrade_fruit'){
    const _remain = _fruitSellRemainingToday();
    if(_remain <= 0){
      _showInGameToast('🍑 今日「超越極限果實」已賣到上限(每天 5 顆),明天再來吧!', '#ff8844', 3000);
      try{ _renderShopBagPanel(); }catch(_){}
      return;
    }
    if(actual > _remain){
      actual = _remain;
      _showInGameToast('🍑 今日剩餘可賣 ' + _remain + ' 顆(每日上限 5 顆),已自動調整數量', '#ffcc44', 2800);
    }
  }
  const coins = (def.sellPrice||0) * actual;
  backpackRemove(id, actual);
  _knowledgeCoins = (_knowledgeCoins||0) + coins;
  // ★ v3.15.58(2026-06-20)— 單件賣出補記知識幣帳本(原本只有「一鍵賣出」shopSellAllItems 有 _logCoinTx,
  //   單件賣出漏記 → GM 洗錢查緝(_fbAdminScanMoneyLaundering)看不到「單件反覆賣出同額」的痕跡)。
  //   記「收入:賣出-道具名」含金額(amount)與時間(at),供查緝偵測「短時間同額重複賣出」=洗錢意圖。
  try{ if(typeof _logCoinTx === 'function') _logCoinTx(coins, '收入:賣出-' + (def.name || id)); }catch(_eSellTx){}
  if(id === 'burst_upgrade_fruit'){ try{ _medalStats.fruitSellToday = (_medalStats.fruitSellToday||0) + actual; }catch(_){} }
  // ★ v4.97.0 主線第二章商店實戰教學 — 賣出完成通知(教學未啟動時為 no-op)
  try{ if(typeof window._msShopTutNotify === 'function') window._msShopTutNotify('sell', id); }catch(_msTutE1){}
  _showInGameToast(`💰 賣出 ${def.name} ×${actual}，獲得 ${coins.toLocaleString()} 知識幣！`, '#ffcc44', 2500);
  try{
    const _sfxSell = document.getElementById('sfx-sell-item');
    if(_sfxSell){ _sfxSell.currentTime=0; _sfxSell.volume=0.595; _sfxSell.play().catch(()=>{}); }
    else playSfx('sfx-coin', 0.7);
  }catch(_){}
  _syncCoinsDisplay();
  _renderShopProducts();
  _renderShopBagPanel();
  // ★ 確實等待雲端同步完成，避免玩家重整時雲端未寫入 → 賣掉的物品復活
  try{ await gameCloudSave(); }catch(e){ console.error('[sell cloud save]', e); }
}

// ════════════════════════════════════════════════════════════════════
// ★ v3.12.0(2026-05-29)— 背包賣出數量選擇器(養成書類專用)
//   bagSellAdjQty(id, delta):調整 window._bagSellQty_{id} ±1,上限為持有量
//   bagSellWithSelectedQty(id):依目前選擇數量賣出(走 shopSellItem 路徑,含 0.8s 冷卻+雲端)
// ════════════════════════════════════════════════════════════════════
function bagSellAdjQty(id, delta){
  const cnt = (typeof backpackGet === 'function') ? backpackGet(id) : 0;
  if(cnt <= 0) return;
  // ★ v3.13.72 — 果實:+/- 上限同時受「持有量」與「今日剩餘可賣量(5/天)」夾制
  let _max = cnt;
  let _isFruitLimit = false;
  if(id === 'burst_upgrade_fruit'){ try{ var _fr = _fruitSellRemainingToday(); if(_fr < cnt){ _max = _fr; _isFruitLimit = true; } else { _max = cnt; } }catch(_){} }
  _max = Math.max(1, _max);
  const cur = window['_bagSellQty_'+id] || 1;
  // ★ v3.15.46 — 數量調整新規則:① + 超過上限 → 彈窗 + 卡在上限(鎖按鈕) ② 數量為 1 時按 - → 跳到最大循環
  let next;
  if(delta > 0){
    if(cur >= _max){
      var _msg = _isFruitLimit ? '🍑 已達今日販賣上限數量' : '💱 已達持有數量,沒有更多可賣了';
      _showInGameToast(_msg, '#ffaa44', 2000);
      next = _max;
    }else{
      next = Math.min(_max, cur + delta);
    }
  }else{
    next = (cur <= 1) ? _max : Math.max(1, cur + delta);  // 從 1 循環到最大,方便調整
  }
  window['_bagSellQty_'+id] = next;
  // 只更新數字 + 合計,不重新渲染整個背包(避免 input focus 跳掉)
  const _qtyEl = document.getElementById('bag-sell-qty-' + id);
  const _totalEl = document.getElementById('bag-sell-total-' + id);
  if(_qtyEl) _qtyEl.textContent = next;
  const _def = (typeof BACKPACK_ITEM_DEF !== 'undefined') ? BACKPACK_ITEM_DEF[id] : null;
  if(_totalEl && _def) _totalEl.textContent = ((_def.sellPrice||0) * next).toLocaleString();
  // ★ v3.15.46 — + 按鈕鎖定視覺(達上限變灰)
  _setPlusBtnLocked('bag-plus-' + id, next >= _max);
}

async function bagSellWithSelectedQty(id){
  const qty = window['_bagSellQty_'+id] || 1;
  // 賣完後 reset 選擇數量為 1(避免下次打開時殘留舊值)
  await shopSellItem(id, qty);
  window['_bagSellQty_'+id] = 1;
}

async function shopSellAllItems(){
  const sellable = SHOP_SELL_ITEMS.filter(si => backpackGet(si.id) > 0);
  if(!sellable.length){
    _showInGameToast('背包中沒有可賣出的物品', '#ff8844', 1800);
    return;
  }
  // 計算總賣價(不再產生 _summary 物品清單)
  let _totalCoins = 0;
  sellable.forEach(si => {
    const have = backpackGet(si.id);
    const def = BACKPACK_ITEM_DEF[si.id]||{};
    _totalCoins += (def.sellPrice||0) * have;
  });
  const _msg = `確認要一鍵賣出 ${sellable.length} 種賣錢物品嗎?\n\n💰 總收益:${_totalCoins.toLocaleString()} 知識幣`;
  // ★ v1.0.20260421.2600 — 改用遊戲內確認視窗(不再用瀏覽器原生 confirm)
  _customConfirm(_msg, async () => {
    // 批次賣出（不觸發個別 toast，最後統一一個提示）
    let _hasTaiwanItem = false;
    let _hasYushanCore = false;
    sellable.forEach(si => {
      const have = backpackGet(si.id);
      const def = BACKPACK_ITEM_DEF[si.id]||{};
      backpackRemove(si.id, have);
      _knowledgeCoins = (_knowledgeCoins||0) + (def.sellPrice||0) * have;
      try{ _logCoinTx((def.sellPrice||0) * have, '收入:賣出-' + (def.name || id)); }catch(_){}
      // ★ v1.1.0 — 偵測台灣物品賣出
      if(si.id && si.id.startsWith && si.id.startsWith('tw_')){
        _hasTaiwanItem = true;
        if(si.id === 'tw_yushan_core') _hasYushanCore = true;
      }
    });
    // ★ v1.1.0 — 觸發台灣關賣物品獎章
    try{
      if(_hasTaiwanItem && typeof window._checkTaiwanSellMedals === 'function'){
        window._checkTaiwanSellMedals('tw_xxx'); // 一般台灣物品
        if(_hasYushanCore) window._checkTaiwanSellMedals('tw_yushan_core');
      }
    }catch(_){}
    // 音效 + toast
    try{
      const _sfxSell = document.getElementById('sfx-sell-item');
      if(_sfxSell){ _sfxSell.currentTime=0; _sfxSell.volume=0.7; _sfxSell.play().catch(()=>{}); }
      else playSfx('sfx-coin', 0.75);
    }catch(_){}
    _showInGameToast(`💰 一鍵賣出完成！共 ${sellable.length} 種物品，獲得 ${_totalCoins.toLocaleString()} 知識幣！`, '#ffcc44', 3500);
    _syncCoinsDisplay();
    _renderShopProducts();
    _renderShopBagPanel();
    try{ await gameCloudSave(); }catch(e){ console.error('[sell all cloud save]', e); }
  });
}

// ════════════════════════════════════════════════════════════════
// ★ 背包系統
// ════════════════════════════════════════════════════════════════

function openBackpackOverlay(){
  const cv = document.getElementById('bag-coins-val');
  if(cv) cv.textContent = (_knowledgeCoins||0).toLocaleString();
  _renderBackpackMain();
  // ★ v5.252.0 — 「📜 獲得紀錄」入口鈕:雙版文字(鐵律 1.232 模式②動態)＋三平台樣式
  try{
    if(typeof window._lxpsGainLogEnsureCss === 'function') window._lxpsGainLogEnsureCss();
    const _gbCute = (window._artStyle === 'cute');
    const _gb = document.getElementById('bag-gainlog-btn');
    if(_gb) _gb.textContent = _gbCute ? '📜 拿到什麼' : '📜 獲得紀錄';
    const _gh = document.getElementById('bag-gainlog-hint');
    if(_gh) _gh.textContent = _gbCute ? '想知道最近拿到了什麼、召喚卷用到哪裡去了?' : '查詢近期獲得的道具、召喚卷使用紀錄、英雄與至寶';
  }catch(_eGb){}
  const ov = document.getElementById('backpack-overlay');
  if(ov) ov.style.display='block';
}

function closeBackpackOverlay(){
  const ov = document.getElementById('backpack-overlay');
  if(ov) ov.style.display='none';
}

// ════════════════════════════════════════════════════════════════════
// ★★ v5.252.0(2026-10-14・老師「新增『最近獲得物品清單』，讓學生可以查詢自己是否有獲得冒險中的獎勵
//    (包含召喚卷的使用紀錄)」)— 學生端「📜 最近獲得物品」清單 ★★
//   入口:背包標題列「📜 獲得紀錄」(cute 版「📜 拿到什麼」);也可 window._lxpsOpenGainLog() 直接開。
//   資料全讀本機(登入時雲端已合併寫回本機,零雲端讀取):
//     🎒 道具   ← lxps_item_log(v5.252.0 新帳本·含背包滿 99 沒放進去的數量)
//     🛡️ 裝備   ← window._equipUnlockHistory(取得類;賣出/送出/回收不列)
//     🎫 召喚卷 ← lxps_ticket_ledger_{uid}(獲得＋使用;使用那筆用券編號 tid 對回英雄/至寶帳本 →「換到誰」)
//     🦸 英雄   ← adv_hero_unlock_history(取得類;回收/確認/稽核類不列)
//     💎 至寶   ← adv_treasure_unlock_history(同上)
//     💰 知識幣 / 💠 水晶 ← lxps_coin_tx / lxps_crystal_tx(只列增加的筆)
//   每筆只列「有 uid 且是本人」或「沒有 uid 的舊紀錄」⇒ 共用 iPad 別人的紀錄不會出現(鐵律 1.41)。
//   畫面:body 直下 position:fixed 真實 px 視窗(不在 #gc 畫布內)⇒ 三平台各自用真實 px 媒體查詢調整(鐵律〇之二)。
//   純讀取,不寫任何資料。
// ════════════════════════════════════════════════════════════════════
window._lxpsGainLogEnsureCss = function(){
  try{
    if(document.getElementById('lxps-gainlog-css')) return;
    var st = document.createElement('style');
    st.id = 'lxps-gainlog-css';
    st.textContent = ''
      // 背包內容區最上方的入口列(#gc 畫布內·設計 px)
      + '#bag-gainlog-bar{display:flex;align-items:center;justify-content:flex-end;gap:20px;margin:0 0 14px;}'
      + '#bag-gainlog-hint{font-size:30px;font-weight:700;color:#a9c8f0;text-align:right;}'
      + '#bag-gainlog-btn{padding:10px 26px;font-size:40px;font-weight:800;background:linear-gradient(135deg,rgba(50,100,190,0.85),rgba(30,60,140,0.85));border:2px solid #8ec5ff;color:#eef6ff;border-radius:12px;cursor:pointer;font-family:inherit;white-space:nowrap;box-shadow:0 0 14px rgba(120,180,255,0.35);}'
      + '#lxps-gainlog-ov{position:fixed;inset:0;z-index:100500;display:flex;align-items:safe center;justify-content:center;background:rgba(0,0,14,0.8);padding:12px;box-sizing:border-box;font-family:"M PLUS Rounded 1c","Nunito",sans-serif;}'
      + '#lxps-gainlog-card{width:min(920px,96vw);max-height:min(92dvh,92vh);display:flex;flex-direction:column;box-sizing:border-box;background:linear-gradient(160deg,rgba(12,22,48,0.98),rgba(8,14,32,0.98));border:2.5px solid rgba(130,190,255,0.75);border-radius:16px;box-shadow:0 0 40px rgba(60,120,255,0.35);overflow:hidden;color:#dfeaff;}'
      + '#lxps-gainlog-card>*{flex:0 0 auto;}'   // 標題/說明/分類/頁尾不被壓縮(手機矮螢幕時只讓清單縮)
      + '#lxps-gainlog-card .gl-head{display:flex;align-items:center;gap:10px;padding:14px 18px 6px;}'
      + '#lxps-gainlog-card .gl-title{flex:1;font-size:24px;font-weight:900;color:#bfe0ff;letter-spacing:1px;}'
      + '#lxps-gainlog-card .gl-close{min-width:88px;min-height:44px;padding:6px 16px;font-size:18px;font-weight:800;background:rgba(70,20,20,0.55);border:2px solid #e86a6a;color:#ffd0d0;border-radius:10px;cursor:pointer;font-family:inherit;}'
      + '#lxps-gainlog-card .gl-sub{padding:0 18px 8px;font-size:15px;line-height:1.55;color:#a9c4e6;}'
      + '#lxps-gainlog-card .gl-chips{display:flex;flex-wrap:wrap;gap:8px;padding:4px 18px 10px;}'
      + '#lxps-gainlog-card .gl-chip{min-height:44px;padding:6px 14px;font-size:16px;font-weight:800;border-radius:22px;border:2px solid rgba(140,190,255,0.45);background:rgba(20,40,80,0.6);color:#cfe3ff;cursor:pointer;font-family:inherit;white-space:nowrap;}'
      + '#lxps-gainlog-card .gl-chip.on{background:linear-gradient(135deg,#3a7bd5,#2a5aa8);border-color:#bfe0ff;color:#fff;}'
      + '#lxps-gainlog-card .gl-list{flex:1 1 auto;min-height:0;overflow-y:auto;-webkit-overflow-scrolling:touch;overscroll-behavior:contain;padding:0 18px 10px;}'
      + '#lxps-gainlog-card .gl-day{position:sticky;top:0;z-index:1;margin:10px 0 4px;padding:5px 10px;font-size:15px;font-weight:900;color:#ffe08a;background:rgba(10,18,40,0.96);border-left:4px solid #ffcc55;border-radius:6px;}'
      + '#lxps-gainlog-card .gl-row{display:flex;align-items:flex-start;gap:10px;padding:8px 6px;border-bottom:1px solid rgba(255,255,255,0.08);font-size:16px;line-height:1.5;}'
      + '#lxps-gainlog-card .gl-time{flex:0 0 auto;min-width:46px;color:#8aa3c8;font-size:14px;padding-top:1px;font-variant-numeric:tabular-nums;}'
      + '#lxps-gainlog-card .gl-ic{flex:0 0 auto;width:26px;text-align:center;font-size:19px;}'
      + '#lxps-gainlog-card .gl-main{flex:1 1 auto;min-width:0;word-break:break-word;}'
      + '#lxps-gainlog-card .gl-src{display:inline-block;margin-left:6px;padding:0 8px;border-radius:9px;font-size:13px;background:rgba(120,170,255,0.16);border:1px solid rgba(120,170,255,0.4);color:#bcd6ff;white-space:nowrap;}'
      + '#lxps-gainlog-card .gl-warn{display:block;margin-top:2px;font-size:14px;color:#ffb27a;}'
      + '#lxps-gainlog-card .gl-got{color:#9effb0;font-weight:800;}'
      + '#lxps-gainlog-card .gl-use{color:#ffc08a;font-weight:800;}'
      + '#lxps-gainlog-card .gl-empty{padding:30px 10px;text-align:center;color:#8fa6c8;font-size:16px;}'
      + '#lxps-gainlog-card .gl-foot{padding:8px 18px 12px;font-size:13px;line-height:1.55;color:#93a9c9;border-top:1px solid rgba(255,255,255,0.08);}'
      // iPad / 平板(寬 ≥ 1000)略放大
      + '@media (min-width:1000px) and (min-height:700px){#lxps-gainlog-card .gl-title{font-size:28px;}#lxps-gainlog-card .gl-row{font-size:18px;}#lxps-gainlog-card .gl-sub{font-size:16px;}}'
      // 手機橫放(高度 ≤ 520):壓縮上下留白、分類列改單行橫向捲動、清單吃剩下的高度;字級守住內文 ≥12/標題 ≥16
      + '@media (orientation:landscape) and (max-height:520px){'
      +   '#lxps-gainlog-ov{padding:4px;}'
      +   '#lxps-gainlog-card{width:min(860px,98vw);max-height:calc(100dvh - 8px);border-radius:12px;}'
      +   '#lxps-gainlog-card .gl-head{padding:6px 12px 2px;}'
      +   '#lxps-gainlog-card .gl-title{font-size:18px;}'
      +   '#lxps-gainlog-card .gl-sub{padding:0 12px 4px;font-size:12px;line-height:1.4;}'
      +   '#lxps-gainlog-card .gl-chips{flex-wrap:nowrap;overflow-x:auto;padding:2px 12px 6px;gap:6px;}'
      +   '#lxps-gainlog-card .gl-chip{font-size:13px;padding:4px 12px;flex:0 0 auto;}'
      +   '#lxps-gainlog-card .gl-list{padding:0 12px 6px;}'
      +   '#lxps-gainlog-card .gl-row{font-size:14px;padding:6px 4px;}'
      +   '#lxps-gainlog-card .gl-time{font-size:12px;}'
      +   '#lxps-gainlog-card .gl-src{font-size:12px;}'
      +   '#lxps-gainlog-card .gl-day{font-size:13px;margin:6px 0 2px;}'
      +   '#lxps-gainlog-card .gl-foot{padding:4px 12px 6px;font-size:12px;}'
      // 背包入口鈕(#gc 畫布內·設計 px·手機約縮 0.36 倍)→ 放大到真實高度 ≥ 44px;提示字放大到真實 ≥ 12px
      +   '#bag-gainlog-btn{font-size:66px;padding:22px 30px;}'
      +   '#bag-gainlog-hint{font-size:40px;}'
      + '}';
    document.head.appendChild(st);
  }catch(_e){}
};
try{ window._lxpsGainLogEnsureCss(); }catch(_eGlCss){}   // 載入即注入,背包入口鈕一出現就有樣式

window._lxpsGainLogRows = function(){
  var _cute = (window._artStyle === 'cute');
  var T = function(c, p){ return _cute ? c : p; };
  var _esc = function(s){ return String(s == null ? '' : s).replace(/[&<>"]/g, function(c){ return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'})[c]; }); };
  var _me = String(window._gUserId || '').slice(0, 12);
  var _mine = function(u){ u = String(u || ''); return !u || !_me || u.slice(0, 12) === _me; };
  var _arr = function(key){ try{ var r = localStorage.getItem(key); var a = r ? JSON.parse(r) : []; return Array.isArray(a) ? a : []; }catch(_){ return []; } };
  var _def = function(id){
    try{ if(typeof BACKPACK_ITEM_DEF !== 'undefined' && BACKPACK_ITEM_DEF[id]) return BACKPACK_ITEM_DEF[id]; }catch(_){}
    return null;
  };
  var _itemNm = function(id){ var d = _def(id); return d ? (String(d.icon || '') + ' ' + String(d.name || id)) : ('📦 ' + id); };
  var _treNm = function(id){
    try{ var db = window.TAIWAN_TREASURES; if(db && db[id] && db[id].name) return String(db[id].name); }catch(_){}
    return String(id);
  };
  var _srcLbl = function(s){
    try{ if(typeof _lxpsUnlockSourceLabel === 'function'){ var o = _lxpsUnlockSourceLabel(s); return o ? o.text : ''; } }catch(_){}
    return '';
  };
  var rows = [];
  var _SKIP_SRC = { admin_delete:1, player_confirmed:1, audit_error_recovered:1, sold:1, gift_sent:1 };

  // ── 英雄 / 至寶(先建 tid → 名稱對照,召喚卷「換到誰」要用)──
  var _tidHit = {};
  var _heroH = _arr('adv_hero_unlock_history');
  _heroH.forEach(function(e){
    if(!e || !e.name || !_mine(e.uid)) return;
    var src = String(e.source || '');
    if(_SKIP_SRC[src] || src.indexOf('audit') === 0) return;
    if(e.tid) String(e.tid).split(',').forEach(function(t){ t = t.trim(); if(t) (_tidHit[t] = _tidHit[t] || []).push('🦸 ' + e.name); });
    rows.push({ at:(Number(e.at) || 0), cat:'hero', ic:'🦸',
      html:'<span class="gl-got">' + T('拿到英雄', '獲得英雄') + '</span> <b>' + _esc(e.name) + '</b>', src:_srcLbl(src) });
  });
  var _treH = _arr('adv_treasure_unlock_history');
  _treH.forEach(function(e){
    if(!e || !e.id || !_mine(e.uid)) return;
    var src = String(e.source || '');
    if(_SKIP_SRC[src] || src.indexOf('audit') === 0) return;
    if(e.tid) String(e.tid).split(',').forEach(function(t){ t = t.trim(); if(t) (_tidHit[t] = _tidHit[t] || []).push('💎 ' + _treNm(e.id)); });
    rows.push({ at:(Number(e.at) || 0), cat:'hero', ic:'💎',
      html:'<span class="gl-got">' + T('拿到至寶', '獲得至寶') + '</span> <b>' + _esc(_treNm(e.id)) + '</b>', src:_srcLbl(src) });
  });

  // ── 召喚卷(獲得＋使用)──
  if(_me){
    _arr('lxps_ticket_ledger_' + window._gUserId).forEach(function(e){
      if(!e || !e.item || !_mine(e.uid)) return;
      var n = Math.abs(parseInt(e.n, 10) || 0) || 1;
      if(e.ev === 'use'){
        var _got = [];
        if(e.tid) String(e.tid).split(',').forEach(function(t){ t = t.trim(); if(t && _tidHit[t]) _got = _got.concat(_tidHit[t]); });
        var _res = String(e.result || '');
        if(!_got.length && _res.indexOf(':') > 0) _got.push(_res.slice(_res.indexOf(':') + 1));   // 寵物券 'SR:綠雉'
        rows.push({ at:(Number(e.at) || 0), cat:'ticket', ic:'🎫',
          html:'<span class="gl-use">' + T('用掉', '使用') + '</span> ' + _esc(_itemNm(e.item)) + ' ×' + n
            + (_got.length ? (' → ' + T('換到 ', '換得 ') + '<b>' + _esc(_got.join('、')) + '</b>') : ''),
          src:'' });
      } else if(e.ev === 'grant'){
        var _gs = String(e.result || '');
        if(_gs === 'grant') _gs = '';
        rows.push({ at:(Number(e.at) || 0), cat:'ticket', ic:'🎫',
          html:'<span class="gl-got">' + T('拿到', '獲得') + '</span> ' + _esc(_itemNm(e.item)) + ' ×' + n, src:_gs });
      }
    });
  }

  // ── 一般道具(v5.252.0 新帳本)──
  _arr('lxps_item_log').forEach(function(e){
    if(!e || !e.it || !_mine(e.uid)) return;
    var n = parseInt(e.n, 10) || 0, x = parseInt(e.x, 10) || 0;
    var _isTk = !!(window._TICKET_LEDGER_KEYS && window._TICKET_LEDGER_KEYS[e.it]);
    var html = n > 0 ? ('<span class="gl-got">' + T('拿到', '獲得') + '</span> ' + _esc(_itemNm(e.it)) + ' ×' + n)
                     : ('<span class="gl-use">' + T('沒拿到', '未入袋') + '</span> ' + _esc(_itemNm(e.it)));
    if(x > 0) html += '<span class="gl-warn">⚠ ' + T('背包已經 99 個滿了,有 ' + x + ' 個沒放進去', '背包已達上限 99,另有 ' + x + ' 個未能放入') + '</span>';
    rows.push({ at:(Number(e.at) || 0), cat:(_isTk ? 'ticket' : 'item'), ic:(_isTk ? '🎫' : '🎒'), html:html, src:String(e.s || '') });
  });

  // ── 裝備(取得類)──
  try{
    var _GSRC = { drop_mob:'冒險・小怪掉落', drop_rare:'冒險・菁英掉落', drop_boss:'冒險・BOSS 掉落', summon:'召喚',
                  shop:'商店', gm_grant:'老師發放', gift:'好友贈送' };
    (Array.isArray(window._equipUnlockHistory) ? window._equipUnlockHistory : []).forEach(function(e){
      if(!e || !e.itemId || !_mine(e.uid12)) return;
      var src = String(e.src || '');
      if(_SKIP_SRC[src] || _SKIP_SRC[String(e.source || '')]) return;
      var g = (typeof GEAR_DB !== 'undefined' && GEAR_DB[e.itemId]) ? GEAR_DB[e.itemId] : null;
      rows.push({ at:(Number(e.at) || 0), cat:'item', ic:'🛡️',
        html:'<span class="gl-got">' + T('拿到裝備', '獲得裝備') + '</span> ' + _esc(g ? (String(g.icon || '') + ' ' + g.n) : e.itemId),
        src:(_GSRC[src] || '') });
    });
  }catch(_eG){}

  // ── 知識幣 / 召喚水晶(只列增加)──
  var _money = function(key, ic, nmC, nmP){
    _arr(key).forEach(function(e){
      if(!e || !_mine(e.uid)) return;
      var a = parseInt(e.amount, 10) || 0;
      if(a <= 0) return;
      var r = String(e.reason || '');
      if(r.indexOf('基準') === 0) return;
      if(r === '(未分類變動)') r = T('其他', '其他來源');
      r = r.replace(/^獲得:/, '');
      rows.push({ at:(Number(e.at) || 0), cat:'money', ic:ic,
        html:'<span class="gl-got">+' + a.toLocaleString() + '</span> ' + T(nmC, nmP), src:r });
    });
  };
  _money('lxps_coin_tx', '💰', '知識幣', '知識幣');
  _money('lxps_crystal_tx', '💠', '召喚水晶', '召喚水晶');

  rows.sort(function(a, b){ return (b.at || 0) - (a.at || 0); });
  return rows;
};

window._lxpsOpenGainLog = function(initCat){
  try{
    window._lxpsGainLogEnsureCss();
    var _cute = (window._artStyle === 'cute');
    var T = function(c, p){ return _cute ? c : p; };
    var _esc = function(s){ return String(s == null ? '' : s).replace(/[&<>"]/g, function(c){ return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'})[c]; }); };
    var _old = document.getElementById('lxps-gainlog-ov'); if(_old) _old.remove();
    var CATS = [
      { k:'all',    c:'📋 全部',        p:'📋 全部' },
      { k:'item',   c:'🎒 道具和裝備',   p:'🎒 道具・裝備' },
      { k:'ticket', c:'🎫 召喚卷',      p:'🎫 召喚卷(含使用)' },
      { k:'hero',   c:'🦸 英雄和至寶',   p:'🦸 英雄・至寶' },
      { k:'money',  c:'💰 知識幣和水晶', p:'💰 知識幣・水晶' }
    ];
    var _cat = initCat || 'all';
    var _rows = window._lxpsGainLogRows();
    var ov = document.createElement('div');
    ov.id = 'lxps-gainlog-ov';
    ov.innerHTML = '<div id="lxps-gainlog-card" role="dialog" aria-modal="true">'
      + '<div class="gl-head"><div class="gl-title">' + T('📜 我最近拿到什麼', '📜 最近獲得物品紀錄') + '</div>'
      + '<button class="gl-close" type="button">✕ ' + T('關掉', '關閉') + '</button></div>'
      + '<div class="gl-sub">' + T('打完冒險、領了獎勵、用了召喚卷,都會記在這裡喔!最新的在最上面。',
                                    '依時間由新到舊,列出你獲得的道具、裝備、召喚卷(含使用紀錄)、英雄、至寶、知識幣與召喚水晶。') + '</div>'
      + '<div class="gl-chips">' + CATS.map(function(c){ return '<button type="button" class="gl-chip" data-k="' + c.k + '">' + T(c.c, c.p) + '</button>'; }).join('') + '</div>'
      + '<div class="gl-list" data-scrollable="true"></div>'
      + '<div class="gl-foot">' + T('📌 道具和裝備從這次更新開始才有完整紀錄。如果覺得少拿了,把這一頁截圖給老師看!',
                                     '📌 一般道具自本次更新(v5.252.0)起開始記錄;召喚卷、英雄、至寶、知識幣、水晶可查到較早的紀錄。若認為獎勵短少,請截圖本頁並告知老師。') + '</div>'
      + '</div>';
    document.body.appendChild(ov);
    var _list = ov.querySelector('.gl-list');
    var _pad = function(v){ return (v < 10 ? '0' : '') + v; };
    var _render = function(){
      Array.prototype.forEach.call(ov.querySelectorAll('.gl-chip'), function(b){ b.classList.toggle('on', b.getAttribute('data-k') === _cat); });
      var rs = _rows.filter(function(r){ return _cat === 'all' || r.cat === _cat; });
      if(!rs.length){
        _list.innerHTML = '<div class="gl-empty">' + T('這裡還沒有紀錄喔,去冒險拿獎勵吧!', '目前沒有符合的紀錄。') + '</div>';
        return;
      }
      var LIMIT = 300, h = '', lastDay = '';
      var _now = new Date(), _today = _now.getFullYear() + '/' + (_now.getMonth() + 1) + '/' + _now.getDate();
      var _y = new Date(_now.getTime() - 86400000), _yday = _y.getFullYear() + '/' + (_y.getMonth() + 1) + '/' + _y.getDate();
      var WK = ['日','一','二','三','四','五','六'];
      rs.slice(0, LIMIT).forEach(function(r){
        var d = new Date(r.at || 0);
        var dk = d.getFullYear() + '/' + (d.getMonth() + 1) + '/' + d.getDate();
        if(dk !== lastDay){
          lastDay = dk;
          var tag = (dk === _today) ? T('(今天)', '(今日)') : (dk === _yday ? T('(昨天)', '(昨日)') : '');
          h += '<div class="gl-day">' + (r.at ? ((d.getMonth() + 1) + '/' + d.getDate() + ' ' + T('星期', '週') + WK[d.getDay()] + ' ' + tag) : T('時間不明', '時間不詳')) + '</div>';
        }
        h += '<div class="gl-row"><span class="gl-time">' + (r.at ? (_pad(d.getHours()) + ':' + _pad(d.getMinutes())) : '--:--') + '</span>'
          + '<span class="gl-ic">' + r.ic + '</span>'
          + '<span class="gl-main">' + r.html + (r.src ? ('<span class="gl-src">' + _esc(r.src) + '</span>') : '') + '</span></div>';
      });
      if(rs.length > LIMIT) h += '<div class="gl-empty">' + T('更早的紀錄太多了,只顯示最近 ' + LIMIT + ' 筆', '僅顯示最近 ' + LIMIT + ' 筆') + '</div>';
      _list.innerHTML = h;
      _list.scrollTop = 0;
    };
    var _close = function(){
      try{ document.removeEventListener('keydown', _onKey, true); }catch(_){}
      try{ ov.remove(); }catch(_){}
    };
    var _onKey = function(ev){ if(ev.key === 'Escape'){ ev.stopPropagation(); _close(); } };
    document.addEventListener('keydown', _onKey, true);
    ov.addEventListener('click', function(ev){ if(ev.target === ov) _close(); });
    ov.querySelector('.gl-close').onclick = function(){ try{ playSfx('sfx-cancel', 0.4); }catch(_){} _close(); };
    Array.prototype.forEach.call(ov.querySelectorAll('.gl-chip'), function(b){
      b.onclick = function(){ try{ playSfx('sfx-sel', 0.5); }catch(_){} _cat = b.getAttribute('data-k'); _render(); };
    });
    _render();
  }catch(_eOpen){ try{ console.warn('[最近獲得物品] 開啟失敗', _eOpen); }catch(_){} }
};

function _renderBackpackMain(){
  const grid = document.getElementById('backpack-grid');
  if(!grid) return;
  _renderBackpackInto(grid, true); // true=顯示使用按鈕
}


// ★ 背包物品說明彈窗（商店右欄 ? 按鈕）
function _showBagItemTip(id, el){
  const old = document.getElementById('bag-item-tip');
  if(old && old._forId===id){ old.remove(); return; }
  if(old) old.remove();
  const def = (typeof BACKPACK_ITEM_DEF !== 'undefined') ? BACKPACK_ITEM_DEF[id] : null;
  if(!def) return;
  const t = document.createElement('div');
  t.id = 'bag-item-tip';
  t._forId = id;
  t.style.cssText = 'position:fixed;z-index:9999;max-width:480px;'+
    'background:rgba(8,10,25,0.97);border:2px solid rgba(100,150,255,0.7);'+
    'color:#cce;font-size:28px;padding:20px 24px;border-radius:16px;line-height:1.6;'+
    'box-shadow:0 0 24px rgba(80,120,255,0.4);pointer-events:auto;';
  const isSell = def.type==='sell_only';
  const sellTxt = isSell ? '<br><span style="color:#ffaa44;">🛒 賣出：'+(def.sellPrice||0).toLocaleString()+' 💰</span>' : '';
  t.innerHTML =
    '<div style="font-size:30px;font-weight:900;color:#ddeeff;margin-bottom:8px;">'+
    def.icon+' '+def.name+'</div>'+
    (def.desc||'')+sellTxt;
  const r2 = el.getBoundingClientRect();
  const tipW = 480;
  // 出現在按鈕左側（避免超出右邊）
  let leftPos = r2.left - tipW - 8;
  if(leftPos < 8) leftPos = 8;
  t.style.left = leftPos + 'px';
  t.style.top  = Math.min(r2.bottom + 4, window.innerHeight - 200) + 'px';
  document.body.appendChild(t);
  setTimeout(function(){
    document.addEventListener('click', function h(ev){
      if(!t.contains(ev.target)){ t.remove(); document.removeEventListener('click',h,true); }
    }, {once:false, capture:true});
  }, 80);
}

