// ── 上下比對確認(上=原存檔 / 下=要存進去的內容) ──
function _ptvCmpLineHtml(pt, otherPt, isNew){
  if(!pt) return '<div style="font-size:17px;color:#666;">（空欄位）</div>';
  var _h = '<div style="font-size:20px;font-weight:900;color:' + (isNew ? '#c6ffd8' : '#ffd9b0') + ';margin-bottom:6px;">'
    + '🏷 ' + _ptvEsc(pt.name || '');
  if(otherPt && (pt.name || '') !== (otherPt.name || '')){
    _h += ' <span style="font-size:15px;color:#ff9;background:rgba(255,220,0,0.18);border-radius:6px;padding:1px 7px;">'
      + _ptvT('名字不一樣', '名稱不同') + '</span>';
  }
  _h += '</div><div style="display:flex;flex-wrap:wrap;gap:8px;">';
  var _hs = pt.heroes || [];
  for(var m = 0; m < _hs.length; m++){
    if(!_hs[m]) continue;
    var _e = (pt.elements && pt.elements[m]) || '';
    var _oe = (otherPt && otherPt.elements && otherPt.elements[m]) || '';
    var _diff = otherPt ? (_e !== _oe) : false;
    // ★ v5.107.0 — 整備三項也要能比對(它們都是陣容存檔的一部分,覆蓋後回不去)
    var _p  = (pt.pets && pt.pets[m]) || '';
    var _op = (otherPt && otherPt.pets && otherPt.pets[m]) || '';
    var _pDiff = otherPt ? (_p !== _op) : false;
    var _petTxt = _p ? ('🐾' + _ptvEsc(_p)) : (_pDiff ? ('🐾' + _ptvT('沒有', '無')) : '');
    var _tl = (pt.treasures && pt.treasures[m]) || null;
    var _ol = (otherPt && otherPt.treasures && otherPt.treasures[m]) || null;
    var _tDiff = (otherPt && Array.isArray(_tl) && Array.isArray(_ol)) ? !_ptvSameList(_tl, _ol) : false;
    var _gl = (pt.gear && pt.gear[m]) || null;
    var _og = (otherPt && otherPt.gear && otherPt.gear[m]) || null;
    var _gDiff = (otherPt && Array.isArray(_gl) && Array.isArray(_og)) ? !_ptvSameList(_gl, _og) : false;
    var _anyDiff = (_diff || _pDiff || _tDiff || _gDiff);
    _h += '<span style="font-size:16px;padding:4px 10px;border-radius:9px;'
      + 'background:' + (_anyDiff ? 'rgba(255,220,0,0.18)' : 'rgba(255,255,255,0.06)') + ';'
      + 'border:1.5px solid ' + (_anyDiff ? 'rgba(255,220,80,0.8)' : 'rgba(255,255,255,0.15)') + ';color:#eee;">'
      + _ptvEsc(_hs[m]) + ' ' + _ptvElemFull(_e) + (_diff ? ' ✏' : '')
      + (_petTxt ? ('<span style="font-size:14px;color:' + (_pDiff ? '#ffdd77' : '#ffcf6e') + ';"> ' + _petTxt + (_pDiff ? '✏' : '') + '</span>') : '')
      + (Array.isArray(_tl) ? ('<span style="font-size:14px;color:' + (_tDiff ? '#ffdd77' : '#ffcc66') + ';"> 💎' + _tl.length + (_tDiff ? '✏' : '') + '</span>') : '')
      + (Array.isArray(_gl) ? ('<span style="font-size:14px;color:' + (_gDiff ? '#ffdd77' : '#9fd0ff') + ';"> 🛡' + _gl.length + (_gDiff ? '✏' : '') + '</span>') : '')
      + '</span>';
  }
  _h += '</div>';
  return _h;
}
