// ════════════════════════════════════════════════════════════════════════════
// ★ v5.103.0 — 舊版「唯讀・點了直接出戰」面板整段保留備查(勿刪·未被任何地方呼叫)
// ════════════════════════════════════════════════════════════════════════════
function openPresetTeamPanel_LEGACY_v5102(){
  const existing = document.getElementById('preset-team-panel');
  if(existing){ existing.remove(); return; }

  const hasAny = _getCurrentPresetTeams().some(p=>p!==null);

  const ov = document.createElement('div');
  ov.id = 'preset-team-panel';
  ov.style.cssText = 'position:fixed;inset:0;z-index:9500;background:rgba(0,0,0,0.88);display:flex;align-items:center;justify-content:flex-start;flex-direction:column;padding:24px;overflow-y:auto;-webkit-overflow-scrolling:touch;overscroll-behavior:contain;touch-action:pan-y;font-family:"M PLUS Rounded 1c","Nunito",sans-serif;';
  // ★ iPad：允許 pan-y 滾動（覆蓋全域 touch-action:none）
  document.documentElement.style.touchAction = 'pan-y';
  document.body.style.touchAction = 'pan-y';

  const box = document.createElement('div');
  box.style.cssText = 'background:linear-gradient(160deg,#0d0a1e,#08061a);border:2.5px solid rgba(180,120,255,0.7);border-radius:20px;padding:28px 32px;max-width:980px;width:100%;box-shadow:0 0 50px rgba(150,80,255,0.35);';

  let html = '<div style="font-size:32px;font-weight:900;color:#cc99ff;margin-bottom:6px;text-align:center;">📋 常用預設陣容</div>';
  if(!hasAny){
    html += '<div style="font-size:22px;color:#666;text-align:center;padding:24px;">（尚無儲存的預設陣容。請先在技能替換頁面儲存一組！）</div>';
  } else {
    html += '<div style="display:flex;flex-direction:column;gap:14px;margin-top:12px;">';
    for(let i=0; i<5; i++){
      const pt = _getCurrentPresetTeams()[i];
      if(!pt){ 
        html += `<div style="padding:12px 18px;background:rgba(20,15,30,0.5);border:1.5px dashed rgba(100,80,150,0.3);border-radius:12px;color:#444;font-size:20px;text-align:center;">欄位${i+1}（空）</div>`;
        continue;
      }
      const slotName = pt.name || `陣容${i+1}`;
      html += `<div onclick="_applyPresetTeam(${i})" style="cursor:pointer;padding:14px 18px;background:rgba(40,25,80,0.7);border:2px solid rgba(180,120,255,0.5);border-radius:14px;transition:border-color 0.15s;"
        onmouseover="this.style.borderColor='rgba(220,160,255,0.9)'" onmouseout="this.style.borderColor='rgba(180,120,255,0.5)'">
        <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px;">
          <div style="font-size:24px;font-weight:900;color:#cc99ff;">欄位${i+1}：${slotName}</div>
          <button onclick="event.stopPropagation();_deletePresetSlot(${i})" style="padding:4px 14px;font-size:17px;background:rgba(60,10,10,0.4);border:1.5px solid #e84040;color:#e84040;border-radius:7px;cursor:pointer;font-family:inherit;">🗑 刪除</button>
        </div>
        <div style="display:flex;gap:10px;flex-wrap:wrap;">
          ${pt.heroes.map((name,hi)=>{
            const imgUrl = _presetHeroImgUrl(name);
            const elem = pt.elements[hi]||'';
            const sk = pt.skills[hi]||{};
            const skLabel = sk.skillName ? `🔄${sk.slot?sk.slot.toUpperCase():''}: ${sk.skillName}` : '（不替換）';
            const _oPos = (typeof getHeroObjPos==='function') ? getHeroObjPos(name) : 'center 20%';
            // ★ v1.0.20260424.0430 — 冒險模式預設陣容顯示當前 Lv,鬥技場不顯示
            const _isAdv = (typeof _adventureMode !== 'undefined' && _adventureMode);
            const _heroLv = _isAdv && (typeof getHeroLevel === 'function') ? getHeroLevel(name) : 0;
            const _lvLabel = (_isAdv && _heroLv > 0) ? ` <span style="color:#88ccff;font-size:16px;">Lv${_heroLv}</span>` : '';
            // ★ v4.33.0(任務1)— 冒險模式顯示該英雄攜帶的跟隨寵物(去背圖+名);鬥技場禁寵物不顯示。
            //   優先讀存檔當時的 pt.pets[hi],舊存檔(無 pets 欄位)退回讀當下跟隨寵物,不留空白。
            let _petName = '';
            if(_isAdv){
              _petName = (pt.pets && typeof pt.pets[hi] !== 'undefined' && pt.pets[hi])
                ? pt.pets[hi]
                : ((typeof window._petFollowOf === 'function') ? (window._petFollowOf(name) || '') : '');
            }
            let _petHtml = '';
            if(_petName){
              const _petImg = (typeof window._petNobgUrl === 'function') ? window._petNobgUrl(_petName) : '';
              _petHtml = `<div style="display:flex;align-items:center;gap:5px;margin-top:2px;">`
                + (_petImg
                    ? `<img src="${_petImg}" style="width:30px;height:30px;object-fit:contain;filter:drop-shadow(0 0 5px rgba(255,210,110,0.85));" onerror="this.onerror=null;this.replaceWith(Object.assign(document.createElement('span'),{textContent:'🐾',style:'font-size:22px'}))">`
                    : `<span style="font-size:22px;">🐾</span>`)
                + `<span style="font-size:15px;color:#ffcf6e;font-weight:700;">${_petName}</span></div>`;
            }
            return `<div style="display:flex;flex-direction:column;align-items:center;gap:5px;width:200px;">
              <div style="width:200px;height:160px;border-radius:10px;overflow:hidden;border:1.5px solid rgba(200,150,255,0.4);background:#0a0818;position:relative;flex-shrink:0;">
                ${imgUrl?`<div style="width:100%;height:100%;background:url('${imgUrl}') ${_oPos}/cover;"></div>`:`<div style="width:100%;height:100%;display:flex;align-items:center;justify-content:center;font-size:52px;">${(typeof AVATARS!=='undefined'&&AVATARS[name])||'⚔'}</div>`}
              </div>
              <div style="font-size:19px;font-weight:800;color:#ddd;">${name}${_lvLabel}</div>
              <div style="font-size:17px;color:#88aaff;">${elem?_presetElemLabel(elem):''}</div>
              <div style="font-size:15px;color:#cc99ff;text-align:center;max-width:200px;word-break:break-all;">${skLabel}</div>
              ${_petHtml}
            </div>`;
          }).join('')}
        </div>
        <div style="margin-top:10px;text-align:right;">
          <span style="font-size:18px;color:#88cc88;font-weight:700;">▶ 點擊套用此陣容</span>
        </div>
      </div>`;
    }
    html += '</div>';
  }
  html += "<div style='text-align:center;margin-top:18px;'><button onclick=\"_closePresetOv('preset-team-panel')\" style='padding:10px 32px;font-size:22px;background:rgba(60,10,10,0.4);border:2px solid #e84040;color:#e84040;border-radius:10px;cursor:pointer;font-family:inherit;'>✕ 關閉</button></div>";

  box.innerHTML = html;
  // ★ 點擊背景關閉 + 恢復 touch-action
  ov.addEventListener('click', function(e){
    if(e.target === ov){
      ov.remove();
      document.documentElement.style.touchAction = '';
      document.body.style.touchAction = '';
    }
  });
  ov.appendChild(box);
  document.body.appendChild(ov);
}

function _deletePresetSlot(slotIdx){
  // ★ v3.5.53 — 2 秒冷卻(同預設陣容儲存)
  if(!window._btnCooldown('preset_delete', 2000)) return;
  // ★★ v5.103.0(2026-08-21)— 兩處修正 ★★
  //   ① 補二次確認:本視窗自 v5.103.0 起變成「可編輯」,畫面上按鈕變多、誤觸風險升高,
  //      而刪除是不可復原的;與預設陣容編輯器 _peDeleteSlot 同款 _customConfirm 守門(口徑一致)。
  //   ② 刪除後改「就地 _ptvRender 刷新」,**不再** remove 整個面板再 openPresetTeamPanel() 重開 ——
  //      重開會把 window._ptvDrafts 整包清空,連「其他欄位還沒儲存的元素/名稱修改」一起丟掉。
  //   (原 v3.5.53 版本保留備查:
  //     _setCurrentPresetTeamSlot(slotIdx, null); gameCloudSave();
  //     _showInGameToast(...); const ov=...; if(ov){ov.remove();...} openPresetTeamPanel(); )
  var _doDel = function(){
    _setCurrentPresetTeamSlot(slotIdx, null);
    try{ if(window._ptvDrafts) delete window._ptvDrafts[slotIdx]; }catch(_){}
    gameCloudSave();
    _showInGameToast('🗑 欄位' + (slotIdx + 1) + ' 已刪除', '#ff8888', 1500);
    try{
      if(document.getElementById('preset-team-panel') && typeof _ptvRender === 'function'){ _ptvRender(); return; }
    }catch(_){}
    var ov = document.getElementById('preset-team-panel');
    if(ov){ ov.remove(); document.documentElement.style.touchAction=''; document.body.style.touchAction=''; }
    openPresetTeamPanel();
  };
  try{
    if(typeof _customConfirm === 'function'){
      _customConfirm((typeof _ptvT === 'function')
        ? _ptvT('確定要刪掉欄位' + (slotIdx + 1) + ' 這一隊嗎？', '確定要刪除欄位' + (slotIdx + 1) + ' 的陣容嗎？（無法復原）')
        : ('確定要刪除欄位' + (slotIdx + 1) + ' 的陣容嗎？'), _doDel);
      return;
    }
  }catch(_){}
  _doDel();
}

// ★★ v5.103.0(2026-08-21)— 新增**選用**第二參數 overridePt ★★
//   用途:預設陣容視窗的「這次先不存，直接出發」——把草稿組成的陣容直接帶上場，
//   存檔一個位元組都不動(_getCurrentPresetTeams() 完全不被寫入)。
//   ⚠ 既有呼叫點(_ptv 之外全部)只傳一個參數 ⇒ overridePt 為 undefined ⇒ 行為與修改前一字不差。
//   ⚠ 下方所有邏輯(冒險合法性檢查 / 鬥技場 UR 守門 v5.91.0 / 戰前養成套用 v5.74.0 /
//     寵物還原 v4.33.0 / variant 切換)全部照舊讀同一個 pt，**一行未動**。
function _applyPresetTeam(slotIdx, overridePt){
  const pt = overridePt || _getCurrentPresetTeams()[slotIdx];
  if(!pt){ _showInGameToast('此欄位沒有儲存的陣容', '#ff8844', 1500); return; }

  const isAdvMode = window._advSystemReady && _adventureMode === true && !!_adventureStage;
  if(isAdvMode){
    try{
      const _unlocked = (typeof advGetUnlockedHeroes === 'function') ? advGetUnlockedHeroes() : [];
      const _initial = (typeof ADV_HERO_POOL !== 'undefined' && ADV_HERO_POOL.maokong) ? ADV_HERO_POOL.maokong : [];
      const _basePool = (typeof ADV_HERO_POOL !== 'undefined' && ADV_HERO_POOL[_adventureStage]) || [];
      const _allowed = new Set([..._initial, ..._basePool, ..._unlocked]);
      const _invalid = pt.heroes.filter(n => !_allowed.has(n));
      if(_invalid.length){
        _showInGameToast(
          '⛔ 陣容包含未解鎖英雄:' + _invalid.join('、') + ' — 無法在冒險模式套用',
          '#ff4444', 4500
        );
        try{ playSfx('sfx-cancel', 0.7); }catch(_){}
        return;
      }
    }catch(_preE){ console.warn('[預設陣容] 防禦性檢查失敗:', _preE); }
    /* ★★ v5.227.0(老師「冒險模式隊伍最多只能配置 2 名 UR」)★★
       一鍵套用預設陣容是**繞過編組頁**的另一條進場路徑,confirmHeroPick 那道守門在這裡碰不到,
       兩處都要有才擋得住(與 v5.91.0 鬥技場 UR 走同一個教訓:只守顯示層一定會被別的入口繞過)。
       ⚠ 同樣「拒絕整筆」不自動剔除——剔掉會變 3 打 4,而且玩家不會發現。
       ⚠ 理論上 UR≥3 的舊陣容已被 _lxpsPurgeOverURPresets 在載入時清掉,這裡是清理漏網時的最後一道。 */
    try{
      var _urAdvP = window._lxpsAdvURCheck(pt.heroes);
      if(_urAdvP && _urAdvP.over){
        _showInGameToast('⛔ 這個陣容有 ' + _urAdvP.n + ' 名 UR 英雄(' + _urAdvP.names.join('、') + ')\n\n冒險隊伍最多只能帶 ' + _urAdvP.max + ' 名 UR,請重新編組。', '#ff4444', 5500);
        try{ playSfx('sfx-cancel', 0.7); }catch(_){}
        try{ console.warn('[冒險 UR 上限] 預設陣容超標,已擋下:', _urAdvP.names); }catch(_){}
        return;
      }
    }catch(_eUrPt){ console.warn('[冒險 UR 上限] 預設陣容檢查失敗(保守放行):', _eUrPt); }
  }

  // ★★ v5.91.0（老師 2026-08-20 回報「有人用 UR 角色打鬥技場」）— 鬥技場路徑補上 UR 守門 ★★
  //   【漏口】上方那整段合法性檢查包在 if(isAdvMode) 裡 → 鬥技場模式一行都不檢查。
  //           而鬥技場預設陣容 _arenaPresetTeams 與冒險的 _advPresetTeams 是**各自獨立的兩份**，
  //           v3.13.71 立下「UR 禁用於鬥技場」之前存的舊陣容至今仍留在雲端 arenaPresetTeams，
  //           玩家只要在鬥技場主頁一鍵套用那筆舊陣容，就完全繞過英雄池的 UR 過濾直接帶 UR 上場。
  //   【修法】非冒險模式（＝鬥技場）改為必檢 UR，違規整筆拒絕套用並明確告知是哪幾隻。
  //   ⚠ 刻意「拒絕整筆」而不是「自動剔除違規者」：剔掉會變成 3 人上場打 4 人＝更不公平，
  //     且玩家不會發現隊伍被動過手腳；直接擋下並要求重新編組才是可預期的行為。
  //   ⚠ 只擋 UR，不順手加其他黑名單：BOSS／日本菁英／活動限定在選英雄池與 arena.js
  //     _arenaIsTeamValid 已有守門，這裡多加一層會改變既有可套用範圍（超出老師本輪指示）。
  if(!isAdvMode){
    try{
      var _urBad = (typeof window._arenaListBannedUR === 'function')
        ? window._arenaListBannedUR(pt.heroes) : [];
      if(_urBad.length){
        _showInGameToast(
          '⛔ 鬥技場不能使用 UR 英雄：' + _urBad.join('、') + '\n\n這是為了維持比賽公平，請改用其他英雄重新編組。',
          '#ff4444', 5000
        );
        try{ playSfx('sfx-cancel', 0.7); }catch(_){}
        try{ console.warn('[鬥技場 UR 守門] 預設陣容含 UR，已擋下：', _urBad); }catch(_){}
        return;
      }
    }catch(_eArUr){ console.warn('[鬥技場 UR 守門] 預設陣容檢查失敗:', _eArUr); }
  }


  // 關閉英雄選擇頁
  const hpo = document.getElementById('hero-pick-overlay');
  if(hpo) hpo.style.display='none';

  // 建立 G.p1
  G.p1 = pt.heroes.map((name, i)=>{
    const h = newHero(name, 'p1', i);
    // 套用元素
    if(pt.elements[i]){
      h.element = pt.elements[i];
      if(typeof applyElemBonus==='function') applyElemBonus(h);
    }
    return h;
  });

  // ★ 冒險模式：套用素質投資、技能等級、爆發等級（與 confirmHeroPick 相同邏輯）
  if(isAdvMode){
    G.p1.forEach(h => {
      const _inv = (_heroStatInvested && _heroStatInvested[h.name]) || {};
      if(_inv.hp)  { h.hp  += _inv.hp;  h.curHp = h.hp; }
      if(_inv.atk) { h.atk += _inv.atk; }
      if(_inv.sp)  { h.sp  += _inv.sp;  }
      if(_inv.spd) { h.spd += _inv.spd; }
      // ★ 冒險模式：等級每級 +2% HP
      try{ _applyAdvLevelHpBonus(h); }catch(_){}
      h._skLv = (_heroSkillLevels && _heroSkillLevels[h.name])
        ? { s1: (_heroSkillLevels[h.name].s1 || 0), s2: (_heroSkillLevels[h.name].s2 || 0) }
        : { s1: 0, s2: 0 };
      h._burstLvAdv = (_heroBurstLevels && _heroBurstLevels[h.name]) || 0;
    });
    // ★ v4.33.0(任務1·甲)— 套用冒險預設陣容時,還原「存檔當時各英雄攜帶的跟隨寵物」。
    //   跟隨寵物是「每英雄全域一隻」,套用即把全域跟隨槽寫回此陣容的寵物組合;
    //   寵物已不在馴養名單(退養/未擁有)則靜默略過,不影響英雄本身套用。戰前 _applyFollowPetToHero 會據此上寵物。
    try{
      if(pt.pets && Array.isArray(pt.pets) && typeof window._petSetFollow === 'function'){
        pt.heroes.forEach(function(hn, i){
          var _pn = pt.pets[i];
          if(_pn && (typeof window._petIsTamed !== 'function' || window._petIsTamed(_pn))){
            try{ window._petSetFollow(_pn, hn); }catch(_ePsf){}
          }
        });
      }
    }catch(_ePresetPetApply){ console.warn('[預設陣容 還原寵物]', _ePresetPetApply); }
    // ════════════════════════════════════════════════════════════════════
    // ★★ v5.107.0(老師裁定「寵物、至寶、裝備的更換都要一起重新儲存」)— 還原至寶與裝備 ★★
    //   一個陣容 = 一套完整整備組合,套用即把四位隊員的至寶／裝備切回本陣容存的那一套。
    //   ⚠ 只動**本陣容這四位英雄**身上的至寶／裝備,其他英雄一律不碰。
    //   ⚠ 快照裡的至寶／裝備可能已被賣掉／送人／被 GM 收回 → 查無資料一律靜默略過
    //     (同 pets 的 `_petIsTamed` 守門口徑),絕不因此中斷整個套用流程。
    //   ⚠ `Array.isArray` 守門:舊存檔沒有這兩個欄位 → 整段跳過,行為與 v5.106.0 完全一致(零回歸)。
    //   ⚠ 至寶採「先卸這四位、再依快照低階寫回」:刻意**不走** `_equipTaiwanTreasureToHero`,
    //     那支帶自動卸舊／同槽衝突／槽位上限邏輯,而快照本來就是一組合法組合,
    //     走它反而可能連鎖卸掉不該卸的;低階寫回精準且冪等。
    //   ⚠ 裝備反過來**要走** `window._gearEquipToHero`:它負責同部位衝突、轉裝與 `at2` 時間戳,
    //     繞過去自己寫 `equippedTo` 會讓 `_gearRepairEquipped` 的「同部位只留最新一件」判錯。
    // ════════════════════════════════════════════════════════════════════
    try{
      if(Array.isArray(pt.treasures) && typeof _taiwanTreasureData !== 'undefined' && _taiwanTreasureData){
        var _teamSet = {};
        pt.heroes.forEach(function(hn){ if(hn) _teamSet[hn] = true; });
        // ① 先卸下本陣容四位身上現有的全部至寶
        Object.keys(_taiwanTreasureData).forEach(function(_tid){
          var _rec = _taiwanTreasureData[_tid];
          if(_rec && _rec.equippedTo && _teamSet[_rec.equippedTo]) _rec.equippedTo = null;
        });
        // ② 依快照逐位還原(該至寶若正裝在隊外英雄身上,先清掉:一個至寶不能同時裝兩人)
        pt.heroes.forEach(function(hn, i){
          if(!hn) return;
          var _ids = pt.treasures[i];
          if(!Array.isArray(_ids)) return;
          _ids.forEach(function(_tid){
            if(!_tid) return;
            var _rec = _taiwanTreasureData[_tid];
            if(!_rec) return;                                   // 已賣出/送人/被收回 → 略過
            if(typeof TAIWAN_TREASURES !== 'undefined' && !TAIWAN_TREASURES[_tid]) return;
            _rec.equippedTo = hn;
          });
        });
        try{ if(typeof _saveTaiwanTreasureData === 'function') _saveTaiwanTreasureData(); }catch(_){}
      }
    }catch(_ePresetTreApply){ console.warn('[預設陣容 還原至寶]', _ePresetTreApply); }
    try{
      if(Array.isArray(pt.gear) && typeof _gearGetHeroEquipped === 'function'
         && typeof window._gearEquipToHero === 'function' && typeof window._gearUnequip === 'function'){
        // ① 先卸下本陣容四位身上現有的全部裝備
        pt.heroes.forEach(function(hn){
          if(!hn) return;
          try{
            (_gearGetHeroEquipped(hn) || []).forEach(function(x){
              if(x && x.eqUid) window._gearUnequip(x.eqUid);
            });
          }catch(_){}
        });
        // ② 依快照逐位還原(走既有 API,同部位衝突與轉裝交給它處理)
        pt.heroes.forEach(function(hn, i){
          if(!hn) return;
          var _ids = pt.gear[i];
          if(!Array.isArray(_ids)) return;
          _ids.forEach(function(_uid){
            if(!_uid) return;
            try{ window._gearEquipToHero(_uid, hn); }catch(_){}   // 實例不存在時該支自己回 false,不拋
          });
        });
        try{ if(typeof _gearRepairEquipped === 'function') _gearRepairEquipped(); }catch(_){}
      }
    }catch(_ePresetGearApply){ console.warn('[預設陣容 還原裝備]', _ePresetGearApply); }
    // ════════════════════════════════════════════════════════════════════
    // ★★ v5.74.0(老師 2026-08-18 回報·裁定丙)— 本路徑漏套「至寶 + 裝備 + 跟隨寵物」根治
    //   【症狀】老師回報大天狗圖鑑特技 96、進戰鬥只剩 43(= 基礎 15 + 投資/膠囊,
    //           缺少的 53 正是至寶 + 裝備 + 寵物)。
    //   【根因】本函式只套了「投資 / 等級HP / 膠囊 / 技能等級 / 爆發等級」,
    //           三大養成系統一個都沒套;上方 v4.33.0 註解寫的「戰前 _applyFollowPetToHero
    //           會據此上寵物」是**錯的假設** —— advStartBattle / startBattle 都沒有補套點。
    //   【位置】必須排在上方 _petSetFollow 還原跟隨槽「之後」,否則 helper 讀到的跟隨槽是舊的。
    //   【冪等】helper 內建 h._battlePrepApplied 旗標;本路徑與 confirmHeroPick 互斥,不會雙套。
    // ════════════════════════════════════════════════════════════════════
    try{
      G.p1.forEach(function(h){
        try{ if(typeof window._applyBattlePrepToHero === 'function') window._applyBattlePrepToHero(h, '_applyPresetTeam'); }
        catch(_eOneBp){ console.warn('[預設陣容 戰前養成套用] 單隻失敗', h && h.name, _eOneBp); }
      });
    }catch(_ePresetBattlePrep){ console.warn('[預設陣容 戰前養成套用]', _ePresetBattlePrep); }
  }

  // 套用技能替換
  G.p1.forEach((h, i)=>{
    const sk = pt.skills[i];
    if(sk && sk.slot && sk.skillName){
      try{ if(sk.skillName === '兵貫神速之計') sk.skillName = '兵貴神速之計'; }catch(_eSkFix){}   // 🔧 v5.263.0 錯字更正:舊存的預設陣容仍是「兵貫」⇒ 讀入時轉成新名稱
      // 從 NEW_SKILLS_DB 找技能資料
      const skillData = (typeof NEW_SKILLS_DB!=='undefined') ? NEW_SKILLS_DB.find(s=>s.n===sk.skillName) : null;
      if(skillData){
        h[sk.slot] = {...skillData};
        log(`[${h.name}] 預設陣容技能替換：${sk.slot.toUpperCase()} → ${sk.skillName}`);
      }
    }
  });

  // 建立 p2（冒險模式固定；鬥技隨機）
  if(isAdvMode){
    document.getElementById('skill-replace-confirm').style.display = 'none';
    document.getElementById('skill-replace-confirm-adv').style.display = '';
    // ★ 依玩家選擇的 BOSS variant 切換陣容（預設陣容路徑也要支援換路線）
    let _variant2 = null;
    try{
      const variants2 = (typeof ADV_BOSS_VARIANTS !== 'undefined' && ADV_BOSS_VARIANTS[_adventureStage]) || [];
      if(variants2.length){
        const idx2 = (window._advSelectedVariantIdx||0) % variants2.length;
        _variant2 = variants2[idx2];
      }
    }catch(_){}
    window._currentBossVariantInfo = _variant2;
    let bossTeam;
    if(_variant2 && _variant2.id === 'apricot'){
      bossTeam = (window._advApricotPreviewTeam && window._advApricotPreviewTeam.length)
        ? window._advApricotPreviewTeam
        : (typeof _buildApricotTeam === 'function' ? _buildApricotTeam() : ADV_BOSS_TEAMS[_adventureStage]);
    } else if(_variant2 && _variant2.id === 'darkorb'){
      // ★ v3.8.7(2026-05-26) — 木柵第三隻 BOSS:黑暗球‧希望型態(單獨陣容,無小怪)
      //   ★ ROOT CAUSE:之前漏掉這個分支 → _applyPresetTeam 走 fallback 到 ADV_BOSS_TEAMS.maokong
      //                 = 九尾空貓怪三角陣容 → BOSS 對白也跟著抓到九尾貓 → BGM 對但陣容/對白錯
      //                 記憶傳承 v48 鐵律 1.61 已記載,本版正式落地實際存檔
      bossTeam = [{ name:'黑暗球‧希望型態', element:'dark' }];
    } else if(_variant2 && _adventureStage === 'egypt' && typeof window._buildEgyptBossTeam === 'function'){
      bossTeam = window._buildEgyptBossTeam(_variant2);
    } else if(_variant2 && _adventureStage === 'japan' && typeof window._buildJapanBossTeam === 'function'){
      // ★ v1.0.20260421.0500 — 日本關依 variant 動態組陣容
      bossTeam = window._buildJapanBossTeam(_variant2);
    } else if(_variant2 && _adventureStage === 'china' && typeof window._buildChinaBossTeam === 'function'){
      // ★ v5.41.0 — 中國關 Phase 3:五路線依 variant 動態組陣容(鐵律 1.61 教訓:漏分支會 fallback 錯陣容+錯對白)
      bossTeam = window._buildChinaBossTeam(_variant2);
    } else if(_adventureStage === 'taiwan' && typeof window._buildTaiwanBossTeam === 'function'){
      // ★ v1.0.20260428.3810 — 台灣關依玩家在地圖上選的 BOSS 動態組陣容
      //   (台灣關沒有固定的 ADV_BOSS_TEAMS,要用 _buildTaiwanBossTeam(bossId))
      bossTeam = window._buildTaiwanBossTeam(window._advSelectedTaiwanBoss);
    } else {
      bossTeam = ADV_BOSS_TEAMS[_adventureStage];
    }
    // ★ v1.0.20260428.3810 — 防禦:bossTeam 還是空(極端情況)就拒絕套用,避免崩潰
    if(!bossTeam || !Array.isArray(bossTeam) || !bossTeam.length){
      console.error('[_applyPresetTeam] bossTeam 為空,stage=' + _adventureStage + ', 取消套用');
      _showInGameToast('⚠ 此關卡尚未支援快速套用陣容,請手動選角', '#ff8844', 3000);
      return;
    }
    G.p2 = bossTeam.map((b,i)=>{
      const h = newHero(b.name,'p2',i);
      h.element = b.element;
      if(typeof applyElemBonus==='function') applyElemBonus(h);
      // ★ 被魅惑的玩家英雄：套用玩家圖鑑中的素質/等級/技能/爆發升級
      if(b.charmedFromHero){
        const _src = b.charmedFromHero;
        h._displayName = '被魅惑的' + _src;
        h._isCharmedEnemy = true;
        const _inv = (typeof _heroStatInvested !== 'undefined' && _heroStatInvested[_src]) || {};
        if(_inv.hp) { h.hp += _inv.hp; h.curHp = h.hp; }
        if(_inv.atk) h.atk += _inv.atk;
        if(_inv.sp)  h.sp  += _inv.sp;
        if(_inv.spd) h.spd += _inv.spd;
        const _lv = (typeof _heroLevels !== 'undefined' && _heroLevels[_src]) || 1;
        if(_lv > 1){
          const _bonusPct = (_lv - 1) * 0.02;
          const _bonusHp = Math.round(h.hp * _bonusPct);
          h.hp += _bonusHp;
          h.curHp = h.hp;
        }
        h._skLv = (typeof _heroSkillLevels !== 'undefined' && _heroSkillLevels[_src])
          ? { s1: (_heroSkillLevels[_src].s1||0), s2: (_heroSkillLevels[_src].s2||0) }
          : { s1:0, s2:0 };
        h._burstLvAdv = (typeof _heroBurstLevels !== 'undefined' && _heroBurstLevels[_src]) || 0;
      }
      // ★ v1.0.20260420.3200 — HP 難度倍率改在 advStartMiniBattle 套用,同 confirmHeroPick 說明
      return h;
    });
    _showInGameToast(`✅ 套用陣容「${pt.name||'預設陣容'}」！`, '#cc99ff', 2000);
    // 直接進過場演出（跳過元素選擇和技能替換）
    fadeTransition(()=>{
      // ★ v5.84.0(P2 丙)— 進第一個場景劇情前，先跑「整備遮罩」把該關場景圖/BGM/我方爆發影片備妥
      //   (清單全命中快取 → 不顯示遮罩直接進場;點一下遮罩或 25 秒硬上限一律放行,絕不卡關)
      try{
        if(typeof window._lxpsAdvPrepGate === 'function'){
          window._lxpsAdvPrepGate(_adventureStage, function(){
            try{ advStartCutscene(_adventureStage); }catch(e){ console.error(e); advStartBattle(); }
          });
        } else {
          advStartCutscene(_adventureStage);
        }
      }catch(e){ console.error(e); advStartBattle(); }
    }, 400);
  } else {
    // 鬥技模式:建立隨機 p2
    // ★ v3.13.27(2026-06-03) — 三層黑名單(BUG #1 鬥技場敵方陣容):排除 BOSS / 日本菁英 / 活動限定,
    //   日本三妖怪英雄版白名單放行
    const _heroDb = (typeof HERO_DB !== 'undefined') ? HERO_DB : {};
    const _bossSetA = new Set(typeof BOSS_NAMES !== 'undefined' ? BOSS_NAMES : []);
    const _jpArenaA = (typeof JAPAN_ARENA_EXCLUDE !== 'undefined' && JAPAN_ARENA_EXCLUDE instanceof Set)
      ? JAPAN_ARENA_EXCLUDE : new Set();
    const _evtOnlyA = (typeof EVENT_ONLY_HEROES !== 'undefined' && EVENT_ONLY_HEROES instanceof Set)
      ? EVENT_ONLY_HEROES : new Set();
    const _jpBossWLA = (typeof JAPAN_BOSS_HEROES !== 'undefined' && JAPAN_BOSS_HEROES instanceof Set)
      ? JAPAN_BOSS_HEROES : new Set();
    const allHeroes = Object.keys(_heroDb).filter(n => {
      if(_jpBossWLA.has(n)) return true;
      if(_bossSetA.has(n))  return false;
      if(_jpArenaA.has(n))  return false;
      if(_evtOnlyA.has(n))  return false;
      return true;
    });
    const p1names = pt.heroes;
    const pool = allHeroes.filter(n=>!p1names.includes(n));
    const shuffled = pool.sort(()=>Math.random()-0.5).slice(0,4);
    G.p2 = shuffled.map((name,i)=>{
      const h = newHero(name,'p2',i);
      // 隨機元素
      const elems = ['fire','water','earth','wind','light','dark'];
      h.element = elems[Math.floor(Math.random()*elems.length)];
      if(typeof applyElemBonus==='function') applyElemBonus(h);
      return h;
    });
    // ★ v3.13.27(2026-06-03) — 進戰鬥前設鬥技場 context 旗標(否則 startTurn safety net hide adventure-overlay 條件不成立)
    try{ window._arenaBgmContext = true; }catch(_){}
    // ★ v3.13.27 — 場次 +1 由 startTurn 處理(同主流程)
    try{ window._arenaBattleStartPending = true; }catch(_){}
    _showInGameToast(`✅ 套用陣容「${pt.name||'預設陣容'}」!`, '#cc99ff', 2000);
    // 直接開始戰鬥(跳過技能替換處理,直接進入戰場初始化)
    fadeTransition(()=>{
      const _skipSro = document.getElementById('skill-replace-overlay');
      if(_skipSro) _skipSro.style.display = 'none';
      // ★ v3.13.27 — 也清掉關卡頁與選角頁(預設陣容路徑沒手動關它們)
      const _hpo2 = document.getElementById('hero-pick-overlay');
      if(_hpo2) _hpo2.style.display = 'none';
      const _advOvX = document.getElementById('adventure-overlay');
      if(_advOvX) _advOvX.style.display = 'none';
      // 初始化物品牌組
      var _initInv=[null,null,null];
      for(var _si=0;_si<3;_si++){
        var _drawn=drawItem(); var _tries=0;
        while(_drawn.type==='equip'&&_tries<10){ _drawn=drawItem(); _tries++; }
        if(_drawn.type!=='equip') _initInv[_si]=_drawn;
      }
      G.inv=_initInv;
      var _initInv2=[null,null,null];
      for(var _si2=0;_si2<3;_si2++){
        var _drawn2=drawItem(); var _tries2=0;
        while(_drawn2.type==='equip'&&_tries2<10){ _drawn2=drawItem(); _tries2++; }
        if(_drawn2.type!=='equip') _initInv2[_si2]=_drawn2;
      }
      G.inv2=_initInv2;
      G.p1.concat(G.p2).forEach(h=>{ h._initState={hp:h.hp,atk:h.atk,sp:h.sp,spd:h.spd}; });
      // ★ v3.13.27(2026-06-03) — 走鬥技場戰鬥 BGM 3 首輪播(鐵律 1.159),原本寫死 bgm-battle 是冒險戰鬥 BGM
      if(typeof bgmFadeTo==='function') try{ bgmFadeTo('bgm-arena-battle-list',800); }catch(_){}
      try{ playBattleStartSfx(); }catch(_){}
      try{ renderField(true); }catch(_){}
      try{ renderItems(); updateUI(); }catch(_){}
      if(typeof ctrlBattleToggle==='function') ctrlBattleToggle(true);
      (function(){ var bsOv=document.getElementById('battle-start-overlay');
        var bsTxt=document.querySelector('.bs-text');
        if(bsOv&&bsTxt){ bsOv.classList.add('show'); sndGong();
          flashScreen('rgba(255,200,30,1)',400);
          setTimeout(function(){ bsOv.classList.remove('show'); }, 3200); }
      })();
      log('═══ 戰鬥開始(預設陣容)═══');
      _pSetTimeout(startTurn, 600);
    }, 400);
  }
}

function _closePresetOv(id){
  var el=document.getElementById(id);
  if(el) el.remove();
  // ★ v3.5.49 — 若是「整裝完畢」流程中的儲存面板被取消,需繼續觸發出發 callback
  //   避免玩家點到取消後永遠無法進入戰鬥
  try{
    if((id === 'preset-save-panel' || id === 'preset-name-input') && typeof window._pendingAfterPresetSave === 'function'){
      // 還有沒收掉的 preset-name-input?若 preset-save-panel 取消,name-input 不會存在,反之亦然
      // 但保險起見都檢查一下
      var _other = (id === 'preset-save-panel') ? document.getElementById('preset-name-input') : document.getElementById('preset-save-panel');
      if(_other) return; // 若另一個還在,不處理(由它接手)
      var _cb = window._pendingAfterPresetSave;
      window._pendingAfterPresetSave = null;
      setTimeout(()=>{ try{ _cb(); }catch(e){ console.warn('[v3.5.49 取消儲存後繼續]',e); } }, 200);
    }
  }catch(_){}
}


// ════════════════════════════════════════════════════════════════
// ★ v5.36.0(2026-08-14·老師需求1)— 英雄圖鑑「📋 預設陣容」編輯器
//   入口:英雄圖鑑標題列「返回」與「主角造型」之間(#hero-preset-edit-btn)。
//   資料:直接編輯 _advPresetTeams(冒險模式常用預設陣容),與英雄選擇頁
//   「常用預設陣容」面板同一份資料 → 儲存即同步,套用流程(_applyPresetTeam)零改動。
//   ★ 刻意寫死 _advPresetTeams 不走 _getCurrentPresetTeams:圖鑑可在 _adventureStage=null
//     情境開啟,模式判定會誤指鬥技場陣列(鐵律1.203 同病),此編輯器語意=冒險常用陣容。
//   互動(老師裁定):①直接點隊員槽 → 開英雄選擇器替換該槽英雄(即點即存)
//                   ②每位隊員「📖 圖鑑整備」→ 直接開該英雄圖鑑詳情頁換至寶/裝備/寵物/投資,
//                     關閉後自動回到編輯器(圖層位階比照冒險編組 v3.11.30/v3.12.0 圖鑑整備:
//                     此處編輯器掛 body 直系(常態 z=9990 低於 toast 9999·圖鑑整備 detach 態才動態升 10600),整備期間改「隱藏編輯器」
//                     讓下方圖鑑詳情自然浮現,回流分支還原 → 零 stacking context 手術、行為等價)
//   可選英雄池 = 初始8隻(ADV_HERO_POOL.maokong)∪ advGetUnlockedHeroes()(含主角),
//   與 _applyPresetTeam 冒險合法性檢查同口徑 → 編出的陣容保證可套用。
//   替換英雄時:該槽元素/替換技能重設為「不指定」(進戰鬥再選·零風險),其餘槽原值保留;
//   跟隨寵物依 _petFollowOf 全隊重新快照(與 _confirmSavePreset v4.33.0 同款)。
//   純資料層寫入僅 _advPresetTeams + gameCloudSave()(advPresetTeams 整包陣列上雲·無深合併幻影)。
// ════════════════════════════════════════════════════════════════
function _peT(c, p){ return (typeof _artStyle !== 'undefined' && _artStyle === 'cute') ? c : p; }
// 建立中草稿(尚未存檔的新陣容·記憶體暫存;關閉編輯器即棄置)
window._peDrafts = window._peDrafts || {};

function _peHeroPool(){
  var pool = [];
  var seen = {};
  var add = function(n){
    if(!n || seen[n]) return;
    try{ if(typeof HERO_DB === 'undefined' || !HERO_DB[n]) return; }catch(_){ return; }
    seen[n] = 1; pool.push(n);
  };
  try{ ((typeof ADV_HERO_POOL !== 'undefined' && ADV_HERO_POOL.maokong) || []).forEach(add); }catch(_){}
  try{ ((typeof advGetUnlockedHeroes === 'function' && advGetUnlockedHeroes()) || []).forEach(add); }catch(_){}
  return pool;
}

function openPresetEditorPanel(){
  var existing = document.getElementById('preset-editor-panel');
  if(existing){ existing.remove(); try{ window._peReturnToEditor = null; }catch(_){} return; }
  try{ window._peReturnToEditor = null; }catch(_){}
  // ★ z-index 動態:常態 9990(低於 _showInGameToast 的 9999 → 換人/命名/刪除 toast 可見;
  //   body 直系任意正 z 天生蓋過 adventure-overlay z510 stacking context 內的圖鑑 10000/詳情 10500);
  //   僅當圖鑑正處於「編組/WB 整備 detach 到 body」狀態(hero-page-overlay 父節點=body·真 z10000 生效)
  //   才升 10600 蓋過它(此罕見巢狀流程 toast 暫被蓋·可接受)。
  var _peZ = 9990;
  try{
    var _hpZ = document.getElementById('hero-page-overlay');
    if(_hpZ && _hpZ.parentNode === document.body) _peZ = 10600;
  }catch(_){}
  window._peZBase = _peZ;
  var ov = document.createElement('div');
  ov.id = 'preset-editor-panel';
  ov.style.cssText = 'position:fixed;inset:0;z-index:' + _peZ + ';background:rgba(0,0,0,0.9);display:flex;align-items:flex-start;justify-content:center;padding:24px;overflow-y:auto;-webkit-overflow-scrolling:touch;overscroll-behavior:contain;touch-action:pan-y;font-family:"M PLUS Rounded 1c","Nunito",sans-serif;';
  document.documentElement.style.touchAction = 'pan-y';
  document.body.style.touchAction = 'pan-y';
  ov.addEventListener('click', function(e){
    if(e.target === ov){ _peClose(); }
  });
  document.body.appendChild(ov);
  _peRender();
}
function _peClose(){
  var ov = document.getElementById('preset-editor-panel');
  if(ov) ov.remove();
  try{ window._peReturnToEditor = null; }catch(_){}
  try{ window._peDrafts = {}; }catch(_){}
  document.documentElement.style.touchAction = '';
  document.body.style.touchAction = '';
}

function _peMemberCellHtml(slotIdx, memIdx, name, elem, sk, isDraft){
  var _empty = !name;
  var _img = _empty ? '' : _presetHeroImgUrl(name);
  var _oPos = (!_empty && typeof getHeroObjPos === 'function') ? getHeroObjPos(name) : 'center 20%';
  var _lv = (!_empty && typeof getHeroLevel === 'function') ? getHeroLevel(name) : 0;
  var _dispName = _empty ? '' : ((typeof window._heroDisplayName === 'function') ? window._heroDisplayName(name) : name);
  var _skLabel = '';
  if(!_empty){
    _skLabel = (sk && sk.skillName) ? ('🔄' + (sk.slot ? sk.slot.toUpperCase() : '') + ': ' + sk.skillName) : _peT('(進戰鬥再選技能)', '(不替換)');
  }
  var _petHtml = '';
  if(!_empty){
    try{
      var _petName = (typeof window._petFollowOf === 'function') ? (window._petFollowOf(name) || '') : '';
      if(_petName){
        var _petImg = (typeof window._petNobgUrl === 'function') ? window._petNobgUrl(_petName) : '';
        _petHtml = '<div style="display:flex;align-items:center;gap:4px;">'
          + (_petImg ? ('<img src="' + _petImg + '" style="width:24px;height:24px;object-fit:contain;" onerror="this.style.display=\'none\'">') : '<span style="font-size:16px;">🐾</span>')
          + '<span style="font-size:14px;color:#ffcf6e;font-weight:700;">' + _petName + '</span></div>';
      }
    }catch(_){}
  }
  var _cellInner = _empty
    ? '<div style="width:100%;height:120px;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#8866cc;font-size:44px;">＋<div style="font-size:16px;color:#7755aa;">' + _peT('點我選英雄', '點擊選擇英雄') + '</div></div>'
    : ('<div style="width:100%;height:120px;border-radius:9px;overflow:hidden;background:#0a0818;">'
        + (_img ? ('<div style="width:100%;height:100%;background:url(\'' + _img + '\') ' + _oPos + '/cover;"></div>')
                : ('<div style="width:100%;height:100%;display:flex;align-items:center;justify-content:center;font-size:44px;">' + ((typeof AVATARS !== 'undefined' && AVATARS[name]) || '⚔') + '</div>'))
      + '</div>');
  return '<div style="display:flex;flex-direction:column;align-items:center;gap:5px;width:170px;">'
    + '<div onclick="event.stopPropagation();_peOpenHeroPicker(' + slotIdx + ',' + memIdx + ',' + (isDraft ? 'true' : 'false') + ')" title="' + _peT('點一下換英雄', '點擊替換此槽英雄') + '"'
    + ' style="width:170px;cursor:pointer;border:2px solid ' + (_empty ? 'rgba(150,100,255,0.35)' : 'rgba(200,150,255,0.55)') + ';border-radius:11px;padding:4px;background:rgba(20,12,44,0.85);transition:border-color 0.15s;"'
    + ' onmouseover="this.style.borderColor=\'rgba(230,180,255,0.95)\'" onmouseout="this.style.borderColor=\'' + (_empty ? 'rgba(150,100,255,0.35)' : 'rgba(200,150,255,0.55)') + '\'">'
    + _cellInner
    + (_empty ? '' : ('<div style="font-size:17px;font-weight:800;color:#eee;text-align:center;margin-top:4px;">' + _dispName + (_lv > 0 ? (' <span style="color:#88ccff;font-size:14px;">Lv' + _lv + '</span>') : '') + '</div>'
        + '<div style="font-size:14px;color:#88aaff;text-align:center;">' + (elem ? _presetElemLabel(elem) : '') + '</div>'
        + '<div style="font-size:13px;color:#cc99ff;text-align:center;word-break:break-all;">' + _skLabel + '</div>'))
    + '</div>'
    + (_empty ? '' : ('<button onclick="event.stopPropagation();_peOpenCodex(' + slotIdx + ',\'' + String(name).replace(/'/g, "\\'") + '\')" title="打開英雄圖鑑進行至寶、裝備、寵物與能力整備,關閉後直接回到編輯器"'
        + ' style="padding:5px 12px;font-size:17px;font-weight:700;font-family:inherit;background:linear-gradient(135deg,rgba(60,40,0,0.9),rgba(40,30,0,0.85));border:2px solid rgba(212,168,67,0.7);color:#ffe8a0;border-radius:9px;cursor:pointer;letter-spacing:1px;box-shadow:0 0 8px rgba(212,168,67,0.3);">📖 圖鑑整備</button>'))
    + _petHtml
    + '</div>';
}

function _peRender(){
  var ov = document.getElementById('preset-editor-panel');
  if(!ov) return;
  var box = document.getElementById('preset-editor-box');
  if(!box){
    box = document.createElement('div');
    box.id = 'preset-editor-box';
    box.style.cssText = 'background:linear-gradient(160deg,#0d0a1e,#08061a);border:2.5px solid rgba(180,120,255,0.7);border-radius:20px;padding:26px 30px;max-width:1000px;width:100%;box-shadow:0 0 50px rgba(150,80,255,0.35);margin:auto 0;';
    ov.appendChild(box);
  }
  var html = '<div style="font-size:32px;font-weight:900;color:#cc99ff;margin-bottom:4px;text-align:center;">' + _peT('📋 我的常用隊伍', '📋 預設陣容編輯') + '</div>';
  html += '<div style="font-size:18px;color:#9988bb;text-align:center;margin-bottom:14px;line-height:1.6;">'
    + _peT('點隊員格子就能換英雄;按「📖 圖鑑整備」幫他換至寶、裝備、寵物!排好的隊伍打關卡時可以一鍵套用喔!',
           '點擊隊員槽即可替換英雄;「📖 圖鑑整備」可直接開啟該英雄圖鑑頁更換至寶、裝備、寵物與投資能力。此處與英雄選擇頁「常用預設陣容」即時同步,可於選關時一鍵套用。')
    + '</div>';
  html += '<div style="display:flex;flex-direction:column;gap:14px;">';
  for(var i = 0; i < 5; i++){
    var pt = _advPresetTeams[i];
    var draft = window._peDrafts[i] || null;
    if(!pt && !draft){
      html += '<div onclick="_peStartDraft(' + i + ')" style="padding:16px 18px;background:rgba(20,15,30,0.6);border:1.5px dashed rgba(150,100,255,0.4);border-radius:12px;color:#9977dd;font-size:22px;text-align:center;cursor:pointer;" '
        + 'onmouseover="this.style.borderColor=\'rgba(200,150,255,0.8)\'" onmouseout="this.style.borderColor=\'rgba(150,100,255,0.4)\'">'
        + '欄位' + (i + 1) + '(空)　➕ ' + _peT('排一隊新隊伍!', '建立新陣容') + '</div>';
      continue;
    }
    var isDraft = !pt;
    var src = pt || draft;
    var slotName = src.name || ('陣容' + (i + 1));
    var heroes = src.heroes;
    html += '<div style="padding:14px 18px;background:rgba(40,25,80,0.7);border:2px solid ' + (isDraft ? 'rgba(255,200,100,0.55)' : 'rgba(180,120,255,0.5)') + ';border-radius:14px;">'
      + '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px;flex-wrap:wrap;gap:8px;">'
      + '<div style="font-size:24px;font-weight:900;color:' + (isDraft ? '#ffcc66' : '#cc99ff') + ';">欄位' + (i + 1) + ':' + slotName
      + (isDraft ? ('<span style="font-size:16px;color:#ffaa66;margin-left:10px;">' + _peT('(選滿 4 位就會儲存)', '(建立中·選滿 4 位英雄後自動儲存)') + '</span>') : '') + '</div>'
      + '<div style="display:flex;gap:8px;">'
      + (isDraft
          ? ('<button onclick="event.stopPropagation();_peCancelDraft(' + i + ')" style="padding:4px 14px;font-size:16px;background:rgba(60,10,10,0.4);border:1.5px solid #e84040;color:#e84040;border-radius:7px;cursor:pointer;font-family:inherit;">✕ ' + _peT('不排了', '取消建立') + '</button>')
          : ('<button onclick="event.stopPropagation();_peRenameSlot(' + i + ')" style="padding:4px 14px;font-size:16px;background:rgba(30,50,90,0.5);border:1.5px solid rgba(120,180,255,0.6);color:#aaddff;border-radius:7px;cursor:pointer;font-family:inherit;">📝 命名</button>'
            + '<button onclick="event.stopPropagation();_peDeleteSlot(' + i + ')" style="padding:4px 14px;font-size:16px;background:rgba(60,10,10,0.4);border:1.5px solid #e84040;color:#e84040;border-radius:7px;cursor:pointer;font-family:inherit;">🗑 刪除</button>'))
      + '</div></div>'
      + '<div style="display:flex;gap:12px;flex-wrap:wrap;">';
    for(var m = 0; m < 4; m++){
      var hn = heroes[m] || null;
      var el = (src.elements && src.elements[m]) || '';
      var sk = (src.skills && src.skills[m]) || null;
      html += _peMemberCellHtml(i, m, hn, el, sk, isDraft);
    }
    html += '</div></div>';
  }
  html += '</div>';
  html += '<div style="text-align:center;margin-top:18px;"><button onclick="_peClose()" style="padding:10px 32px;font-size:22px;background:rgba(60,10,10,0.4);border:2px solid #e84040;color:#e84040;border-radius:10px;cursor:pointer;font-family:inherit;">✕ 關閉</button></div>';
  box.innerHTML = html;
}

function _peStartDraft(slotIdx){
  try{ playSfx('sfx-sel', 0.5); }catch(_){}
  window._peDrafts[slotIdx] = { name: '陣容' + (slotIdx + 1), heroes: [null, null, null, null], elements: ['', '', '', ''], skills: [null, null, null, null] };
  _peRender();
}
function _peCancelDraft(slotIdx){
  try{ playSfx('sfx-cancel', 0.4); }catch(_){}
  delete window._peDrafts[slotIdx];
  _peRender();
}

// 英雄選擇器(單槽替換)— z=10650 蓋過編輯器 10600
function _peOpenHeroPicker(slotIdx, memIdx, isDraft){
  try{ playSfx('sfx-sel', 0.5); }catch(_){}
  var old = document.getElementById('preset-editor-pick');
  if(old) old.remove();
  var src = isDraft ? window._peDrafts[slotIdx] : _advPresetTeams[slotIdx];
  if(!src) return;
  var used = {};
  (src.heroes || []).forEach(function(n, j){ if(n && j !== memIdx) used[n] = 1; });
  var pool = _peHeroPool().filter(function(n){ return !used[n]; });
  var pk = document.createElement('div');
  pk.id = 'preset-editor-pick';
  pk.style.cssText = 'position:fixed;inset:0;z-index:' + ((window._peZBase || 9990) + 20) + ';background:rgba(0,0,0,0.9);display:flex;align-items:flex-start;justify-content:center;padding:24px;overflow-y:auto;-webkit-overflow-scrolling:touch;overscroll-behavior:contain;touch-action:pan-y;font-family:"M PLUS Rounded 1c","Nunito",sans-serif;';
  pk.addEventListener('click', function(e){ if(e.target === pk) pk.remove(); });
  var html = '<div style="background:linear-gradient(160deg,#0d0a1e,#08061a);border:2.5px solid rgba(180,120,255,0.7);border-radius:20px;padding:24px 28px;max-width:1000px;width:100%;box-shadow:0 0 50px rgba(150,80,255,0.35);margin:auto 0;">'
    + '<div style="font-size:28px;font-weight:900;color:#cc99ff;margin-bottom:6px;text-align:center;">' + _peT('選一位英雄放進第 ' + (memIdx + 1) + ' 格', '選擇英雄(第 ' + (memIdx + 1) + ' 槽)') + '</div>'
    + '<div style="font-size:16px;color:#9988bb;text-align:center;margin-bottom:14px;">' + _peT('同一隊裡的英雄不會重複出現喔', '已在此陣容其他槽位的英雄不列出') + '</div>'
    + '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:12px;">';
  pool.forEach(function(n){
    var _img = _presetHeroImgUrl(n);
    var _oPos = (typeof getHeroObjPos === 'function') ? getHeroObjPos(n) : 'center 20%';
    var _lv = (typeof getHeroLevel === 'function') ? getHeroLevel(n) : 0;
    var _dispName = (typeof window._heroDisplayName === 'function') ? window._heroDisplayName(n) : n;
    var _isCur = (src.heroes && src.heroes[memIdx] === n);
    html += '<div onclick="_pePickHero(' + slotIdx + ',' + memIdx + ',' + (isDraft ? 'true' : 'false') + ',\'' + String(n).replace(/'/g, "\\'") + '\')"'
      + ' style="cursor:pointer;border:2px solid ' + (_isCur ? 'rgba(120,255,160,0.9)' : 'rgba(150,110,220,0.45)') + ';border-radius:11px;padding:5px;background:rgba(20,12,44,0.85);transition:border-color 0.15s;"'
      + ' onmouseover="this.style.borderColor=\'rgba(230,180,255,0.95)\'" onmouseout="this.style.borderColor=\'' + (_isCur ? 'rgba(120,255,160,0.9)' : 'rgba(150,110,220,0.45)') + '\'">'
      + '<div style="width:100%;height:110px;border-radius:8px;overflow:hidden;background:#0a0818;">'
      + (_img ? ('<div style="width:100%;height:100%;background:url(\'' + _img + '\') ' + _oPos + '/cover;"></div>')
              : ('<div style="width:100%;height:100%;display:flex;align-items:center;justify-content:center;font-size:40px;">' + ((typeof AVATARS !== 'undefined' && AVATARS[n]) || '⚔') + '</div>'))
      + '</div>'
      + '<div style="font-size:16px;font-weight:800;color:#eee;text-align:center;margin-top:5px;">' + _dispName + (_lv > 0 ? (' <span style="color:#88ccff;font-size:13px;">Lv' + _lv + '</span>') : '') + (_isCur ? ' <span style="color:#88ffaa;font-size:13px;">✓目前</span>' : '') + '</div>'
      + '</div>';
  });
  html += '</div>'
    + '<div style="text-align:center;margin-top:16px;"><button onclick="document.getElementById(\'preset-editor-pick\').remove()" style="padding:9px 30px;font-size:20px;background:rgba(60,10,10,0.4);border:2px solid #e84040;color:#e84040;border-radius:10px;cursor:pointer;font-family:inherit;">✕ 取消</button></div>'
    + '</div>';
  pk.innerHTML = html;
  document.body.appendChild(pk);
}

function _pePickHero(slotIdx, memIdx, isDraft, name){
  var pk = document.getElementById('preset-editor-pick');
  if(pk) pk.remove();
  try{ playSfx('sfx-confirm', 0.5); }catch(_){}
  if(isDraft){
    var d = window._peDrafts[slotIdx];
    if(!d) return;
    d.heroes[memIdx] = name;
    d.elements[memIdx] = '';
    d.skills[memIdx] = { slot: null, skillName: null };
    var _filled = d.heroes.filter(Boolean).length;
    if(_filled >= 4){
      // 選滿 4 位 → 命名後正式存入 _advPresetTeams
      _peAskName(slotIdx, d.name, function(newName){
        d.name = newName;
        _peCommitSlot(slotIdx, d);
        delete window._peDrafts[slotIdx];
        _showInGameToast(_peT('✅ 隊伍「' + newName + '」排好囉!打關卡時可以一鍵套用!', '✅ 陣容「' + newName + '」已儲存到欄位' + (slotIdx + 1) + '!'), '#cc99ff', 2500);
        try{ playSfx('sfx-powerup', 0.7); }catch(_){}
        _peRender();
      });
      return;
    }
    _peRender();
    return;
  }
  // 既有陣容:即點即存(該槽元素/技能重設,其餘槽保留)
  if(!window._btnCooldown('preset_editor_swap', 800)) return;
  var pt = _advPresetTeams[slotIdx];
  if(!pt) return;
  if(pt.heroes[memIdx] === name){ _peRender(); return; }
  pt.heroes[memIdx] = name;
  if(!Array.isArray(pt.elements)) pt.elements = ['', '', '', ''];
  if(!Array.isArray(pt.skills)) pt.skills = [null, null, null, null];
  pt.elements[memIdx] = '';
  pt.skills[memIdx] = { slot: null, skillName: null };
  _peCommitSlot(slotIdx, pt);
  _showInGameToast(_peT('✅ 換好了!第 ' + (memIdx + 1) + ' 格現在是「' + name + '」', '✅ 欄位' + (slotIdx + 1) + ' 第 ' + (memIdx + 1) + ' 槽已替換為「' + name + '」'), '#cc99ff', 2000);
  _peRender();
}

// 寫入 _advPresetTeams + 整備三項快照 + 雲端存檔(單一寫入點)
function _peCommitSlot(slotIdx, pt){
  // ★★ v5.108.0 — 本編輯器是第三條寫入路徑(老師本輪只提到技能替換頁,這條一併補齊)★★
  //   舊版只寫 pets ⇒ 從編輯器存的陣容套用時至寶／裝備不會還原,與另兩條路徑口徑不一致。
  //   ★ 走 `window._lxpsPresetPrepSnapshot` 單一真相;本編輯器只操作 `_advPresetTeams`
  //     (v5.36.0 刻意不走 _getCurrentPresetTeams·鐵律 1.203)⇒ 一律以「冒險」口徑取快照。
  //   (原 v5.36.0 版本保留備查:
  //     if(typeof window._petFollowOf === 'function')
  //       pt.pets = pt.heroes.map(function(hn){ return hn ? (window._petFollowOf(hn) || null) : null; });  )
  try{
    var _prep = (typeof window._lxpsPresetPrepSnapshot === 'function')
      ? window._lxpsPresetPrepSnapshot(pt.heroes, false) : null;
    if(_prep){
      pt.pets      = _prep.pets;
      pt.treasures = _prep.treasures;
      pt.gear      = _prep.gear;
    }
  }catch(_ePet){ console.warn('[預設陣容編輯器 整備快照]', _ePet); }
  _advPresetTeams[slotIdx] = pt;
  try{ gameCloudSave(); }catch(_eSave){ console.warn('[預設陣容編輯器 存檔]', _eSave); }
}

// 命名輸入(沿用冒險自由輸入 10 字·確定後走 cb)
function _peAskName(slotIdx, defaultName, cb){
  var old = document.getElementById('preset-editor-name');
  if(old) old.remove();
  var nv = document.createElement('div');
  nv.id = 'preset-editor-name';
  nv.style.cssText = 'position:fixed;inset:0;z-index:' + ((window._peZBase || 9990) + 40) + ';background:rgba(0,0,0,0.88);display:flex;align-items:center;justify-content:center;font-family:"M PLUS Rounded 1c","Nunito",sans-serif;';
  nv._peNameCb = cb;
  nv.innerHTML = '<div style="background:linear-gradient(160deg,#0d0a1e,#08061a);border:2.5px solid rgba(180,120,255,0.7);border-radius:20px;padding:30px 38px;max-width:520px;width:90%;text-align:center;box-shadow:0 0 50px rgba(150,80,255,0.35);">'
    + '<div style="font-size:28px;font-weight:900;color:#cc99ff;margin-bottom:12px;">✏️ ' + _peT('幫這隊取個名字吧!', '輸入陣容名稱') + '</div>'
    + '<div style="font-size:18px;color:#aaa;margin-bottom:14px;">最多10個字元(中英文皆可)</div>'
    + '<input id="preset-editor-name-field" maxlength="10" placeholder="' + defaultName + '" value="' + defaultName + '"'
    + ' style="width:100%;padding:10px 16px;font-size:26px;font-weight:700;background:rgba(20,15,40,0.9);border:2px solid rgba(180,120,255,0.6);color:#ddc0ff;border-radius:10px;font-family:inherit;box-sizing:border-box;text-align:center;outline:none;">'
    + '<div style="display:flex;gap:12px;justify-content:center;margin-top:20px;">'
    + '<button onclick="_peConfirmName(' + slotIdx + ')" style="padding:12px 40px;font-size:24px;font-weight:800;background:rgba(100,60,200,0.35);border:2px solid #cc99ff;color:#cc99ff;border-radius:10px;cursor:pointer;font-family:inherit;">✔ 確定</button>'
    + '<button onclick="document.getElementById(\'preset-editor-name\').remove()" style="padding:12px 28px;font-size:22px;background:rgba(60,10,10,0.3);border:2px solid #e84040;color:#e84040;border-radius:10px;cursor:pointer;font-family:inherit;">✕ 取消</button>'
    + '</div></div>';
  document.body.appendChild(nv);
  setTimeout(function(){ var f = document.getElementById('preset-editor-name-field'); if(f){ try{ f.focus({ preventScroll: true }); }catch(_){ try{ f.focus(); }catch(_){} } try{ f.select(); }catch(_){} } }, 100);
}
function _peConfirmName(slotIdx){
  var nv = document.getElementById('preset-editor-name');
  if(!nv) return;
  var f = document.getElementById('preset-editor-name-field');
  var name = f ? (f.value.trim().slice(0, 10) || ('陣容' + (slotIdx + 1))) : ('陣容' + (slotIdx + 1));
  var cb = nv._peNameCb;
  nv.remove();
  if(typeof cb === 'function'){ try{ cb(name); }catch(_e){ console.warn('[預設陣容編輯器 命名]', _e); } }
}

function _peRenameSlot(slotIdx){
  if(!window._btnCooldown('preset_editor_rename', 800)) return;
  var pt = _advPresetTeams[slotIdx];
  if(!pt) return;
  _peAskName(slotIdx, pt.name || ('陣容' + (slotIdx + 1)), function(newName){
    pt.name = newName;
    _peCommitSlot(slotIdx, pt);
    _showInGameToast(_peT('✅ 改名成功!現在叫「' + newName + '」', '✅ 欄位' + (slotIdx + 1) + ' 已更名為「' + newName + '」'), '#aaddff', 2000);
    try{ playSfx('sfx-confirm', 0.6); }catch(_){}
    _peRender();
  });
}

function _peDeleteSlot(slotIdx){
  if(!window._btnCooldown('preset_delete', 2000)) return;   // 與 _deletePresetSlot 共用同鍵冷卻
  var _doDel = function(){
    _advPresetTeams[slotIdx] = null;
    try{ gameCloudSave(); }catch(_){}
    _showInGameToast('🗑 欄位' + (slotIdx + 1) + ' 已刪除', '#ff8888', 1500);
    _peRender();
  };
  try{
    if(typeof _customConfirm === 'function'){
      _customConfirm(_peT('確定要刪掉這一隊嗎?', '確定要刪除欄位' + (slotIdx + 1) + ' 的陣容嗎?'), _doDel);
      return;
    }
  }catch(_){}
  _doDel();
}

// 「📖 圖鑑整備」— 隱藏編輯器 → 直接開該英雄圖鑑詳情;closeHeroDetail/closeHeroPage 回流分支還原
function _peOpenCodex(slotIdx, name){
  try{ playSfx('sfx-confirm', 0.5); }catch(_){}
  window._peReturnToEditor = { slot: slotIdx, name: name };
  var ov = document.getElementById('preset-editor-panel');
  if(ov) ov.style.display = 'none';
  var pk = document.getElementById('preset-editor-pick');
  if(pk) pk.remove();
  // 圖鑑若未開(防禦:理論上編輯器只從圖鑑開啟)→ 先開圖鑑 grid
  try{
    var _hp = document.getElementById('hero-page-overlay');
    if(_hp && _hp.style.display === 'none'){ openHeroPage(); }
  }catch(_){}
  var _tryOpenPe = function(tries){
    var _grid = document.getElementById('hero-page-grid');
    if(_grid && _grid.querySelector('.hero-grid-card')){
      try{ openHeroDetail(name); }catch(_){}
    } else if(tries > 0){
      setTimeout(function(){ _tryOpenPe(tries - 1); }, 100);
    } else {
      try{ openHeroDetail(name); }catch(_){}
    }
  };
  setTimeout(function(){ _tryOpenPe(25); }, 80);
}
// 回流(closeHeroDetail / closeHeroPage 共用):重新顯示編輯器並刷新(等級/至寶/寵物變更立即反映)
function _peReturnFromCodex(){
  try{
    if(!window._peReturnToEditor) return false;
    window._peReturnToEditor = null;
    var ov = document.getElementById('preset-editor-panel');
    if(ov){
      ov.style.display = 'flex';
      _peRender();
      document.documentElement.style.touchAction = 'pan-y';
      document.body.style.touchAction = 'pan-y';
    }
    return true;
  }catch(_e){ console.warn('[預設陣容編輯器 圖鑑整備回流]', _e); return false; }
}
try{ window.openPresetEditorPanel = openPresetEditorPanel; }catch(_ePeW){}


// ═══════════════════════════════════════════════════════════
// ★ 技能升級等級系統
// ═══════════════════════════════════════════════════════════

// 目前正在執行技能的等級倍率（execSkill 開始時設定，endAction 重置）
let _activeSkLvMult = 1.0;
let _activeSkLv = 0;
let _playerAtkFlag = false; // ★ 玩家普攻旗標（用於天賦觸發）

// 取得技能升級倍率：每級 +10%
function _skLvBoost(heroName, slot) {
  if(!heroName || !slot || !_heroSkillLevels) return 1.0;
  const lv = (_heroSkillLevels[heroName]||{})[slot] || 0;
  return 1.0 + lv * 0.05;  // ★ 每級+5%（與 _activeSkLvMult 一致）
}

// 取得技能升級後的持續回合數（基礎 + 每 perLv 級+1回合）
function _skLvDur(baseDur, perLv=2) {
  return baseDur + Math.floor(_activeSkLv / perLv);
}

