  const inv = _heroStatInvested[name] || {hp:0,atk:0,sp:0,spd:0};
  const sk1Lv = (_heroSkillLevels[name]||{}).s1 || 0;
  const sk2Lv = (_heroSkillLevels[name]||{}).s2 || 0;
  /* ★ v5.8.0 老師需求3 — 主角繼承爆發時,詳情頁顯示來源英雄的爆發(const→let 以便替換) */
  let burst = typeof BURST_DB !== 'undefined' ? BURST_DB[name] : null;
  try{ if(_pgiDetailR && _pgiDetailR.burst && _pgiDetailR.burst.bd) burst = _pgiDetailR.burst.bd; }catch(_ePgB){}
  const trait = typeof HERO_TRAIT !== 'undefined' ? HERO_TRAIT[name] : null;
  const _storedTraitLv = _heroTraitLevel[name] || 0;
