          const _pTotal = (_p.hp||0) + (_p.atk||0) + (_p.sp||0) + (_p.spd||0);
          const _rFree = Math.max(0, freeP - _pTotal);
          if(freeP <= 0 && _pTotal === 0) return '';
          if(!_heroIsUnlocked) return '';
