// ★ v3.16.26(2026-06-26)— 「自動還原被 v3.16.19 誤回收的練過英雄」協調器(登入一次性)
//   登入後呼叫 → uid 已設定 → window._fbRestoreLeveledAuditRecovered(只還原暫存等級>1 的練過英雄)
//   → 還原成功後同步記憶體(_heroLevels)+本機(adv_unlocked_heroes / adv_hero_unlock_history 補 audit_auto_restored)
//     讓英雄連同等級立刻顯示、且不被 advGetUnlockedHeroes 出口過濾隱藏(不重載·不寫 _authoritativeRestoreAt)。
//   一次性:本機旗標 lxps_audit_leveled_restore_v1_<uid> + 雲端旗標 _auditLeveledRestoreV1(函式內)雙重防重跑。
// ════════════════════════════════════════════════════════════════════
window._lxpsRestoreLeveledOnLogin = async function(){
  try{
    var _uid = window._gUserId || '';
    if(!_uid) return;
    if(window._auditLeveledRestoreRunning) return;
    var _flagKey = 'lxps_audit_leveled_restore_v1_' + _uid;
    try{ if(localStorage.getItem(_flagKey)) return; }catch(_eF){}
    if(typeof window._fbRestoreLeveledAuditRecovered !== 'function') return;
    window._auditLeveledRestoreRunning = true;
    try{
      var _res = await window._fbRestoreLeveledAuditRecovered(_uid);
      if(_res && _res.ok){
        try{ localStorage.setItem(_flagKey, String(Date.now())); }catch(_eS){}
        var _list = (_res.restored && _res.restored.length) ? _res.restored : [];
        if(_list.length){
          var _now = Date.now(); var _u12 = String(_uid).slice(0, 12); var _lvMap = _res.levels || {};
          // ① 還原記憶體等級(只升不降)
          try{
            if(typeof _heroLevels === 'object' && _heroLevels){
              _list.forEach(function(n){ var _c = (typeof _heroLevels[n] === 'number') ? _heroLevels[n] : 0; _heroLevels[n] = Math.max(_c, Number(_lvMap[n]) || 1); });
            }
          }catch(_e1){}
          // ② 本機 adv_unlocked_heroes 加回(讓 advGetUnlockedHeroes 立刻看到)
          try{
            var _rawU = localStorage.getItem('adv_unlocked_heroes'); var _u = _rawU ? JSON.parse(_rawU) : [];
            if(!Array.isArray(_u)) _u = [];
            var _uS = {}; _u.forEach(function(x){ _uS[x] = 1; });
            _list.forEach(function(n){ if(!_uS[n]){ _u.push(n); _uS[n] = 1; } });
            localStorage.setItem('adv_unlocked_heroes', JSON.stringify(_u));
          }catch(_e2){}
          // ③ 本機 adv_hero_unlock_history 補 audit_auto_restored(最新一筆蓋過 audit_error_recovered → 出口過濾不再隱藏)
          try{
            var _rawH = localStorage.getItem('adv_hero_unlock_history'); var _h = _rawH ? JSON.parse(_rawH) : [];
            if(!Array.isArray(_h)) _h = [];
            _list.forEach(function(n){ _h.push({ name:n, at:_now, source:'audit_auto_restored', uid:_u12, auditRestored:true, reason:'練過的英雄一律保留·自動還原' }); });
            if(_h.length > 400) _h = _h.slice(-400);
            localStorage.setItem('adv_hero_unlock_history', JSON.stringify(_h));
          }catch(_e3){}
          console.warn('[練過英雄自動還原 v3.16.26] 已還原 ' + _list.length + ' 隻被誤回收的練過英雄(等級已補回·技能/天賦/爆發升級需重練):', _list);
        }
      }
    } finally { window._auditLeveledRestoreRunning = false; }
  }catch(_e){ try{ window._auditLeveledRestoreRunning = false; }catch(_ee){} }
};

