function _showStorageInsufficientModal(freeMB, neededMB, minMB){
  try{
    const _old = document.getElementById('_storage-insufficient-modal');
    if(_old && _old.parentNode) _old.parentNode.removeChild(_old);
    const _wrap = document.createElement('div');
    _wrap.id = '_storage-insufficient-modal';
    _wrap.style.cssText = 'position:fixed;inset:0;z-index:99999;background:rgba(0,0,0,0.78);'
      + 'display:flex;align-items:center;justify-content:center;font-family:inherit;padding:20px;box-sizing:border-box;';
    _wrap.innerHTML = ''
      + '<div style="background:linear-gradient(135deg,rgba(50,20,20,0.98),rgba(30,10,10,0.99));'
      +   'border:3px solid rgba(255,140,80,0.85);border-radius:18px;padding:28px 32px;'
      +   'width:min(500px,100%);box-sizing:border-box;color:#fff;'
      +   'box-shadow:0 8px 36px rgba(255,120,60,0.35);">'
      +   '<div style="font-size:48px;text-align:center;margin-bottom:8px;">💾</div>'
      +   '<div style="font-size:22px;font-weight:900;color:#ffbb66;margin-bottom:14px;text-align:center;letter-spacing:1px;">'
      +     '裝置空間不足,無法完整安裝'
      +   '</div>'
      +   '<div style="font-size:14px;color:#ddd;line-height:1.65;background:rgba(0,0,0,0.4);'
      +     'border-radius:10px;padding:14px 16px;margin-bottom:14px;">'
      +     '<div style="margin-bottom:6px;">📦 完整下載安裝需要:<b style="color:#ffd066;">至少 ' + minMB + ' MB</b>(預估資源約 ' + neededMB + ' MB + 系統緩衝)</div>'
      +     '<div>📱 你的裝置現在可用:<b style="color:#ff8866;">約 ' + freeMB.toFixed(0) + ' MB</b>' + (freeMB < minMB ? ' ❌' : '') + '</div>'
      +   '</div>'
      +   '<div style="font-size:14px;color:#aaffcc;background:rgba(20,60,40,0.4);border:1.5px solid rgba(120,200,160,0.5);border-radius:10px;padding:12px 14px;margin-bottom:14px;line-height:1.65;">'
      +     '✅ <b>還是可以玩!</b> 不用完整安裝,直接用網頁版即可(像現在這樣)。<br>'
      +     '網頁版會在每次連網時即時抓取需要的資源,只是斷網時無法遊玩。'
      +   '</div>'
      +   '<div style="font-size:13px;color:#ffaa66;margin-bottom:16px;line-height:1.6;">'
      +     '💡 <b>想完整安裝怎麼辦?</b><br>'
      +     '・刪掉裝置上不需要的相片 / 影片 / app<br>'
      +     '・清掉 Safari 或 Chrome 的歷史紀錄/快取<br>'
      +     '・清出空間後,重整本頁面再試一次'
      +   '</div>'
      +   '<div style="display:flex;gap:10px;">'
      +     '<button id="_storage-modal-ok" style="flex:1;padding:12px 18px;font-size:15px;font-weight:800;'
      +       'background:linear-gradient(135deg,rgba(100,180,255,0.4),rgba(50,120,200,0.6));'
      +       'border:2px solid #88bbff;color:#fff;border-radius:10px;cursor:pointer;font-family:inherit;">'
      +       '✅ 知道了,先用網頁版玩' +
      '     </button>'
      +   '</div>'
      + '</div>';
    document.body.appendChild(_wrap);
    const _close = function(){ try{ _wrap.parentNode && _wrap.parentNode.removeChild(_wrap); }catch(_){} };
    document.getElementById('_storage-modal-ok').onclick = _close;
    _wrap.onclick = function(ev){ if(ev.target === _wrap) _close(); };
  }catch(e){ console.warn('[_showStorageInsufficientModal] 例外', e); }
}

