// ══════════════════════════════════════════════════════
// ★ 暱稱系統
// ══════════════════════════════════════════════════════
function openNicknameModal() {
  const existing = document.getElementById('_nickname-modal');
  if (existing) { existing.remove(); return; }
  if (!window._fbUser) { bannerFX(null, '請先登入', '#ff6666', 1500); return; }

  const current = window._playerNickname || window._fbUser.displayName || '';

  const modal = document.createElement('div');
  modal.id = '_nickname-modal';
  modal.style.cssText = 'position:fixed;inset:0;z-index:29999;background:rgba(0,0,8,0.88);'
    + 'display:flex;align-items:center;justify-content:center;'
    + 'font-family:"M PLUS Rounded 1c","Nunito",sans-serif;';
  modal.onclick = e => { if (e.target === modal) modal.remove(); };

  // 解析現有暱稱的形容詞/名詞(含限定稱號詞)
  let _initAdj = _NICK_ADJ[0], _initNoun = _NICK_NOUN[0];
  const _curClean = current.replace(/\s*#\d+$/, '').trim();
  const _allAdjW  = _NICK_ADJ.concat(_NICK_ADJ_SPECIAL.map(o=>o.w));
  const _allNounW = _NICK_NOUN.concat(_NICK_NOUN_SPECIAL.map(o=>o.w));
  for (const adj of _allAdjW) {
    if (_curClean.startsWith(adj)) {
      const rest = _curClean.slice(adj.length);
      if (_allNounW.includes(rest)) { _initAdj = adj; _initNoun = rest; break; }
    }
  }

  const _adjOptions  = _NICK_ADJ.map(a  => `<option value="${a}"  ${a===_initAdj  ?'selected':''}>${a}</option>`).join('');
  const _nounOptions = _NICK_NOUN.map(n => `<option value="${n}" ${n===_initNoun ?'selected':''}>${n}</option>`).join('');
  // ★ v3.15.68 — 限定稱號選項:已解鎖 → ✨ 可選;未解鎖 → 🔒 停用 + 達成條件提示(給玩家追求目標的誘因)
  const _buildSpecialOpts = (arr, sel) => arr.map(o => {
    const _has = (typeof window._hasNickReq === 'function') && window._hasNickReq(o.req);
    return _has
      ? `<option value="${o.w}" ${o.w===sel?'selected':''}>✨ ${o.w}</option>`
      : `<option value="🔒${o.w}" disabled>🔒 ${o.w}(需${_nickReqHint(o.req)})</option>`;
  }).join('');
  const _adjSpecialOpts  = '<optgroup label="✨ 限定稱號(達成成就解鎖)">' + _buildSpecialOpts(_NICK_ADJ_SPECIAL,  _initAdj)  + '</optgroup>';
  const _nounSpecialOpts = '<optgroup label="✨ 限定稱號(達成成就解鎖)">' + _buildSpecialOpts(_NICK_NOUN_SPECIAL, _initNoun) + '</optgroup>';
  const _selStyle = 'padding:10px 12px;font-size:19px;font-weight:700;background:rgba(20,30,50,0.95);'
    + 'border:1.5px solid rgba(100,200,255,0.5);color:#e0f0ff;border-radius:10px;font-family:inherit;'
    + 'outline:none;cursor:pointer;flex:1;';

  const _isIPad = navigator.maxTouchPoints > 1 && /Macintosh|iPad/.test(navigator.userAgent);
  const _fs = _isIPad ? '' : 'font-size:clamp(22px,2vw,32px);';
  const _btnFs = _isIPad ? 'font-size:18px;' : 'font-size:clamp(18px,1.8vw,28px);';
  const _selStyleFull = _selStyle + (_isIPad ? '' : 'font-size:clamp(19px,1.8vw,28px);');
  modal.innerHTML =
    '<div style="background:linear-gradient(160deg,#0a0e1e,#060810);'
    + 'border:2.5px solid rgba(100,200,255,0.7);border-radius:20px;'
    + 'padding:clamp(28px,3vw,44px) clamp(28px,4vw,52px);max-width:min(96vw,clamp(540px,58vw,800px));width:100%;text-align:center;">'
    + '<div style="' + _fs + 'font-size:clamp(24px,2.5vw,36px);font-weight:900;color:#88ddff;margin-bottom:6px;">✏️ 設定暱稱</div>'
    + '<div style="font-size:clamp(13px,1.3vw,18px);color:#aaa;margin-bottom:clamp(14px,1.5vw,22px);">選一個「形容詞＋名詞」組合成你的暱稱</div>'
    // 下拉選單
    + '<div style="display:flex;gap:clamp(6px,0.8vw,12px);margin-bottom:clamp(12px,1.2vw,18px);">'
    + '<select id="_nick-adj" style="' + _selStyleFull + '">' + _adjOptions + _adjSpecialOpts + '</select>'
    + '<select id="_nick-noun" style="' + _selStyleFull + '">' + _nounOptions + _nounSpecialOpts + '</select>'
    + '</div>'
    // 即時預覽
    + '<div id="_nick-preview" style="font-size:clamp(20px,2.2vw,32px);font-weight:800;color:#ffcc44;'
    + 'background:rgba(255,180,0,0.1);border:1px solid rgba(255,180,0,0.3);border-radius:10px;'
    + 'padding:clamp(8px,1vw,14px);margin-bottom:clamp(12px,1.2vw,18px);letter-spacing:1px;"></div>'
    // 隨機按鈕
    + '<button onclick="_nickRandom()" style="width:100%;padding:clamp(8px,1vw,12px);font-size:clamp(14px,1.5vw,22px);font-weight:700;'
    + 'background:rgba(100,80,200,0.2);border:1.5px solid rgba(180,120,255,0.5);color:#cc99ff;'
    + 'border-radius:10px;cursor:pointer;font-family:inherit;margin-bottom:clamp(8px,1vw,12px);">🎲 幫我隨機選一個</button>'
    // ★ v3.11.4(2026-05-27) — 改回班級座號姓名按鈕(BUG #7)
    //   只有在名冊內的學生才顯示(老師需求:讓玩家可以改回班級座號姓名格式)
    + (function(){
        try{
          const _eml = (window._fbUser && window._fbUser.email || '').toLowerCase().trim();
          const _rosEntry = (typeof window._getRosterEntry === 'function') ? window._getRosterEntry(_eml) : null;
          const _label = _rosEntry && typeof window._formatRosterLabel === 'function' ? window._formatRosterLabel(_rosEntry) : '';
          if(!_label) return '';  // 不在名冊就不顯示這顆按鈕(避免老師、訪客誤按)
          return '<button onclick="_nickResetToRoster()" style="width:100%;padding:clamp(8px,1vw,12px);font-size:clamp(13px,1.4vw,20px);font-weight:700;'
            + 'background:rgba(80,140,200,0.2);border:1.5px solid rgba(120,200,255,0.55);color:#88ddff;'
            + 'border-radius:10px;cursor:pointer;font-family:inherit;margin-bottom:clamp(12px,1.5vw,20px);">'
            + '🎓 改回我的預設名稱「' + _label + '」</button>';
        }catch(_eRsB){ return ''; }
      })()
    + '<div style="display:flex;gap:10px;justify-content:center;">'
    + '<button onclick="_saveNickname()" style="padding:clamp(10px,1vw,14px) clamp(28px,3vw,48px);' + _btnFs + 'font-weight:800;'
    + 'background:rgba(50,150,255,0.25);border:2px solid rgba(100,200,255,0.7);color:#88ddff;'
    + 'border-radius:11px;cursor:pointer;font-family:inherit;">✔ 儲存</button>'
    + '<button onclick="_nickModalClose()" style="padding:clamp(10px,1vw,14px) clamp(20px,2.5vw,36px);' + _btnFs + 'color:#888;'
    + 'background:none;border:1px solid #444;border-radius:11px;cursor:pointer;font-family:inherit;">取消</button>'
    + '</div></div>';

  document.body.appendChild(modal);

  // 即時預覽更新
  function _updateNickPreview() {
    const adj  = document.getElementById('_nick-adj');
    const noun = document.getElementById('_nick-noun');
    const prev = document.getElementById('_nick-preview');
    if (adj && noun && prev) prev.textContent = adj.value + noun.value;
  }
  setTimeout(() => {
    _updateNickPreview();
    const a = document.getElementById('_nick-adj');
    const n = document.getElementById('_nick-noun');
    if (a) a.addEventListener('change', _updateNickPreview);
    if (n) n.addEventListener('change', _updateNickPreview);
  }, 50);
}

function _nickModalClose(){
  var e=document.getElementById('_nickname-modal');
  if(e) e.remove();
}

// ════════════════════════════════════════════════════════════════
// ★ v3.11.4(2026-05-27) — 改回班級座號姓名(BUG #7)
//   老師需求:讓玩家可以改回自己原本預設暱稱(班級座號姓名)
//   實作:
//     1. 從名冊取出該 email 對應的 5324蔣同學 格式短碼
//     2. 寫入 localStorage + Firebase(同 _saveNickname 路徑)
//     3. 跳過 _checkNicknameClean 驗證(班級座號姓名不在詞庫內,
//        但這是「合法的預設名」,要繞過驗證)
//   風險評估:此函式只在「該 email 在名冊內」時觸發,輸出格式由 _formatRosterLabel
//             嚴格產生,不能被玩家自由輸入,所以繞驗證安全。
// ════════════════════════════════════════════════════════════════
async function _nickResetToRoster(){
  try{
    if(!window._fbUser){ bannerFX(null, '請先登入', '#ff6666', 1500); return; }
    const _eml = (window._fbUser.email || '').toLowerCase().trim();
    if(!_eml){ bannerFX(null, '無 email 資料', '#ff6666', 1500); return; }
    const _rosEntry = (typeof window._getRosterEntry === 'function') ? window._getRosterEntry(_eml) : null;
    if(!_rosEntry){
      bannerFX(null, '你不在名冊內,無法套用預設名稱', '#ffaa44', 2500);
      return;
    }
    const _label = (typeof window._formatRosterLabel === 'function') ? window._formatRosterLabel(_rosEntry) : '';
    if(!_label){
      bannerFX(null, '名冊資料不完整', '#ffaa44', 2000);
      return;
    }
    const uid = window._fbUser.uid;
    if(!uid) return;

    // ★ v3.11.4 微調:不用 confirm()(iPad PWA 全螢幕模式上可能被擋)
    //   此操作可逆(可隨時再打開暱稱 modal 改回原本),不需要二次確認
    //   按下按鈕本身就視為玩家確認

    // 寫本地
    localStorage.setItem('lxps_nickname_' + uid, _label);
    window._playerNickname = _label;
    // 更新 UI
    const nm = document.getElementById('google-name');
    if(nm) nm.textContent = _label;
    const advNm = document.getElementById('adv-user-name');
    if(advNm) advNm.textContent = _label;

    // 同步雲端(同 _saveNickname 的 3 次 retry)
    let _fbOk = false;
    for(let _r = 0; _r < 3; _r++){
      try{
        if(window._fbUser && typeof window._fbSave === 'function'){
          _fbOk = await window._fbSave(uid, { displayName: _label, email: _eml });
          if(_fbOk) break;
        }
      }catch(e){ console.warn('[暱稱重置] Firebase 同步失敗 (第 ' + (_r+1) + ' 次)', e); }
      if(_r < 2) await new Promise(r => setTimeout(r, 3000));
    }
    _nickModalClose();
    if(_fbOk){
      bannerFX(null, `✅ 暱稱已改回「${_label}」!已同步雲端`, '#88ddff', 2200);
      try{ playSfx('sfx-confirm', 0.6); }catch(_){}
    } else {
      bannerFX(null, `⚠️ 暱稱已改回「${_label}」,但雲端同步失敗,請稍後重試`, '#ffaa44', 4500);
      try{ playSfx('sfx-cancel', 0.5); }catch(_){}
    }
  }catch(e){
    console.error('[_nickResetToRoster] 失敗', e);
    bannerFX(null, '改回預設名稱失敗,請稍後再試', '#ff6666', 2500);
  }
}
window._nickResetToRoster = _nickResetToRoster;
function _nickRandom(){
  const r = _randomNickname();
  const clean = r.replace(/\s*#\d+$/, '').trim();
  let foundAdj='', foundNoun='';
  for(const adj of _NICK_ADJ){
    if(clean.startsWith(adj)){
      const rest = clean.slice(adj.length);
      if(_NICK_NOUN.includes(rest)){ foundAdj=adj; foundNoun=rest; break; }
    }
  }
  const a=document.getElementById('_nick-adj');
  const n=document.getElementById('_nick-noun');
  const p=document.getElementById('_nick-preview');
  if(a&&foundAdj) a.value=foundAdj;
  if(n&&foundNoun) n.value=foundNoun;
  if(p&&foundAdj&&foundNoun) p.textContent=foundAdj+foundNoun;
}

