        //   送禮邏輯:_openGiftDialog(i) 打開禮物選擇彈窗,_giftCanSendToFriend(uid) 判定今日是否已送過
        + `<div style="display:flex;gap:5px;padding:0 12px 12px;">`
        // ★ v4.55.0 — 📇 名片按鈕(主角捏臉系統 Phase 1;好友未捏臉則顯示預設造型)
        //   管理員測試期 gating:_AVATAR_ADMIN_ONLY=true 時僅管理員渲染此按鈕(正式開放改 avatar_db.js 開關即可)
        + (function(){
            const _gateOn = (typeof window._AVATAR_ADMIN_ONLY === 'undefined') || window._AVATAR_ADMIN_ONLY === true;
            const _isAdm = (typeof window._isAdminUser === 'function' && window._isAdminUser());
            if(_gateOn && !_isAdm) return '';
            return `<button onclick="_openFriendAvatarCard(${i})" title="查看這位好友的冒險者名片" style="flex:0 0 auto;padding:7px 8px;font-size:12px;font-weight:700;`
              + `background:rgba(80,140,220,0.25);border:1.5px solid rgba(130,190,255,0.7);color:#99ccff;`
              + `border-radius:8px;cursor:pointer;font-family:inherit;white-space:nowrap;">📇</button>`;
          })()
        + `<button onclick="_inviteFriendHero(${i})" style="flex:1;padding:7px 3px;font-size:12px;font-weight:700;`
        + `background:rgba(255,100,180,0.25);border:1.5px solid rgba(255,130,200,0.7);color:#ff99cc;`
        + `border-radius:8px;cursor:pointer;font-family:inherit;white-space:nowrap;">🤝 邀請</button>`
        + (function(){
            // ★ v3.12.0 — 送禮按鈕(依今日是否已送過判定狀態)
            const _giftState = (typeof window._giftGetStateForFriend === 'function')
              ? window._giftGetStateForFriend(f.uid) : { canSend:true, reason:'' };
            if(!_giftState.canSend){
              const _tooltip = _giftState.reason || '今日已送過';
              return `<button title="${_tooltip}" disabled style="flex:1;padding:7px 3px;font-size:12px;font-weight:700;background:rgba(80,80,80,0.2);border:1.5px solid #555;color:#888;border-radius:8px;cursor:not-allowed;font-family:inherit;white-space:nowrap;opacity:0.55;">🎁 已送</button>`;
            }
            return `<button onclick="_openGiftDialog(${i})" style="flex:1;padding:7px 3px;font-size:12px;font-weight:700;background:rgba(255,200,80,0.25);border:1.5px solid rgba(255,200,80,0.7);color:#ffd966;border-radius:8px;cursor:pointer;font-family:inherit;white-space:nowrap;">🎁 送禮</button>`;
          })()
        + (_hasRep
            ? `<button onclick="_toggleFriendDetail(${i})" style="flex:1;padding:7px 3px;font-size:12px;font-weight:700;background:rgba(120,80,200,0.25);border:1.5px solid rgba(180,120,255,0.7);color:#cc99ff;border-radius:8px;cursor:pointer;font-family:inherit;white-space:nowrap;">▾ 詳細</button>`
            : '<div style="flex:1;"></div>')
        + `<button onclick="_deleteFriend(${i})" style="padding:7px 9px;font-size:13px;`
        + `background:rgba(60,10,10,0.5);border:1.5px solid rgba(200,60,60,0.5);color:#ff8888;`
