// ★ v3.14.4(2026-06-10)— 老師需求 2:送禮記錄(送出/收到,保留 7 天)+ 回禮
//   結構:window._giftLog = [{ dir:'sent'|'recv', uid, name, giftName, icon,
//                              heart, msgIdx, ts }] 新→舊不保證,顯示時排序。
//   存檔:_buildSafeData 帶 giftLog;_applySafeData 以 (dir|uid|ts) 去重 union,
//        每次讀寫都裁剪 7 天外與 100 筆上限,Firestore doc 體積可控。
// ════════════════════════════════════════════════════════════════════
window._giftLogTrim = function(){
  try{
    if(!Array.isArray(window._giftLog)) window._giftLog = [];
    const _cut = Date.now() - 7*24*60*60*1000;
    window._giftLog = window._giftLog.filter(function(r){ return r && (r.ts||0) >= _cut; });
    if(window._giftLog.length > 100){
      window._giftLog.sort(function(a,b){ return (b.ts||0)-(a.ts||0); });
      window._giftLog = window._giftLog.slice(0, 100);
    }
  }catch(_){ window._giftLog = []; }
};
window._giftLogAdd = function(dir, rec){
  try{
    if(!Array.isArray(window._giftLog)) window._giftLog = [];
    window._giftLog.push({
      dir: dir === 'recv' ? 'recv' : 'sent',
      uid: String(rec.uid || ''),
      name: String(rec.name || '好友').slice(0, 30),
      giftName: String(rec.giftName || '').slice(0, 30),
      icon: String(rec.icon || '🎁').slice(0, 4),
      heart: Math.max(0, Math.floor(rec.heart || 0)),
      msgIdx: (typeof rec.msgIdx === 'number' && rec.msgIdx >= 0 && rec.msgIdx <= 4) ? Math.floor(rec.msgIdx) : -1,
      ts: rec.ts || Date.now(),
    });
    window._giftLogTrim();
  }catch(_e){ console.warn('[送禮記錄 v3.14.4] add 失敗', _e); }
};

