// 初始化全域旗標
if(typeof window._friendshipHeart !== 'number') window._friendshipHeart = 0;
if(!window._giftHistory) window._giftHistory = { date:'', sentUids:[] };

// 計算某時間戳的「8:00 跨日字串」── 若該時刻 < 08:00,算前一天(台灣時區)
// ★ v3.15.38 — 抽出 _giftKeyForTs(ts) 供 giftLog 校正使用;_giftGetTodayKey 改為呼叫之(DRY,邏輯不變)
window._giftKeyForTs = function(ts){
  try{
    const base = (typeof ts === 'number' && ts > 0) ? new Date(ts) : new Date();
    // 取台灣時區 YYYY-MM-DD
    const _tw = new Date(base.toLocaleString('en-US', { timeZone:'Asia/Taipei' }));
    const _h = _tw.getHours();
    // < 08:00 算「昨天 08:00」週期
    if(_h < 8){
      _tw.setDate(_tw.getDate() - 1);
    }
    const _y = _tw.getFullYear();
    const _m = String(_tw.getMonth()+1).padStart(2,'0');
    const _d = String(_tw.getDate()).padStart(2,'0');
    return _y + '-' + _m + '-' + _d + '-08';
  }catch(e){
    // fallback:UTC 簡單版
    return new Date((typeof ts==='number' && ts>0) ? ts : Date.now()).toISOString().slice(0,10) + '-08';
  }
};
window._giftGetTodayKey = function(){ return window._giftKeyForTs(Date.now()); };

// 跨日自動 reset _giftHistory + 跨帳號殘留防護 + 以 giftLog 校正今日 sentUids
window._giftMaybeResetHistory = function(){
  const todayKey = window._giftGetTodayKey();
  const _curUid = window._gUserId || '';
  // (1) 跨日,或持有者 uid 與目前帳號不符(共用 iPad 換帳號殘留)→ 重置今日記錄
  if(!window._giftHistory
     || window._giftHistory.date !== todayKey
     || (window._giftHistory._uid != null && _curUid && window._giftHistory._uid !== _curUid)){
    window._giftHistory = { date: todayKey, sentUids: [], _uid: _curUid };
  }
  if(window._giftHistory._uid == null && _curUid) window._giftHistory._uid = _curUid;
  // (2) ★ v3.15.38 — 以「送禮記錄 giftLog」為權威反推今日真實 sentUids,清除殘留/幽靈計數。
  //   根因:共用 iPad 換帳號殘留或雲端寫入時序,可能讓 sentUids 帶到非本人的送禮對象,
  //   造成「送禮紀錄真的 0 次」的學生卻被擋「今日已送 5/5」。送禮當下 sentUids 與 giftLog
  //   一起寫,故以今日 giftLog 'sent' 的去重收禮者重建 sentUids(上限 5)→ 幽靈計數自動消失,
  //   真實已送對象仍保留(「今日已送過此好友」判定亦因此正確)。
  try{
    if(Array.isArray(window._giftLog) && typeof window._giftKeyForTs === 'function'){
      const _real = [];
      for(let _gi=0; _gi<window._giftLog.length; _gi++){
        const _r = window._giftLog[_gi];
        if(_r && _r.dir === 'sent' && _r.uid && _r.ts && window._giftKeyForTs(_r.ts) === todayKey){
          if(_real.indexOf(_r.uid) < 0) _real.push(_r.uid);
        }
      }
      window._giftHistory.sentUids = _real.slice(0, 5);
    }
  }catch(_){}
};

// 取得今日送出次數
window._giftGetTodayCount = function(){
  window._giftMaybeResetHistory();
  return (window._giftHistory.sentUids || []).length;
};

// 判定某個好友 uid 今日是否可送禮
window._giftGetStateForFriend = function(friendUid){
  if(!friendUid) return { canSend:false, reason:'好友資料異常' };
  if(friendUid === window._gUserId) return { canSend:false, reason:'不能送自己' };
  window._giftMaybeResetHistory();
  const _cnt = (window._giftHistory.sentUids || []).length;
  if(_cnt >= 5) return { canSend:false, reason:'今日已送 5/5 次,明早 8:00 重置' };
  if((window._giftHistory.sentUids || []).indexOf(friendUid) >= 0){
    return { canSend:false, reason:'今日已送過此好友' };
  }
  return { canSend:true };
};

// 取得自己手上某種禮物的持有量(用 cost.type / cost.key 判定)
// ★ v3.12.2(2026-05-30) — 修正 'crystal' 通道:召喚水晶實際存在背包 'summon_crystal' key,
//   不是 window._crystalCount(該變數在現行版本沒被維護,永遠是 undefined → 0)
//   症狀:玩家有 10 顆水晶,送禮卻顯示 0 顆無法送
window._giftGetMyHave = function(giftDef){
  if(!giftDef || !giftDef.cost) return 0;
  const c = giftDef.cost;
  try{
    if(c.type === 'coins') return (typeof _knowledgeCoins === 'number') ? _knowledgeCoins : 0;
    if(c.type === 'crystal'){
      // ★ v3.12.2 — 走 backpack('summon_crystal'),跟左下角顯示用同源
      if(typeof backpackGet === 'function') return backpackGet('summon_crystal') || 0;
      if(window._playerBackpack) return window._playerBackpack.summon_crystal || 0;
      return 0;
    }
    if(c.type === 'backpack' && c.key){
      return (typeof backpackGet === 'function') ? backpackGet(c.key) : 0;
    }
  }catch(_){}
  return 0;
};

// 判定是否有足夠數量送出
window._giftCanAfford = function(giftDef){
  if(!giftDef || !giftDef.cost) return false;
  return window._giftGetMyHave(giftDef) >= (giftDef.cost.amount || 0);
};

// 累加友情之心 + 達 100 自動發 SSR 卷
window._giftAddHeart = async function(amount){
  if(typeof window._friendshipHeart !== 'number') window._friendshipHeart = 0;
  window._friendshipHeart += (amount || 0);
  let _grantedSsr = false;
  let _ssrFullCompensate = false;  // ★ v3.12.0 BUG #18:SSR 卷滿了的補償標記
  if(window._friendshipHeart >= 100){
    // ★ v3.12.0(2026-05-29)BUG #18 — SSR 卷 99 上限保護
    //   如果玩家 SSR 卷已經 99,backpackAdd 會 silent cap
    //   原本邏輯會把友情之心歸零但卷沒拿到 → 玩家白損失
    //   新邏輯:SSR 卷 < 99 才發,並歸零;已 99 → 友情之心保留在 99(不歸零),
    //          並發 10,000 知識幣 + 5 個豪華典藏經驗書當補償(讓玩家有感),
    //          下次玩家用掉 SSR 卷後,下次達 100 就能正常拿到
    try{
      const _curSsr = (typeof backpackGet === 'function') ? backpackGet('summon_ticket_ssr') : 0;
      if(_curSsr >= 99){
        // SSR 卷已滿 → 維持友情之心在 99 + 給補償
        window._friendshipHeart = 99;
        if(typeof _knowledgeCoins !== 'undefined'){
          _knowledgeCoins = (_knowledgeCoins||0) + 10000;
          try{ if(typeof _logCoinTx === 'function') _logCoinTx(10000, '收入:友情之心滿額補償(SSR卷已滿)'); }catch(_){}   // ★ v5.247.0
          if(typeof _syncCoinsDisplay === 'function') _syncCoinsDisplay();
        }
        if(typeof backpackAdd === 'function'){
          backpackAdd('hero_exp_book_deluxe', 5);  // 5 本精裝經驗書
        }
        _ssrFullCompensate = true;
      } else {
        // SSR 卷未滿 → 正常發放並歸零
        window._friendshipHeart = 0;
        if(typeof backpackAdd === 'function'){
          backpackAdd('summon_ticket_ssr', 1);
          _grantedSsr = true;
        }
      }
    }catch(eS){ console.warn('[v3.12.0 SSR 卷發放]', eS); }
  }
  // 更新 UI
  try{
    const _numEl = document.getElementById('_friendship-heart-num');
    const _fillEl = document.getElementById('_friendship-heart-fill');
    if(_numEl) _numEl.textContent = window._friendshipHeart;
    if(_fillEl) _fillEl.style.width = Math.min(100, window._friendshipHeart) + '%';
  }catch(_){}
  // ★ v3.13.94 — 友情之心獲得寫入活動紀錄(供 GM 查證)
  try{
    if(typeof window._logActivity === 'function'){
      window._logActivity('heart_gain', {
        amount: (amount || 0),
        heartAfter: window._friendshipHeart,
        grantedSsr: !!_grantedSsr
      });
    }
  }catch(_eHeartLog){}
  // 雲端同步
  try{ if(typeof gameCloudSave === 'function') gameCloudSave(); }catch(_){}
  if(_grantedSsr){
    // 隔 400ms 彈獲得通知,讓進度條動畫先跑完
    setTimeout(function(){
      try{
        if(typeof bannerFX === 'function'){
          bannerFX(null, '💕 友情滿溢!獲得 🌈 SSR 英雄召喚卷 ×1!', '#ff88dd', 4500);
        }
        if(typeof playSfx === 'function') playSfx('sfx-confirm', 0.8);
      }catch(_){}
    }, 400);
  } else if(_ssrFullCompensate){
    // ★ v3.12.0 BUG #18 — SSR 卷滿補償通知
    setTimeout(function(){
      try{
        if(typeof bannerFX === 'function'){
          bannerFX(null, '💕 友情之心爆表!但 SSR 卷已滿 99,改贈 💰 10,000 + 📕 精裝經驗書 ×5!(下次再達 100 補卷)', '#ff88dd', 6000);
        }
        if(typeof playSfx === 'function') playSfx('sfx-coin', 0.8);
      }catch(_){}
    }, 400);
  }
};

// ════════════════════════════════════════════════════════════════════
// ★ v3.14.4(2026-06-10)— 老師需求 2:送禮記錄 modal + 回禮
//   - 列出 7 天內「送出 / 收到」記錄(日期時間、對象、禮物、勉勵話)
//   - 收到的每筆可「💝 回禮」:走既有 _openGiftDialog 流程
//     (送完自動記 sentUids + _refreshFriendListInner → 該好友贈禮按鈕同步灰化)
//   - 今日已送滿 5 人 → 按任何回禮只顯示「今天已經送完5次禮物,等明天再送吧~」
// ════════════════════════════════════════════════════════════════════
window._giftReplyTo = function(uid, name){
  try{
    if(typeof playSfx === 'function') playSfx('sfx-sel', 0.5);
    // 守門 1:今日 5 次上限(老師指定文案)
    if(typeof window._giftGetTodayCount === 'function' && window._giftGetTodayCount() >= 5){
      bannerFX(null, '🎁 今天已經送完5次禮物,等明天再送吧~', '#ffaa66', 2800);
      return;
    }
    // 守門 2:今日已送過此人
    const _st = (typeof window._giftGetStateForFriend === 'function')
      ? window._giftGetStateForFriend(uid) : { canSend:true };
    if(!_st.canSend){
      bannerFX(null, '⛔ ' + (_st.reason || '今日已送過此好友'), '#ff8844', 2400);
      return;
    }
    // 守門 3:必須在好友清單(回禮走標準送禮流程)
    const _idx = (typeof _friendList !== 'undefined' && Array.isArray(_friendList))
      ? _friendList.findIndex(function(f){ return f && f.uid === uid; }) : -1;
    if(_idx < 0){
      bannerFX(null, '😢 ' + (name || '對方') + ' 目前不在你的好友清單,無法回禮', '#ff8866', 3000);
      return;
    }
    // 關記錄 modal → 開標準送禮 dialog
    try{ const _lm = document.getElementById('_gift-log-modal'); if(_lm) _lm.remove(); }catch(_){}
    window._openGiftDialog(_idx);
  }catch(_e){ console.warn('[回禮 v3.14.4] 例外', _e); }
};

window._openGiftLogModal = function(){
  try{
    if(typeof playSfx === 'function') playSfx('sfx-sel', 0.5);
    if(typeof window._giftLogTrim === 'function') window._giftLogTrim();
    const _log = Array.isArray(window._giftLog) ? window._giftLog.slice() : [];
    _log.sort(function(a, b){ return (b.ts||0) - (a.ts||0); });  // 新→舊

    const _esc = function(s){
      return String(s == null ? '' : s).replace(/[<>&"']/g, function(c){
        return { '<':'&lt;', '>':'&gt;', '&':'&amp;', '"':'&quot;', "'":'&#39;' }[c];
      });
    };
    const _fmtT = function(ts){
      try{
        const d = new Date(ts);
        const p = function(n){ return n < 10 ? '0'+n : ''+n; };
        return (d.getMonth()+1) + '/' + d.getDate() + ' ' + p(d.getHours()) + ':' + p(d.getMinutes());
      }catch(_){ return '—'; }
    };

    const _rows = _log.length ? _log.map(function(r){
      const _isRecv = r.dir === 'recv';
      const _dirTag = _isRecv
        ? '<span style="color:#ffaadd;font-weight:900;">💝 收到</span>'
        : '<span style="color:#ffe066;font-weight:900;">🎁 送出</span>';
      const _who = _isRecv ? ('來自 <b>' + _esc(r.name) + '</b>') : ('給 <b>' + _esc(r.name) + '</b>');
      const _msg = (r.msgIdx >= 0 && Array.isArray(window._GIFT_MESSAGES) && window._GIFT_MESSAGES[r.msgIdx])
        ? '<div style="margin-top:4px;color:#ffb8dd;font-size:12.5px;">💌 「' + _esc(window._GIFT_MESSAGES[r.msgIdx]) + '」</div>'
        : '';
      const _replyBtn = _isRecv && r.uid
        ? '<button onclick="_giftReplyTo(\'' + _esc(r.uid).replace(/'/g, '') + '\',\'' + _esc(r.name).replace(/'/g, '') + '\')" '
          + 'style="padding:6px 14px;font-size:13px;font-weight:800;flex:0 0 auto;'
          + 'background:linear-gradient(135deg,rgba(255,140,200,0.45),rgba(220,80,150,0.55));'
          + 'border:1.5px solid #ff99cc;color:#fff;border-radius:9px;cursor:pointer;font-family:inherit;">💝 回禮</button>'
        : '';
      return '<div style="display:flex;align-items:center;gap:10px;background:'
        + (_isRecv ? 'rgba(80,40,70,0.4)' : 'rgba(70,55,25,0.4)') + ';'
        + 'border:1.5px solid ' + (_isRecv ? 'rgba(255,150,210,0.4)' : 'rgba(255,200,90,0.4)') + ';'
        + 'border-radius:10px;padding:10px 13px;margin-bottom:8px;">'
        + '<div style="flex:1;min-width:0;">'
        + '<div style="font-size:13.5px;color:#ddd;line-height:1.5;">'
        + _dirTag + ' · ' + _who + ' · ' + (r.icon || '🎁') + ' ' + _esc(r.giftName)
        + (r.heart > 0 ? ' <span style="color:#ffaadd;">+' + r.heart + '💕</span>' : '')
        + ' <span style="color:#888;font-size:12px;">' + _fmtT(r.ts) + '</span></div>'
        + _msg
        + '</div>'
        + _replyBtn
        + '</div>';
    }).join('')
    : '<div style="text-align:center;color:#998;padding:36px 0;font-size:15px;">最近 7 天還沒有送禮或收禮記錄,<br>送個禮物給好友開始累積友情之心吧~ 🎁</div>';

    const _old = document.getElementById('_gift-log-modal');
    if(_old) _old.remove();
    const ov = document.createElement('div');
    ov.id = '_gift-log-modal';
    ov.style.cssText = 'position:fixed;inset:0;z-index:25010;background:rgba(0,0,12,0.86);'
      + 'display:flex;align-items:center;justify-content:center;padding:20px;'
      + 'font-family:"M PLUS Rounded 1c","Nunito",sans-serif;';
    ov.innerHTML = ''
      + '<div style="background:linear-gradient(160deg,rgba(40,25,40,0.98),rgba(25,15,30,0.99));'
      + 'border:3px solid rgba(255,150,200,0.65);border-radius:18px;padding:22px 24px;'
      + 'width:min(94vw,640px);max-height:86vh;display:flex;flex-direction:column;'
      + 'box-shadow:0 0 50px rgba(255,140,200,0.4);">'
      + '<div style="display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:10px;">'
      + '<div style="font-size:21px;font-weight:900;color:#ff99cc;letter-spacing:2px;">📜 送禮記錄<span style="font-size:13px;color:#998;font-weight:400;margin-left:8px;">(保留 7 天)</span></div>'
      + '<button onclick="document.getElementById(\'_gift-log-modal\').remove()" style="padding:6px 16px;font-size:14px;font-weight:700;background:rgba(60,10,10,0.4);border:1.5px solid #e84040;color:#e84040;border-radius:8px;cursor:pointer;font-family:inherit;">✕ 關閉</button>'
      + '</div>'
      + '<div style="font-size:13px;color:#ddc;margin-bottom:12px;background:rgba(60,40,80,0.35);padding:8px 12px;border-radius:8px;border-left:3px solid rgba(255,180,200,0.55);">'
      + '🎁 今日已送 <b style="color:#ffe066;">' + (typeof window._giftGetTodayCount === 'function' ? window._giftGetTodayCount() : 0) + '/5</b>'
      + ' · 收到的禮物可以按「💝 回禮」直接回送對方喔!'
      + '</div>'
      + '<div style="flex:1;overflow-y:auto;-webkit-overflow-scrolling:touch;padding:2px;">' + _rows + '</div>'
      + '</div>';
    document.body.appendChild(ov);
    ov.addEventListener('click', function(e){ if(e.target === ov) ov.remove(); });
  }catch(_e){ console.warn('[送禮記錄 modal v3.14.4] 例外', _e); }
};

// ★ v3.14.4 — 勉勵話 chip 選擇切換(老師需求 3)
window._giftPickMsg = function(mi){
  try{
    if(typeof playSfx === 'function') playSfx('sfx-sel', 0.4);
    window._giftSelMsgIdx = mi;
    document.querySelectorAll('._gift-msg-chip').forEach(function(c){
      const _isSel = parseInt(c.getAttribute('data-mi'), 10) === mi;
      c.style.background = _isSel
        ? 'linear-gradient(135deg,rgba(255,140,200,0.5),rgba(220,90,160,0.5))'
        : 'rgba(60,40,70,0.5)';
      c.style.border = '1.5px solid ' + (_isSel ? '#ff99cc' : 'rgba(180,140,200,0.4)');
      c.style.color = _isSel ? '#fff' : '#ccb8d8';
      const _m = (window._GIFT_MESSAGES || [])[parseInt(c.getAttribute('data-mi'), 10)] || '';
      c.textContent = (_isSel ? '✔ ' : '') + _m;
    });
  }catch(_){}
};

// 開啟送禮選擇彈窗
window._openGiftDialog = function(friendIdx){
  if(typeof playSfx === 'function') playSfx('sfx-sel', 0.5);
  const f = _friendList[friendIdx];
  if(!f){ bannerFX(null, '❌ 找不到好友資料', '#ff6666', 1800); return; }

  // 守門:今日是否已送過
  const _state = window._giftGetStateForFriend(f.uid);
  if(!_state.canSend){
    bannerFX(null, '⛔ ' + (_state.reason || '無法送禮'), '#ff8844', 2200);
    return;
  }

  // 移除舊 modal
  const _old = document.getElementById('_gift-dialog');
  if(_old) _old.remove();

  const _friendLabel = (typeof window._getFriendLabel === 'function')
    ? window._getFriendLabel(f.email || '', f.name || '')
    : (f.name || f.email || '好友');
  const _safeLabel = String(_friendLabel).replace(/[<>&"']/g, function(c){
    return { '<':'&lt;', '>':'&gt;', '&':'&amp;', '"':'&quot;', "'":'&#39;' }[c];
  });

  const ov = document.createElement('div');
  ov.id = '_gift-dialog';
  ov.style.cssText = 'position:fixed;inset:0;z-index:25000;background:rgba(0,0,12,0.86);'
    + 'display:flex;align-items:center;justify-content:center;padding:20px;'
    + 'font-family:"M PLUS Rounded 1c","Nunito",sans-serif;';

  // 建立 7 個禮物選項 HTML
  const _items = (window._GIFT_CATALOG || []).map(function(g){
    const _have = window._giftGetMyHave(g);
    const _need = g.cost.amount || 0;
    const _afford = _have >= _need;
    const _haveText = (g.cost.type === 'coins')
      ? '持有 ' + (_have || 0).toLocaleString()
      : '持有 ' + _have;
    const _bg = _afford ? 'rgba(40,30,15,0.85)' : 'rgba(40,40,40,0.45)';
    const _border = _afford ? 'rgba(255,200,80,0.6)' : 'rgba(120,120,120,0.4)';
    const _nameCol = _afford ? '#ffe066' : '#888';
    const _btnHtml = _afford
      ? '<button onclick="_giftConfirmSend(' + friendIdx + ',\'' + g.id + '\')" style="margin-top:10px;width:100%;padding:10px;font-size:15px;font-weight:800;background:linear-gradient(135deg,rgba(255,180,60,0.45),rgba(200,120,30,0.55));border:2px solid #ffaa44;color:#fff5dd;border-radius:8px;cursor:pointer;font-family:inherit;letter-spacing:1px;">🎁 送出</button>'
      : '<button disabled style="margin-top:10px;width:100%;padding:10px;font-size:15px;font-weight:800;background:rgba(60,60,60,0.3);border:2px solid #555;color:#666;border-radius:8px;cursor:not-allowed;font-family:inherit;opacity:0.5;">🔒 數量不足</button>';
    return ''
      + '<div style="background:' + _bg + ';border:2px solid ' + _border + ';border-radius:12px;padding:14px 12px;display:flex;flex-direction:column;align-items:stretch;text-align:center;' + (_afford ? '' : 'opacity:0.55;') + '">'
      + '<div style="font-size:38px;line-height:1;margin-bottom:6px;">' + g.icon + '</div>'
      + '<div style="font-size:16px;font-weight:900;color:' + _nameCol + ';margin-bottom:4px;line-height:1.25;">' + g.name + '</div>'
      + '<div style="font-size:13px;color:#bbb;line-height:1.45;margin-bottom:8px;flex:1;">' + g.desc + '</div>'
      + '<div style="font-size:13px;color:' + (_afford ? '#88ffaa' : '#ff8844') + ';font-weight:700;">' + _haveText + '</div>'
      + '<div style="font-size:13px;color:#ffaadd;font-weight:700;margin-top:4px;">💕 +' + g.heart + ' 友情之心</div>'
      + _btnHtml
      + '</div>';
  }).join('');

  const _todayCnt = window._giftGetTodayCount();
  const _heart = window._friendshipHeart || 0;

  // ★ v3.14.4 — 勉勵話選擇(預設第 1 句;chips 單選)
  window._giftSelMsgIdx = 0;
  const _msgChips = (window._GIFT_MESSAGES || []).map(function(m, mi){
    return '<button class="_gift-msg-chip" data-mi="' + mi + '" onclick="_giftPickMsg(' + mi + ')" '
      + 'style="padding:7px 13px;font-size:13px;font-weight:700;border-radius:16px;cursor:pointer;font-family:inherit;'
      + 'background:' + (mi === 0 ? 'linear-gradient(135deg,rgba(255,140,200,0.5),rgba(220,90,160,0.5))' : 'rgba(60,40,70,0.5)') + ';'
      + 'border:1.5px solid ' + (mi === 0 ? '#ff99cc' : 'rgba(180,140,200,0.4)') + ';'
      + 'color:' + (mi === 0 ? '#fff' : '#ccb8d8') + ';">'
      + (mi === 0 ? '✔ ' : '') + m + '</button>';
  }).join('');

  ov.innerHTML = ''
    + '<div style="background:linear-gradient(160deg,rgba(40,25,40,0.98),rgba(25,15,30,0.99));'
    + 'border:3px solid rgba(255,150,200,0.65);border-radius:18px;padding:24px 26px;'
    + 'max-width:min(96vw,820px);max-height:88vh;display:flex;flex-direction:column;'
    + 'box-shadow:0 0 50px rgba(255,140,200,0.4);">'
    + '<div style="display:flex;align-items:center;justify-content:space-between;gap:14px;margin-bottom:14px;flex-wrap:wrap;">'
    + '<div style="font-size:24px;font-weight:900;color:#ff99cc;letter-spacing:2px;">🎁 送禮給 <span style="color:#ffe066;">' + _safeLabel + '</span></div>'
    + '<button onclick="document.getElementById(\'_gift-dialog\').remove()" style="padding:6px 16px;font-size:14px;font-weight:700;background:rgba(60,10,10,0.4);border:1.5px solid #e84040;color:#e84040;border-radius:8px;cursor:pointer;font-family:inherit;">✕ 取消</button>'
    + '</div>'
    + '<div style="font-size:14px;color:#ddc;margin-bottom:12px;line-height:1.6;background:rgba(60,40,80,0.35);padding:10px 14px;border-radius:8px;border-left:3px solid rgba(255,180,200,0.55);">'
    + '・每天最多送 <b style="color:#ffe066;">5 個不同好友</b>(目前 ' + _todayCnt + '/5)・早上 8:00 重置<br>'
    + '・你目前的 <b style="color:#ffaadd;">💕 友情之心:' + _heart + '/100</b> ・集滿 100 自動換 🌈 SSR 召喚卷 ×1'
    + '</div>'
    // ★ v3.14.4 — 勉勵話勾選區(老師需求 3)
    + '<div style="margin-bottom:12px;background:rgba(50,25,55,0.45);padding:10px 14px;border-radius:8px;border-left:3px solid rgba(255,150,220,0.6);">'
    + '<div style="font-size:13px;color:#ffaadd;font-weight:800;margin-bottom:7px;letter-spacing:1px;">💌 選一句勉勵的話送給好友:</div>'
    + '<div style="display:flex;gap:7px;flex-wrap:wrap;">' + _msgChips + '</div>'
    + '</div>'
    + '<div style="overflow-y:auto;flex:1;-webkit-overflow-scrolling:touch;padding:2px;">'
    + '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:12px;">'
    + _items
    + '</div>'
    + '</div>'
    + '</div>';

  document.body.appendChild(ov);
  // 點背景關閉
  ov.addEventListener('click', function(e){
    if(e.target === ov) ov.remove();
  });
};

// 確認送出禮物
window._giftConfirmSend = async function(friendIdx, giftId){
  if(!window._btnCooldown('gift_send', 1500)) return;
  const f = _friendList[friendIdx];
  if(!f){ bannerFX(null, '❌ 找不到好友資料', '#ff6666', 1800); return; }
  const g = (window._GIFT_CATALOG || []).find(x => x.id === giftId);
  if(!g){ bannerFX(null, '❌ 找不到禮物資料', '#ff6666', 1800); return; }

  // 再次守門(防玩家開著 modal 期間達上限)
  const _state = window._giftGetStateForFriend(f.uid);
  if(!_state.canSend){
    bannerFX(null, '⛔ ' + _state.reason, '#ff8844', 2200);
    return;
  }
  if(!window._giftCanAfford(g)){
    bannerFX(null, '❌ 你的 ' + g.name + ' 數量不足', '#ff6644', 2200);
    return;
  }

  // 扣自己持有量
  // ★ v3.12.2(2026-05-30) — 'crystal' 通道走 backpack('summon_crystal')
  try{
    const c = g.cost;
    if(c.type === 'coins'){
      _knowledgeCoins = Math.max(0, (_knowledgeCoins||0) - c.amount);
      try{ if(typeof _logCoinTx === 'function') _logCoinTx(-c.amount, '送禮:給 ' + String((f && (f.name || f.email)) || '好友').slice(0, 16)); }catch(_){}   // ★ v5.247.0
      if(typeof _syncCoinsDisplay === 'function') _syncCoinsDisplay();
    } else if(c.type === 'crystal'){
      if(typeof backpackRemove === 'function') backpackRemove('summon_crystal', c.amount, '送禮給 ' + String((f && (f.name || f.email)) || '好友').slice(0, 16));
      if(typeof _syncSummonCrystalDisplay === 'function') _syncSummonCrystalDisplay();
    } else if(c.type === 'backpack' && c.key){
      if(typeof backpackRemove === 'function') backpackRemove(c.key, c.amount);
    }
  }catch(eDeduct){ console.error('[v3.12.0 送禮扣自己]', eDeduct); }

  // 寫入對方 pendingGifts(跨玩家 Firestore 寫入,需要 Rules 開放)
  let _sentOk = false;
  // ★ v3.14.4 — 勉勵話索引(老師需求 3):取 dialog 勾選,預設 0
  const _msgIdxSel = (typeof window._giftSelMsgIdx === 'number'
                      && window._giftSelMsgIdx >= 0 && window._giftSelMsgIdx <= 4)
    ? Math.floor(window._giftSelMsgIdx) : 0;
  try{
    if(typeof window._fbSendGift === 'function'){
      _sentOk = await window._fbSendGift(f.uid, {
        from: window._gUserId,
        fromName: (window._fbUser && (window._fbUser.displayName || window._fbUser.email))
                  || window._gUserEmail || '好友',
        itemId: g.id,
        deliver: g.deliver,
        ts: Date.now(),
        msgIdx: _msgIdxSel,  // ★ v3.14.4 — 勉勵話
      });
    }
  }catch(eSend){ console.error('[v3.12.0 寫入 pendingGifts]', eSend); }

  if(!_sentOk){
    // 寫入失敗 → 把扣掉的還回去,提示老師(Rules 沒開)
    // ★ v3.12.2(2026-05-30) — 'crystal' 通道改走 backpack
    try{
      const c = g.cost;
      if(c.type === 'coins'){
        _knowledgeCoins = (_knowledgeCoins||0) + c.amount;
        try{ if(typeof _logCoinTx === 'function') _logCoinTx(c.amount, '退款:送禮失敗'); }catch(_){}   // ★ v5.247.0
        if(typeof _syncCoinsDisplay === 'function') _syncCoinsDisplay();
      } else if(c.type === 'crystal'){
        if(typeof backpackAdd === 'function') backpackAdd('summon_crystal', c.amount, '送禮失敗退回');
        if(typeof _syncSummonCrystalDisplay === 'function') _syncSummonCrystalDisplay();
      } else if(c.type === 'backpack' && c.key){
        if(typeof backpackAdd === 'function') backpackAdd(c.key, c.amount);
      }
    }catch(_eRefund){}
    bannerFX(null, '⚠ 送禮未成功(已自動退還):可能今日已送過此好友,或請老師確認 Firestore 設定', '#ff8844', 4200);
    return;
  }

  // 記錄今日送過
  window._giftMaybeResetHistory();
  window._giftHistory.sentUids = window._giftHistory.sentUids || [];
  if(window._giftHistory.sentUids.indexOf(f.uid) < 0){
    window._giftHistory.sentUids.push(f.uid);
  }
  // ★ v3.14.4 — 寫入送禮記錄(老師需求 2:7 天內送出/收到記錄)
  try{
    if(typeof window._giftLogAdd === 'function'){
      window._giftLogAdd('sent', {
        uid: f.uid,
        name: (typeof window._getFriendLabel === 'function')
          ? window._getFriendLabel(f.email || '', f.name || '')
          : (f.name || f.email || '好友'),
        giftName: g.name, icon: g.icon, heart: g.heart,
        msgIdx: _msgIdxSel, ts: Date.now(),
      });
    }
  }catch(_eGl){ console.warn('[送禮記錄 v3.14.4] sent 記錄失敗', _eGl); }
  // ★ v3.13.94 — 送禮寫入活動紀錄(供 GM 查證送禮次數)
  try{
    if(typeof window._logActivity === 'function'){
      window._logActivity('gift_sent', {
        toUid: (f.uid || '').slice(0,12),
        toName: f.name || f.email || '',
        gift: (g && (g.id || g.name)) || '',
        heart: (g && g.heart) || 0
      });
    }
  }catch(_eGiftLog){}

  // 加友情之心(內部會處理 100 → SSR 卷邏輯 + 雲端同步)
  // ★ v5.31.0 — 堆疊物受贈抵銷帳(handoff 裁定):送出的若是「曾受贈且尚未抵銷完」的同款堆疊物 → 本次不加心
  //   (防 A↔B 原樣互送刷心;coins 禮包不追蹤維持原狀)
  let _heartToAdd = g.heart;
  try{
    const _ck = (g.cost && g.cost.type === 'crystal') ? 'summon_crystal'
              : (g.cost && g.cost.type === 'backpack' && g.cost.key) ? g.cost.key : null;
    if(_ck && typeof window._giftRecvLedgerConsume === 'function'
       && window._giftRecvLedgerConsume(_ck, (g.cost.amount || 1))){
      _heartToAdd = 0;
      try{ bannerFX(null, '💔 這份是好友送你的同款禮物,回送不加友情之心(禮物照常送達)', '#ffaacc', 3200); }catch(_){}
    }
  }catch(_eLcs){}
  if(_heartToAdd > 0) await window._giftAddHeart(_heartToAdd);

  // 雲端同步存檔(把 _giftHistory 寫雲端 + 扣完的資源)
  try{ if(typeof gameCloudSave === 'function') gameCloudSave(); }catch(_){}

  // UI 反饋
  const _friendLabel = (typeof window._getFriendLabel === 'function')
    ? window._getFriendLabel(f.email || '', f.name || '')
    : (f.name || f.email || '好友');
  if(typeof bannerFX === 'function'){
    bannerFX(null, '🎁 已送 ' + g.name + ' 給 ' + _friendLabel + '!+' + g.heart + ' 💕', '#ffcc66', 2800);
  }
  if(typeof playSfx === 'function') playSfx('sfx-coin', 0.65);

  // 更新今日送出次數顯示
  try{
    const _cntEl = document.getElementById('_gift-today-count');
    if(_cntEl) _cntEl.textContent = window._giftGetTodayCount();
  }catch(_){}

  // 關閉送禮 modal
  const _giftOv = document.getElementById('_gift-dialog');
  if(_giftOv) _giftOv.remove();

  // 重渲好友面板(讓該好友的「🎁 送禮」按鈕變灰)
  try{
    if(typeof _refreshFriendListInner === 'function') _refreshFriendListInner();
  }catch(_){}
};

// 收禮端 ── 領取所有 pending gifts(onAuth hook 觸發)
window._giftClaimPendingGifts = async function(){
  if(!window._gUserId) return;

  // ★ v3.13.10(2026-06-01)— 收集禮物資訊,迴圈結束後一次顯示彙整 modal
  const _giftSummary = [];

  // ★ v3.13.16 — 世界 BOSS 每日入場券:改由「登入領禮流程」統一發放(每次登入都會跑,
  //   含自動續登,比進度彈窗可靠),並把結果以「系統禮物」併入好友禮物清單;達上限 5/5 也顯示。
  //   注意:grantDailyTickets 直接寫雲端,這裡必須同步本地 _playerBackpack,
  //   否則本函式結尾的 gameCloudSave 會用舊的本地背包覆蓋掉剛發的券。
  try{
    if(window._wbDailyLimit && typeof window._wbDailyLimit.grantDailyTickets === 'function'){
      const _tk = await window._wbDailyLimit.grantDailyTickets();
      if(_tk){
        const _maxT = (typeof window._wbDailyLimit.getTicketMax === 'function')
          ? window._wbDailyLimit.getTicketMax() : 5;
        // 同步本地背包到雲端權威值(避免 gameCloudSave 覆蓋)
        try{
          if(typeof _playerBackpack === 'object' && _playerBackpack
             && (_tk.reason === 'ok' || _tk.reason === 'already_granted_today')){
            if((_tk.total || 0) > 0) _playerBackpack['wb_entry_ticket'] = _tk.total;
            else delete _playerBackpack['wb_entry_ticket'];
          }
        }catch(_eSync){ console.warn('[v3.13.16 入場券本地同步]', _eSync); }
        // 組系統禮物項目
        if(_tk.granted > 0){
          _giftSummary.push({
            fromName: '🎟️ 世界 BOSS 每日場次',
            content: '🎟️ 世界 BOSS 挑戰入場券 ×' + _tk.granted
              + '(昨日沒用完的場次轉換,目前持有 ' + _tk.total + '/' + _maxT + ')',
            replacedByCoins: false
          });
        } else if(_tk.reason === 'ok' && (_tk.unused || 0) > 0 && (_tk.total || 0) >= _maxT){
          _giftSummary.push({
            fromName: '🎟️ 世界 BOSS 每日場次',
            content: '🎟️ 挑戰入場券已達上限 ' + _tk.total + '/' + _maxT
              + '(昨日仍有沒打完的場次,但已滿無法再轉換 — 先用掉幾張再來累積吧!)',
            replacedByCoins: false
          });
        }
      }
    }
  }catch(_eTk){ console.warn('[v3.13.16 每日入場券發放/顯示]', _eTk); }

  // 讀好友跨玩家 pendingGifts(Firestore)
  let gifts = [];
  if(typeof window._fbReadPendingGifts === 'function'){
    try{
      gifts = await window._fbReadPendingGifts(window._gUserId);
    }catch(eRead){ console.warn('[v3.12.0 讀取 pendingGifts]', eRead); gifts = []; }
  }
  if(gifts && gifts.length > 0){
    console.log('[v3.12.0] 領取 pendingGifts 共 ' + gifts.length + ' 筆');
  }

  // 逐筆領取
  for(let i = 0; i < gifts.length; i++){
    const _gift = gifts[i];
    // ★ v5.31.0 — 裝備 Phase 4:裝備禮物分支(deliver.type='gear' 攜整顆實例;不在 _GIFT_CATALOG,須先於查表處理)
    if(_gift && _gift.deliver && _gift.deliver.type === 'gear'){
      let _gr = { ok:false, text:'' };
      try{ if(typeof window._gearReceiveGift === 'function') _gr = window._gearReceiveGift(_gift); }catch(_eGr){ console.error('[裝備收禮]', _eGr); }
      if(_gr.ok){
        const _fromNameG = _gift.fromName || '好友';
        const _msgIdxG = (typeof _gift.msgIdx === 'number' && _gift.msgIdx >= 0 && _gift.msgIdx <= 4) ? Math.floor(_gift.msgIdx) : -1;
        _giftSummary.push({ fromName:_fromNameG, content:_gr.text, replacedByCoins:!!_gr.replaced,
          msgText:(_msgIdxG >= 0 && Array.isArray(window._GIFT_MESSAGES)) ? (window._GIFT_MESSAGES[_msgIdxG] || '') : '' });
        try{
          if(typeof window._giftLogAdd === 'function'){
            window._giftLogAdd('recv', { uid:_gift.from || '', name:_fromNameG, giftName:'裝備禮物', icon:'🛡️', heart:0, msgIdx:_msgIdxG, ts:_gift.ts || Date.now() });
          }
        }catch(_){}
        try{
          if(typeof window._fbDeletePendingGift === 'function' && _gift.docId){
            await window._fbDeletePendingGift(window._gUserId, _gift.docId);
          }
        }catch(eDelG){ console.warn('[裝備收禮 刪 pendingGift]', eDelG); }
      }
      continue;   // 失敗(GEAR_DB 未載/驗證不過)→ 保留 pendingGift 待下次登入再領,不刪不吞
    }
    const _giftDef = (window._GIFT_CATALOG || []).find(x => x.id === _gift.itemId);
    if(!_giftDef){
      console.warn('[v3.12.0 領禮] 找不到禮物定義,跳過', _gift.itemId);
      continue;
    }

    // 嘗試發放
    // ★ v3.12.2(2026-05-30) — 'crystal' 通道改走 backpack + 99 上限保護
    let _actualGiven = '';
    let _replacedByCoins = false;
    try{
      const d = _gift.deliver || _giftDef.deliver;
      if(d.type === 'coins'){
        _knowledgeCoins = (_knowledgeCoins||0) + d.amount;
        try{ if(typeof _logCoinTx === 'function') _logCoinTx(d.amount, '收禮:好友送的知識幣'); }catch(_){}   // ★ v5.247.0
        _actualGiven = '💰 ' + d.amount.toLocaleString() + ' 知識幣';
      } else if(d.type === 'crystal'){
        // ★ v3.12.2 — 走 backpack('summon_crystal')+ 99 上限保護(對齊背包物品)
        const _curHave = (typeof backpackGet === 'function') ? backpackGet('summon_crystal') : 0;
        const _canAdd = Math.min(d.amount, Math.max(0, 99 - _curHave));
        if(_canAdd > 0 && typeof backpackAdd === 'function'){
          backpackAdd('summon_crystal', _canAdd, '收到好友送禮');
        }
        try{ if(typeof window._giftRecvLedgerAdd === 'function') window._giftRecvLedgerAdd('summon_crystal', _canAdd); }catch(_){}   // ★ v5.31.0 抵銷帳
        const _overflow = d.amount - _canAdd;
        if(_overflow > 0){
          _knowledgeCoins = (_knowledgeCoins||0) + 3000;
          try{ if(typeof _logCoinTx === 'function') _logCoinTx(3000, '收禮:水晶已滿轉幣'); }catch(_){}   // ★ v5.247.0
          _replacedByCoins = true;
        }
        _actualGiven = (_canAdd > 0 ? '💎 召喚水晶 ×' + _canAdd : '')
          + (_replacedByCoins ? (_canAdd > 0 ? ' + ' : '') + '💰 3,000 知識幣(水晶已滿,自動兌換)' : '');
        if(typeof _syncSummonCrystalDisplay === 'function') _syncSummonCrystalDisplay();
      } else if(d.type === 'backpack' && d.key){
        // 99 上限保護:滿了自動轉 3000 幣
        const _curHave = (typeof backpackGet === 'function') ? backpackGet(d.key) : 0;
        const _canAdd = Math.min(d.amount, Math.max(0, 99 - _curHave));
        if(_canAdd > 0){
          if(typeof backpackAdd === 'function') backpackAdd(d.key, _canAdd);
          try{ if(typeof window._giftRecvLedgerAdd === 'function') window._giftRecvLedgerAdd(d.key, _canAdd); }catch(_){}   // ★ v5.31.0 抵銷帳
          // ★ v3.13.95 — 收到的若是靈魂碎片:記活動紀錄(★ v3.15.42 乙:改手動合成,不再自動換券)
          try{
            if(d.key === 'soul_shard_ssr' || d.key === 'soul_shard_sr'){
              const _sr = (d.key === 'soul_shard_ssr') ? 'ssr' : 'sr';
              if(typeof window._logActivity === 'function') window._logActivity('shard', { rarity:_sr, amount:_canAdd, source:'gift_received' });
            }
          }catch(_eShardGift){}
        }
        const _overflow = d.amount - _canAdd;
        if(_overflow > 0){
          _knowledgeCoins = (_knowledgeCoins||0) + 3000;
          try{ if(typeof _logCoinTx === 'function') _logCoinTx(3000, '收禮:背包已滿轉幣'); }catch(_){}   // ★ v5.247.0
          _replacedByCoins = true;
        }
        const _bpDef = (typeof BACKPACK_ITEM_DEF !== 'undefined') ? BACKPACK_ITEM_DEF[d.key] : null;
        const _name = _bpDef ? _bpDef.name : d.key;
        _actualGiven = (_canAdd > 0 ? (_bpDef && _bpDef.icon ? _bpDef.icon + ' ' : '') + _name + ' ×' + _canAdd : '')
          + (_replacedByCoins ? (_canAdd > 0 ? ' + ' : '') + '💰 3,000 知識幣(背包已滿,自動兌換)' : '');
      }
    }catch(eDeliver){ console.error('[v3.12.0 發禮失敗]', eDeliver); continue; }

    // ★ v3.13.10(2026-06-01)— 改成「彙整列表 modal」而非逐筆 bannerFX
    //   原版每筆禮物 bannerFX(null, ..., 5000) 全部用相同的 position:fixed top:8vw
    //   N 筆禮物完全疊在同一個位置 + 5 秒後一起消失 → 玩家只看到第一筆
    //   新版:累積到 _giftSummary,迴圈結束後用 _showGiftSummaryModal 一次顯示完整列表
    const _fromName = _gift.fromName || '好友';
    // ★ v3.14.4 — 勉勵話(老師需求 3:收到時顯示,備感溫馨)
    const _msgIdxRecv = (typeof _gift.msgIdx === 'number'
                         && _gift.msgIdx >= 0 && _gift.msgIdx <= 4)
      ? Math.floor(_gift.msgIdx) : -1;
    const _msgTextRecv = (_msgIdxRecv >= 0 && Array.isArray(window._GIFT_MESSAGES))
      ? (window._GIFT_MESSAGES[_msgIdxRecv] || '') : '';
    _giftSummary.push({
      fromName: _fromName,
      content: _actualGiven,
      replacedByCoins: _replacedByCoins,
      msgText: _msgTextRecv,  // ★ v3.14.4
    });
    // ★ v3.14.4 — 寫入送禮記錄(recv,老師需求 2:可從記錄直接回禮)
    try{
      if(typeof window._giftLogAdd === 'function'){
        window._giftLogAdd('recv', {
          uid: _gift.from || '',
          name: _fromName,
          giftName: _giftDef.name, icon: _giftDef.icon, heart: 0,
          msgIdx: _msgIdxRecv, ts: _gift.ts || Date.now(),
        });
      }
    }catch(_eGlR){ console.warn('[送禮記錄 v3.14.4] recv 記錄失敗', _eGlR); }

    // 從 Firestore 刪掉這筆已領取的禮物
    try{
      if(typeof window._fbDeletePendingGift === 'function' && _gift.docId){
        await window._fbDeletePendingGift(window._gUserId, _gift.docId);
      }
    }catch(eDel){ console.warn('[v3.12.0 刪 pendingGift]', eDel); }
  }

  // 同步顯示 + 雲端
  try{
    if(typeof _syncCoinsDisplay === 'function') _syncCoinsDisplay();
    if(typeof gameCloudSave === 'function') gameCloudSave();
  }catch(_){}

  // ★ v3.13.10(2026-06-01)— 一次顯示彙整 modal(取代 N 個疊在一起的 bannerFX)
  if(_giftSummary.length > 0){
    try{ _showGiftSummaryModal(_giftSummary); }catch(_eGsm){ console.warn('[v3.13.10 顯示禮物彙整 modal] 失敗', _eGsm); }
  }
};

// ════════════════════════════════════════════════════════════════════
// ★ v3.13.10(2026-06-01)— 好友禮物彙整 modal
//   取代原本「逐筆 bannerFX」造成的全部疊在一起的問題,
//   改用單一 modal 列出所有禮物,玩家按確認鍵領取。
//   支援多筆滾動顯示;每筆顯示「送禮人 + 禮物內容」+「水晶/背包滿 自動兌換」提示。
// ════════════════════════════════════════════════════════════════════
function _showGiftSummaryModal(giftList){
  if(!Array.isArray(giftList) || giftList.length === 0) return;

  // 移除已存在的 modal(防 race 多開)
  try{
    const _oldOv = document.getElementById('_gift-summary-modal');
    if(_oldOv) _oldOv.remove();
  }catch(_){}

  const _ov = document.createElement('div');
  _ov.id = '_gift-summary-modal';
  _ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.85);z-index:2147483640;'
    + 'display:flex;align-items:center;justify-content:center;'
    + 'padding:20px;font-family:inherit;';

  // 列出禮物項目
  const _itemsHtml = giftList.map((g, idx) => {
    const _safeFrom = String(g.fromName || '好友').replace(/[<>&"']/g, function(c){
      return { '<':'&lt;', '>':'&gt;', '&':'&amp;', '"':'&quot;', "'":'&#39;' }[c];
    });
    // ★ v3.14.4 — 勉勵話顯示(老師需求 3)
    const _safeMsg = g.msgText
      ? String(g.msgText).replace(/[<>&"']/g, function(c){
          return { '<':'&lt;', '>':'&gt;', '&':'&amp;', '"':'&quot;', "'":'&#39;' }[c];
        })
      : '';
    return '<div style="background:rgba(255,200,80,0.12);border:1.5px solid rgba(255,200,80,0.6);'
      + 'border-radius:10px;padding:12px 14px;margin-bottom:10px;display:flex;align-items:center;gap:10px;">'
      + '<div style="font-size:24px;flex-shrink:0;">🎁</div>'
      + '<div style="flex:1;min-width:0;">'
      + '<div style="color:#ffe066;font-weight:700;font-size:14px;margin-bottom:3px;">'
      + '來自 ' + _safeFrom + '</div>'
      + '<div style="color:#fff;font-size:14px;word-break:break-word;">'
      + (g.content || '(內容未知)') + '</div>'
      + (_safeMsg
          ? '<div style="margin-top:6px;color:#ffb8dd;font-size:13.5px;font-weight:700;'
            + 'background:rgba(255,140,200,0.12);border-left:3px solid rgba(255,150,210,0.7);'
            + 'border-radius:6px;padding:5px 10px;">💌 「' + _safeMsg + '」</div>'
          : '')
      + '</div>'
      + '</div>';
  }).join('');

  _ov.innerHTML = '<div style="background:linear-gradient(135deg,#2a1f10,#3a2a18);'
    + 'border:2.5px solid #ffcc66;border-radius:16px;'
    + 'max-width:min(92vw,500px);max-height:85vh;width:100%;'
    + 'box-shadow:0 8px 32px rgba(255,200,80,0.3),0 0 60px rgba(255,200,80,0.15);'
    + 'display:flex;flex-direction:column;overflow:hidden;">'
    + '<div style="padding:18px 20px 12px;text-align:center;border-bottom:1.5px solid rgba(255,200,80,0.3);">'
    + '<div style="font-size:28px;margin-bottom:5px;">🎁🎊🎁</div>'
    + '<div style="color:#ffcc66;font-size:18px;font-weight:800;letter-spacing:1px;">'
    + '你有 ' + giftList.length + ' 份獎勵 / 禮物!</div>'
    + '<div style="color:#ffe066;font-size:12px;margin-top:4px;opacity:0.85;">'
    + '詳情如下 👇</div>'
    + '</div>'
    + '<div style="padding:14px 16px;overflow-y:auto;flex:1;">'
    + _itemsHtml
    + '</div>'
    + '<div style="padding:12px 16px;border-top:1.5px solid rgba(255,200,80,0.3);text-align:center;">'
    + '<button id="_gift-summary-ok" style="padding:10px 32px;font-size:15px;font-weight:800;'
    + 'background:linear-gradient(135deg,#ffcc66,#ffaa44);color:#1a1108;'
    + 'border:none;border-radius:10px;cursor:pointer;font-family:inherit;'
    + 'box-shadow:0 3px 12px rgba(255,200,80,0.5);">確認領取</button>'
    + '</div>'
    + '</div>';

  document.body.appendChild(_ov);

  const _btn = document.getElementById('_gift-summary-ok');
  if(_btn){
    _btn.onclick = function(){
      try{ _ov.remove(); }catch(_){}
    };
  }

  // 點外層也可關閉
  _ov.onclick = function(e){
    if(e.target === _ov){
      try{ _ov.remove(); }catch(_){}
    }
  };

  // 播一次愉悅音效(只一次,不疊)
  try{
    if(typeof playSfx === 'function') playSfx('sfx-coin', 0.7);
  }catch(_){}
}
// ════════════════════════════════════════════════════════════════════
// ★ v3.12.0 — 好友送禮系統結束
// ════════════════════════════════════════════════════════════════════

// ★ v1.0.20260424.1150 — 用邀請碼加好友(取代 email 查詢)
async function _addFriendByInviteCode(){
  // ★ v3.5.53 — 3 秒冷卻(加好友本來就是慢動作,防 spam)
  if(!window._btnCooldown('add_friend', 3000)) return;
  const input = document.getElementById('_add-friend-input');
  if(!input){
    bannerFX(null, '❌ 找不到輸入框,請重新開啟好友面板', '#ff6666', 2000);
    return;
  }
  const code = input.value.trim().toUpperCase();
  if(!code){
    bannerFX(null, '請輸入好友的 8 碼邀請碼', '#ff9944', 1500);
    // ★ FIX 20260518 — preventScroll 防止頁面被捲動
    try{ input.focus({preventScroll:true}); }catch(_){ try{ input.focus(); }catch(_){} }
    return;
  }
  if(code.length !== 8){
    bannerFX(null, '邀請碼必須是 8 個字元', '#ff6666', 1800);
    return;
  }
  // 檢查格式(只允許英文+數字)
  if(!/^[A-Z0-9]+$/.test(code)){
    bannerFX(null, '邀請碼只能含英文字母和數字', '#ff6666', 1800);
    return;
  }
  // 不能加自己
  if(code === window._myInviteCode){
    bannerFX(null, '不能加自己為好友!', '#ff6666', 1500);
    return;
  }
  if(!window._gUserId){
    bannerFX(null, '請先登入再加好友', '#ff6666', 2000);
    return;
  }
  if(!window._fbFindByInviteCode){
    bannerFX(null, '好友功能載入中,請稍後再試', '#ff9944', 2000);
    return;
  }
  try{
    bannerFX(null, '🔍 搜尋中...', '#88ccff', 2000);
    let found = null;
    try{
      found = await window._fbFindByInviteCode(code);
    } catch(qErr){
      console.error('[查詢好友]', qErr);
      const _msg = '查詢失敗:' + (qErr.code || qErr.message || '網路錯誤');
      bannerFX(null, _msg, '#ff6666', 4000);
      return;
    }
    if(!found){
      // ★ v5.136.0 — 走到這裡代表「原碼與易混淆別名都查不到」(別名 fallback 在 _fbFindByInviteCode 內)。
      //   ⇒ 剩下的可能是:對方代碼還沒同步到雲端、或抄錯的不是 0/O/1/I/L 這五個字。
      //   舊文案只說「請確認邀請碼正確」,學生只會一直重打同一組。改為指出具體該怎麼做。
      bannerFX(null,
        '找不到邀請碼「' + code + '」\n' +
        '① 請同學用「點一下代碼複製」的方式傳給你,不要用手抄\n' +
        '② 若同學剛登入,請他重新整理一次再給你代碼',
        '#ff6666', 5000);
      return;
    }
    if(!found.uid){
      bannerFX(null, '查詢結果異常,請回報', '#ff6666', 3000);
      return;
    }
    // 已是好友
    if(_friendList.some(f => f.uid === found.uid)){
      bannerFX(null, '已是好友了!', '#ffcc44', 1500);
      return;
    }
    const friendInfo = {
      uid: found.uid,
      email: found.email || '',  // email 雖不再用於查詢但仍存著做識別
      name: found.displayName || found.email || ('好友 ' + code),
      inviteCode: code
    };
    await window._fbAddFriend(window._gUserId, friendInfo);
    _friendList.push(friendInfo);
    bannerFX(null, '✅ 已加 ' + friendInfo.name + ' 為好友!', '#44ff88', 1800);
    playSfx('sfx-confirm', 0.6);
    input.value = '';
    _renderFriendPanel();
  }catch(e){
    console.error('[加好友]', e);
    bannerFX(null, '加好友失敗:' + (e.message || '未知錯誤'), '#ff6666', 3000);
  }
}

async function _addFriendByEmail() {
  // ★ v3.5.53 — 3 秒冷卻(共用 add_friend key,跟邀請碼版同一冷卻)
  if(!window._btnCooldown('add_friend', 3000)) return;
  const input = document.getElementById('_add-friend-input');
  if (!input) {
    bannerFX(null, '❌ 找不到輸入框，請重新開啟好友面板', '#ff6666', 2000);
    return;
  }
  const email = input.value.trim().toLowerCase();
  if (!email) {
    bannerFX(null, '請輸入好友的 Gmail 帳號', '#ff9944', 1500);
    // ★ FIX 20260518 — preventScroll 防止頁面被捲動
    try{ input.focus({preventScroll:true}); }catch(_){ try{ input.focus(); }catch(_){} }
    return;
  }
  if (!email.includes('@')) {
    bannerFX(null, '請輸入有效的 Gmail 帳號', '#ff6666', 1500);
    return;
  }
  if (email === (window._fbUser && window._fbUser.email && window._fbUser.email.toLowerCase())) {
    bannerFX(null, '不能加自己為好友', '#ff6666', 1500);
    return;
  }
  if (_friendList.some(f => f.email === email)) {
    bannerFX(null, '已是好友了！', '#ffcc44', 1500);
    return;
  }
  // ★ 防呆：確認 Firebase 已初始化
  if (!window._gUserId) {
    bannerFX(null, '請先登入再加好友', '#ff6666', 2000);
    return;
  }
  if (!window._fbFindByEmail) {
    bannerFX(null, '好友功能載入中，請稍後再試', '#ff9944', 2000);
    console.warn('[加好友] _fbFindByEmail 尚未就緒', Object.keys(window).filter(k=>k.startsWith('_fb')));
    return;
  }
  // ★ 鎖定按鈕避免重複點擊
  const btn = document.querySelector('#_friend-panel button[onclick="_addFriendByEmail()"]');
  if (btn) { btn.disabled = true; btn.textContent = '搜尋中...'; }
  try {
    bannerFX(null, '🔍 搜尋中...', '#88ccff', 2000);
    let found = null;
    try {
      found = await window._fbFindByEmail(email);
    } catch(qErr) {
      console.error('[查詢好友]', qErr);
      // ★ v1.0.20260424.1100 — 詳細錯誤訊息(網路/權限/Firestore 索引等)
      const _msg = '查詢失敗:' + (qErr.code || qErr.message || '網路錯誤');
      bannerFX(null, _msg, '#ff6666', 4000);
      console.warn('[加好友] 玩家可參考 console 訊息回報問題');
      return;
    }
    if (!found) {
      // ★ v1.0.20260424.1100 — 找不到時提示更清楚:可能原因
      bannerFX(null, '找不到「' + email + '」\n請確認:1) 完整 Gmail 2) 對方至少登入過一次', '#ff6666', 4500);
      console.warn('[加好友] 找不到 email:', email,
                    '→ 對方須登入過遊戲,且帳號的 email 欄位已寫入 players collection');
      return;
    }
    if(!found.uid) {
      bannerFX(null, '查詢結果異常(無 uid),請回報', '#ff6666', 3000);
      console.error('[加好友] found 缺 uid:', found);
      return;
    }
    const friendInfo = { uid: found.uid, email: found.email || email, name: found.displayName || email };
    await window._fbAddFriend(window._gUserId, friendInfo);
    _friendList.push(friendInfo);
    bannerFX(null, '✅ 已加 ' + friendInfo.name + ' 為好友！', '#44ff88', 1800);
    playSfx('sfx-confirm', 0.6);
    _renderFriendPanel();
  } catch(e) {
    console.error('[加好友]', e);
    bannerFX(null, '加好友失敗：' + (e.code || e.message || '未知錯誤'), '#ff6666', 3000);
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = '+ 加好友'; }
  }
}

async function _deleteFriend(idx) {
  const f = _friendList[idx];
  if (!f) return;
  await window._fbRemoveFriend(window._gUserId, f);
  _friendList.splice(idx, 1);
  delete _friendHeroData[f.uid];
  bannerFX(null, `已刪除好友 ${f.name || f.email}`, '#aaa', 1500);
  _renderFriendPanel();
}

// ── 邀請好友英雄：注入選角頁 ──
function _inviteFriendHero(idx) {
  const f = _friendList[idx];
  if (!f) return;
  const fd = _friendHeroData[f.uid];
  if (!fd || !fd.representativeHero) {
    bannerFX(null, `${f.name || f.email} 尚未設定代表英雄`, '#ff9944', 2000);
    return;
  }
  _invitedFriendHero = { ...fd.representativeHero, _ownerName: f.name || f.email, _ownerUid: f.uid };
  // ★★ v4.90.0(老師裁定 Q5乙·安全關鍵)—— 借來的「主角」必須改成唯一引擎名。
  //   根因:好友借用機制全檔用英雄名字認人(_invitedFriendHero.name === name 有10+處),
  //         而每位玩家的主角都叫「主角」→ 借好友主角時會連自己的主角一起被誤判成好友英雄
  //         → 自己主角的投資/至寶/等級全不套用、打完不給經驗;同隊兩隻同名更會讓技能/爆發等級查表撞在一起。
  //   解法:給唯一別名(好友·<暱稱> / 主角好友)+複製資料表條目(比照既有「主角‧覺醒」別名做法),
  //         名稱唯一後上述 10 幾個既有咀喉點完全不必動 → 零回歸。
  try{
    if(window._isProtagHero && window._isProtagHero(_invitedFriendHero.name)){
      var _fpNick = '';
      try{ _fpNick = (fd.avatarCard && fd.avatarCard.nick) ? fd.avatarCard.nick : (f.name || ''); }catch(_){}
      var _alias = window._pgiFriendProtagName(_fpNick);
      window._pgiEnsureFriendProtagAlias(_alias, { pgi: (fd.representativeHero && fd.representativeHero.pgi) ? fd.representativeHero.pgi : null });
      _invitedFriendHero.name = _alias;
      _invitedFriendHero._dispName = _alias;
      // 好友自己的爆發繼承來源(隨代表英雄快照帶過來·不吃我的 BD)
      try{
        if(fd.representativeHero && fd.representativeHero.pgi && fd.representativeHero.pgi.burst)
          _invitedFriendHero._pgiBurstSrc = fd.representativeHero.pgi.burst;
      }catch(_){}
    }
  }catch(_ePgiFP){ console.warn('[v4.90.0 好友主角別名]', _ePgiFP); }
  bannerFX(null, `🤝 已邀請 ${f.name} 的 ${fd.representativeHero.name}！去選角頁挑選隊友吧！`, '#ff88cc', 2500);
  playSfx('sfx-confirm', 0.7);
  const panel = document.getElementById('_friend-panel');
  if (panel) panel.remove();
  // 更新好友按鈕顯示邀請中的英雄名
  const badge = document.getElementById('adv-friend-badge');
  if (badge) { badge.style.display = 'block'; badge.textContent = '1'; }
}

// ── 選角頁：加入好友英雄卡 ──
function _injectFriendHeroCard() {
  // ★ v3.5.26(2026-05-22) — 世界 BOSS 戰禁用好友協助角色(第三道防線)
  //   雖然世界 BOSS 戰另走 world-boss-ui.html 選角(不會走進這函式),
  //   但保險起見加判定,避免任何路徑誤插入好友卡。
  try{
    if(typeof _adventureStage !== 'undefined' && _adventureStage === 'worldboss'){
      console.log('[v3.5.26] _injectFriendHeroCard: 世界 BOSS 戰偵測,不渲染好友卡');
      return;
    }
  }catch(_){}
  const grid = document.querySelector('.hpick-adv-grid') || document.querySelector('.hpick-arena-grid');
  if (!grid || !_invitedFriendHero) return;
  // ★★ v5.106.0(老師裁定④)— 鬥技場也能借用好友英雄 ★★
  //   舊版本函式只找 `.hpick-adv-grid`,且呼叫點在 `if(_isAdventurePickMode){…return;}` 之內
  //   ⇒ 鬥技場編組頁根本不會出現好友卡。本輪改為兩種格子都支援,呼叫點也補到鬥技場分支。
  //   ★ 鬥技場一律 Lv1／技能爆發 Lv1／無裝備至寶寵物(老師裁定④),故卡片只顯示**純基礎值**,
  //     與 confirmHeroPick 的 `G.p1 = _heroPickSelected.map(newHero)` 完全一致(鐵律 1.153 公平制);
  //     顯示好友的養成強度會直接騙人(實戰吃不到),所以刻意不顯示、也不顯示至寶列。
  const _fbArena = !(window._isAdventurePickMode === true);
  // 移除舊的好友卡
  grid.querySelectorAll('.friend-hero-card').forEach(el => el.remove());

  const fh = _invitedFriendHero;
  const name = fh.name;
  const lv   = _fbArena ? 1 : (fh.level || 1);   // ★ v5.106.0 鬥技場強制 Lv1（與英雄池卡片同口徑）
  const img  = fh.img || (typeof HERO_IMGS !== 'undefined' ? HERO_IMGS[name] : '') || '';
  const av   = (typeof AVATARS !== 'undefined' && AVATARS[name]) || '🤝';

  // ★ FIX 20260518(g) — 計算真實能力 + 至寶數量,顯示在卡片上
  let _statsLine = '';
  let _treasureLine = '';
  try{
    if(typeof _calcFriendHeroStats === 'function'){
      // ★ v5.106.0 — 鬥技場走 baseOnly（純基礎·含妖王弱化）；冒險維持完整好友強度
      const s = _calcFriendHeroStats(fh, _fbArena ? { baseOnly:true } : null);
      _statsLine = `<div style="font-size:11px;text-align:center;padding:2px 4px;color:#ffe8a0;line-height:1.4;">`
        + `❤️${s.hp} ⚔${s.atk} ✨${s.sp} 💨${s.spd}</div>`;
      // ★ v5.106.0 — 鬥技場不吃至寶 ⇒ 不顯示至寶列（顯示了會讓學生以為有加成）
      if(!_fbArena && s.treasures && s.treasures.length > 0){
        const _trIcons = s.treasures.map(t => {
          const def = (typeof TAIWAN_TREASURES !== 'undefined') ? TAIWAN_TREASURES[t.id] : null;
          return def ? (def.icon || '💎') : '💎';
        }).join(' ');
        _treasureLine = `<div style="font-size:13px;text-align:center;padding:2px 4px;color:#ffcc66;">💎${_trIcons}</div>`;
      }
    }
  }catch(e){ console.warn('[好友卡] 計算能力失敗', e); }

  const node = document.createElement('div');
  node.className = (_fbArena ? 'hpick-arena-card friend-hero-card' : 'hpick-adv-node friend-hero-card');   /* ★ v5.106.0 兩種格子各用自己的 class（清除選擇器與版面才對得上） */
  node.style.cssText = 'position:relative;width:155px;cursor:pointer;border-radius:14px;overflow:hidden;'
    + 'border:2.5px solid rgba(255,130,200,0.9);background:rgba(30,5,20,0.95);'
    + 'transition:transform 0.15s,border-color 0.15s;flex-shrink:0;'
    + 'box-shadow:0 0 14px rgba(255,100,180,0.4);';
  node.innerHTML =
    (img ? `<img src="${img}" style="width:100%;height:120px;object-fit:cover;display:block;">` : `<div style="width:100%;height:120px;display:flex;align-items:center;justify-content:center;font-size:44px;">${av}</div>`)
    + `<div style="font-size:15px;text-align:center;padding:5px 3px 2px;color:#ffcce0;font-weight:700;line-height:1.3;"><span style="font-size:11px;color:#ff9ad0;background:rgba(255,100,180,0.22);border:1px solid rgba(255,130,200,0.8);border-radius:4px;padding:0 4px;margin-right:3px;font-weight:800;vertical-align:middle;">友</span>${name} <span style="font-size:13px;color:#ff99cc;font-weight:600;">Lv.${lv}</span></div>`
    + _statsLine
    + _treasureLine
    + `<div style="font-size:11px;text-align:center;padding:2px 4px 5px;color:#ff88cc;">🤝 ${fh._ownerName}</div>`
    // 粉紅握手圖示（右上角）
    + `<div style="position:absolute;top:4px;right:4px;background:rgba(255,100,180,0.9);border-radius:50%;`
    + `width:22px;height:22px;line-height:22px;text-align:center;font-size:13px;">🤝</div>`;

  node.onclick = () => _selectFriendHero(name);
  grid.insertBefore(node, grid.firstChild);
}

function _selectFriendHero(name) {
  if (!_invitedFriendHero || _invitedFriendHero.name !== name) return;
  // ★ 好友英雄直接佔用4格中的一格（與普通英雄相同邏輯）
  const alreadyIdx = _heroPickSelected.indexOf(name);
  if(alreadyIdx >= 0){
    // 取消選取
    _heroPickSelected.splice(alreadyIdx, 1);
    window._friendHeroInParty = false;
    bannerFX(null, `${name} 已取消加入`, '#aaa', 1200);
    playSfx('sfx-cancel', 0.5);
    const friendCard = document.querySelector('.friend-hero-card');
    if(friendCard){ friendCard.style.background='rgba(30,5,20,0.95)'; friendCard.style.borderColor='rgba(255,130,200,0.9)'; friendCard.querySelectorAll('[style*="#ff44aa"]').forEach(el=>el.remove()); }
    updatePickedBadges();
    document.getElementById('hero-pick-count').textContent=`請選擇 4 名英雄出戰（已選 ${_heroPickSelected.length} / 4）`;
    document.getElementById('hero-pick-confirm').disabled=_heroPickSelected.length<4;
    return;
  }
  if(_heroPickSelected.length >= 4){ bannerFX(null,'隊伍已滿（4人）','#ff8844',1200); return; }
  if (!window._friendHeroInParty) {
    window._friendHeroInParty = true;
    _heroPickSelected.push(name);
    updatePickedBadges();
    document.getElementById('hero-pick-count').textContent=`請選擇 4 名英雄出戰（已選 ${_heroPickSelected.length} / 4）`;
    document.getElementById('hero-pick-confirm').disabled=_heroPickSelected.length<4;
    bannerFX(null, `🤝 ${name} 加入隊伍！`, '#ff88cc', 1500);
    playSfx('sfx-confirm', 0.6);
    // 高亮友方卡片
    const friendCard = document.querySelector('.friend-hero-card');
    if (friendCard) {
      friendCard.style.background = 'rgba(80,5,40,0.95)';
      friendCard.style.borderColor = 'rgba(255,80,160,1)';
      const badge = document.createElement('div');
      badge.style.cssText = 'position:absolute;top:4px;left:4px;background:#ff44aa;color:#fff;font-size:12px;font-weight:900;border-radius:50%;width:20px;height:20px;line-height:20px;text-align:center;';
      badge.textContent = '✓';
      friendCard.appendChild(badge);
    }
  } else {
    // 取消
    window._friendHeroInParty = false;
    bannerFX(null, `${name} 已取消加入`, '#aaa', 1200);
    try{ updatePickedBadges(); }catch(_){}
    const friendCard = document.querySelector('.friend-hero-card');
    if (friendCard) {
      friendCard.style.background = 'rgba(30,5,20,0.95)';
      friendCard.style.borderColor = 'rgba(255,130,200,0.9)';
      friendCard.querySelectorAll('[style*="background:#ff44aa"]').forEach(el => el.remove());
    }
  }
}

// ── 戰鬥開始：將好友英雄加入 G.p1 ──
function _injectFriendHeroIntoBattle() {
  if (!_invitedFriendHero || !window._friendHeroInParty) return;
  // ★ v3.5.26(2026-05-22) — 世界 BOSS 戰禁用好友協助角色(雙重保險)
  //   即使有路徑繞過 advStartBattle 內的攔截,這裡也再擋一次。
  //   原因同上:防止借用高等好友英雄造成排行榜不公。
  try{
    if(typeof _adventureStage !== 'undefined' && _adventureStage === 'worldboss'){
      window._friendHeroInParty = false;
      console.log('[v3.5.26] _injectFriendHeroIntoBattle: 世界 BOSS 戰偵測,中止注入');
      return;
    }
  }catch(_){}
  // ★ v5.106.0(老師裁定④)— 第四道保險：非冒險模式（＝鬥技場）一律不注入好友養成資料。
  //   鬥技場本來就走 confirmHeroPick 的另一條分支、不會呼叫本函式；但既然 v5.106.0 起
  //   鬥技場也看得到好友卡了，這裡補一道守門，杜絕任何新入口誤呼叫而破壞公平制（鐵律 1.153）。
  try{
    if(!(typeof _adventureMode !== 'undefined' && _adventureMode === true
         && typeof _adventureStage !== 'undefined' && _adventureStage)){
      console.log('[v5.106.0] 非冒險模式(鬥技場)，好友英雄只借角色不借養成，跳過注入');
      return;
    }
  }catch(_eFbInj){}
  const fh = _invitedFriendHero;
  const name = fh.name;
  if (!name || typeof HERO_DB === 'undefined' || !HERO_DB[name]) return;
  // ★ 好友英雄已透過 _heroPickSelected 編入 G.p1，找到對應 hero 更新其屬性
  const existingHero = G.p1 ? G.p1.find(h => h.name === name) : null;
  const friendLv = fh.level || 1;
  // 計算好友等級的 HP 加成（線性 +2%/級，無條件進位；以好友投資後HP為基準）
  const applyFriendLvHpBonus = (hero, baseAfterInvest) => {
    if(friendLv <= 1) return 0;
    const bonus = Math.ceil(baseAfterInvest * 0.02 * (friendLv - 1));
    if(bonus > 0){
      hero.hp   += bonus;
      hero.curHp = hero.hp;
      hero._advLvHpBonus = bonus;
    }
    return bonus;
  };
  if(existingHero){
    // 先撤銷「_applyAdvLevelHpBonus」套用的本地玩家等級HP加成（若有）
    if(existingHero._advLvHpBonus){
      existingHero.hp   -= existingHero._advLvHpBonus;
      existingHero.curHp = existingHero.hp;
      existingHero._advLvHpBonus = 0;
    }
    // 套用好友的等級/素質/技能到已建立的英雄物件
    const inv = fh.statInvested || {};
    existingHero.hp  = Math.max(1, existingHero.hp  + (inv.hp  || 0));
    existingHero.atk = Math.max(1, existingHero.atk + (inv.atk || 0));
    existingHero.sp  = Math.max(1, existingHero.sp  + (inv.sp  || 0));
    existingHero.spd = Math.max(1, existingHero.spd + (inv.spd || 0));
    existingHero.curHp = existingHero.hp;
    // ★ v3.13.16 — 至寶必須在「等級HP加成」之前套用,讓至寶HP也吃 +2%/級
    //   (對齊卡片 _calcFriendHeroStats:等級加成基準 = 基礎+投資+至寶,完整反映好友強度)
    //   不能用 _applyTaiwanTreasureToHero,因為它讀本地玩家裝備資料
    try {
      _applyFriendTreasuresToHero(existingHero, fh.treasures);
    } catch(e){ console.warn('[好友至寶套用] 失敗', e); }
    // ★ 套用好友的等級HP加成（以「投資後+至寶後」的HP為基準）
    applyFriendLvHpBonus(existingHero, existingHero.hp);
    // 套用技能等級
    // ★ v3.13.88 — 一律設 _skLv(好友值,缺則 0)。舊版只在 fh.skillLevels 存在時才設,
    //   舊代表英雄資料(無 skillLevels)會讓 _skLv 留空 → execSkill fallback 讀本機同名技能等級
    //   → 好友英雄用到『本機玩家自己的技能等級』。改成一律設,杜絕 fallback。
    existingHero._skLv = {
      s1: (fh.skillLevels && fh.skillLevels.s1) || 0,
      s2: (fh.skillLevels && fh.skillLevels.s2) || 0
    };
    if(typeof fh.burstLevel !== 'undefined'){ existingHero._burstLvAdv = fh.burstLevel || 0; }
    else { existingHero._burstLvAdv = existingHero._burstLvAdv || 0; }
    existingHero._isFriendHero = true;
    // ★ v3.13.88 — 封鎖極限膠囊洩漏:好友英雄已套好友自己的數據,標記 _capsuleApplied 防止
    //   任何後續 _applyAdvLevelHpBonus 把『本機玩家的膠囊投資(_heroCapsuleInvested[同名])』加上去。
    existingHero._capsuleApplied = true;
    // ★ v5.275.0 好友命星:依好友代表英雄快照 cst 套用(唯讀;不讀本機命星)
    try{ if(typeof window._cstApplyFriend === 'function') window._cstApplyFriend(existingHero, fh); }catch(_eCstF){}
    log(`[好友英雄] ${name}（${fh._ownerName}）Lv.${friendLv} 屬性已套用！`);
    return;
  }
  // fallback: 若未在 G.p1 中（舊邏輯）
  const pos = G.p1.length;
  if (pos >= 4) { log('隊伍已滿，無法加入好友英雄'); return; }
  const h = typeof newHero === 'function' ? newHero(name, 'p1', pos) : null;
  if (!h) return;
  // 套用好友的素質加成
  const inv = fh.statInvested || {};
  h.hp  = Math.max(1, h.hp  + (inv.hp  || 0));
  h.atk = Math.max(1, h.atk + (inv.atk || 0));
  h.sp  = Math.max(1, h.sp  + (inv.sp  || 0));
  h.spd = Math.max(1, h.spd + (inv.spd || 0));
  h.curHp = h.hp;
  // ★ v3.13.16 — 至寶先套(在等級HP加成前),讓至寶HP也吃 +2%/級,對齊卡片顯示
  try {
    _applyFriendTreasuresToHero(h, fh.treasures);
  } catch(e){ console.warn('[好友至寶套用] 失敗', e); }
  // ★ 套用好友的等級HP加成（以投資後+至寶後HP為基準,完整反映好友強度）
  applyFriendLvHpBonus(h, h.hp);
  // 套用技能等級
  const skl = fh.skillLevels || {};
  h._skLv = { s1: skl.s1 || 0, s2: skl.s2 || 0 };
  // 套用爆發等級
  h._burstLvAdv = fh.burstLevel || 0;
  // 標記為好友英雄（UI顯示粉紅框）
  h._isFriendHero = true;
  h._friendOwner  = fh._ownerName;
  // ★ v3.13.88 — 封鎖極限膠囊洩漏(同 existing 路徑):防 _applyAdvLevelHpBonus 加上本機膠囊投資
  h._capsuleApplied = true;
  // ★ v5.275.0 好友命星(同上)
  try{ if(typeof window._cstApplyFriend === 'function') window._cstApplyFriend(h, fh); }catch(_eCstF2){}
  G.p1.push(h);
  log(`🤝 [好友英雄] ${name}（${fh._ownerName}）加入戰鬥！Lv.${friendLv}`);
}

function _applyFriendTreasuresToHero(h, treasures) {
  if (!h || !treasures || !Array.isArray(treasures) || !treasures.length) {
    h._treasureEff = h._treasureEff || {};
    return;
  }
  // ★ v3.15.71 — 好友英雄至寶件數(供鐵匠天賦「工匠魂」累計;借來的好友鐵匠/隊中有借來英雄裝至寶時正確計數)
  try{ h._twTreasureCount = treasures.length; }catch(_){}
  let _addHp = 0, _addAtk = 0, _addSp = 0, _addSpd = 0;
  const _eff = {};
  treasures.forEach(t => {
    if (!t) return;
    _addHp  += (t.hp  || 0);
    _addAtk += (t.atk || 0);
    _addSp  += (t.sp  || 0);
    _addSpd += (t.spd || 0);
    if (t.eff && typeof t.eff === 'object') {
      Object.keys(t.eff).forEach(k => { _eff[k] = (_eff[k] || 0) + t.eff[k]; });
    }
  });
  // ★ v5.43.0 — 金箍棒如意神力(好友英雄版):攻擊額外 +(等級 × atkPerHeroLvPct%),與本尊路徑同口徑
  // ⚠ v5.154.0 起金箍棒已改用 blockRateFlat/dodgeRateFlat,本區塊不再觸發,保留不刪(理由同上方本尊路徑註記)
  try{
    if(_eff.atkPerHeroLvPct){
      const _jgbLvF = Math.max(1, (h.lv | 0) || 1);
      _addAtk += Math.max(1, Math.floor(_jgbLvF * (_eff.atkPerHeroLvPct / 100)));
    }
  }catch(_eJgbF){}
  if (_addHp)  { h.hp  = (h.hp  || 0) + _addHp;  h.curHp = h.hp; }
  if (_addAtk) { h.atk = (h.atk || 0) + _addAtk; }
  if (_addSp)  { h.sp  = (h.sp  || 0) + _addSp;  }
  if (_addSpd) { h.spd = (h.spd || 0) + _addSpd; }
  h._treasureEff = _eff;
  try{ console.log('[好友至寶套用] '+h.name+' 加成:',
    {hp:_addHp,atk:_addAtk,sp:_addSp,spd:_addSpd}, 'effects:', _eff); }catch(_){}
}

// ── 開啟選關頁時讀取雲端好友和代表英雄 ──
async function _loadFriendSystemData() {
  if (!window._gUserId || !window._fbLoad) return;
  try {
    const data = await window._fbLoad(window._gUserId);
    if (data) {
      _myRepHero  = data.representativeHero || null;
      try{ window._myRepHero = _myRepHero; }catch(_){}   // ★ v3.16.43 — local + window 同步(避免簽到流程/即時監聽讀到不一致的舊 window 值)
      _friendList = data.friends || [];
    }
  } catch(e) { console.warn('[好友系統] 讀取失敗', e); }
  _loadRepHeroBar();
  // 更新好友英雄邀請狀態
  if (_invitedFriendHero) {
    const badge = document.getElementById('adv-friend-badge');
    if (badge) { badge.style.display = 'block'; badge.textContent = '1'; }
  }
}


// ★ v5.167.0(2026-09-10・老師需求「新增關閉視窗按鈕,不強制登入」)—
//   單一收口 helper:只把 login-gate-modal 藏起來,不清除、不新增、不觸碰任何
//   登入判定旗標或本機/雲端資料;學生按下後回到原本畫面(通常是首頁),可以
//   改點不需要登入的小遊戲模式入口(#minigame-btn 本就是一顆單純 <a> 連結,
//   從未被本閘門擋過)。★ 刻意不順手清共用登入戳記/最近帳號清單等——那些
//   都是純粹的登入輔助資訊,跟「要不要登入」是兩回事,關閉視窗不代表要清掉。
function _lxpsCloseLoginGate(){
  try{
    const modal = document.getElementById('login-gate-modal');
    if(modal) modal.style.display = 'none';
  }catch(_eCloseLg){}
  /* ★ v5.216.0 — 學生按「✕ 關閉視窗」放棄登入 ⇒ 清掉「登入後要去荒島/小遊戲」的旗標，不留給下一次登入 */
  try{ if(typeof window._lxpsConsumePendingEntry === 'function') window._lxpsConsumePendingEntry(); }catch(_){}
}
window._lxpsCloseLoginGate = _lxpsCloseLoginGate;

async function showLoginGate() {
  // ★ v1.1.0 — 標記遊戲已開始,啟動方向監聽(手機直立時自動顯示提示)
  window._gameInitialized = true;
  try{
    if(typeof window._setupOrientationWatcher === 'function'){
      window._setupOrientationWatcher();
      if(typeof window._isMobileDevice === 'function' && window._isMobileDevice()){
        if(typeof window._isPortrait === 'function' && window._isPortrait()){
          window._showPortraitReminder();
        }
      }
    }
  }catch(_){}
  // 已登入 → 直接進冒險
  // ★ v3.13.9(2026-06-01)鐵律 1.143:雙條件守門,防 _gUserId 殘留誤放訪客進去
  //   舊版只看 _gUserId,但這個變數在「v3.10.1 攔截器把 Firebase 自動還原檔下」之前
  //   會有短暫時間是「前一位玩家 uid」狀態,玩家若在這段 race window 點按鈕 →
  //   直接 openAdventureOverlay → 進入別人的雲端進度,污染對方的存檔。
  //   修法:同時要求 _lxpsLoggedInThisSession=true(本 session 跑完 onAuth 真正登入過)。
  //   若 _gUserId 有值但 _lxpsLoggedInThisSession 還沒設 → 表示 onAuth 還在跑,
  //   顯示 modal 等使用者點按鈕後 onAuth 自然完成,不放走任何中間態。
  //
  // ★ v5.159.0(2026-09-09・老師回報「登入成功後按開始冒險又跳出要登入」)—
  //   根因:v5.152.0 把帳號列改成「三道雲端閘門(維修/休息/停權)讀取之前」就先畫,
  //   但 _gUserId/_lxpsLoggedInThisSession 這兩個旗標要等三道閘門讀完才設。
  //   校網慢時,學生會看到自己的名字/帳號列已經出現(以為登入成功)、但這兩個旗標
  //   還沒設,這時點「開始冒險」會被下面這行判定成「沒登入」,再次跳出登入閘門。
  //   修法:若 Firebase 手上其實已經有 currentUser(代表 onAuth 正在處理、不是真的
  //   沒登入),先短暫等待(最多 8 秒、每 200ms 檢查一次)讓旗標補齊,而不是立刻
  //   顯示閘門嚇學生;等不到才照舊往下顯示閘門(行為與修改前一致,不是新的卡關)。
  if(!(window._gUserId && window._lxpsLoggedInThisSession) && window._fbAuth && window._fbAuth.currentUser){
    var _sgWaited = 0;
    while(_sgWaited < 8000 && !(window._gUserId && window._lxpsLoggedInThisSession)){
      await new Promise(function(_r){ setTimeout(_r, 200); });
      _sgWaited += 200;
    }
  }
  if(window._gUserId && window._lxpsLoggedInThisSession){ openAdventureOverlay(); return; }
  // ★ v3.11.14 — Firebase 尚未載入 → 不准訪客進入,顯示閘門 + 重試提示
  //   (舊版這裡會 openAdventureOverlay() 放訪客進去,正是污染雲端的破口之一)
  // ★ v5.176.0(2026-09-11・老師回報「登入以開始遊戲的小視窗還是沒有出現關閉的按鈕」)—
  //   【根因】login-gate-modal 靜態掛在 #gc 容器內(HTML 結構逐行核對確認)，而 #gc 有
  //     isolation:isolate + transform:scale(scaleToViewport() 套用，讓整組遊戲版面等比縮放
  //     塞進不同裝置的視窗) ⇒ #gc 是它所有 position:fixed 子孫元素的「containing block」，
  //     不再是真正的瀏覽器視窗。login-gate-modal 本身的 position:fixed;inset:0，以及裡面
  //     那顆「✕ 關閉視窗」按鈕的 position:fixed;top:16px;right:16px，全部被錯誤地拿去對齊
  //     #gc 縮放後的座標系，而不是玩家實際看到的螢幕——在大多數裝置的縮放比例下，這顆按鈕
  //     因此落在畫面看不到／點不到的地方，老師看到的正是「按鈕沒有出現」。
  //   ★ 這正是 v5.104.0 修過的同一種 bug(#custom-confirm-overlay 當時被 #_gc_wrapper 的
  //     position:fixed 蓋住)，只是這次的病灶是「containing block 換位」而非「stacking
  //     context 排序」，但修法完全通用：顯示前把整個 modal 搬成 document.body 的直系子節點，
  //     搬出 #gc 的 transform 影響範圍，position:fixed 才會真正對齊瀏覽器視窗。
  //   ★ 冪等處理(只搬一次)+ try/catch 安全網，搬失敗也不影響原本顯示登入閘門的行為。
  try{
    var _lgModalDetach = document.getElementById('login-gate-modal');
    if(_lgModalDetach && (_lgModalDetach.parentNode !== document.body || _lgModalDetach !== document.body.lastElementChild)){
      document.body.appendChild(_lgModalDetach);
    }
    // ★ v5.243.0 手機橫式:搬到 body 之後撤掉 v5.242.0 _lxpsFixGcClamp 在畫布內套上的 max 字級(33px !important),
    //   否則真實 px 呈現時變成巨字,字級交回 #lxps-phone-css 的登入閘門規則
    try{ if(typeof window._lxpsUndoClampFix === 'function') window._lxpsUndoClampFix(_lgModalDetach); }catch(_){}
  }catch(_eLgDetach){ console.warn('[v5.176.0 login-gate-modal 提升圖層]', _eLgDetach); }
  const modal = document.getElementById('login-gate-modal');
  if(modal) modal.style.display = 'flex';
  // ★ v5.136.0(老師裁定①丙)— 每次開閘門都重新渲染「這台平板登入過的帳號」
  //   (刻意不只渲染一次:剛登出的帳號會由 _addRecentAccount 加進清單,重開時要看得到)
  try{ if(typeof window._lgRenderRecentAccounts === 'function') window._lgRenderRecentAccounts(); }
  catch(_eLg){ console.warn('[登入閘門] 最近帳號清單渲染失敗(不影響登入)', _eLg); }
  try{ if(typeof window._lxpsRenderSharedLoginBanner === 'function') window._lxpsRenderSharedLoginBanner(); }
  catch(_eSb){ console.warn('[登入閘門] 共用登入橫幅渲染失敗(不影響登入)', _eSb); }
  if(!window._fbSignIn){
    console.warn('[強制登入] Firebase 尚未就緒,顯示閘門等候 / 提示重新整理');
    // 600ms 後再試一次:Firebase 通常很快就緒,就緒後按鈕即可正常登入
    setTimeout(function(){
      try{
        if(!window._fbSignIn && document.getElementById('login-gate-modal') &&
           document.getElementById('login-gate-modal').style.display !== 'none'){
          // 仍未就緒 → 提示玩家重新整理(不放行)
          const _hint = document.getElementById('_login-gate-loading-hint');
          if(_hint) _hint.style.display = 'block';
        }
      }catch(_){}
    }, 600);
  }
}

// ★ v3.11.14(2026-05-28) — 「進度已載入完畢,可以開始遊玩」確認視窗
//   老師需求:玩家登入後,確認雲端最豐富資料已覆蓋本地,跳視窗告知可以開始。
//   附帶顯示「載入到幾隻英雄 / 最高等級 / 知識幣」讓玩家一眼確認進度正確,
//   萬一看到「只有 8 隻」就知道載入異常,可立即反映(而不是默默玩到錯誤進度)。
// ★ v3.13.6(2026-05-31) — 老師需求:追加 4 個每日狀態欄位(防止換裝置重複領)
//   ① 免費 1 次召喚 — 雲端 dailyFreeSummonDate vs 今日台灣日期字串
//   ② 好友送禮剩餘 — window._giftHistory.sentUids 跨日合併後的 5 - count
//   ③ 今日知識王 — window._kingChallenge._todayClaimed (跨日重置後)
//   ④ 今日世界 BOSS — window._wbDailyLimit.getTodayCount() (async,讀雲端)
//   設計重點:
//     - 數字一律先顯示「⏳ 載入中」,等真實值就緒才填入
//     - 「開始遊玩」按鈕在所有值就緒前 disabled,避免玩家「看到 0 跑出去重新挑戰」恐慌
//     - 每個欄位獨立輪詢 5 次 × 600ms = 3 秒總等待,每個就緒就點亮
//     - 4 個全就緒(或全 timeout)按鈕才解鎖,並把欄位旁邊改顯示綠色 ✅
window._lxpsShowProgressLoadedPopup = function(){
  try{
    if(document.getElementById('_progress-loaded-modal')) return; // 防重複
    // ★ v3.13.64 — Layer E:資料未就緒(載入失敗)時絕不顯示「進度載入完畢」視窗,
    //   否則會顯示「載到 8 隻」嚇到玩家。此時應由載入失敗視窗接手,這裡直接 return。
    try{
      var _curUid = (typeof window._lxpsAuthUid === 'function') ? window._lxpsAuthUid() : (window._gUserId || null);
      if(!_curUid || window._dataReadyForUid !== _curUid){
        console.warn('[進度載入完畢視窗 v3.13.64] 資料未就緒,跳過顯示(由載入失敗視窗處理)');
        return;
      }
    }catch(_eRdy){}
    // 統計目前載入到的進度
    var heroCount = 0, maxLv = 0;
    try{
      var arr = (typeof advGetUnlockedHeroes === 'function') ? (advGetUnlockedHeroes() || []) : [];
      heroCount = arr.length;
    }catch(_){}
    // ★ v3.11.19(鐵律 1.52)— 最高等級「多源取最大值」,修「解鎖數正確但等級顯示 0」。
    //   舊版只讀 _heroLevels;但 advGetUnlockedHeroes 來源是 localStorage(載入快),
    //   _heroLevels 是雲端 _applySafeData merge 後才填的 module 變數(載入慢),
    //   兩者時序不一致 → 解鎖數對、_heroLevels 還是 {} → maxLv=0。
    //   改成:① module _heroLevels ② window._heroLevels ③ localStorage 'adv_hero_levels'
    //         三源逐一掃,取最大值;全部都空才會是 0。
    function _scanMaxLv(obj){
      try{
        if(obj && typeof obj === 'object'){
          Object.keys(obj).forEach(function(k){
            var lv = parseInt(obj[k], 10) || 0;
            if(lv > maxLv) maxLv = lv;
          });
        }
      }catch(_){}
    }
    try{ if(typeof _heroLevels === 'object') _scanMaxLv(_heroLevels); }catch(_){}
    try{ _scanMaxLv(window._heroLevels); }catch(_){}
    try{
      var _rawLv = localStorage.getItem('adv_hero_levels');
      if(_rawLv) _scanMaxLv(JSON.parse(_rawLv));
    }catch(_){}
    // ★ v3.11.26(鐵律 1.52)— 知識幣「多源取最大值」,修「英雄/等級正確但知識幣顯示 0」。
    //   舊版 bug:module 變數 _knowledgeCoins 在 line 68707 已 `let = 0` 宣告,
    //   所以 typeof 永遠 !== 'undefined' → 三元永遠走 module 值,
    //   但雲端 merge 寫的是 window._knowledgeCoins(line 88902),彈窗觸發時
    //   module 變數可能還停在初始 0 → 永遠 fallback 不到雲端值 → 顯示 0。
    //   修法:同時掃 window._knowledgeCoins / window._coinCount / module _knowledgeCoins,
    //   取三者最大值(知識幣只會是非負數,取 max 不會誤判)。
    var coins = 0;
    function _scanCoins(v){ try{ var n = (typeof v === 'number') ? v : parseInt(v, 10); if(!isNaN(n) && n > coins) coins = n; }catch(_){} }
    try{ _scanCoins(window._knowledgeCoins); }catch(_){}
    try{ _scanCoins(window._coinCount); }catch(_){}
    try{ if(typeof _knowledgeCoins !== 'undefined') _scanCoins(_knowledgeCoins); }catch(_){}

    var box = document.createElement('div');
    box.id = '_progress-loaded-modal';
    box.style.cssText = 'position:fixed;inset:0;z-index:99997;'
      + 'background:rgba(0,0,8,0.86);display:flex;align-items:center;justify-content:center;'
      + 'padding:24px;backdrop-filter:blur(6px);'
      + "font-family:'M PLUS Rounded 1c','Nunito',sans-serif;";
    box.innerHTML =
      '<div style="background:linear-gradient(160deg,#102a18,#08200f);border:3px solid #66dd99;'
        + 'border-radius:20px;padding:26px 30px;max-width:min(500px,94vw);text-align:center;'
        + 'box-shadow:0 0 50px rgba(80,220,140,0.35);max-height:92vh;overflow-y:auto;">'
        + '<div style="font-size:42px;margin-bottom:6px;">✅</div>'
        + '<div style="font-size:clamp(20px,2.8vw,28px);font-weight:900;color:#88ffbb;margin-bottom:8px;">'
          + '進度已載入完畢!</div>'
        + '<div style="font-size:clamp(13px,1.6vw,17px);color:#d8ffe8;line-height:1.6;margin-bottom:14px;">'
          + '已從雲端同步你的存檔,確認下方數字後即可開始</div>'
        // ── 進度區塊 ──
        + '<div style="background:rgba(0,0,0,0.3);border:1px solid rgba(120,220,160,0.4);'
          + 'border-radius:12px;padding:11px 14px;margin-bottom:10px;font-size:clamp(13px,1.55vw,16px);'
          + 'color:#bfeecf;line-height:1.85;text-align:left;display:inline-block;min-width:min(300px,86vw);">'
          + '<div style="font-size:13px;color:#88dda8;font-weight:800;margin-bottom:4px;letter-spacing:1px;">✦ 角色進度</div>'
          + '🦸 已解鎖英雄:<b style="color:#fff;">' + heroCount + '</b> 隻<br>'
          + '⭐ 最高英雄等級:<b id="_prog-maxlv" style="color:#fff;">Lv.' + maxLv + '</b><br>'
          + '💰 知識幣:<b id="_prog-coins" style="color:#fff;">' + (coins||0).toLocaleString() + '</b>'
          + '</div>'
        // ★ v3.13.6 — 每日狀態區塊(防換裝置重複領)
        + '<div style="background:rgba(40,30,10,0.45);border:1px solid rgba(255,200,80,0.45);'
          + 'border-radius:12px;padding:11px 14px;margin-bottom:12px;font-size:clamp(13px,1.55vw,16px);'
          + 'color:#ffe8a8;line-height:1.85;text-align:left;display:inline-block;min-width:min(300px,86vw);">'
          + '<div style="font-size:13px;color:#ffcc66;font-weight:800;margin-bottom:4px;letter-spacing:1px;">'
            + '✦ 今日狀態(雲端同步中)<span id="_prog-daily-spin" style="margin-left:6px;color:#ffaa66;">⏳</span></div>'
          + '🔮 免費召喚:<b id="_prog-free-summon" style="color:#aaa;">⏳ 載入中</b><br>'
          + '🎁 好友送禮剩餘:<b id="_prog-gift-left" style="color:#aaa;">⏳ 載入中</b> / 5<br>'
          + '👑 知識王挑戰:<b id="_prog-king" style="color:#aaa;">⏳ 載入中</b><br>'
          + '🐉 世界 BOSS 場次:<b id="_prog-wb" style="color:#aaa;">⏳ 載入中</b> / 2<br>'
          /* ★ v3.13.7(2026-05-31)— 世界 BOSS 挑戰入場券 */
          + '🎟️ 挑戰入場券:<b id="_prog-wb-ticket" style="color:#aaa;">⏳ 載入中</b> / 5'
          + '</div>'
        + '<div style="font-size:clamp(11px,1.3vw,13px);color:#7fae8f;margin-bottom:14px;line-height:1.55;">'
          + '※ 若英雄數量明顯比你記得的少,請先別玩,立即告訴老師。<br>'
          + '※ 每日狀態載完才能開始,避免不同裝置重複領取獎勵。</div>'
        + '<button id="_progress-loaded-ok" style="padding:12px 36px;font-size:clamp(16px,2.1vw,21px);'
          + 'font-weight:900;background:linear-gradient(135deg,#888,#666);border:none;'
          + 'color:#ccc;border-radius:12px;cursor:not-allowed;letter-spacing:2px;opacity:0.6;'
          + "font-family:inherit;box-shadow:0 4px 18px rgba(80,80,80,0.3);\" disabled>⏳ 載入中,請稍候...</button>"
      + '</div>';
    document.body.appendChild(box);
    var _ok = document.getElementById('_progress-loaded-ok');
    if(_ok){
      _ok.onclick = function(){
        if(_ok.disabled) return;  // ★ v3.13.6 — 按鈕鎖定狀態下不可點
        try{ if(typeof playSfx === 'function') playSfx('sfx-confirm', 0.6); }catch(_){}
        if(box.parentNode) box.remove();
      };
    }
    try{ if(typeof playSfx === 'function') playSfx('sfx-powerup', 0.6); }catch(_){}

    // ★ v3.13.6(2026-05-31)— 每日狀態 4 個欄位的雲端權威讀取 + UI 更新
    // ★ v3.13.7(2026-05-31)— 加第 5 個欄位:挑戰入場券(grantDailyTickets 結束後讀)
    //   設計:每個欄位獨立輪詢(因為 5 個來源不同步:有些等 _applySafeData merge、
    //         有些是 async API),全就緒才解鎖按鈕
    var _dailyDone = { freeSummon:false, gift:false, king:false, wb:false, wbTicket:false };
    function _markDailyOk(key){
      _dailyDone[key] = true;
      // 全就緒 → 解鎖按鈕
      if(_dailyDone.freeSummon && _dailyDone.gift && _dailyDone.king && _dailyDone.wb && _dailyDone.wbTicket){
        try{
          var _ok2 = document.getElementById('_progress-loaded-ok');
          if(_ok2){
            _ok2.disabled = false;
            _ok2.style.cssText = 'padding:13px 38px;font-size:clamp(17px,2.2vw,23px);'
              + 'font-weight:900;background:linear-gradient(135deg,#66dd99,#33bb77);border:none;'
              + 'color:#06210f;border-radius:12px;cursor:pointer;letter-spacing:2px;'
              + "font-family:inherit;box-shadow:0 4px 18px rgba(80,220,140,0.4);";
            _ok2.textContent = '開始遊玩 ▶';
          }
          var _spin = document.getElementById('_prog-daily-spin');
          if(_spin){ _spin.style.color = '#88ffbb'; _spin.textContent = '✅'; }
        }catch(_){}
      }
    }

    // ★ v5.165.0(2026-09-10・老師回報「登入彈出的調查和提醒視窗按了沒反應」)—
    //   根因:④世界BOSS場次與⑤挑戰入場券兩個欄位直接 await Firestore 的
    //   getTodayCount()/getTicketCount(),沒有任何逾時機制。校網真的卡死時,
    //   這兩支 Promise 可能永遠不 resolve 也不 reject,_markDailyOk 永遠不會
    //   被這兩個欄位呼叫到,「開始遊玩」按鈕就會永久卡在 disabled(⏳ 載入中)
    //   ——玩家看到的就是「彈窗跳出來,但按鈕按了沒反應」。
    //   修法:8 秒全域看門狗,逾時仍未全部就緒時,把還沒完成的欄位文字改標
    //   「⚠ 逾時,稍後可在遊戲內查看」並強制解鎖按鈕(不等這幾個逾時欄位)。
    //   純安全網,不改動任何一支既有的讀取邏輯或 5 次重試機制。
    setTimeout(function(){
      try{
        var _ok3 = document.getElementById('_progress-loaded-ok');
        if(!_ok3 || !_ok3.disabled) return;   // 已經正常解鎖過,不必介入
        var _timeoutLabels = { freeSummon:'_prog-free-summon', gift:'_prog-gift-left',
          king:'_prog-king', wb:'_prog-wb', wbTicket:'_prog-wb-ticket' };
        for(var _k in _timeoutLabels){
          if(!_dailyDone[_k]){
            var _el = document.getElementById(_timeoutLabels[_k]);
            if(_el){ _el.style.color = '#ffaa88'; _el.textContent = '⚠ 逾時(稍後可在遊戲內查看)'; }
          }
        }
        _ok3.disabled = false;
        _ok3.style.cssText = 'padding:13px 38px;font-size:clamp(17px,2.2vw,23px);'
          + 'font-weight:900;background:linear-gradient(135deg,#66dd99,#33bb77);border:none;'
          + 'color:#06210f;border-radius:12px;cursor:pointer;letter-spacing:2px;'
          + "font-family:inherit;box-shadow:0 4px 18px rgba(80,220,140,0.4);";
        _ok3.textContent = '開始遊玩 ▶';
        var _spin2 = document.getElementById('_prog-daily-spin');
        if(_spin2){ _spin2.style.color = '#ffaa88'; _spin2.textContent = '⚠'; }
      }catch(_){}
    }, 8000);

    // ── ① 免費召喚狀態 ──
    function _refreshFreeSummon(){
      try{
        if(typeof _isDailyFreeSummonAvailable === 'function'){
          var _avail = !!_isDailyFreeSummonAvailable();
          var _el = document.getElementById('_prog-free-summon');
          if(_el){
            if(_avail){
              _el.style.color = '#88ffbb';
              _el.textContent = '✅ 可使用';
            } else {
              _el.style.color = '#ffaa88';
              _el.textContent = '✓ 今日已用';
            }
          }
          return true;
        }
      }catch(_){}
      return false;
    }
    // 立即試一次;沒就緒就輪詢
    if(_refreshFreeSummon()){
      _markDailyOk('freeSummon');
    } else {
      var _fsRetries = 0;
      var _fsTimer = setInterval(function(){
        _fsRetries++;
        if(_refreshFreeSummon() || _fsRetries >= 5){
          clearInterval(_fsTimer);
          _markDailyOk('freeSummon');
        }
      }, 600);
    }

    // ── ② 好友送禮剩餘 ──
    function _refreshGift(){
      try{
        // 先觸發跨日重置(若有 _giftMaybeResetHistory)
        if(typeof window._giftMaybeResetHistory === 'function'){
          try{ window._giftMaybeResetHistory(); }catch(_){}
        }
        var _gh = window._giftHistory;
        if(_gh && Array.isArray(_gh.sentUids)){
          var _used = _gh.sentUids.length;
          var _left = Math.max(0, 5 - _used);
          var _el = document.getElementById('_prog-gift-left');
          if(_el){
            if(_left > 0){
              _el.style.color = '#88ffbb';
              _el.textContent = '✅ 還可送 ' + _left + ' 位';
            } else {
              _el.style.color = '#ffaa88';
              _el.textContent = '✓ 已送 5/5';
            }
          }
          return true;
        }
      }catch(_){}
      return false;
    }
    if(_refreshGift()){
      _markDailyOk('gift');
    } else {
      var _gtRetries = 0;
      var _gtTimer = setInterval(function(){
        _gtRetries++;
        if(_refreshGift() || _gtRetries >= 5){
          clearInterval(_gtTimer);
          _markDailyOk('gift');
        }
      }, 600);
    }

    // ── ③ 知識王挑戰狀態 ──
    function _refreshKing(){
      try{
        // 跨日重置先跑
        if(typeof window._kingCheckReset === 'function'){
          try{ window._kingCheckReset(); }catch(_){}
        }
        var _kc = window._kingChallenge;
        if(_kc && typeof _kc._todayClaimed !== 'undefined'){
          var _el = document.getElementById('_prog-king');
          if(_el){
            if(_kc._todayClaimed){
              _el.style.color = '#ffaa88';
              _el.textContent = '✓ 今日已完成';
            } else if(_kc._snapshot){
              _el.style.color = '#ffcc66';
              _el.textContent = '⏸ 進行中(可繼續)';
            } else {
              _el.style.color = '#88ffbb';
              _el.textContent = '✅ 可挑戰';
            }
          }
          return true;
        }
      }catch(_){}
      return false;
    }
    if(_refreshKing()){
      _markDailyOk('king');
    } else {
      var _kRetries = 0;
      var _kTimer = setInterval(function(){
        _kRetries++;
        if(_refreshKing() || _kRetries >= 5){
          clearInterval(_kTimer);
          _markDailyOk('king');
        }
      }, 600);
    }

    // ── ④ 世界 BOSS 場次(async,讀雲端最權威) ──
    (function _refreshWb(){
      try{
        if(window._wbDailyLimit && typeof window._wbDailyLimit.getTodayCount === 'function'){
          window._wbDailyLimit.getTodayCount().then(function(_cnt){
            try{
              var _limit = (typeof window._wbDailyLimit.getLimit === 'function')
                ? window._wbDailyLimit.getLimit() : 2;
              var _left = Math.max(0, _limit - (_cnt||0));
              var _el = document.getElementById('_prog-wb');
              if(_el){
                if(_left > 0){
                  _el.style.color = '#88ffbb';
                  _el.textContent = '✅ 已打 ' + (_cnt||0) + ',還可 ' + _left;
                } else {
                  _el.style.color = '#ffaa88';
                  _el.textContent = '✓ 已打滿 ' + (_cnt||0) + '/' + _limit;
                }
              }
            }catch(_){}
            _markDailyOk('wb');
          }).catch(function(_eFetch){
            console.warn('[progress-modal wb] getTodayCount 失敗,保守顯示 0', _eFetch);
            try{
              var _el = document.getElementById('_prog-wb');
              if(_el){
                _el.style.color = '#ffaa88';
                _el.textContent = '⚠ 載入失敗(預設 0)';
              }
            }catch(_){}
            _markDailyOk('wb');
          });
          return;
        }
      }catch(_){}
      // _wbDailyLimit 模組未就緒 → 等 600ms 再試,最多 5 次
      var _wbRetries = 0;
      var _wbTimer = setInterval(function(){
        _wbRetries++;
        if(window._wbDailyLimit && typeof window._wbDailyLimit.getTodayCount === 'function'){
          clearInterval(_wbTimer);
          window._wbDailyLimit.getTodayCount().then(function(_cnt){
            try{
              var _limit = (typeof window._wbDailyLimit.getLimit === 'function')
                ? window._wbDailyLimit.getLimit() : 2;
              var _left = Math.max(0, _limit - (_cnt||0));
              var _el = document.getElementById('_prog-wb');
              if(_el){
                if(_left > 0){
                  _el.style.color = '#88ffbb';
                  _el.textContent = '✅ 已打 ' + (_cnt||0) + ',還可 ' + _left;
                } else {
                  _el.style.color = '#ffaa88';
                  _el.textContent = '✓ 已打滿 ' + (_cnt||0) + '/' + _limit;
                }
              }
            }catch(_){}
            _markDailyOk('wb');
          }).catch(function(){
            try{
              var _el = document.getElementById('_prog-wb');
              if(_el){
                _el.style.color = '#ffaa88';
                _el.textContent = '⚠ 載入失敗';
              }
            }catch(_){}
            _markDailyOk('wb');
          });
        } else if(_wbRetries >= 5){
          clearInterval(_wbTimer);
          try{
            var _el = document.getElementById('_prog-wb');
            if(_el){
              _el.style.color = '#ffaa88';
              _el.textContent = '⚠ 模組未就緒';
            }
          }catch(_){}
          _markDailyOk('wb');
        }
      }, 600);
    })();

    // ── ⑤ 世界 BOSS 挑戰入場券(async)──
    // ★ v3.13.7(2026-05-31)— 流程:先呼叫 grantDailyTickets(換日自動補發),完成後讀 getTicketCount 顯示
    //   邏輯:
    //     - grantDailyTickets 內部有 wbTicketLastGrantDateStr 守門,同日重複呼叫不會多發
    //     - 若昨日有未用完場次,會自動把對應張數加進背包(上限 5)
    //     - getTicketCount 讀最新值(雲端權威)
    (function _refreshTicket(){
      function _doFetch(){
        // ★ v3.13.16 — 發券改由 _giftClaimPendingGifts(登入領禮流程)統一處理並顯示在禮物清單,
        //   這裡只「顯示目前持有數」,不再 grant(避免雙重發放,且讓禮物清單能正確顯示今日新發/5-5)。
        var _grantPromise = Promise.resolve(null);
        _grantPromise.then(function(_gr){
          if(!window._wbDailyLimit || typeof window._wbDailyLimit.getTicketCount !== 'function'){
            try{
              var _el0 = document.getElementById('_prog-wb-ticket');
              if(_el0){
                _el0.style.color = '#ffaa88';
                _el0.textContent = '⚠ 模組未就緒';
              }
            }catch(_){}
            _markDailyOk('wbTicket');
            return;
          }
          return window._wbDailyLimit.getTicketCount().then(function(_n){
            try{
              var _el = document.getElementById('_prog-wb-ticket');
              if(_el){
                var _cnt = _n || 0;
                if(_cnt >= 1){
                  _el.style.color = '#88ffcc';
                  _el.textContent = '🎟️ 持有 ' + _cnt;
                } else {
                  _el.style.color = '#aaccff';
                  _el.textContent = '— 目前無';
                }
              }
              // grantDailyTickets 若有新發放,加個小提示
              if(_gr && _gr.granted > 0){
                try{
                  var _el2 = document.getElementById('_prog-wb-ticket');
                  if(_el2){
                    _el2.textContent += ' (今日新發 +' + _gr.granted + ')';
                    _el2.style.color = '#ffe066';
                  }
                }catch(_){}
              }
            }catch(_){}
            _markDailyOk('wbTicket');
          }).catch(function(e){
            console.warn('[progress-modal ticket] getTicketCount 失敗', e);
            try{
              var _el = document.getElementById('_prog-wb-ticket');
              if(_el){
                _el.style.color = '#ffaa88';
                _el.textContent = '⚠ 載入失敗';
              }
            }catch(_){}
            _markDailyOk('wbTicket');
          });
        });
      }
      // 等模組就緒(最多 5 次 × 600ms)
      if(window._wbDailyLimit && typeof window._wbDailyLimit.getTicketCount === 'function'){
        _doFetch();
        return;
      }
      var _tRetries = 0;
      var _tTimer = setInterval(function(){
        _tRetries++;
        if(window._wbDailyLimit && typeof window._wbDailyLimit.getTicketCount === 'function'){
          clearInterval(_tTimer);
          _doFetch();
        } else if(_tRetries >= 5){
          clearInterval(_tTimer);
          try{
            var _el = document.getElementById('_prog-wb-ticket');
            if(_el){
              _el.style.color = '#ffaa88';
              _el.textContent = '⚠ 模組未就緒';
            }
          }catch(_){}
          _markDailyOk('wbTicket');
        }
      }, 600);
    })();

    // ★ v3.11.19 — 防殘留 race:若彈窗瞬間 _heroLevels 還沒 merge 完(maxLv=0 但 heroCount>0),
    //   1.5 秒內每 300ms 重掃一次三源,等級一就緒就即時更新顯示(避免老師看到 Lv.0)。
    // ★ v3.11.26 — 同時補救知識幣(coins=0 但 heroCount>0 = 雲端 coins 還沒 merge 進來)。
    if((maxLv === 0 || coins === 0) && heroCount > 0){
      var _retries = 0;
      var _lvDone = (maxLv > 0), _coinDone = (coins > 0);
      var _lvTimer = setInterval(function(){
        _retries++;
        // 重掃最高等級
        if(!_lvDone){
          var _m = 0;
          var _scan = function(o){ try{ if(o && typeof o==='object') Object.keys(o).forEach(function(k){ var v=parseInt(o[k],10)||0; if(v>_m)_m=v; }); }catch(_){} };
          try{ if(typeof _heroLevels==='object') _scan(_heroLevels); }catch(_){}
          try{ _scan(window._heroLevels); }catch(_){}
          try{ var r=localStorage.getItem('adv_hero_levels'); if(r) _scan(JSON.parse(r)); }catch(_){}
          if(_m > 0){
            var _el = document.getElementById('_prog-maxlv');
            if(_el) _el.textContent = 'Lv.' + _m;
            _lvDone = true;
          }
        }
        // 重掃知識幣
        if(!_coinDone){
          var _c = 0;
          var _sc = function(v){ try{ var n=(typeof v==='number')?v:parseInt(v,10); if(!isNaN(n)&&n>_c)_c=n; }catch(_){} };
          try{ _sc(window._knowledgeCoins); }catch(_){}
          try{ _sc(window._coinCount); }catch(_){}
          try{ if(typeof _knowledgeCoins !== 'undefined') _sc(_knowledgeCoins); }catch(_){}
          if(_c > 0){
            var _ce = document.getElementById('_prog-coins');
            if(_ce) _ce.textContent = (_c||0).toLocaleString();
            _coinDone = true;
          }
        }
        if((_lvDone && _coinDone) || _retries >= 5) clearInterval(_lvTimer);
      }, 300);
    }
    // 12 秒後自動關閉(避免玩家沒按到一直擋著)
    setTimeout(function(){ try{ if(box.parentNode) box.remove(); }catch(_){} }, 12000);
  }catch(e){ console.warn('[v3.11.14 進度載入完畢視窗] 例外', e); }
};

window._waitForCloudReady = async function(maxWaitMs){
  // 訪客模式不需要等雲端
  if(!window._gUserId) return true;
  // 已經載完了直接放行
  if(window._cloudLoadDone === true) return true;

  const _maxWait = (typeof maxWaitMs === 'number' && maxWaitMs > 0) ? maxWaitMs : 15000;
  const _start = Date.now();

  // 顯示溫和的「進度載入中」遮罩
  let _overlay = null;
  try{
    _overlay = document.getElementById('_cloud-wait-overlay');
    if(!_overlay){
      _overlay = document.createElement('div');
      _overlay.id = '_cloud-wait-overlay';
      _overlay.style.cssText = 'position:fixed;inset:0;z-index:99998;'
        + 'background:linear-gradient(135deg,rgba(20,15,40,0.92),rgba(10,8,30,0.95));'
        + 'display:flex;flex-direction:column;align-items:center;justify-content:center;'
        + 'color:#e0d8ff;font-family:"M PLUS Rounded 1c","Nunito",sans-serif;'
        + 'backdrop-filter:blur(4px);';
      _overlay.innerHTML =
        '<div style="font-size:clamp(28px,3.4vw,42px);font-weight:900;color:#ffe066;'
          + 'text-shadow:0 2px 8px rgba(0,0,0,0.6),0 0 16px rgba(255,200,80,0.4);margin-bottom:18px;">'
          + '☁️ 正在載入您的進度...'
          + '</div>'
        + '<div style="font-size:clamp(14px,1.7vw,20px);color:#d8c8f0;margin-bottom:24px;">'
          + '請稍候,正在從雲端同步角色等級與知識幣'
          + '</div>'
        + '<div style="width:min(420px,80vw);height:8px;background:rgba(40,30,60,0.85);'
          + 'border:1px solid rgba(180,140,220,0.6);border-radius:8px;overflow:hidden;position:relative;">'
          + '<div style="position:absolute;top:0;left:-30%;width:30%;height:100%;'
            + 'background:linear-gradient(90deg,transparent,#ffaa44,transparent);'
            + 'animation:_cloudWaitShimmer 1.4s linear infinite;"></div>'
          + '</div>';
      // 插入動畫 keyframes
      if(!document.getElementById('_cloud-wait-style')){
        const _st = document.createElement('style');
        _st.id = '_cloud-wait-style';
        _st.textContent = '@keyframes _cloudWaitShimmer{0%{left:-30%;}100%{left:100%;}}';
        document.head.appendChild(_st);
      }
      document.body.appendChild(_overlay);
    }
  }catch(_){}

  // 輪詢 _cloudLoadDone,每 100ms 檢查一次
  while(!window._cloudLoadDone && (Date.now() - _start) < _maxWait){
    await new Promise(r => setTimeout(r, 100));
  }

  // 移除遮罩
  try{ if(_overlay && _overlay.parentNode) _overlay.parentNode.removeChild(_overlay); }catch(_){}

  if(!window._cloudLoadDone){
    console.warn('[_waitForCloudReady] 等待 ' + _maxWait + 'ms 仍未載完,放行避免卡住');
    return false;
  }
  return true;
};

// ★★ v5.136.0 — 登入閘門「登入成功之後」的共用流程(單一真相)★★
//   抽出來的原因:v5.136.0 新增了「點最近帳號直接登入」第二個入口,
//   若兩條路各自複製一份載入流程,日後只改一邊就會出現「有的入口不等雲端載完就進遊戲」
//   這種最難查的存檔污染。兩個入口一律走這一支。
async function _lgAfterSignIn(user){
  try{ sessionStorage.removeItem('lxps_login_then_adventure'); }catch(_){}
  /* ★ v5.216.0 — 先讀回「登入前要去哪顆入口」(荒島 isl / 小遊戲 mg)，讀到就清掉；
     結尾依此決定導頁或照舊 openAdventureOverlay()。⚠ 一定要在最前面讀，避免中途任何一步丟例外把旗標留給下一位同學。 */
  var _pendingEntry = null;
  try{ _pendingEntry = (typeof window._lxpsConsumePendingEntry === 'function') ? window._lxpsConsumePendingEntry() : null; }catch(_){ _pendingEntry = null; }
  // ★ v5.141.0 — _doSignInFlow 的 popup 路徑回傳的是 UserCredential（{user, providerId…}）不是 user，
  //   舊碼 user.uid 其實是 undefined，一路靠 gameCloudLoad 的 _lxpsResolveUid 自我修復才沒出事；
  //   這裡正規化成真正的 user，並先把帳號列畫上（首頁與選關頁左上名字／頭像不再等 onAuth 跑完 6 次讀取）。
  try{ if(user && !user.uid && user.user && user.user.uid) user = user.user; }catch(_){}
  try{ if(user && user.uid && !(window._fbUser && window._fbUser.uid)) window._fbUser = user; }catch(_){}
  try{ if(user && user.uid && typeof window._lxpsPaintAccountBar === 'function') window._lxpsPaintAccountBar(user); }catch(_){}
  // ★ v3.13.17 — 直接用手上的 user.uid 載入,不依賴 currentUser/_gUserId 的時序,
  //   避免 redirect 流程「已回 user 但 currentUser 短暫落後」的 race 把剛登入的玩家誤踢回登入頁。
  try{ window._gUserId = user.uid; window._lxpsLoggedInThisSession = true; }catch(_){}
  try{ if(typeof window._lxpsSyncAdventureBtnState === 'function') window._lxpsSyncAdventureBtnState(); }catch(_){}
  // ★ v5.165.0(2026-09-10・老師需求「大對抗和小遊戲登入任一邊，30分鐘內都不用再重新登入」)—
  //   同源(minigame/ 只是子目錄)寫一份共用 localStorage 時間戳+uid+email，供另一邊(小遊戲)
  //   在 30 分鐘內快速帶入登入提示(login_hint)，跳過完整選擇帳號畫面。
  //   ⚠ 這不是繞過 Firebase 驗證的後門：另一邊仍要走一次真正的 Google 登入流程，
  //   只是幫玩家把游標預先對準同一個帳號、少一步選擇；30 分鐘一到或登出後自動失效。
  try{
    localStorage.setItem('lxps_shared_login_ts', String(Date.now()));
    localStorage.setItem('lxps_shared_login_uid', user.uid || '');
    localStorage.setItem('lxps_shared_login_email', user.email || '');
  }catch(_){}
  await gameCloudLoad(user.uid);
  try{ if(window._waitForCloudReady) await window._waitForCloudReady(15000); }catch(_){}
  /* ★ v5.216.0 — 從荒島/小遊戲入口登入的：直接導頁過去(不彈「進度載入完畢」視窗，那是冒險模式的東西)；導頁失敗才退回冒險。 */
  if(_pendingEntry){
    var _went = false;
    try{ _went = !!window._lxpsGoPendingEntry(_pendingEntry); }catch(_){ _went = false; }
    if(_went) return;
  }
  // ★ v3.11.14 — 確認雲端最豐富資料已覆蓋本地後,跳「進度載入完畢」視窗
  try{ if(typeof window._lxpsShowProgressLoadedPopup === 'function') window._lxpsShowProgressLoadedPopup(); }catch(_){}
  openAdventureOverlay();
}

/* ★★ v5.250.0(老師「部分 iPad 登入卡很久進不了遊戲」)— 25 台同時開機時,登入元件(game_cloud.js 1.6MB + Firebase SDK)
   常常比登入視窗晚到。舊碼:先把登入視窗關掉,再發現 _fbSignIn 還沒好 ⇒ 只在 console 印一行,畫面什麼都沒有,
   學生以為按了沒反應、一直重按。改成:元件還沒好時視窗不關,按鈕旁顯示「登入元件下載中…」並自動等它(最多 30 秒),
   一好就直接接著登入;30 秒還沒好才請學生重新整理。 */
function _lgWaitSignInReady(fnName){
  return new Promise(function(res){
    if(typeof window[fnName] === 'function'){ res(true); return; }
    var t0 = Date.now(), tip = null;
    try{
      var sub = document.getElementById('lg-subtitle');   /* 放在登入視窗副標題正下方(視窗本體沒有 class 可抓) */
      tip = document.createElement('div'); tip.id = 'lg-wait-sdk';
      tip.style.cssText = 'margin:0 0 14px;font-size:clamp(16px,2.6vh,24px);color:#ffe08a;font-weight:800;text-align:center;';
      tip.textContent = '⏳ 登入元件下載中,請稍等…(不用重按)';
      if(sub && !document.getElementById('lg-wait-sdk')) sub.insertAdjacentElement('afterend', tip);
      else if(!sub){ tip = null; try{ if(typeof window._showSimpleToast === 'function') window._showSimpleToast('⏳ 登入元件下載中,請稍等…(不用重按)', 'warn'); }catch(_t){} }
    }catch(_){}
    var iv = setInterval(function(){
      var ok = (typeof window[fnName] === 'function');
      if(ok || Date.now() - t0 > 30000){
        clearInterval(iv);
        try{ var e = document.getElementById('lg-wait-sdk'); if(e) e.remove(); }catch(_){}
        res(ok);
      } else if(tip){ tip.textContent = '⏳ 登入元件下載中,請稍等…(不用重按,' + Math.round((Date.now() - t0) / 1000) + ' 秒)'; }
    }, 400);
  });
}
async function loginGateGoogle() {
  const modal = document.getElementById('login-gate-modal');
  if(!window._fbSignIn){
    if(window._lgWaiting) return;   /* 已經在等了,重按不重複排隊 */
    window._lgWaiting = true;
    const _ready = await _lgWaitSignInReady('_fbSignIn');
    window._lgWaiting = false;
    if(!_ready){
      try{ if(typeof window._showSimpleToast === 'function') window._showSimpleToast('⚠️ 登入元件一直下載不下來,請下拉重新整理頁面再試一次', 'warn'); }catch(_){}
      return;
    }
  }
  if(modal) modal.style.display = 'none';
  if(window._fbSignIn) {
    try{ sessionStorage.setItem('lxps_login_then_adventure', '1'); }catch(_){}
    const user = await window._fbSignIn();
    if(user) {
      await _lgAfterSignIn(user);
    } else {
      // 登入取消,清旗標
      try{ sessionStorage.removeItem('lxps_login_then_adventure'); }catch(_){}
      // 再顯示選擇
      showLoginGate();
    }
  } else {
    console.warn('[Firebase] 尚未載入,請重新整理頁面。');
  }
}

// ★★ v5.136.0(老師裁定①丙)— 點「這台平板登入過的帳號」直接登入 ★★
//   ⚠ 這不是「免驗證切換」:_fbSignInWithHint 在 v5.136.0 已改為
//     prompt:'select_account' + login_hint ⇒ Google 一定會顯示帳號選擇/密碼流程,
//     login_hint 只是幫學生把游標對準自己那一格。共用平板的防線一步都沒少。
window.loginGateGoogleAs = async function(email){
  if(!email){ return loginGateGoogle(); }
  const modal = document.getElementById('login-gate-modal');
  if(!window._fbSignInWithHint){
    /* ★ v5.250.0 元件還沒下載好:先不關視窗,等它(同 loginGateGoogle) */
    if(window._lgWaiting) return;
    window._lgWaiting = true;
    const _ready2 = await _lgWaitSignInReady('_fbSignInWithHint');
    window._lgWaiting = false;
    if(!_ready2){
      console.warn('[登入閘門] _fbSignInWithHint 未就緒,退回一般登入');
      return loginGateGoogle();
    }
  }
  if(modal) modal.style.display = 'none';
  try{ sessionStorage.setItem('lxps_login_then_adventure', '1'); }catch(_){}
  let user = null;
  try{ user = await window._fbSignInWithHint(email); }
  catch(e){ console.warn('[登入閘門] 指定帳號登入失敗', e); }
  if(user){
    await _lgAfterSignIn(user);
  } else {
    try{ sessionStorage.removeItem('lxps_login_then_adventure'); }catch(_){}
    showLoginGate();
  }
};

// ★ v5.165.0(老師需求「大對抗和小遊戲登入任一邊，30分鐘內都不用再重新登入」)—
//   讀共用時間戳,30分鐘內顯示一顆「✅ 繼續使用 X 帳號」快速按鈕(login_hint 帶入，
//   非跳過驗證);逾時、被登出清除、或本機從未在小遊戲登入過都不顯示,自動退回一般流程。
window._lxpsRenderSharedLoginBanner = function(){
  var box = document.getElementById('lg-shared-login-banner');
  if(!box) return;
  var ts = 0, email = '';
  try{
    ts = parseInt(localStorage.getItem('lxps_shared_login_ts') || '0', 10);
    email = localStorage.getItem('lxps_shared_login_email') || '';
  }catch(_){}
  if(!email || !ts || (Date.now() - ts) >= 30 * 60 * 1000){
    box.style.display = 'none'; box.innerHTML = '';
    return;
  }
  var _esc = String(email).replace(/'/g, "\\'");
  box.style.display = 'block';
  box.innerHTML =
    '<button onclick="playSfx(\'sfx-confirm\',0.5);window.loginGateGoogleAs(\'' + _esc + '\')" style="' +
    'width:100%;padding:18px 24px;font-size:24px;font-weight:800;' +
    'background:linear-gradient(135deg,rgba(40,150,80,0.85),rgba(20,100,60,0.95));' +
    'border:3px solid rgba(120,255,180,0.7);color:#eaffea;border-radius:18px;cursor:pointer;' +
    'font-family:inherit;">✅ 繼續使用「' + email + '」(剛才在小遊戲用過)</button>';
};

// ★★ v5.136.0 — 渲染登入閘門的「這台平板登入過的帳號」清單 ★★
//   ⚠ 純顯示層,零雲端讀寫:資料來源是本機 localStorage 的 lxps_recent_accounts,
//     由 _addRecentAccount 在每次登入成功時維護(上限 6 個 LRU)。
//   ⚠ 清單為空(全新平板 / 剛清過快取)時整塊隱藏,不留一片空白框。
window._lgRenderRecentAccounts = function(){
  const box = document.getElementById('lg-recent-accounts');
  if(!box) return;
  let list = [];
  try{
    if(typeof window._getRecentAccounts === 'function') list = window._getRecentAccounts() || [];
  }catch(e){ console.warn('[登入閘門] 讀取最近帳號失敗', e); list = []; }
  // 沒有 email 的帳號按下去 login_hint 帶不出東西,直接不列(避免學生點了沒反應)
  list = list.filter(function(a){ return a && a.email; });
  if(list.length === 0){ box.style.display = 'none'; box.innerHTML = ''; return; }

  const _esc = function(s){
    return String(s == null ? '' : s)
      .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
      .replace(/"/g,'&quot;').replace(/'/g,'&#39;');
  };
  let html = '<div style="font-size:22.5px;color:#88bbff;font-weight:800;margin-bottom:12px;">'
           + '👤 這台裝置登入過的帳號(點一下登入)</div>';
  list.forEach(function(a){
    const _img = a.photoURL
      ? '<img src="' + _esc(a.photoURL) + '" referrerpolicy="no-referrer" '
        + 'style="width:60px;height:60px;border-radius:50%;object-fit:cover;flex-shrink:0;background:#222;">'
      : '<div style="width:60px;height:60px;border-radius:50%;background:linear-gradient(135deg,#4a9eff,#9b6dff);'
        + 'display:flex;align-items:center;justify-content:center;font-size:28.5px;color:#fff;font-weight:900;flex-shrink:0;">'
        + _esc((a.displayName || a.email || '?').slice(0,1).toUpperCase()) + '</div>';
    html += '<div class="_lg-acct-row" data-lg-email="' + _esc(a.email) + '" '
      + 'style="display:flex;align-items:center;gap:18px;padding:15px 21px;margin-bottom:12px;'
      + 'border:2.25px solid #3a5a8a;border-radius:18px;background:rgba(80,140,255,0.10);cursor:pointer;">'
      + _img
      + '<div style="flex:1;min-width:0;">'
      +   '<div style="font-size:24px;font-weight:700;color:#ffeeaa;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">'
      +     _esc(a.displayName || a.email) + '</div>'
      +   '<div style="font-size:18px;color:#8899aa;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">'
      +     _esc(a.email) + '</div>'
      + '</div>'
      + '<div style="font-size:19.5px;color:#88ccff;flex-shrink:0;">登入 ›</div>'
      + '</div>';
  });
  html += '<div style="font-size:18px;color:#889;line-height:1.5;margin:3px 0 6px;">'
        + '找不到自己的名字?按下面的「使用 Google 登入」,再從 Google 的清單裡選。</div>';
  box.innerHTML = html;
  box.style.display = 'block';
  // 逐列掛事件(不用 inline onclick,避免 email 內的引號把屬性打斷)
  Array.prototype.forEach.call(box.querySelectorAll('._lg-acct-row'), function(row){
    row.addEventListener('click', function(){
      const _em = row.getAttribute('data-lg-email') || '';
      try{ playSfx('sfx-confirm', 0.5); }catch(_){}
      window.loginGateGoogleAs(_em);
    });
  });
};

function loginGateSkip() {
  // ★ v3.11.14(2026-05-28) — 強制登入:訪客試玩入口已移除。
  //   保留此函式以防舊程式/快取殘留呼叫,行為改為「不進遊戲、留在登入閘門」。
  console.warn('[強制登入] loginGateSkip 已停用,玩家必須登入才能遊玩');
  const modal = document.getElementById('login-gate-modal');
  if(modal) modal.style.display = 'flex';
  try{ if(typeof window._lgRenderRecentAccounts === 'function') window._lgRenderRecentAccounts(); }catch(_){}   // ★ v5.136.0
}


