let _advMiniBattleActive = false;
let _advMiniBattleNextScene = 0;
let _advBossTeamSaved = null; // 儲存BOSS陣容，小怪戰後恢復

// ══════════════════════════════════════════════
//  小怪戰問答系統
// ══════════════════════════════════════════════

// 依場景取得小怪戰題庫
// ★ 新設計：
//   場景0（河堤）：鎖定玩家擅長科目，從「沒自信（簡單）」題庫開始
//   場景1（步道）：鎖定玩家擅長科目，使用玩家選擇的難度
//   場景2（茶園）：已改為隨機事件，通常不會進這個函式；若進了就比照場景1
function _advMiniGetQuizPool(sceneIdx) {
  try{ _pcqWeeklyResetCheck(); }catch(_){} // ★ v3.16.52 — 進小怪戰題庫前先判定本週是否需重置累積答對進度
  const grade   = _advPlayerGrade      || '小學中年級';
  const subject = _advPlayerSubject    || '自然';
  const diff    = _advPlayerDifficulty || '普通';
  // ★ v1.0.20260420.1700 — 三個五下自然獨立題庫(不在 ADV_QUIZ_DB 內),直接從對應陣列取題
  //   修復 Bug:選這些科目時小怪戰/pet 事件瞬間彈「所有題目都出過囉」重選視窗
  if(!window._miniQuizUsedIds) window._miniQuizUsedIds = new Set();
  // ★ v1.0.20260428 — 持久已答對題目過濾 helper(每分支共用)
  //   用 _persistentCorrectQuestions[科目] 過濾;若該科目都答對則重置該科目進度
  function _filterPersistentMini(rawPool, subjectKey){
    if(!subjectKey || !rawPool || !rawPool.length) return rawPool || [];
    if(typeof _persistentCorrectQuestions !== 'object' || !_persistentCorrectQuestions) return rawPool;
    const correctMap = _persistentCorrectQuestions[subjectKey];
    if(!correctMap || typeof correctMap !== 'object') return rawPool;
    const filtered = rawPool.filter(q => !correctMap[q.id]);
    if(filtered.length === 0 && rawPool.length >= 3){
      try{
        const _correctCount = Object.keys(correctMap).length;
        console.log('[題庫-mini] 🎉 ['+subjectKey+'] '+_correctCount+' 題全部答對! 自動重置進度');
        _persistentCorrectQuestions[subjectKey] = {};
        try{ if(typeof gameCloudSave === 'function') gameCloudSave(); }catch(_){}
        try{ bannerFX(null, '🎉 ['+subjectKey+'] 全題庫已答對! 重置進度', '#88ff99', 2500); }catch(_){}
      }catch(_){}
      return rawPool;
    }
    return filtered.length > 0 ? filtered : rawPool;
  }
  // ★ v1.0.20260424.0750 — 照顧與陪伴幼兒 / 領養與照顧狗狗 (專屬題庫,獨立記錄已答對)
  //   修復 Bug:選這兩個題庫進小怪戰跳出「所有題目都出過」重選視窗
  //   ★ v3.14.10 — 世界機關王大賽(機關王雙人組)併入同邏輯
  if(subject === '照顧與陪伴幼兒' || subject === '領養與照顧狗狗' || subject === '世界機關王大賽'){
    const _full = (subject === '照顧與陪伴幼兒')
      ? (typeof ADV_QUIZ_CARE_INFANT !== 'undefined' ? ADV_QUIZ_CARE_INFANT : [])
      : (subject === '領養與照顧狗狗')
      ? (typeof ADV_QUIZ_DOG_CARE !== 'undefined' ? ADV_QUIZ_DOG_CARE : [])
      : (typeof ADV_QUIZ_GREENMECH !== 'undefined' ? ADV_QUIZ_GREENMECH : []);
    const _key = (subject === '照顧與陪伴幼兒') ? 'careInfantPerfect'
               : (subject === '領養與照顧狗狗') ? 'dogCarePerfect'
               : 'greenMechPerfect';
    let _correctSet = {};
    try { _correctSet = (_medalStats && _medalStats[_key]) || {}; } catch(_){}
    // 過濾:本場未抽過 + 尚未答對的
    const _remaining = _full.filter(q => !_correctSet[q.id] && !window._miniQuizUsedIds.has(q.id));
    if(_remaining.length > 0) return _remaining;
    // 全部答對(理論上會觸發解鎖+清空進度) → 退而求其次,從全題庫抽未抽過的
    return _full.filter(q => !window._miniQuizUsedIds.has(q.id));
  }
  if(subject === '五下自然期中評量' && typeof ADV_QUIZ_5S_MIDTERM !== 'undefined'){
    const _raw = ADV_QUIZ_5S_MIDTERM.filter(q => !window._miniQuizUsedIds.has(q.id));
    return _filterPersistentMini(_raw, subject);
  }
  if(subject === '五下自然第三單元' && typeof ADV_QUIZ_5S_U3_ANIMAL !== 'undefined'){
    const _raw = ADV_QUIZ_5S_U3_ANIMAL.filter(q => !window._miniQuizUsedIds.has(q.id));
    return _filterPersistentMini(_raw, subject);
  }
  if(subject === '五下自然第四單元' && typeof ADV_QUIZ_5S_U4_SOUND !== 'undefined'){
    const _raw = ADV_QUIZ_5S_U4_SOUND.filter(q => !window._miniQuizUsedIds.has(q.id));
    return _filterPersistentMini(_raw, subject);
  }
  // ★ v5.115.0 — 六上自然四單元(小怪戰路徑,與 BOSS 戰 advGetQuizPool 同口徑)
  if(subject === '六上自然第一單元' && typeof ADV_QUIZ_6S_U1_WEATHER !== 'undefined'){
    const _raw = ADV_QUIZ_6S_U1_WEATHER.filter(q => !window._miniQuizUsedIds.has(q.id));
    return _filterPersistentMini(_raw, subject);
  }
  if(subject === '六上自然第二單元' && typeof ADV_QUIZ_6S_U2_HEAT !== 'undefined'){
    const _raw = ADV_QUIZ_6S_U2_HEAT.filter(q => !window._miniQuizUsedIds.has(q.id));
    return _filterPersistentMini(_raw, subject);
  }
  if(subject === '六上自然第三單元' && typeof ADV_QUIZ_6S_U3_LAND !== 'undefined'){
    const _raw = ADV_QUIZ_6S_U3_LAND.filter(q => !window._miniQuizUsedIds.has(q.id));
    return _filterPersistentMini(_raw, subject);
  }
  if(subject === '六上自然第四單元' && typeof ADV_QUIZ_6S_U4_EM !== 'undefined'){
    const _raw = ADV_QUIZ_6S_U4_EM.filter(q => !window._miniQuizUsedIds.has(q.id));
    return _filterPersistentMini(_raw, subject);
  }
  // ★ v1.0.20260428.2400 — 台灣環島題庫分支(依玩家在地圖選的 BOSS,只出該關 30 題)
  // ★ v1.0.20260428.3000 — 移除難度篩選,題目全 30 題池;難度只影響顯示選項數(由 _trimOptionsByTaiwanDifficulty 處理)
  if(subject === '台灣環島' || (typeof _adventureStage !== 'undefined' && _adventureStage === 'taiwan')){
    if(typeof TAIWAN_QUIZ_DB !== 'undefined'){
      const _bossId = window._advSelectedTaiwanBoss || null;
      // 只挑當前選定 BOSS 的題目;若沒選 BOSS(理論不會發生)則全 300 題
      const _twAll = _bossId
        ? TAIWAN_QUIZ_DB.filter(q => q.bossId === _bossId)
        : TAIWAN_QUIZ_DB.slice();
      // 過濾掉本場已抽的(_miniQuizUsedIds)
      const _tw = _twAll.filter(q => !window._miniQuizUsedIds.has(q.id));
      // 加上跨關卡持久已答對過濾
      const _twFiltered = _filterPersistentMini(_tw, '台灣環島');
      console.log('[題庫] 台灣關分支觸發,bossId=' + _bossId + ',可用 ' + _twFiltered.length + ' 題(難度=' + (window._advPlayerDifficulty || '未設') + ',只影響顯示選項數)');
      return _twFiltered;
    }
  }
  if(subject === '日本關' || (typeof _adventureStage !== 'undefined' && _adventureStage === 'japan')){
    if(!Array.isArray(window._japanShuffleBag) || !window._japanShuffleBag.length){
      const _jpAll = ADV_QUIZ_DB.filter(q => q.subject === '日本關').slice();
      for(let i = _jpAll.length - 1; i > 0; i--){
        const j = Math.floor(Math.random() * (i + 1));
        [_jpAll[i], _jpAll[j]] = [_jpAll[j], _jpAll[i]];
      }
      window._japanShuffleBag = _jpAll;
      try{ log(`📚 [日本關] 題庫已重新洗牌,共 ${_jpAll.length} 題,下一輪前保證不重複。`); }catch(_){}
    }
    // 進一步過濾掉本場已抽的(_miniQuizUsedIds,同場小怪戰不重複);
    // bag 本身已涵蓋「跨戰鬥、跨 BOSS/小怪不重複」
    const _jp = window._japanShuffleBag.filter(q => !window._miniQuizUsedIds.has(q.id));
    // ★ v1.0.20260428 — 加上跨關卡持久已答對過濾
    const _jpFiltered = _filterPersistentMini(_jp, '日本關');
    console.log('[題庫] 日本關分支觸發 (小怪戰)，可用', _jpFiltered.length, '題 (bag剩', window._japanShuffleBag.length, ')');
    return _jpFiltered;
  }
  // ★ v3.15.9 — 埃及關小怪戰題庫修正:本函式(小怪戰專用,與 BOSS 戰的 advGetQuizPool 不同路徑)
  //   原本只有日本/台灣有「|| _adventureStage==='xxx'」分支,獨缺埃及分支。
  //   而過場 advStartCutscene 會把 _advPlayerSubject 清空 → 本函式第 3 行 subject 退到預設「自然」,
  //   於是埃及小怪戰掉到最末段 ADV_QUIZ_DB.filter(q=>q.subject==='自然') → 出自然題而非埃及題。
  //   (v3.15.2 只修了 BOSS 戰的 _advSessionQuestions,沒修這條小怪路徑。)
  //   修法:比照日本關,subject==='埃及' 或 _adventureStage==='egypt' 即鎖定埃及 30 題題庫。
  if(subject === '埃及' || (typeof _adventureStage !== 'undefined' && _adventureStage === 'egypt')){
    const _egAll = ADV_QUIZ_DB.filter(q => q.subject === '埃及');
    const _eg = _egAll.filter(q => !window._miniQuizUsedIds.has(q.id));
    const _egFiltered = _filterPersistentMini(_eg, '埃及');
    console.log('[題庫] 埃及關分支觸發 (小怪戰)，過濾後可用', _egFiltered.length, '/', _egAll.length, '題');
    return _egFiltered;
  }
  // ★ v5.45.0 — 中國關 Phase 6 小怪戰題庫分支(比照埃及 v3.15.9 修法:
  //   小怪戰與 BOSS 戰不同路徑,subject 被過場清空時以 _adventureStage==='china' 兜底鎖定中國題庫)
  if(subject === '中國關' || (typeof _adventureStage !== 'undefined' && _adventureStage === 'china')){
    const _cnAll = ADV_QUIZ_DB.filter(q => q.subject === '中國關');
    const _cn = _cnAll.filter(q => !window._miniQuizUsedIds.has(q.id));
    const _cnFiltered = _filterPersistentMini(_cn, '中國關');
    console.log('[題庫] 中國關分支觸發 (小怪戰)，過濾後可用', _cnFiltered.length, '/', _cnAll.length, '題');
    return _cnFiltered;
  }
  let pool = ADV_QUIZ_DB.filter(q =>
    q.subject === subject &&
    !window._miniQuizUsedIds.has(q.id)
  );
  // 套用跨關卡持久已答對過濾(會在過濾後池太小時自動重置)
  pool = _filterPersistentMini(pool, subject);
  // 若還是太少(本場 _miniQuizUsedIds 蓋掉太多),放寬到「全科目」
  if(pool.length < 2){
    pool = ADV_QUIZ_DB.filter(q => q.subject === subject);
    pool = _filterPersistentMini(pool, subject);
  }
  return pool;
}

function _advMiniQuizAsk(onDone) {
  const sceneIdx = _advSceneIdx;
  const pool = _advMiniGetQuizPool(sceneIdx);
  if(!pool || pool.length === 0){
    if(typeof _advMiniBattleActive !== 'undefined' && !_advMiniBattleActive){
      try{ console.log('[_advMiniQuizAsk] 小怪戰已結束,直接 onDone'); }catch(_){}
      if(onDone) onDone();
      return;
    }
    // 防卡死:重試次數上限保護(2 次仍空 → 跳過避免無限迴圈)
    if(typeof window._miniQuizRepickAttempts !== 'number') window._miniQuizRepickAttempts = 0;
    if(window._miniQuizRepickAttempts >= 2){
      try{ console.warn('[_advMiniQuizAsk] 重置 2 次仍題庫為空,跳過答題環節避免卡死'); }catch(_){}
      try{ log(`⚠ 題庫持續為空,自動跳過答題環節`); }catch(_){}
      window._miniQuizRepickAttempts = 0;
      if(onDone) onDone();
      return;
    }
    window._miniQuizRepickAttempts++;
    // 自動重置題庫狀態(不彈視窗、不換題庫、不換難度)
    try{
      if(typeof window._miniQuizUsedIds !== 'undefined') window._miniQuizUsedIds = new Set();
      // 日本關 shuffle bag 也清掉,讓 _advMiniGetQuizPool 重新洗牌
      if(Array.isArray(window._japanShuffleBag)) window._japanShuffleBag = [];
      try{ log(`📚 [題庫] 已全部答過,自動洗牌重新開始一輪(題序、答案序隨機)。`); }catch(_){}
    }catch(_){}
    // 直接再問下一題
    setTimeout(()=>{ try{ _advMiniQuizAsk(onDone); }catch(e){ if(onDone) onDone(); } }, 150);
    return;
  }
  // ★ v1.0.20260511.6130 — 成功抽到題目,重置重選計數
  window._miniQuizRepickAttempts = 0;
  if(!Array.isArray(window._miniRecentQuestionIds)) window._miniRecentQuestionIds = [];
  const _miniRecent = window._miniRecentQuestionIds;
  const _fresh = pool.filter(p => !_miniRecent.includes(p.id));
  const _candidates = _fresh.length ? _fresh : pool;
  const q = _candidates[Math.floor(Math.random() * _candidates.length)];
  if(!q){ if(onDone) onDone(); return; }
  // 維護近期佇列:隨 pool 大小動態調整 window
  const _maxWindow = Math.max(15, Math.floor(pool.length * 0.75));
  _miniRecent.push(q.id);
  while(_miniRecent.length > _maxWindow) _miniRecent.shift();
  window._miniQuizUsedIds.add(q.id);
  try{
    if(Array.isArray(window._japanShuffleBag) && window._japanShuffleBag.length){
      const _bi = window._japanShuffleBag.findIndex(x => x.id === q.id);
      if(_bi >= 0) window._japanShuffleBag.splice(_bi, 1);
    }
    if(typeof _advUsedQuestionIds !== 'undefined' && _advUsedQuestionIds && typeof _advUsedQuestionIds.add === 'function'){
      _advUsedQuestionIds.add(q.id);
    }
  }catch(_syncE){ console.warn('[題庫同步] 小怪戰抽題後同步失敗:', _syncE); }
  window._miniQuizOnDone = onDone;
  window._miniQuizCurrentQ = q;
  window._miniQuizPhase = 'asking';
  // ★ v3.4.18 — 記錄 onDone 設定時間戳,讓 _gpIsAnyLegitModalOpen 與 iPad nudge 能判斷
  //   「onDone 已掛超過 X 秒但 overlay 沒 .show」= 殭屍 callback,該救援
  window._miniQuizOnDoneSetAt = Date.now();

  const qOv = document.getElementById('adv-quiz-overlay');
  if(!qOv){ if(onDone) onDone(); return; }

  // 停止 BOSS 計時器
  if(typeof _advQuizTimerHandle !== 'undefined' && _advQuizTimerHandle){
    clearInterval(_advQuizTimerHandle); _advQuizTimerHandle = null;
  }

  // 設定題目標籤
  const qLbl = document.getElementById('adv-quiz-label');
  if(qLbl) qLbl.textContent = '🐾 小怪出題！回答正確可獲得知識幣';

  try{ if(typeof _updateSpecialQuizProgressBar === 'function') _updateSpecialQuizProgressBar(); }catch(_progE){ console.warn('[quiz progress]', _progE); }

  // 設定題目文字
  const qEl = document.getElementById('adv-quiz-question');
  if(qEl) qEl.textContent = q.question;
  try{ if(qEl) window._lxpsQuizMediaApply(qEl, q); }catch(_qm){}   // ★ v5.145.0 題圖／播放鈕(只加不改)

  // 隱藏計時器
  const timerEl = document.getElementById('adv-quiz-timer');
  if(timerEl) timerEl.style.display = 'none';

  // 清除法寶列
  const tbEl = document.getElementById('adv-quiz-treasure-bar');
  if(tbEl) tbEl.innerHTML = '';

  // 用相同的 aqo-btn 系統建立選項（支援洗牌）
  const optDiv = document.getElementById('adv-quiz-options');
  const letters = ['A','B','C','D'];
  // ★ v1.0.20260428 — 依玩家難度過濾選項數量(沒自信2 / 普通3 / 我很會4)
  const _rawOpts = (q.options || [q.A, q.B, q.C, q.D].filter(Boolean));
  const _miniDiffFilt = _filterOptionsByDifficulty(_rawOpts, q.answer, _advPlayerDifficulty);
  const _miniFiltOpts = _miniDiffFilt.options;
  const _miniFiltCorrectIdx = _miniDiffFilt.correctIdx;
  const origOpts = _miniFiltOpts.map((text, i) => ({text, origIdx:i}));
  // 洗牌
  for(let si=origOpts.length-1; si>0; si--){
    const sj = Math.floor(Math.random()*(si+1));
    [origOpts[si], origOpts[sj]] = [origOpts[sj], origOpts[si]];
  }
  const correctOrigIdx = _miniFiltCorrectIdx;
  const newCorrectIdx  = origOpts.findIndex(o => o.origIdx === correctOrigIdx);
  const newCorrectLetter = letters[newCorrectIdx] || _miniDiffFilt.correctLetter;
  optDiv.innerHTML = '';
  origOpts.forEach((opt, i) => {
    const btn = document.createElement('button');
    btn.className = 'aqo-btn';
    btn.dataset.letter = letters[i];
    btn.dataset.isCorrect = (opt.origIdx === correctOrigIdx) ? '1' : '0';
    btn.innerHTML = '<span class="aqo-letter">' + letters[i] + '</span>' + opt.text;
    btn.onclick = () => _advMiniQuizSubmit(letters[i], btn.dataset.isCorrect === '1');
    optDiv.appendChild(btn);
  });
  // ★ v5.245.0 — 互動音樂題(小怪/寵物題同樣適用;小怪題本來就不計時)
  try{ if(typeof window._lxpsEarMount === 'function') window._lxpsEarMount(q, 'mini'); }catch(_eEarM){}

  qOv.classList.add('show');
  // ★ v3.4.19 — 修 BUG:13:45:53/13:46:30 玩家連續回報「題目沒正常出現」,
  //   症狀:_advMiniQuizAsk 跑完 qOv.classList.add('show') 後,3 秒 visibility watchdog
  //         檢查 overlay.show=false,代表 .show 被別處立刻 remove 掉 / CSS race / display 殘留 none。
  //   修法 1:同步加 inline style.display='' 清掉殘留 display:none(救援關閉時設的);
  //   修法 2:用 requestAnimationFrame 確保 DOM 應用 .show 後再驗證一次,若 .show 真的沒生效則 console.warn。
  try{
    if(qOv.style.display === 'none' || qOv.style.display === ''){
      // 清掉 inline display(可能被前一次救援設成 'none'),讓 CSS .show 生效
      qOv.style.display = '';
    }
    // 強制 reflow + RAF 驗證
    void qOv.offsetWidth;
    if(typeof requestAnimationFrame === 'function'){
      requestAnimationFrame(function(){
        try{
          if(!qOv.classList.contains('show')){
            console.warn('[_advMiniQuizAsk] .show 被立刻 remove,強制補回');
            qOv.classList.add('show');
            qOv.style.display = '';
          }
        }catch(_){}
      });
    }
  }catch(_eShowFix){ console.warn('[_advMiniQuizAsk] 確保 .show 失敗', _eShowFix); }

  // ★ 問答教學引導已移除
}


