window._petFollowFilterKey = 'all';
window._petFollowHeroPass = function(name){
  try{
    var _k = window._petFollowFilterKey || 'all';
    if(_k === 'all') return true;
    if(_k === 'cond'){
      var _needs = (typeof _condSearchEffects !== 'undefined' && Array.isArray(_condSearchEffects)) ? _condSearchEffects : [];
      if(_needs.length === 0) return true;
      var _effs = (typeof HERO_SKILL_EFFECTS !== 'undefined' && HERO_SKILL_EFFECTS[name]) ? HERO_SKILL_EFFECTS[name] : [];
      return _needs.every(function(e){ return _effs.indexOf(e) >= 0; });
    }
    if(_k.indexOf('rarity_') === 0){
      var _want = _k.slice(7);
      var _r = (typeof _getHeroRarity === 'function') ? _getHeroRarity(name) : null;
      return _r === _want;
    }
    var _types = (typeof _heroSkillTypes === 'function') ? (_heroSkillTypes(name) || []) : [];
    return _types.indexOf(_k) >= 0;
  }catch(_e){ return true; }
};
window._petPickFollowHero = function(petName){
  try{
    var rec = window._tamedPets && window._tamedPets[petName]; if(!rec) return;
    window._petFollowFilterKey = 'all';   // 每次開啟重置篩選
    window._petFollowPickerPet = petName;
    window._petFollowPickerRender();
  }catch(_e){ console.warn('[寵物跟隨挑英雄V2]', _e); }
};
