      return '<div onclick="playSfx(\'sfx-confirm\',0.6);window._petSetFollow(\''+_pnEsc+'\',\''+hnEsc+'\');document.getElementById(\'_pet-follow-hero-modal\').remove();try{var _d=document.getElementById(\'pet-detail-modal\');if(_d)_d.remove();}catch(_){}try{if(typeof _buildPetPage===\'function\')_buildPetPage();}catch(_){}try{if(typeof _showPetDetail===\'function\')_showPetDetail(\''+_pnEsc+'\');}catch(_){}" style="width:118px;background:'+(isCur?'rgba(40,90,60,0.95)':'rgba(22,38,30,0.92)')+';border:2px solid '+(isCur?'rgba(120,255,180,0.9)':'rgba(80,220,140,0.35)')+';border-radius:12px;overflow:hidden;cursor:pointer;text-align:center;">'
