      + (rec.followTo ? '<button onclick="playSfx(\'sfx-cancel\',0.5);window._petSetFollow(\''+_pnEsc+'\',null);document.getElementById(\'_pet-follow-hero-modal\').remove();try{var _d=document.getElementById(\'pet-detail-modal\');if(_d)_d.remove();}catch(_){}try{if(typeof _buildPetPage===\'function\')_buildPetPage();}catch(_){}try{if(typeof _showPetDetail===\'function\')_showPetDetail(\''+_pnEsc+'\');}catch(_){}" style="padding:10px 22px;border-radius:10px;background:rgba(80,40,40,0.7);border:1.5px solid rgba(255,120,120,0.5);color:#ffbbaa;font-size:16px;font-weight:700;cursor:pointer;font-family:inherit;">🚫 '+(_cute?'先不跟任何英雄':'取消跟隨')+'</button>' : '')
      + '<button onclick="playSfx(\'sfx-cancel\',0.4);document.getElementById(\'_pet-follow-hero-modal\').remove()" style="padding:10px 30px;font-size:18px;font-weight:700;background:rgba(40,40,50,0.8);border:1.5px solid rgba(150,150,160,0.5);color:#ccc;border-radius:10px;cursor:pointer;font-family:inherit;">✕ 關閉</button>'
      + '</div>';
    m.appendChild(box);
