// ═══════════════════════════════════════════════════════════════════
// ★ v4.0.0 — 寵物馴養大系統 Phase A+(2026-07-03 老師裁決)
//   ①好感度改「獨立累積制」(初始0·上限100·戰鬥20%+1·勝BOSS+1·小屋互動):
//     忠誠夥伴四階門檻 25/50/75/100 不變,僅換好感度來源
//   ②寵物小屋(圖鑑上方入口·全螢幕背景 寵物小屋.png·BGM 寵物小屋BGM.m4a·
//     3 槽位入住[裁決A甲:玩家自選]·每日撫摸/玩耍/餵食各1次)
//   ③餵食=主食教學(裁決B:食物表依類型分好·餵對好感+2 EXP+1·餵錯好感-1可重試)
//   ④馴養知識問答(裁決:每次用飼料出1題·答對成功率×1.5·答錯×0.5·夾0.05~0.95·
//     無答題獎勵·不可用法寶·取材 PET_KNOWLEDGE 別名/主食/習性/天敵)
//   ⑤隨機寵物召喚卷 pet_summon_ticket(未馴養 SSR10%/SR30%/R60%·直接馴養收服·v4.9.0 口徑正名)
// ═══════════════════════════════════════════════════════════════════
// ══════════════════════════════════════════════════════════════════
// ★ v4.10.0 需求(修正5) — 戰鬥寵物出現機制統一
//   ①所有戰鬥中出現的寵物(答題獎勵 get_pet / 動物學家召喚)依稀有度出現率:
//     SSR=15% / SR=30% / R=55%。先擲稀有度層,再從該層均勻抽 1 隻;
//     該層在池中為空 → 依剩餘層機率重新正規化(絕不空手)。
//   ②每次出現皆「單獨機率」:完全不設「優先未收錄/未馴養」加權,
//     保持高稀有度寵物真正的稀少感(已馴養/未馴養機率相同)。
//   ③五色鳥為教學必得寵物,不入戰鬥出現池(不佔玩家抽取機率)。
// ══════════════════════════════════════════════════════════════════
window._PET_APPEAR_RATE = { SSR: 0.15, SR: 0.30, R: 0.55 };
window._petRollByRarity = function(pool, n){
  try{
    var src = (pool || []).filter(function(e){ return e && (e.pet || e.n) && (e.pet || e.n) !== '五色鳥'; });
    if(!src.length) src = (pool || []).slice();   // 全池只剩五色鳥的極端 fallback(理論不會發生)
    var want = Math.max(1, n || 1);
    var out = [];
    for(var i = 0; i < want && src.length; i++){
      // 依剩餘池分層
      var tiers = { SSR: [], SR: [], R: [] };
      src.forEach(function(e){
        var pn = e.pet || e.n;
        var r = (window.PET_RARITY && window.PET_RARITY[pn]) || 'R';
        if(!tiers[r]) r = 'R';
        tiers[r].push(e);
      });
      // 空層剔除後重新正規化
      var keys = ['SSR','SR','R'].filter(function(k){ return tiers[k].length; });
      if(!keys.length) break;
      var total = keys.reduce(function(s, k){ return s + window._PET_APPEAR_RATE[k]; }, 0);
      var roll = Math.random() * total, tier = keys[keys.length - 1];
      for(var ki = 0; ki < keys.length; ki++){
        roll -= window._PET_APPEAR_RATE[keys[ki]];
        if(roll < 0){ tier = keys[ki]; break; }
      }
      var arr = tiers[tier];
      var picked = arr[Math.floor(Math.random() * arr.length)];
      out.push(picked);
      // 同批去重(動物學家一次呼喚 4 隻不重複;每隻仍是獨立擲層)
      src = src.filter(function(e){ return e !== picked; });
    }
    return out;
  }catch(_e){
    console.warn('[寵物稀有度抽選]', _e);
    var fb = (pool || []).slice().sort(function(){ return Math.random() - 0.5; });
    return fb.slice(0, Math.max(1, n || 1));
  }
};
// 戰鬥中「已馴養/未馴養」小徽章 HTML(寵物出現視窗用)
window._petTameBadgeHtml = function(pn, fs){
  try{
    var f = fs || 15;
    if(window._petIsTamed && window._petIsTamed(pn)){
      return '<span style="display:inline-block;font-size:' + f + 'px;font-weight:900;color:#0a2a18;background:linear-gradient(135deg,#7dffb0,#3fd97f);border-radius:8px;padding:2px 9px;vertical-align:middle;">🎓 已馴養</span>';
    }
    return '<span style="display:inline-block;font-size:' + f + 'px;font-weight:900;color:#3a2a08;background:linear-gradient(135deg,#ffe28a,#f0b74a);border-radius:8px;padding:2px 9px;vertical-align:middle;">✨ 未馴養</span>';
  }catch(_){ return ''; }
};
// ★ v4.20.0(任務4) — 戰鬥寵物出現視窗「稀有度 + 收集狀態」合併徽章:
//   稀有度徽章(_petRarityBadgeHtml)+ 狀態:
//     🎓 已馴養(_petIsTamed 權威)
//     👀 已相遇 + ✨ 未馴養(_isPetMet 出現並攜帶過但尚未收錄馴養·v4.9.0 語義)
//     🌫 未相遇 + ✨ 未馴養(從沒見過的新寵物)
//   徽章反映「出現當下」快照(裝備攜帶後才算相遇·語義正確);寵物名皆為內建常數無 XSS 風險。
window._petStatusBadgesHtml = function(pn, fs){
  try{
    var f = fs || 15, out = '';
    try{ if(typeof window._petRarityBadgeHtml === 'function') out += (window._petRarityBadgeHtml(pn, f) || ''); }catch(_){}
    var _chip = function(txt, fg, bg){
      return ' <span style="display:inline-block;font-size:' + f + 'px;font-weight:900;color:' + fg + ';background:' + bg + ';border-radius:8px;padding:2px 9px;vertical-align:middle;">' + txt + '</span>';
    };
    if(window._petIsTamed && window._petIsTamed(pn)){
      out += _chip('🎓 已馴養', '#0a2a18', 'linear-gradient(135deg,#7dffb0,#3fd97f)');
    }else{
      var _met = false;
      try{ _met = !!(window._isPetMet && window._isPetMet(pn)); }catch(_){}
      if(_met){
        out += _chip('👀 已相遇', '#102a3a', 'linear-gradient(135deg,#9adcff,#5db2e8)');
      }else{
        out += _chip('🌫 未相遇', '#eaeaf2', 'linear-gradient(135deg,#8a8aa0,#5f5f74)');
      }
      out += _chip('✨ 未馴養', '#3a2a08', 'linear-gradient(135deg,#ffe28a,#f0b74a)');
    }
    return out;
  }catch(_){ return ''; }
};
// 攜帶「已馴養」寵物 → 好感 +1(戰鬥中出現並攜帶;每場每寵最多 1 次防刷)
window._petCarryAffOnce = function(pn, hero){
  try{
    if(!pn || !(window._petIsTamed && window._petIsTamed(pn))) return;
    if(typeof G === 'undefined' || !G) return;
    G._petCarryAffGiven = G._petCarryAffGiven || {};
    if(G._petCarryAffGiven[pn]) return;
    G._petCarryAffGiven[pn] = 1;
    var na = window._petAddAff(pn, 1);
    var _cute = (typeof _artStyle !== 'undefined' && _artStyle === 'cute');
    try{ log('💖 [' + pn + '] 很開心又能一起冒險!好感 +1(目前 ' + na + ')'); }catch(_){}
    try{ if(hero && typeof showPopup === 'function') showPopup(hero, '💖+1', 'energy'); }catch(_){}
    try{ _showInGameToast(_cute ? ('💖 [' + pn + '] 好開心!好感 +1!') : ('💖 攜帶已馴養寵物 [' + pn + ']:好感 +1(目前 ' + na + ')'), '#ffbbdd', 2200); }catch(_){}
    try{ Promise.resolve(gameCloudSave()).catch(function(){}); }catch(_){}
  }catch(_e){ console.warn('[攜帶好感]', _e); }
};
window._petHouseSlots = Array.isArray(window._petHouseSlots) ? window._petHouseSlots : [null, null, null];
window._petHouseDaily = (window._petHouseDaily && typeof window._petHouseDaily === 'object' && window._petHouseDaily.rec) ? window._petHouseDaily : { d:'', rec:{} };

// 好感度累加(初始0·上限100·達100彈 MAX 提示)
window._petAddAff = function(pn, delta, quiet){
  try{
    var rec = window._tamedPets && window._tamedPets[pn]; if(!rec) return 0;
    var before = Math.max(0, Math.min(100, rec.aff|0 || 0));
    var after  = Math.max(0, Math.min(100, before + (parseInt(delta,10)||0)));
    rec.aff = after;
    if(after >= 100 && before < 100 && !quiet){
      var _cute = (window._artStyle === 'cute');
      try{ _showInGameToast(_cute ? ('💖 ['+pn+'] 好感度 MAX!牠最喜歡你了!') : ('💖 ['+pn+'] 好感度達 100 MAX!「忠誠夥伴」效果全開!'), '#ff99cc', 3200); }catch(_){}
    }
    // ★ v4.6.0 — 寵物獎章:好感首達 100 即時檢查(💖心心相印;涵蓋小屋互動/戰鬥好感全部路徑)
    try{ if(after >= 100 && before < 100 && typeof window._checkPetMedals === 'function') window._checkPetMedals(); }catch(_){}
    return after;
  }catch(_){ return 0; }
};

// ★ v4.12.0 — 寵物小屋互動好感「每日硬上限 +5」(老師需求:撫摸+1、餵對+2、遊戲+2=每日 5)
//   任何重複連點/網路重試/未來新互動都絕不可能讓「小屋來源好感」單日超過 5(防重複累加根治)。
//   額度記於當日 _petHouseDayRec(pn).affGain(隨 petHouseDaily 上雲·跨日 8:00 歸零)。
//   ★ 只夾「正向加值」;餵錯 −1 走 _petAddAff 直接扣(懲罰不受上限管)。
//   ★ 戰鬥好感(攜帶/勝場/勝 BOSS)是獨立來源,走 _petAddAff,不受此上限影響。
window._PET_HOUSE_AFF_DAILY_CAP = 5;
window._petHouseAddAff = function(pn, delta){
  try{
    var want = Math.max(0, parseInt(delta, 10) || 0);
    if(want <= 0) return window._petAffection(pn);
    var rec = window._petHouseDayRec(pn);                 // 內含跨日重置
    var got = Math.max(0, rec.affGain | 0 || 0);
    var give = Math.max(0, Math.min(window._PET_HOUSE_AFF_DAILY_CAP - got, want));
    rec.affGain = got + give;
    return window._petAddAff(pn, give, true);             // quiet:達 100 的 MAX 提示交由呼叫端決定
  }catch(_){ return window._petAffection(pn); }
};

// ★ v4.12.0 — 好感度分級標籤(老師指定五級)
window._petAffLabel = function(aff){
  var a = Math.max(0, Math.min(100, aff | 0 || 0));
  if(a >= 100) return '不離不棄';
  if(a >= 75)  return '非常親密';
  if(a >= 50)  return '有點親密';
  if(a >= 25)  return '已經熟識';
  return '有點陌生';
};

// 台灣「寵物互動日」字串·每日互動紀錄跨日自動歸零
// ★ v4.9.0 需求3 — 重置時間由台灣午夜 0:00 改為「台灣早上 8:00」(老師裁決)。
//   台灣 8:00 == UTC 0:00 → 直接取 UTC 日期即得「早上 8 點才換日」的日鍵(同 _dailyBonusInfo 口徑)。
window._petTwDateStr = function(){
  var t = new Date();
  return t.getUTCFullYear()+'-'+String(t.getUTCMonth()+1).padStart(2,'0')+'-'+String(t.getUTCDate()).padStart(2,'0');
};
window._petHouseDayRec = function(pn){
  var d = window._petTwDateStr();
  if(!window._petHouseDaily || window._petHouseDaily.d !== d){ window._petHouseDaily = { d:d, rec:{} }; }
  if(!window._petHouseDaily.rec[pn]) window._petHouseDaily.rec[pn] = {};
  return window._petHouseDaily.rec[pn];
};
window._petHouseCanDo = function(pn, act){ try{ if(typeof window._isAdminUser === 'function' && window._isAdminUser()) return true; return !window._petHouseDayRec(pn)[act]; }catch(_){ return false; } };
// ★ v4.9.0 需求3 — 每日互動「鎖定當日夥伴」:第一次互動前先確認今天的入住寵物;
//   一旦確認開始互動,今日即無法再更換入住寵物(防止換寵刷每日互動),明日早上 8:00 隨日鍵重置。
//   鎖定名單存於 _petHouseDaily.lock(隨既有 petHouseDaily_s 序列化上雲·跨日自動歸零)。
window._petHouseLockInfo = function(){
  try{
    var d = window._petTwDateStr();
    if(!window._petHouseDaily || window._petHouseDaily.d !== d){ window._petHouseDaily = { d:d, rec:{} }; }
    var lk = window._petHouseDaily.lock;
    return (Array.isArray(lk) && lk.length) ? lk : null;
  }catch(_){ return null; }
};
window._petHouseLockToday = function(){
  try{
    var d = window._petTwDateStr();
    if(!window._petHouseDaily || window._petHouseDaily.d !== d){ window._petHouseDaily = { d:d, rec:{} }; }
    window._petHouseDaily.lock = (window._petHouseSlots || []).filter(function(x){ return !!x; }).slice(0, 3);
    try{ Promise.resolve(gameCloudSave()).catch(function(){}); }catch(_){}
    try{ window._petHouseRender(); }catch(_){}
  }catch(_){}
};
// 未鎖定 → 彈確認視窗(列出目前入住的寵物);玩家按「開始互動」才鎖定並執行 onOk。已鎖定 → 直接 onOk。
window._petHouseAskLock = function(onOk){
  try{
    if(window._petHouseLockInfo()){ if(onOk) onOk(); return; }
    var _cute = (typeof _artStyle !== 'undefined' && _artStyle === 'cute');   // ★ 鐵律1.232:bare 判定
    var names = (window._petHouseSlots || []).filter(function(x){ return !!x; });
    if(!names.length){
      try{ _showInGameToast(_cute ? '🏠 先按 ➕ 請寵物來住,才能一起玩喔!' : '🏠 請先邀請寵物入住,才能開始互動。', '#ffee99', 2600); }catch(_){}
      return;
    }
    var old = document.getElementById('_ph-lock-modal'); if(old) old.remove();
    var m = document.createElement('div');
    m.id = '_ph-lock-modal';
    m.style.cssText = 'position:fixed;inset:0;z-index:9650;background:rgba(0,0,0,0.8);display:flex;align-items:center;justify-content:center;padding:20px;font-family:inherit;';
    var box = document.createElement('div');
    box.style.cssText = 'background:linear-gradient(160deg,rgba(26,32,16,0.99),rgba(12,14,7,0.99));border:2.5px solid rgba(255,220,120,0.75);border-radius:20px;max-width:560px;width:100%;padding:24px 22px 20px;text-align:center;box-shadow:0 14px 40px rgba(0,0,0,0.6);';
    box.innerHTML = '<div style="font-size:52px;line-height:1;margin-bottom:8px;">🔒</div>'
      + '<div style="font-size:clamp(21px,2.6vw,27px);font-weight:900;color:#ffe8a0;margin-bottom:10px;">' + (_cute ? '今天要和牠們一起玩嗎?' : '確認今日互動夥伴') + '</div>'
      + '<div style="font-size:clamp(17px,2vw,21px);color:#ffeecc;font-weight:800;margin-bottom:10px;">🐾 ' + names.join('、') + '</div>'
      + '<div style="font-size:clamp(15px,1.7vw,18px);color:#f2ffe8;line-height:1.75;">' + (_cute
        ? '一旦開始互動,<b>今天就不能換寵物</b>囉!<br>要等<b>明天早上 8:00</b> 重置才能換。'
        : '一旦開始互動,今日將<b>無法再更換入住寵物</b>;<br>每日互動次數於<b>明日早上 8:00</b> 重置。') + '</div>';
    var row = document.createElement('div');
    row.style.cssText = 'display:flex;gap:10px;justify-content:center;margin-top:18px;flex-wrap:wrap;';
    var no = document.createElement('button');
    no.textContent = '✕ ' + (_cute ? '再想想' : '再想想');
    no.style.cssText = 'padding:11px 24px;font-size:17px;font-weight:800;background:rgba(50,55,52,0.85);border:1.5px solid rgba(150,160,155,0.5);color:#cfe;border-radius:12px;cursor:pointer;font-family:inherit;';
    no.onclick = function(){ try{ playSfx('sfx-cancel',0.4); }catch(_){} m.remove(); };
    var yes = document.createElement('button');
    yes.textContent = '✅ 開始互動!';
    yes.style.cssText = 'padding:12px 30px;font-size:clamp(18px,2.1vw,22px);font-weight:900;background:linear-gradient(135deg,rgba(40,130,75,0.97),rgba(60,190,110,0.97));border:2px solid rgba(120,255,175,0.9);color:#eaffef;border-radius:12px;cursor:pointer;font-family:inherit;box-shadow:0 4px 16px rgba(70,220,140,0.45);';
    yes.onclick = function(){
      try{ playSfx('sfx-confirm',0.6); }catch(_){}
      window._petHouseLockToday();
      m.remove();
      try{ _showInGameToast(_cute ? '🐾 好!今天就和「'+names.join('、')+'」一起玩!' : '🔒 已鎖定今日互動夥伴:'+names.join('、'), '#aaffcc', 3000); }catch(_){}
      if(onOk){ try{ onOk(); }catch(_){} }
    };
    row.appendChild(no); row.appendChild(yes);
    box.appendChild(row);
    m.appendChild(box);
    document.body.appendChild(m);
    try{ playSfx('sfx-gentle',0.5); }catch(_){}
  }catch(_e){ console.warn('[小屋互動鎖]', _e); }
};

// ══════════════════════════════════════════════════════════════════
// ★ v4.10.0 需求(修正1+2) — 每日互動鎖改「逐槽位」制(取代 v4.9.0 全域三夥伴一次鎖):
//   鐵則:每個寵物槽位每天只綁定「一種寵物」互動;該槽一旦開始任何互動
//   (撫摸/玩耍/餵食其一)即鎖定該槽寵物,今日不可更換該槽;三槽各自獨立。
//   教學/互動結束後仍有空槽或未鎖槽 → 可再請「還沒互動過的寵物」入住補互動。
//   每天台灣早上 8:00 隨 _petTwDateStr 日鍵重置(資料掛 _petHouseDaily.lockSlots
//   隨既有 petHouseDaily_s 序列化上雲)。舊 _petHouseLockInfo/LockToday/AskLock
//   三函式保留不刪(誤刪是大忌·相容舊呼叫);新流程一律走下列逐槽版。
// ══════════════════════════════════════════════════════════════════
// 取得今日某槽鎖定的寵物名(null=該槽今日尚未鎖定);含 v4.9.0 legacy lock 陣列一次性遷移
window._petHouseSlotLock = function(idx){
  try{
    var d = window._petTwDateStr();
    if(!window._petHouseDaily || window._petHouseDaily.d !== d){ window._petHouseDaily = { d:d, rec:{} }; }
    var hd = window._petHouseDaily;
    if(!hd.lockSlots || typeof hd.lockSlots !== 'object'){
      hd.lockSlots = { 0:null, 1:null, 2:null };
      // legacy 遷移:v4.9.0 全域 lock 陣列(當日)→ 依「目前槽位」映射到 lockSlots(只做一次)
      if(Array.isArray(hd.lock) && hd.lock.length){
        (window._petHouseSlots || []).forEach(function(pn, i){
          if(pn && hd.lock.indexOf(pn) >= 0) hd.lockSlots[i] = pn;
        });
      }
    }
    return hd.lockSlots[idx] || null;
  }catch(_){ return null; }
};
// 鎖定某槽今日夥伴
window._petHouseLockSlot = function(idx, pn){
  try{
    window._petHouseSlotLock(idx);   // 確保今日結構存在(含遷移)
    window._petHouseDaily.lockSlots[idx] = pn;
    try{ Promise.resolve(gameCloudSave()).catch(function(){}); }catch(_){}
    try{ window._petHouseRender(); }catch(_){}
    try{ if(typeof window._petNavBadgeRefresh === 'function') window._petNavBadgeRefresh(); }catch(_){}
  }catch(_){}
};
// 逐槽互動守門:該槽鎖到別隻→擋;未鎖→彈單寵確認視窗,按「開始互動」才鎖並執行 onOk;
// 已鎖到同一隻→直接 onOk。回傳 true=可直接進行(呼叫端繼續),false=已擋或等確認。
window._petHouseAskLockSlot = function(idx, pn, onOk){
  try{
    var _cute = (typeof _artStyle !== 'undefined' && _artStyle === 'cute');   // ★ 鐵律1.232:bare 判定
    // ★ v4.21.0 — GM 測試不受逐槽鎖定限制:GM 一律放行(不鎖槽·可自由換寵重複互動測試),學生行為完全不變。
    if(typeof window._isAdminUser === 'function' && window._isAdminUser()) return true;
    var lk = window._petHouseSlotLock(idx);
    // ★ v4.12.0 致命修復 — 「已鎖到同一隻」只回傳 true 讓呼叫端「繼續跑自己的本體一次」,
    //   絕不可在此再呼叫 onOk():呼叫端(_petHouseFeed/_petHouseFeedMode/_petPlayStart)傳入的
    //   onOk 正是「重新呼叫自己」,若此處 onOk()→feed→askLock→onOk()→feed… 會無窮遞迴,
    //   展開時每層 _petHouseFeed 本體各跑一次 _petAddAff(+2) → 好感度暴衝到 100(clamp)。
    //   confirm 首鎖的 onOk 由 yes.onclick 另行呼叫(見下方),與此分支無關。
    if(lk && lk === pn){ return true; }
    if(lk && lk !== pn){
      try{ _showInGameToast(_cute ? ('🔒 這個位置今天已經和 ['+lk+'] 綁在一起囉,明天早上 8:00 後才能換!') : ('🔒 此槽位今日已鎖定 ['+lk+'],明日早上 8:00 重置後才能更換。'), '#ffcc88', 2800); }catch(_){}
      return false;
    }
    // ★ v4.26.0 老師需求(復原/強化逐槽鎖定·防退出拉回來重刷) — 硬性每日「最多互動 3 隻寵物」上限:
    //   逐槽鎖定(lockSlots)本身仍在(互動任一隻即彈確認、確認後鎖此槽),但若 lockSlots 因
    //   關閉重開/重載而遺失,學生可能對新寵物重刷。此處再加一道「不依賴槽位」的硬閘門,改用
    //   「今日已互動寵物集合」= 已鎖槽值(lockSlots)∪ 今日互動紀錄 rec 有完成旗標者(pat/fed/play)。
    //   兩者皆已隨 petHouseDaily(_s) 序列化上雲、每天台灣早上 8:00 隨日鍵重置 → 全程唯讀既有欄位、
    //   零新增存檔欄位=零資料模型風險(守誤刪是大忌)。本寵已在集合內=繼續完成剩餘活動(canDo 另控),
    //   不擋;本寵為「今日第 4 隻不同寵物」才擋 → 即使 lockSlots 完全失效仍保證一天最多互動 3 隻。
    try{
      var _todaySet = {};
      var _ls = (window._petHouseDaily && window._petHouseDaily.lockSlots) || {};
      [0,1,2].forEach(function(si){ if(_ls[si]) _todaySet[_ls[si]] = 1; });
      var _rc = (window._petHouseDaily && window._petHouseDaily.rec) || {};
      Object.keys(_rc).forEach(function(p){ var r = _rc[p]; if(r && (r.pat || r.fed || r.play)) _todaySet[p] = 1; });
      if(!_todaySet[pn] && Object.keys(_todaySet).length >= 3){
        try{ _showInGameToast(_cute ? '🔒 今天已經和三隻寵物一起玩過囉!要等明天早上 8:00 後才能再找新夥伴喔~' : '🔒 每日互動上限:今日已與 3 隻寵物互動並綁定,明日早上 8:00 重置後才能更換夥伴。', '#ffcc88', 3200); }catch(_){}
        return false;
      }
    }catch(_){}
    var old = document.getElementById('_ph-lock-modal'); if(old) old.remove();
    var m = document.createElement('div');
    m.id = '_ph-lock-modal';
    m.style.cssText = 'position:fixed;inset:0;z-index:9650;background:rgba(0,0,0,0.8);display:flex;align-items:center;justify-content:center;padding:20px;font-family:inherit;';
    var box = document.createElement('div');
    box.style.cssText = 'background:linear-gradient(160deg,rgba(26,32,16,0.99),rgba(12,14,7,0.99));border:2.5px solid rgba(255,220,120,0.75);border-radius:20px;max-width:560px;width:100%;padding:24px 22px 20px;text-align:center;box-shadow:0 14px 40px rgba(0,0,0,0.6);';
    box.innerHTML = '<div style="font-size:52px;line-height:1;margin-bottom:8px;">🔒</div>'
      + '<div style="font-size:clamp(21px,2.6vw,27px);font-weight:900;color:#ffe8a0;margin-bottom:10px;">' + (_cute ? '今天這個位置要跟牠玩嗎?' : '確認此槽位今日互動夥伴') + '</div>'
      + '<div style="font-size:clamp(18px,2.1vw,22px);color:#ffeecc;font-weight:800;margin-bottom:10px;">🐾 ' + pn + '</div>'
      + '<div style="font-size:clamp(15px,1.7vw,18px);color:#f2ffe8;line-height:1.75;">' + (_cute
        ? '一旦開始互動,<b>這個位置今天就只能跟 ['+pn+'] 玩</b>囉!<br>其他空位還是可以請別的寵物來。<br>要等<b>明天早上 8:00</b> 重置才能換。'
        : '一旦開始互動,此槽位今日將<b>鎖定為 ['+pn+']、無法更換</b>;<br>其他槽位不受影響,仍可安排其他寵物互動。<br>每日互動與鎖定於<b>明日早上 8:00</b> 重置。') + '</div>';
    var row = document.createElement('div');
    row.style.cssText = 'display:flex;gap:10px;justify-content:center;margin-top:18px;flex-wrap:wrap;';
    var no = document.createElement('button');
    no.textContent = '✕ 再想想';
    no.style.cssText = 'padding:11px 24px;font-size:17px;font-weight:800;background:rgba(50,55,52,0.85);border:1.5px solid rgba(150,160,155,0.5);color:#cfe;border-radius:12px;cursor:pointer;font-family:inherit;';
    no.onclick = function(){ try{ playSfx('sfx-cancel',0.4); }catch(_){} m.remove(); };
    var yes = document.createElement('button');
    yes.textContent = '✅ 開始互動!';
    yes.style.cssText = 'padding:12px 30px;font-size:clamp(18px,2.1vw,22px);font-weight:900;background:linear-gradient(135deg,rgba(40,130,75,0.97),rgba(60,190,110,0.97));border:2px solid rgba(120,255,175,0.9);color:#eaffef;border-radius:12px;cursor:pointer;font-family:inherit;box-shadow:0 4px 16px rgba(70,220,140,0.45);';
    yes.onclick = function(){
      try{ playSfx('sfx-confirm',0.6); }catch(_){}
      window._petHouseLockSlot(idx, pn);
      m.remove();
      try{ _showInGameToast(_cute ? '🐾 好!這個位置今天就和 ['+pn+'] 一起玩!' : '🔒 已鎖定:此槽位今日互動夥伴為 ['+pn+']。', '#aaffcc', 2800); }catch(_){}
      if(onOk){ try{ onOk(); }catch(_){} }
    };
    row.appendChild(no); row.appendChild(yes);
    box.appendChild(row);
    m.appendChild(box);
    document.body.appendChild(m);
    try{ playSfx('sfx-gentle',0.5); }catch(_){}
    return false;
  }catch(_e){ console.warn('[小屋逐槽互動鎖]', _e); return true; }
};
// ★ v4.10.0 — 關卡主頁寵物鈕「本日有未互動寵物」標示:
//   條件=存在已馴養寵物 P,其今日三互動未全完成,且(P 已鎖入某槽 或 尚有未鎖定/空槽可安排)。
// ★ v4.12.0(老師需求) — 「今日互動!」標示改「只看目前入住三槽的寵物」:
//   三槽住的寵物「撫摸+餵食+遊戲」全部完成 → 回 false(關卡頁 badge 隱藏);
//   隔天早上 8:00 隨日鍵重置後,當日互動旗標清空 → 自然重現。
//   (不再因「玩家還有其他未入住寵物/尚有空槽」而持續亮起,避免做完仍一直提醒。)
window._petHouseHasPendingToday = function(){
  try{
    if(!(window._petSysOpenForMe && window._petSysOpenForMe())) return false;
    var slots = window._petHouseSlots || [];
    var d = window._petTwDateStr();
    var rec = (window._petHouseDaily && window._petHouseDaily.d === d && window._petHouseDaily.rec) ? window._petHouseDaily.rec : {};
    var anyResident = false;
    for(var i = 0; i < 3; i++){
      var pn = slots[i];
      if(!pn || !(window._petIsTamed && window._petIsTamed(pn))) continue;   // 空槽/未馴養跳過
      anyResident = true;
      var r = rec[pn] || {};
      if(!(r.pat && r.play && r.fed)) return true;   // 此入住寵物今日仍有互動可做
    }
    return false;   // 三槽住的寵物今日皆完成(或全空)→ 隱藏
  }catch(_){ return false; }
};
window._petNavBadgeRefresh = function(){
  try{
    var show = window._petHouseHasPendingToday();
    // 關卡頁靜態寵物鈕(仿獎章鈕浮層:inline overflow:visible + 絕對定位小標)
    var btn = document.getElementById('adv-nav-pet-btn');
    if(btn){
      var chip = document.getElementById('_pet-nav-badge');
      if(show){
        if(!chip){
          btn.style.overflow = 'visible';
          btn.style.position = btn.style.position || 'relative';
          chip = document.createElement('span');
          chip.id = '_pet-nav-badge';
          chip.textContent = '🐾 今日互動!';
          chip.style.cssText = 'position:absolute;top:-14px;left:50%;transform:translateX(-50%);z-index:30;font-size:12px;font-weight:900;color:#221a04;background:linear-gradient(135deg,#ffe27a,#ffb84a);border:1.5px solid rgba(255,255,255,0.8);border-radius:10px;padding:2px 8px;white-space:nowrap;pointer-events:none;box-shadow:0 2px 8px rgba(0,0,0,0.4);animation:pulse 1.4s infinite;';
          btn.appendChild(chip);
        }
      } else if(chip){ chip.remove(); }
    }
    // 手機版導覽寵物鈕:紅點
    var mbtn = document.querySelector('#_mobile-nav .mn-btn[data-act="pet"]');
    if(mbtn){
      var dot = mbtn.querySelector('._pet-nav-dot');
      if(show){
        if(!dot){
          mbtn.style.position = mbtn.style.position || 'relative';
          dot = document.createElement('span');
          dot.className = '_pet-nav-dot';
          dot.style.cssText = 'position:absolute;top:2px;right:8px;width:11px;height:11px;border-radius:50%;background:#ff5544;border:1.5px solid #fff;pointer-events:none;animation:pulse 1.4s infinite;';
          mbtn.appendChild(dot);
        }
      } else if(dot){ dot.remove(); }
    }
  }catch(_){}
};

// ★ v4.10.0(修正3) — 小屋互動(戳戳/撫摸)專用提示視窗:
//   原 _showInGameToast 置頂置中 44px 會蓋住寵物圖片 → 改為「畫面最右下」小型版
//   (整體縮小約 20%:字 44→35px·padding/寬同比),bottom 錨在食物清單(max-height:34vh)
//   正上方 → 不影響選擇食物清單,也不再蓋住寵物。僅小屋互動提示走此版,其餘 toast 不動。
// ★ v4.12.0(老師需求) — 小屋互動提示/確認回饋:整體再縮小約 30%(字 35→24px·padding 同比)、
//   位置改「畫面最右下角」(right/bottom:12px)、★單一實例★(固定 id·新提示先移除舊的·並清掉舊的
//   淡出計時器)→ 徹底消除「多個 toast 疊生、各自淡出時間錯開」造成的邊框不自然閃爍;
//   邊框發光收斂(box-shadow 由飽和 0.27→0.16 透明度)避免視覺閃動。
// ★ v4.26.0(老師需求·圖2) — 互動提示改「錨定在互動中的寵物正上方」:
//   新增第 4 參數 anchorIdx(互動槽位 0/1/2)→ 讀 #_ph-img-{idx} 的畫面位置,
//   把提示置中貼在該寵物圖「正上方」;無 anchorIdx / 找不到該寵物圖 → 退回舊版
//   「畫面最右下角」(相容舊呼叫,誤刪是大忌:舊定位保留於 !_anchored 分支)。
window._phHintToast = function(msg, color, dur, anchorIdx){
  try{
    var c = color || '#ffee99', d = dur || 2400;
    var old = document.getElementById('_ph-hint-toast');
    if(old){ try{ if(old._phT1) clearTimeout(old._phT1); }catch(_){} try{ if(old._phT2) clearTimeout(old._phT2); }catch(_){} try{ old.remove(); }catch(_){} }
    var t = document.createElement('div');
    t.id = '_ph-hint-toast';
    var _baseCss = 'position:fixed;z-index:9999;'
      + 'background:rgba(10,15,30,0.95);border:1.5px solid ' + c + ';color:' + c + ';'
      + 'font-size:19px;font-weight:700;padding:6px 12px;border-radius:10px;pointer-events:none;'
      + 'font-family:"M PLUS Rounded 1c","Nunito",sans-serif;max-width:min(290px,72vw);'
      + 'box-shadow:0 0 10px ' + c + '22;';
    var _anchored = false;
    try{
      if(anchorIdx !== undefined && anchorIdx !== null){
        var _img = document.getElementById('_ph-img-' + anchorIdx);
        if(_img){
          var r = _img.getBoundingClientRect();
          if(r && r.width > 0 && r.top > 0){
            var _cx = r.left + r.width / 2;
            var _bottomPx = Math.max(8, (window.innerHeight - r.top) + 8);   // 貼在寵物圖上緣上方 8px
            t.style.cssText = _baseCss + 'text-align:center;left:' + _cx + 'px;bottom:' + _bottomPx + 'px;transform:translateX(-50%);';
            _anchored = true;
          }
        }
      }
    }catch(_){}
    // 舊定位(v4.12.0 右下角):anchorIdx 未傳或找不到寵物圖時沿用
    if(!_anchored){ t.style.cssText = _baseCss + 'text-align:left;right:10px;bottom:10px;'; }
    t.textContent = msg;
    document.body.appendChild(t);
    // 錨定模式:置中後夾住不超出視窗左右邊(避免最左/最右槽位的提示被切掉)
    if(_anchored){
      try{
        var rr = t.getBoundingClientRect();
        if(rr.left < 6) t.style.left = (t.offsetWidth / 2 + 6) + 'px';
        else if(rr.right > window.innerWidth - 6) t.style.left = (window.innerWidth - t.offsetWidth / 2 - 6) + 'px';
      }catch(_){}
    }
    t._phT1 = setTimeout(function(){
      t.style.opacity = '0'; t.style.transition = 'opacity 0.4s';
      t._phT2 = setTimeout(function(){ if(t.parentNode) t.remove(); }, 450);
    }, d);
  }catch(_){ try{ _showInGameToast(msg, color, dur); }catch(__){} }
};

