// ══════════════════════════════════════════════════════════════════
// ★ 小屋互動表情(撫摸/餵食):正確→開心換圖、錯誤→生氣(去背圖+💢符號)
//   開心(正確行動):換成 寵物名_開心.webp(repo 根目錄·webp),1.5s 後自動還原去背圖;
//                    圖未上傳(404)時 onerror 立即還原去背圖→不破圖、等同現況。
//   生氣(錯誤行動):★不換圖★·維持原本去背圖·僅疊「💢 生氣符號」1.5s(老師之後補「不悅」
//                    專屬表情圖·屆時把 sad 分支改走 _petSadUrl 換圖即可·函式已保留)。
// ══════════════════════════════════════════════════════════════════
window._petHappyUrl = function(pn){
  return './' + encodeURIComponent(pn + '_開心.webp');
};
window._petSadUrl = function(pn){
  return './' + encodeURIComponent(pn + '_不悅.webp');
};
// 表情顯示時間(ms):部分互動 950~1250ms 會重繪卡片自然還原;戳戳生氣不重繪則由此計時還原
window._PET_EMOTE_MS = 1500;
window._PET_ANGRY_SYMBOL = '💢';
// mood:'happy'(開心/正確)→短暫換成開心圖·到時自動還原去背圖
//      'sad'/'angry'(生氣/錯誤)→★不換圖★·維持原本去背圖·僅在寵物圖上疊「💢 生氣符號」·到時自動移除
//   (不悅專屬表情圖老師之後補·屆時把 sad 分支改走 _petSadUrl 換圖即可·_petSadUrl 已保留備用)
window._petHouseEmote = function(slotIdx, mood){
  try{
    var wrap = document.getElementById('_ph-img-' + slotIdx);
    if(!wrap) return;
    var img = wrap.querySelector('img');
    if(!img) return;
    var pn = (window._petHouseSlots && window._petHouseSlots[slotIdx]) || null;
    if(!pn) return;

    if(mood === 'sad' || mood === 'angry'){
      // ★ v4.13.0 生氣/不悅:換成「寵物名_不悅.webp」(老師上傳·圖本身右上已含 💢 表情·不再另疊符號);
      //   _PET_EMOTE_MS(1.5s)後自動還原去背圖;圖未上傳(404)→ onerror 立即還原去背圖(不破圖、等同舊行為)。
      var _surl = (typeof window._petSadUrl === 'function') ? window._petSadUrl(pn) : '';
      if(!_surl) return;
      if(!img._petBaseSrc){ img._petBaseSrc = (img.getAttribute('src') || img.src || ''); }
      var _sbase = img._petBaseSrc;
      if(!_sbase) return;
      if(img._petEmoteTimer){ try{ clearTimeout(img._petEmoteTimer); }catch(_){} img._petEmoteTimer = null; }
      img.onerror = function(){ try{ this.onerror = null; this.src = _sbase; }catch(_){} };
      img.src = _surl;
      img._petEmoteTimer = setTimeout(function(){
        try{ img.onerror = null; img.src = _sbase; img._petEmoteTimer = null; }catch(_){}
      }, window._PET_EMOTE_MS);
      return;
    }

    // happy:短暫換成開心圖·到時自動還原去背圖
    var _url = (typeof window._petHappyUrl === 'function') ? window._petHappyUrl(pn) : '';
    if(!_url) return;
    // 記住「基準去背圖」src(第一次進表情前顯示中的圖·含去背圖 404 後已 fallback 的 petImg),供還原
    if(!img._petBaseSrc){ img._petBaseSrc = (img.getAttribute('src') || img.src || ''); }
    var _base = img._petBaseSrc;
    if(!_base) return;
    // 清掉舊的還原計時(連續互動不殘留)
    if(img._petEmoteTimer){ try{ clearTimeout(img._petEmoteTimer); }catch(_){} img._petEmoteTimer = null; }
    // 開心圖尚未上傳(404)→ onerror 立即還原基準去背圖(不破圖、無錯誤圖示)
    img.onerror = function(){ try{ this.onerror = null; this.src = _base; }catch(_){} };
    img.src = _url;
    img._petEmoteTimer = setTimeout(function(){
      try{ img.onerror = null; img.src = _base; img._petEmoteTimer = null; }catch(_){}
    }, window._PET_EMOTE_MS);
  }catch(_){}
};

