      // ★ v4.1.0 餵食拖曳:餵錯左右顫抖 + 問號、拖曳光點尾巴、幽靈食物、寵物放置高亮
      + '@keyframes _phShake{0%,100%{transform:translateX(0) rotate(0deg);}15%{transform:translateX(-11px) rotate(-4deg);}30%{transform:translateX(10px) rotate(4deg);}45%{transform:translateX(-8px) rotate(-3deg);}60%{transform:translateX(7px) rotate(3deg);}75%{transform:translateX(-5px) rotate(-2deg);}90%{transform:translateX(4px) rotate(1deg);}}'
      + '._ph-shaking{animation:_phShake 0.6s ease-in-out 1;}'
      + '@keyframes _phQmark{0%{transform:translateY(0) scale(0.4) rotate(-8deg);opacity:0;}18%{transform:translateY(-18px) scale(1.3) rotate(6deg);opacity:1;}55%{transform:translateY(-26px) scale(1.15) rotate(-5deg);opacity:1;}100%{transform:translateY(-42px) scale(1) rotate(4deg);opacity:0;}}'
      + '._ph-qmark{position:absolute;font-size:36px;font-weight:900;color:#ffdd55;text-shadow:0 2px 6px rgba(0,0,0,0.75);pointer-events:none;animation:_phQmark 1.2s ease-out forwards;z-index:31;}'
      + '@keyframes _phSpark{0%{transform:translate(-50%,-50%) scale(1.15);opacity:1;}100%{transform:translate(-50%,-50%) scale(0.15) translateY(14px);opacity:0;}}'
      + '._ph-spark{position:fixed;pointer-events:none;z-index:9600;text-shadow:0 0 7px rgba(255,240,150,0.95);animation:_phSpark 0.6s ease-out forwards;}'
      + '._ph-food-ghost{position:fixed;transform:translate(-50%,-50%) scale(1.5);font-size:60px;pointer-events:none;z-index:9590;filter:drop-shadow(0 6px 11px rgba(0,0,0,0.6));will-change:left,top;}'
