      + '@keyframes _phAngry{0%{transform:translateY(0) scale(0.4) rotate(-10deg);opacity:0;}25%{transform:translateY(-14px) scale(1.3) rotate(8deg);opacity:1;}100%{transform:translateY(-32px) scale(1) rotate(-6deg);opacity:0;}}'
