        const _id = t.map[name];
        const _def = (typeof BACKPACK_ITEM_DEF !== 'undefined') ? BACKPACK_ITEM_DEF[_id] : null;
        if(!_def) return;
        _sellRows += _row(_def.icon || '🎁', _def.name || _id, t.rate, _def.sellPrice);
