      const _isCnBoss  = (typeof CHINA_ENEMY_BOSS_NAMES !== 'undefined') && CHINA_ENEMY_BOSS_NAMES.has && CHINA_ENEMY_BOSS_NAMES.has(name);
      const _isPixiu   = (name === '貔貅');
