function _unlockMedal(id){
  if(_medals[id]) return; // already unlocked

  // ★ v3.5.34 — 第二層保險:檢查 localStorage 是否已有此獎章記錄
  //   修補 PWA 重複領「日漸成熟」等獎章 BUG。
  //   即使記憶體中的 _medals 變數還沒從雲端 merge 完成(時序競態),
  //   localStorage 的 adv_medals 可能已經有上次登入寫入的記錄。
  //   多查這一層能徹底擋住重複發獎,並把 _medals 變數補上正確資料。
  try{
    const _lsData = localStorage.getItem('adv_medals');
    if(_lsData){
      const _lsMedals = JSON.parse(_lsData);
      if(_lsMedals && _lsMedals[id]){
        console.warn('[獎章保護 v3.5.34] _medals 變數沒有「' + id
          + '」但 localStorage 有 → 補回 _medals,避免重複發獎');
        _medals[id] = _lsMedals[id];
        return;  // 立即返回,不重複發獎
      }
    }
  }catch(_eLsCheck){ /* 讀失敗時繼續,維持原本邏輯 */ }

  _medals[id] = { unlockedAt: Date.now() };
  // ★ v1.0.20260501.4750 — 解鎖時自動發放獎勵(水晶+知識幣)
  const _isTopTier = _MEDAL_TOP_TIER.has(id);
  const _crystalReward = _isTopTier ? 5 : 1;
  const _coinReward = _isTopTier ? 10000 : 2000;
  try{
    if(typeof backpackAdd === 'function'){
      backpackAdd('summon_crystal', _crystalReward, '獎章獎勵');
    }
    if(typeof addKnowledgeCoins === 'function'){
      addKnowledgeCoins(_coinReward, '收入:獎章獎勵');
    } else {
      _knowledgeCoins = (_knowledgeCoins||0) + _coinReward;
    }
    // ★ v1.0.20260501.4780 — 標記此獎章已發過獎勵(避免日後再被「補發掃描」誤判為未領)
    //   旗標必須在 _saveMedals 之前寫入,否則本次寫入雲端的記錄不含 rewarded:true
    _medals[id].rewarded = true;
    _medals[id].rewardedAt = Date.now();
    // 立即雲端同步(fire-and-forget,有 .catch 防 unhandled)
    if(typeof gameCloudSave === 'function'){
      const _p = gameCloudSave();
      if(_p && typeof _p.catch === 'function'){
        _p.catch(e => console.warn('[獎章獎勵 雲端同步失敗,本地已記錄]', e));
      }
    }
  }catch(e){ console.warn('[獎章獎勵發放]', e); }
  _saveMedals();
  const def = MEDAL_DEFS.find(m=>m.id===id);
  if(def){
    _setMedalDot(true);
    // ★ v3.15.61 — earn 任何獎章後刷新「新增獎章挑戰」徽章(若本波最後一枚剛達成 → 徽章消失)
    try{ if(typeof _updateGmMedalW1Badge === 'function') _updateGmMedalW1Badge(); }catch(_){}
    setTimeout(()=>{
      _showMedalCelebration(def, {
        crystals: _crystalReward,
        coins: _coinReward,
        isTopTier: _isTopTier
      });
    }, 400);
  }
}

// ═══════════════════════════════════════════════════════════
// ★ v1.1.0 — 台灣關獎章追蹤系統(50 個獎章的解鎖判定)
// ═══════════════════════════════════════════════════════════

// BOSS id → 獎章 id 對照表(用於各 BOSS 首殺)
const _TW_BOSS_MEDAL_MAP = {
  'changhua_braised':    'tw_kill_changhua',
  'taichung_pineapple':  'tw_kill_taichung',
  'shenkeng_tofu':       'tw_kill_shenkeng',
  'alishan_tree':        'tw_kill_alishan',
  'lanyu_octopus':       'tw_kill_lanyu',
  'sanxia_indigo':       'tw_kill_sanxia',
  'ximen_pearl':         'tw_kill_ximen',
  'sun_moon_mirror_boss':'tw_kill_sunmoon',
  'taipei_101_warlord':  'tw_kill_taipei101',
  'yushan_giant':        'tw_kill_yushan',
};

// 台灣 BOSS 戰勝時呼叫:統一檢查所有戰勝相關獎章
window._checkTaiwanWinMedals = function(opts){
  // opts: { bossId, rounds, allHeroesAlive, soloAlive, lowLv, burstKill, rageSurvived,
  //         noTreasureUsed, perfectQuiz }
  try{
    if(!opts || !opts.bossId) return;
    const bid = opts.bossId;

    // 0. 全環島啟程
    _unlockMedal('tw_first_clear');

    // 1. 各 BOSS 首殺
    if(_TW_BOSS_MEDAL_MAP[bid]) _unlockMedal(_TW_BOSS_MEDAL_MAP[bid]);

    // 2. 累積擊敗
    _medalStats.twBossKills = _medalStats.twBossKills || {};
    _medalStats.twBossKills[bid] = (_medalStats.twBossKills[bid]||0) + 1;
    _medalStats.twTotalKills = (_medalStats.twTotalKills||0) + 1;
    if(_medalStats.twTotalKills >= 5)  _unlockMedal('tw_kills_5');
    if(_medalStats.twTotalKills >= 15) _unlockMedal('tw_kills_15');
    if(_medalStats.twTotalKills >= 30) _unlockMedal('tw_kills_30');
    if(_medalStats.twTotalKills >= 50) _unlockMedal('tw_kills_50');

    // 3. 全員擊破(10 種 BOSS 都至少一次)
    if(Object.keys(_medalStats.twBossKills).length >= 10) _unlockMedal('tw_unique_all_10');

    // 4. 完成趟數
    _medalStats.twClears = (_medalStats.twClears||0) + 1;
    if(_medalStats.twClears >= 5)  _unlockMedal('tw_clears_5');
    if(_medalStats.twClears >= 20) _unlockMedal('tw_clears_20');

    // 5. 戰術成就
    if(opts.rounds && opts.rounds <= 10) _unlockMedal('tw_quick_win');
    if(opts.rounds && opts.rounds <= 5)  _unlockMedal('tw_super_quick');
    if(opts.rounds && opts.rounds <= 15 && bid === 'yushan_giant') _unlockMedal('tw_yushan_quick');

    if(opts.allHeroesAlive){ _medalStats.twNoKoWin = true; _unlockMedal('tw_no_ko'); }
    if(opts.soloAlive){      _medalStats.twSoloWin = true; _unlockMedal('tw_solo_win'); }
    if(opts.lowLv){          _medalStats.twLowLvWin = true; _unlockMedal('tw_low_lv_win'); }
    if(opts.burstKill){      _medalStats.twBurstKill = true; _unlockMedal('tw_burst_kill'); }
    if(opts.rageSurvived){   _medalStats.twRageSurvived = true; _unlockMedal('tw_rage_survived'); }

    // 6. 法寶相關
    const _twUsed = _medalStats.twTreasuresUsedThisBattle || 0;
    if(_twUsed >= 3) _unlockMedal('tw_use_treasure_3');
    if(_twUsed === 0 && opts.noTreasureUsed){ _medalStats.twNoTreasureWin = true; _unlockMedal('tw_no_treasure_win'); }

    // 7. 答題滿分
    if(_medalStats.twQuizCountThisBattle > 0
       && _medalStats.twQuizCorrectThisBattle === _medalStats.twQuizCountThisBattle){
      _medalStats.twQuizPerfect = true;
      _unlockMedal('tw_quiz_perfect');
    }

    // ★ v3.15.61 — 高階獎章:只用 SR 英雄通關台灣任一 BOSS
    try{
      const _twTeam = (typeof G !== 'undefined' && Array.isArray(G.p1)) ? G.p1.filter(h => h && h.name) : [];
      if(_twTeam.length > 0 && typeof _getHeroRarity === 'function'
         && _twTeam.every(h => _getHeroRarity(h.name) === 'SR')){
        _unlockMedal('tw_sr_only');
      }
    }catch(_eTwSr){ console.warn('[台灣SR純隊獎章]', _eTwSr); }

    // 重置本場戰鬥計數
    _medalStats.twTreasuresUsedThisBattle = 0;
    _medalStats.twQuizCountThisBattle = 0;
    _medalStats.twQuizCorrectThisBattle = 0;

    _saveMedals();
  }catch(e){ console.warn('[台灣關獎章] win 檢查失敗', e); }
};

// 答題正確時呼叫
window._checkTaiwanQuizMedals = function(isCorrect){
  try{
    if(_adventureStage !== 'taiwan') return;
    _medalStats.twQuizCountThisBattle = (_medalStats.twQuizCountThisBattle||0) + 1;
    if(isCorrect){
      _medalStats.twCorrectAnswers = (_medalStats.twCorrectAnswers||0) + 1;
      _medalStats.twQuizCorrectThisBattle = (_medalStats.twQuizCorrectThisBattle||0) + 1;
      _medalStats.twQuizStreak = (_medalStats.twQuizStreak||0) + 1;
      if(_medalStats.twQuizStreak > (_medalStats.twQuizMaxStreak||0)){
        _medalStats.twQuizMaxStreak = _medalStats.twQuizStreak;
      }
      if(_medalStats.twCorrectAnswers >= 50)  _unlockMedal('tw_quiz_correct_50');
      if(_medalStats.twCorrectAnswers >= 200) _unlockMedal('tw_quiz_correct_200');
      if(_medalStats.twQuizStreak >= 10) _unlockMedal('tw_quiz_streak_10');
      if(_medalStats.twQuizStreak >= 20) _unlockMedal('tw_quiz_streak_20');
    } else {
      _medalStats.twQuizStreak = 0; // 答錯歸零
    }
    _saveMedals();
  }catch(e){ console.warn('[台灣關獎章] quiz 檢查失敗', e); }
};

// 至寶獲得時呼叫
window._checkTaiwanTreasureMedals = function(treasureId){
  try{
    const data = (typeof _taiwanTreasureData !== 'undefined') ? _taiwanTreasureData : {};
    const ownedCount = Object.keys(data).length;

    _unlockMedal('tw_treasure_first');
    if(ownedCount >= 3)  _unlockMedal('tw_treasure_3');
    if(ownedCount >= 5)  _unlockMedal('tw_treasure_5');
    if(ownedCount >= 8)  _unlockMedal('tw_treasure_8');
    if(ownedCount >= 10) _unlockMedal('tw_treasure_all_10');

    // 玉山專屬
    if(treasureId === 'yushan_protection_seal' || (treasureId && treasureId.indexOf('yushan')>=0)){
      _unlockMedal('tw_yushan_treasure');
    }

    _saveMedals();
  }catch(e){ console.warn('[台灣關獎章] treasure 檢查失敗', e); }
};

// 至寶升級時呼叫
window._checkTaiwanTreasureLvMedals = function(){
  try{
    const data = (typeof _taiwanTreasureData !== 'undefined') ? _taiwanTreasureData : {};
    let maxLv = 0;
    let lv10Count = 0;
    Object.values(data).forEach(rec => {
      if(rec && typeof rec.lv === 'number'){
        if(rec.lv > maxLv) maxLv = rec.lv;
        if(rec.lv >= 10) lv10Count++;
      }
    });
    if(maxLv >= 5)  _unlockMedal('tw_treasure_lv5');
    if(maxLv >= 10) _unlockMedal('tw_treasure_lv10');
    if(lv10Count >= 3) _unlockMedal('tw_treasure_3_lv10');
    _saveMedals();
  }catch(e){ console.warn('[台灣關獎章] treasure-lv 檢查失敗', e); }
};

