// ★★ v5.65.0(2026-08-18)— 丙②:中國關獎章擴充至 40 枚的判定 helper(全部走 _unlockMedal 內部去重=冪等)
//   設計比照台灣關 _checkTaiwanWinMedals / _checkTaiwanQuizMedals 範式,統計欄位存 _medalStats(隨主檔上雲)。
//   ⚠ 全部 helper 皆自帶 _adventureStage==='china' 或呼叫端守門 → 台/日/埃/鬥技場/世界BOSS 零影響。

// 中國妖王戰勝時呼叫:統一檢查累積 / 路線全通 / 戰術 / 單場答題滿分
// opts: { variantId, rounds, allHeroesAlive, soloAlive, lowLv, burstKill }
window._checkChinaWinMedals = function(opts){
  try{
    opts = opts || {};
    // 1. 累積擊敗
    _medalStats.cnTotalKills = (_medalStats.cnTotalKills || 0) + 1;
    if(_medalStats.cnTotalKills >= 5)  _unlockMedal('china_kills_5');
    if(_medalStats.cnTotalKills >= 15) _unlockMedal('china_kills_15');
    if(_medalStats.cnTotalKills >= 30) _unlockMedal('china_kills_30');

    // 2. 五路線全通(以路線 id 記帳;拿不到 id 就不記,不影響其他判定)
    if(opts.variantId){
      _medalStats.cnRouteKills = _medalStats.cnRouteKills || {};
      _medalStats.cnRouteKills[opts.variantId] = (_medalStats.cnRouteKills[opts.variantId] || 0) + 1;
      if(Object.keys(_medalStats.cnRouteKills).length >= 5) _unlockMedal('china_all_routes');
    }

    // 3. 戰術成就
    if(opts.rounds && opts.rounds <= 10) _unlockMedal('china_quick_win');
    if(opts.allHeroesAlive) _unlockMedal('china_no_ko');
    if(opts.soloAlive)      _unlockMedal('china_solo_win');
    if(opts.lowLv)          _unlockMedal('china_low_lv_win');
    if(opts.burstKill)      _unlockMedal('china_burst_kill');

    // 4. 單場答題全對(本場有作答且零答錯)
    var _cnQ = _medalStats.cnQuizCountThisBattle || 0;
    var _cnC = _medalStats.cnQuizCorrectThisBattle || 0;
    if(_cnQ > 0 && _cnQ === _cnC) _unlockMedal('china_quiz_perfect');
    _medalStats.cnQuizCountThisBattle = 0;
    _medalStats.cnQuizCorrectThisBattle = 0;

    // 5. 收服進度(順手複查,避免收服當下漏判)
    try{ if(typeof window._checkChinaHeroCountMedals === 'function') window._checkChinaHeroCountMedals(); }catch(_){}
    _saveMedals();
  }catch(_e){ console.warn('[中國關獎章] 戰勝檢查失敗', _e); }
};

// 中國關答題時呼叫(掛在既有全域答題統計點,內部自行守門)
window._checkChinaQuizMedals = function(isCorrect){
  try{
    if(typeof _adventureStage === 'undefined' || _adventureStage !== 'china') return;
    _medalStats.cnQuizCountThisBattle = (_medalStats.cnQuizCountThisBattle || 0) + 1;
    if(isCorrect){
      _medalStats.cnCorrectAnswers = (_medalStats.cnCorrectAnswers || 0) + 1;
      _medalStats.cnQuizCorrectThisBattle = (_medalStats.cnQuizCorrectThisBattle || 0) + 1;
      _medalStats.cnQuizStreak = (_medalStats.cnQuizStreak || 0) + 1;
      if(_medalStats.cnQuizStreak > (_medalStats.cnQuizMaxStreak || 0)){
        _medalStats.cnQuizMaxStreak = _medalStats.cnQuizStreak;
      }
      if(_medalStats.cnCorrectAnswers >= 50)  _unlockMedal('china_quiz_correct_50');
      if(_medalStats.cnCorrectAnswers >= 200) _unlockMedal('china_quiz_correct_200');
      if(_medalStats.cnQuizStreak >= 10) _unlockMedal('china_quiz_streak_10');
      if(_medalStats.cnQuizStreak >= 20) _unlockMedal('china_quiz_streak_20');
    } else {
      _medalStats.cnQuizStreak = 0;   // 答錯歸零
    }
    _saveMedals();
  }catch(_e){ console.warn('[中國關獎章] quiz 檢查失敗', _e); }
};

// 中華英雄收服數(讀 advGetUnlockedHeroes 即時計算·純判定零寫入解鎖帳本)
window._checkChinaHeroCountMedals = function(){
  try{
    // ⚠ CHINA_EXCLUSIVE_HEROES 是 Set(不是陣列)→ 一律轉成陣列再數
    var _names = [];
    try{
      if(typeof CHINA_EXCLUSIVE_HEROES !== 'undefined' && CHINA_EXCLUSIVE_HEROES){
        _names = (typeof Array.from === 'function' && CHINA_EXCLUSIVE_HEROES.forEach)
          ? Array.from(CHINA_EXCLUSIVE_HEROES)
          : (Array.isArray(CHINA_EXCLUSIVE_HEROES) ? CHINA_EXCLUSIVE_HEROES.slice() : []);
      }
    }catch(_){}
    if(!_names.length) return;
    var _un = [];
    try{ _un = (typeof advGetUnlockedHeroes === 'function') ? (advGetUnlockedHeroes() || []) : []; }catch(_){}
    var _set = {};
    _un.forEach(function(n){ _set[n] = true; });
    var _cnt = 0;
    for(var i = 0; i < _names.length; i++){ if(_set[_names[i]]) _cnt++; }
    if(_cnt >= 1) _unlockMedal('china_recruit');
    if(_cnt >= 4) _unlockMedal('china_hero_4');
    if(_cnt >= 8) _unlockMedal('china_hero_all_8');
    if(_set['諸葛亮']) _unlockMedal('china_zhuge');
    _saveMedals();
  }catch(_e){ console.warn('[中國關獎章] 英雄收服檢查失敗', _e); }
};

// 中華神兵 / 中國神獸收藏(裝備走 equipmentData 實例·寵物走 CARRY_PET_DB 的 _stage:'china')
window._checkChinaCollectionMedals = function(){
  try{
    // 神兵:掃現有裝備實例,對照 GEAR_DB 的 stage==='china'
    try{
      var _inst = (window._gearData && window._gearData.instances) ? window._gearData.instances : null;
      if(_inst && typeof GEAR_DB !== 'undefined'){
        var _gset = {};
        Object.keys(_inst).forEach(function(k){
          var _it = _inst[k]; if(!_it || !_it.itemId) return;
          var _def = GEAR_DB[_it.itemId];
          if(_def && _def.stage === 'china') _gset[_it.itemId] = true;
        });
        var _gn = Object.keys(_gset).length;
        if(_gn >= 1) _unlockMedal('china_gear_first');
        if(_gn >= 6) _unlockMedal('china_gear_6');
      }
    }catch(_){}
    // 神獸:掃已馴養寵物名單(window._tamedPets 為權威·鍵=寵物名),對照 window._CHINA_PET_NAMES(v5.62.0 既有快照 Set)
    try{
      var _pn = window._CHINA_PET_NAMES;
      var _tamed = window._tamedPets;
      if(_pn && _tamed && typeof _tamed === 'object'){
        var _cn = 0;
        Object.keys(_tamed).forEach(function(n){
          if(_pn.has && _pn.has(n)) _cn++;
        });
        if(_cn >= 1) _unlockMedal('china_pet_first');
        if(_cn >= 4) _unlockMedal('china_pet_4');
      }
    }catch(_){}
    _saveMedals();
  }catch(_e){ console.warn('[中國關獎章] 收藏檢查失敗', _e); }
};

// 神農鼎煉丹成就(A=進入鼎/B=採集/C=煉製結果)
//   ★ 老師 2026-08-18 裁定:仙品丹藥「連續」成功 3/6/10 次 → 只計仙品那一次的成敗,
//     煉「非仙品」不影響連勝(不加不減),仙品失敗才歸零。連勝值存 _medalStats.cnAlchImmortalStreak。
window._checkChinaAlchMedal = function(kind, payload){
  try{
    if(kind === 'intro')  { _unlockMedal('china_alch_intro'); }
    if(kind === 'gather') { _unlockMedal('china_alch_gather'); }
    if(kind === 'recipeAll'){ _unlockMedal('china_alch_recipe_all'); }
    if(kind === 'craft'){
      payload = payload || {};
      if(payload.success){
        _unlockMedal('china_alch_first');
        if(payload.immortal) _unlockMedal('china_alch_immortal');
      }
      // 仙品連勝(只有仙品丹藥才進入連勝計算)
      if(payload.immortal){
        if(payload.success){
          _medalStats.cnAlchImmortalStreak = (_medalStats.cnAlchImmortalStreak || 0) + 1;
          if(_medalStats.cnAlchImmortalStreak > (_medalStats.cnAlchImmortalMaxStreak || 0)){
            _medalStats.cnAlchImmortalMaxStreak = _medalStats.cnAlchImmortalStreak;
          }
          // ★ v5.68.0(老師 2026-08-18 裁定)— 門檻由 v5.67.0 的 2/5/7 ★回復為 3/6/10★:
          //   理由=同版新增「五行共鳴 QTE」後,仙品成功率可由 60% 提升至最高 100%,
          //   連續 10 次不再是機率不可達,而是「小遊戲練得好就拿得到」的技術性挑戰。
          //   ★ 獎章 id 一如既往刻意不改(china_alch_streak_3/6/10):已解鎖玩家雲端紀錄完整沿用,
          //     冪等不重發不遺失;MEDAL_DB desc 三筆同步改回 3/6/10。
          // ★★ v5.73.0(老師 2026-08-18 裁定)— QTE 加成由 +8% 降為 +6%(全對 +30%)後,
          //   仙品成功率上限由 100% 降為 **90%** ⇒ 「連續 10 次」的期望機率約 0.9^10 ≒ **34.9%**,
          //   由「練熟即必得」回到「需要運氣+技術」。門檻仍維持 3/6/10 不變(老師本輪未裁定調整);
          //   若日後覺得 streak_10 太難,調的是門檻或加成率,**獎章 id 永遠不動**。
          //   (v5.67.0 下修門檻保留備查:>=2 / >=5 / >=7;原 v5.65.0 亦為 >=3 / >=6 / >=10)
          if(_medalStats.cnAlchImmortalStreak >= 3)  _unlockMedal('china_alch_streak_3');
          if(_medalStats.cnAlchImmortalStreak >= 6)  _unlockMedal('china_alch_streak_6');
          if(_medalStats.cnAlchImmortalStreak >= 10) _unlockMedal('china_alch_streak_10');
        } else {
          _medalStats.cnAlchImmortalStreak = 0;   // 仙品失敗才中斷連勝
        }
      }
    }
    _saveMedals();
  }catch(_e){ console.warn('[中國關獎章] 煉丹檢查失敗', _e); }
};
// ★ v5.68.0(老師需求③)— 仙品連勝「計數顯示」對外查詢點(純讀取零寫入)。
//   _medalStats 隨獎章存檔上雲(medalStats 欄位·綁 uid·跨裝置/跨平板延續),
//   本 helper 只是把它安全地暴露給神農鼎面板與煉丹揭曉使用(跨 script 區塊也讀得到)。
//   回傳:{ cur:當前連勝, max:歷史最佳, goals:[3,6,10] }
window._alchStreakInfo = function(){
  try{
    if(typeof _medalStats === 'undefined' || !_medalStats) return { cur:0, max:0, goals:[3,6,10] };
    var _c = parseInt(_medalStats.cnAlchImmortalStreak) || 0;
    var _m = parseInt(_medalStats.cnAlchImmortalMaxStreak) || 0;
    if(_m < _c) _m = _c;
    return { cur:_c, max:_m, goals:[3,6,10] };
  }catch(_eSk){ return { cur:0, max:0, goals:[3,6,10] }; }
};

// ★ v3.15.60 — 鬥技場成就(由 arena.js 每場結算後呼叫;result='win'/'draw'/'loss',winsLifetime=累積勝場)
window._checkMedalArena = function(result, winsLifetime){
  try{
    if(result === 'win'){
      _unlockMedal('arena_first_win');
      var _wl = winsLifetime || 0;
      if(_wl >= 10) _unlockMedal('arena_win_10');
      if(_wl >= 30) _unlockMedal('arena_win_30');
      if(_wl >= 50) _unlockMedal('arena_win_50');
      _medalStats.arenaWinStreak = (_medalStats.arenaWinStreak || 0) + 1;
      if(_medalStats.arenaWinStreak >= 5) _unlockMedal('arena_streak_5');
      // ★ v3.15.61 — 高階獎章:鬥技場戰術成就(全部需獲勝)
      try{
        // (a) 三軍掃蕩:本場擊倒 3 名以上對手英雄(勝利時 G.p2 陣亡數)
        if(typeof G !== 'undefined' && Array.isArray(G.p2)){
          var _p2Dead = G.p2.filter(function(h){ return h && h.curHp <= 0; }).length;
          if(_p2Dead >= 3) _unlockMedal('arena_kill_3');
        }
        // (b) 無須療傷:全程未對我方使用任何治療
        if(!window._arenaUsedHeal) _unlockMedal('arena_no_heal_win');
        // (c) 閃電雙殺:前 3 回合內擊倒 2 名「不同」對手英雄
        if(Array.isArray(window._arenaKillLog)){
          var _early = {};
          window._arenaKillLog.forEach(function(k){
            if(k && (k.round || 0) <= 3 && k.name) _early[k.name] = true;
          });
          if(Object.keys(_early).length >= 2) _unlockMedal('arena_2kill_3round');
        }
      }catch(_eArenaAdv){ console.warn('[鬥技場高階獎章]', _eArenaAdv); }
    } else {
      _medalStats.arenaWinStreak = 0;  // 平/敗中斷連勝
    }
    _saveMedals();
  }catch(_){}
};

// ★ v3.15.60 — 世界 BOSS:迎戰各龍王成就(世界 BOSS 戰結算時以「當前龍王名」呼叫;勝負皆計「迎戰」)
window._checkMedalWbDragon = function(bossName){
  try{
    var _map = {
      '火山炎龍王':'wb_dragon_fire',  '翠綠森龍王':'wb_dragon_forest',
      '山岳地龍王':'wb_dragon_earth', '風暴雷龍王':'wb_dragon_thunder',
      '深淵海龍王':'wb_dragon_sea',   '邪骨暗龍王':'wb_dragon_dark',
      '神聖光龍王':'wb_dragon_light', '星辰幻龍王':'wb_dragon_illusion'
    };
    var _mid = _map[bossName];
    if(!_mid) return;
    _unlockMedal(_mid);
    var _all = ['wb_dragon_fire','wb_dragon_forest','wb_dragon_earth','wb_dragon_thunder','wb_dragon_sea','wb_dragon_dark','wb_dragon_light','wb_dragon_illusion'];
    var _got = true;
    for(var _i = 0; _i < _all.length; _i++){ if(!_medals[_all[_i]]){ _got = false; break; } }
    if(_got) _unlockMedal('wb_dragon_all');
    _saveMedals();
  }catch(_){}
};

